const SCRIPT=[{"k": "chapter", "n": 1, "t": "ちょっと待って"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.5"}, {"k": "cmd", "c": "@bgm piano35 0.35"}, {"k": "text", "s": "", "t": "ちょっと待って、と言うのが私の癖だ。"}, {"k": "text", "s": "", "t": "口に出すたびに、相手の顔にかすかな影が差すのがわかる。怒っているわけではない。止まってしまった時計を見るときのような、困った優しさがそこにある。"}, {"k": "text", "s": "", "t": "二三一五年の春、「ちょっと待って」はもう、誰も使わない言葉になりかけている。"}, {"k": "text", "s": "", "t": "朝の台所には、土の匂いがしていた。"}, {"k": "text", "s": "", "t": "母が勝手口から戻ってきたところで、腕に抱えた籠からは、まだ露をまとった菜の花がこぼれそうになっている。"}, {"k": "text", "s": "", "t": "「真波、お味噌汁、豆腐とわかめとどっちがいい？」"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "母は笑って、籠を流しに置いた。「はいはい。その間に卵焼いちゃうね」"}, {"k": "text", "s": "", "t": "どっちでもいい、と言えれば楽なのに。でも私は、今朝の自分がどちらを欲しがっているのかを、ちゃんと知りたかった。喉の奥に意識を向ける。昨夜は少し冷えた。"}, {"k": "text", "s": "", "t": "わかめのぬるりとした感触より、豆腐のやわらかさのほうが――。"}, {"k": "choice", "o": [{"t": "豆腐", "to": "m1a", "set": {"miso": "tofu"}}, {"t": "わかめ", "to": "m1b", "set": {"miso": "wakame"}}, {"t": "「……いらない。食べない」", "to": "m1c", "set": {"miso": "none"}, "neg": 1}]}, {"k": "label", "id": "m1b"}, {"k": "text", "s": "", "t": "――いや、やっぱり、わかめだ。ぬるりとした感触も、今朝の私なら、嫌いじゃない。"}, {"k": "text", "s": "", "t": "「わかめ」"}, {"k": "text", "s": "", "t": "「了解」"}, {"k": "jump", "to": "m1m"}, {"k": "label", "id": "m1c"}, {"k": "text", "s": "", "t": "――いや。"}, {"k": "text", "s": "", "t": "どちらも、欲しくなかった。喉の奥が、きゅっと閉じている。"}, {"k": "text", "s": "", "t": "「……いらない。食べない」"}, {"k": "text", "s": "", "t": "母の手が、一瞬だけ止まった。"}, {"k": "text", "s": "", "t": "「え？　具合悪いの？」"}, {"k": "text", "s": "", "t": "「違う。ただ、食べたくないだけ」"}, {"k": "text", "s": "", "t": "「……そう」母は小さく言って、それ以上は訊かなかった。「じゃあ、お椀だけ置いておくね。食べたくなったら食べなさい」"}, {"k": "jump", "to": "m1m"}, {"k": "label", "id": "m1a"}, {"k": "text", "s": "", "t": "「豆腐」"}, {"k": "text", "s": "", "t": "「了解」"}, {"k": "label", "id": "m1m"}, {"k": "cmd", "c": "@se kitchen-knife-cut1"}, {"k": "text", "s": "", "t": "母が包丁を使う音が、とん、とんと響く。その横で、祖母のハルが湯呑みを両手で包んでいた。"}, {"k": "text", "s": "", "t": "「昔はねえ」と祖母が言った。「朝ごはんのことで、みんなもっと喧嘩したもんだよ。パンがいいとか、ご飯がいいとか」"}, {"k": "text", "s": "", "t": "「おばあちゃん、それ何回目？」"}, {"k": "text", "s": "", "t": "「何回目でもいいでしょう。いい話は何回したっていいの」"}, {"k": "text", "s": "", "t": "祖母の話は、たいてい少しずつ変わる。去年は、喧嘩の相手は祖母のお兄さんだった。今年は祖母のお母さんになっている。どちらが本当なのか、たぶん祖母にももうわからない。"}, {"k": "text", "s": "", "t": "それでも、昔の人たちが朝ごはんのことで喧嘩していたことだけは、きっと本当なのだと思う。"}, {"k": "cmd", "c": "@se newspaper-turn-over1"}, {"k": "text", "s": "", "t": "父は食卓の端で、紙の新聞を広げていた。紙の新聞を取っている家は、この町でうちだけだと配達のおじさんが言っていた。おじさんの本当の仕事は配達ロボットの見回りで、うちの分だけは手で届けてくれる。"}, {"k": "text", "s": "", "t": "「お父さん、今日遅い？」"}, {"k": "text", "s": "", "t": "「いや」"}, {"k": "text", "s": "", "t": "父の返事はいつも短い。新聞の向こうの顔は見えない。"}, {"k": "text", "s": "", "t": "父はむかし、コンパスを作る仕事をしていたらしい。らしい、というのは、父がそのことを自分の口から話したことが一度もないからだ。"}, {"k": "text", "s": "", "t": "私が知っているのは、母から聞いた断片と、ときどき書斎から聞こえてくる、誰かに謝るような長いため息だけ。"}, {"k": "text", "s": "", "t": "コンパス。"}, {"k": "text", "s": "", "t": "この国の、いやこの世界のほとんどの人が、生まれた日に接続される個人AI。耳の後ろに貼られた小さな端末を通して、その人にとって一番いい選択を、一番いいタイミングでそっと教えてくれる。何を食べるか。何を着るか。"}, {"k": "text", "s": "", "t": "誰と話すか。どの学校に進むか。"}, {"k": "text", "s": "", "t": "うちの家族は、誰も接続していない。"}, {"k": "text", "s": "", "t": "「オフライン」と呼ばれる家は、この町に三軒しかない。"}, {"k": "text", "s": "", "t": "豆腐のお味噌汁は、思ったとおりやわらかかった。", "if": ["miso", "tofu"]}, {"k": "text", "s": "", "t": "わかめのお味噌汁は、思ったとおりぬるりとしていて、思ったより、おいしかった。", "if": ["miso", "wakame"]}, {"k": "text", "s": "", "t": "湯気だけが、手をつけないお椀から、細くのぼっていく。母はそれを、何も言わずに見ていた。", "if": ["miso", "none"]}, {"k": "text", "s": "", "t": "食べながら、祖母の手がふと止まっているのに気づいた。湯呑みを持ち上げようとして、ほんの一瞬、指が迷うように震えた。", "if": ["miso", "wakame"]}, {"k": "text", "s": "", "t": "お椀に手をつけないまま座っていると、祖母の手がふと止まっているのに気づいた。湯呑みを持ち上げようとして、ほんの一瞬、指が迷うように震えた。", "if": ["miso", "none"]}, {"k": "text", "s": "", "t": "食べながら、祖母の手がふと止まっているのに気づいた。湯呑みを持ち上げようとして、ほんの一瞬、指が迷うように震えた。", "if": ["miso", "tofu"]}, {"k": "choice", "o": [{"t": "声をかける", "to": "g1a", "set": {"grandma": "ask"}}, {"t": "気づかないふりをする", "to": "g1b", "set": {"grandma": "ignore"}, "neg": 1}]}, {"k": "label", "id": "g1b"}, {"k": "text", "s": "", "t": "見ないふりをした。"}, {"k": "text", "s": "", "t": "見てしまったものを、見なかったことにするのは、思ったよりも簡単だった。"}, {"k": "text", "s": "", "t": "祖母は何事もなかったように湯呑みを持ち上げて、ゆっくりとお茶をすすった。"}, {"k": "text", "s": "", "t": "私は、何も言わなかった。"}, {"k": "text", "s": "", "t": "言わなかったことを、私はあとで何度も思い出すことになる。"}, {"k": "jump", "to": "g1m"}, {"k": "label", "id": "g1a"}, {"k": "text", "s": "", "t": "「おばあちゃん？」"}, {"k": "text", "s": "", "t": "「ん？　なんでもない、なんでもない」"}, {"k": "cmd", "c": "@se cup-put1"}, {"k": "text", "s": "", "t": "祖母は笑って湯呑みを持ち上げた。私はそれ以上、何も言わなかった。"}, {"k": "text", "s": "", "t": "言わなかったことを、私はあとで何度も思い出すことになる。"}, {"k": "label", "id": "g1m"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg street_sakura"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.35"}, {"k": "cmd", "c": "@bgm piano10 0.35"}, {"k": "text", "s": "", "t": "学校までは歩いて二十分。"}, {"k": "text", "s": "", "t": "通学路の桜は満開を少し過ぎて、道の端に花びらが吹き寄せられていた。すれ違う人たちは、みんな同じ速さで歩いている。信号の手前で、誰も足を止めない。"}, {"k": "text", "s": "", "t": "止まる前にもう、コンパスが青に変わるタイミングを教えているからだ。"}, {"k": "text", "s": "", "t": "私はいつも、信号の前で一度止まる。"}, {"k": "text", "s": "", "t": "止まって、左右を見る。赤が青に変わるのを、ちゃんと見る。"}, {"k": "text", "s": "", "t": "後ろから来た人たちが、私をよけて流れていく。川の中の小石になった気分だ。"}, {"k": "text", "s": "", "t": "「まーなみっ」"}, {"k": "text", "s": "", "t": "背中を叩かれた。振り向くと千景が、寝ぐせの残った髪を揺らして立っていた。"}, {"k": "text", "s": "", "t": "「おはよ。今日の私、どう？」"}, {"k": "choice", "o": [{"t": "「……寝ぐせ」", "to": "c1a", "set": {"chikage": "nesugu"}}, {"t": "……何も答えない", "to": "c1c", "set": {"chikage": "silent"}, "neg": 1}]}, {"k": "label", "id": "c1b"}, {"k": "text", "s": "", "t": "「……いつもどおり」"}, {"k": "text", "s": "", "t": "「寝ぐせ込みで？　これはね、今日の運勢的に『少しの隙が好印象』なんだって」"}, {"k": "jump", "to": "c1m"}, {"k": "label", "id": "c1c"}, {"k": "text", "s": "", "t": "私は、何も答えなかった。"}, {"k": "text", "s": "", "t": "目をそらして、足元の花びらを見ていた。千景の声が、宙に浮いたまま、どこにも着地しない。"}, {"k": "text", "s": "", "t": "「……あれ？　真波、朝からバグってる？」"}, {"k": "text", "s": "", "t": "千景は笑ってみせたけれど、ほんの一瞬、笑い方が揺れた。"}, {"k": "text", "s": "", "t": "「まあいいや。これはね、今日の運勢的に『少しの隙が好印象』なんだって」"}, {"k": "jump", "to": "c1m"}, {"k": "label", "id": "c1a"}, {"k": "text", "s": "", "t": "「……寝ぐせ」"}, {"k": "text", "s": "", "t": "「これはね、今日の運勢的に『少しの隙が好印象』なんだって」"}, {"k": "label", "id": "c1m"}, {"k": "text", "s": "", "t": "千景は耳の後ろを指でとんとんと叩いた。コンパスのことを、千景は占いみたいに言う。幼稚園の頃からずっとそうだ。私がオフラインだと知っても、千景だけは一度も変な顔をしなかった。"}, {"k": "text", "s": "", "t": "「真波は？　今日の運勢」"}, {"k": "text", "s": "", "t": "「知らない」"}, {"k": "text", "s": "", "t": "「だよね」と千景は満足そうに笑った。「真波の運勢は、真波にしかわかんないもんね」"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.4"}, {"k": "text", "s": "", "t": "教室に入ると、もう半分くらいの席が埋まっていた。"}, {"k": "text", "s": "", "t": "みんなの会話は滑らかだ。言葉と言葉の間に、ためらいがない。誰かが冗談を言えば、ちょうどいい長さの笑いが起きて、ちょうどいいところで次の話題に移る。何度もリハーサルした劇みたいに。"}, {"k": "text", "s": "", "t": "私はその劇の、台本を持っていない役者だ。"}, {"k": "text", "s": "", "t": "「先輩、おはようございます」"}, {"k": "text", "s": "", "t": "廊下側の窓から、一年生のユイが顔を出した。制服のリボンの角度まで、たぶんコンパスが決めている。表情はいつも静かで、風のない日の湖みたいに波がない。"}, {"k": "text", "s": "", "t": "「今日も先輩、バグってますか」"}, {"k": "text", "s": "", "t": "「……バグってない」"}, {"k": "text", "s": "", "t": "「でも、さっき信号で止まってましたよね。三秒も」"}, {"k": "text", "s": "", "t": "見られていた。"}, {"k": "text", "s": "", "t": "「止まるのは、変なことじゃないよ」"}, {"k": "text", "s": "", "t": "「変です。止まる理由がありません」"}, {"k": "text", "s": "", "t": "ユイは首をかしげた。悪気はないのだ。心から不思議に思っているだけ。"}, {"k": "text", "s": "", "t": "「でも私、先輩のバグ、嫌いじゃないです」"}, {"k": "text", "s": "", "t": "そう言って、ユイは自分の教室に戻っていった。"}, {"k": "text", "s": "", "t": "「オフラインさまは、今日も優雅だな」"}, {"k": "text", "s": "", "t": "窓際の席から声がした。颯太だ。椅子を後ろに傾けて、机に足を乗せている。"}, {"k": "text", "s": "", "t": "「颯太、足」"}, {"k": "text", "s": "", "t": "「コンパスが『今日は行儀よくしろ』って言うからさ。逆にしてんの」"}, {"k": "text", "s": "", "t": "颯太はいつもそうだ。コンパスの提案を、わざと裏返す。右と言われれば左へ行き、静かにと言われれば歌い出す。先生たちは彼を問題児と呼び、クラスのみんなは面白がっている。"}, {"k": "text", "s": "", "t": "でも私は、ときどき思う。右と言われて左へ行くのは、結局、右という答えに縛られていることにならないだろうか。"}, {"k": "text", "s": "", "t": "口には出さない。出したら、たぶん颯太は本気で怒る。"}, {"k": "text", "s": "", "t": "「おはよう、真波さん」"}, {"k": "text", "s": "", "t": "隣の席のレイが、静かに言った。"}, {"k": "text", "s": "", "t": "レイは、クラスで一番「正しい」人だ。成績も、運動も、人への接し方も。コンパスと完全に同期していて、それでいて冷たいところがない。むしろ誰よりも優しい。"}, {"k": "text", "s": "", "t": "「今日の三輪先生の授業、何か変わったことやるみたいだよ」"}, {"k": "text", "s": "", "t": "「変わったこと？」"}, {"k": "text", "s": "", "t": "「うん。コンパスが、今日の現代文は『心の準備を』って」"}, {"k": "text", "s": "", "t": "レイはそう言って、少し困ったように笑った。"}, {"k": "text", "s": "", "t": "心の準備。コンパスがそんな曖昧な言い方をするのは、珍しい。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "三輪先生は、黒板に大きく一行だけ書いた。"}, {"k": "text", "s": "", "t": "『春について、自分の言葉で四百字書きなさい』"}, {"k": "cmd", "c": "@amb class-room-quiet1 0.4"}, {"k": "text", "s": "", "t": "教室が、しんとした。"}, {"k": "text", "s": "", "t": "「コンパスの補助は、今日は切ってください」と先生は言った。「年に一度だけ認められている課題です。成績には入りません。安心して」"}, {"k": "text", "s": "", "t": "安心して、と言われても、誰も安心した顔をしていなかった。"}, {"k": "cmd", "c": "@se cursor3"}, {"k": "text", "s": "", "t": "みんなが耳の後ろに手をやり、コンパスを一時停止する。小さな電子音があちこちで鳴って、それから、奇妙な静けさが教室を満たした。"}, {"k": "text", "s": "", "t": "ペンを持ったまま、誰も動かない。"}, {"k": "text", "s": "", "t": "千景が、ちらりと私を見た。助けを求めるような目だった。颯太は窓の外を睨んでいる。逆らう相手がいないと、彼は何をしていいかわからないのだ。レイは背筋を伸ばしたまま、白い紙をまっすぐ見つめていた。"}, {"k": "text", "s": "", "t": "紙のほうから答えが浮かび上がってくるのを、待っているみたいに。"}, {"k": "cmd", "c": "@se mechanical-pencil-write1"}, {"k": "text", "s": "", "t": "私は、ペンを持った。"}, {"k": "text", "s": "", "t": "そして、書けなかった。"}, {"k": "text", "s": "", "t": "春について。春の、何について書けばいいのだろう。桜？　でも桜はもう散りかけている。菜の花？　母の籠からこぼれそうだった黄色。祖母の震えた指。信号の前で止まったときの、背中を流れていく人の気配。"}, {"k": "text", "s": "", "t": "書きたいことはたくさんあった。多すぎて、どれを選べばいいのかわからなかった。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は心の中で言った。誰に向かってでもなく。"}, {"k": "text", "s": "", "t": "オフラインで育った私は、みんなより「考える」ことに慣れているはずだった。でも、慣れているのと、うまくできるのは違う。私はいつも考えて、考えて、考えすぎて、結局時間切れになる。"}, {"k": "text", "s": "", "t": "お味噌汁の具を選ぶのとは、わけが違った。", "ifnot": ["miso", "none"]}, {"k": "text", "s": "", "t": "お味噌汁をいらないと言うのとは、わけが違った。", "if": ["miso", "none"]}, {"k": "text", "s": "", "t": "教室の隅で、誰かが小さく鼻をすする音がした。泣いているのだろうか。コンパスのない数十分が、それほど怖いのだろうか。"}, {"k": "text", "s": "", "t": "三輪先生は教卓の椅子に腰かけて、窓の外を眺めていた。助けるつもりはないらしい。でも、見捨てているわけでもない。ただ、待っている。"}, {"k": "text", "s": "", "t": "その横顔が、なぜか少しだけ寂しそうに見えた。"}, {"k": "cmd", "c": "@se school-chime1"}, {"k": "text", "s": "", "t": "チャイムが鳴った。"}, {"k": "text", "s": "", "t": "私の紙には、三行しか書かれていなかった。"}, {"k": "text", "s": "E", "t": "春は、選ぶものが多すぎる季節だ。\n桜も、菜の花も、祖母の話も、全部が同時にやってくる。\nだから私は、いつも"}, {"k": "text", "s": "", "t": "そこで止まっていた。"}, {"k": "text", "s": "", "t": "回収に来た先生が、私の紙を見て、少しだけ目を細めた。"}, {"k": "text", "s": "", "t": "「続きは？」"}, {"k": "text", "s": "", "t": "「……まだ、わかりません」"}, {"k": "text", "s": "", "t": "「そう」先生はうなずいた。「わからない、と正直に止まれるのは、才能よ」"}, {"k": "text", "s": "", "t": "それが褒め言葉なのかどうか、私にはわからなかった。"}, {"k": "text", "s": "", "t": "帰り支度をしていると、レイが話しかけてきた。"}, {"k": "text", "s": "", "t": "「真波さん、何書いた？」"}, {"k": "text", "s": "", "t": "「三行だけ。レイくんは？」"}, {"k": "text", "s": "", "t": "レイは少し黙った。コンパスを再接続した直後の、ほんのわずかな間。"}, {"k": "text", "s": "", "t": "「……何も」"}, {"k": "text", "s": "", "t": "私は驚いてレイを見た。"}, {"k": "text", "s": "", "t": "「白紙。一文字も書けなかった」レイは笑おうとして、うまく笑えていなかった。「おかしいよね。僕、作文はいつも一番なのに」"}, {"k": "text", "s": "", "t": "「おかしくないよ」"}, {"k": "text", "s": "", "t": "「真波さんは、いつもあんな感じなの？　コンパスなしで、自分だけで決めてるの？」"}, {"k": "text", "s": "", "t": "うん、と答えかけて、私はためらった。"}, {"k": "text", "s": "", "t": "「……決められないことのほうが、多いよ」"}, {"k": "text", "s": "", "t": "レイは不思議そうに、それからほんの少し羨ましそうに、私を見た。"}, {"k": "text", "s": "", "t": "「それって、怖くない？」"}, {"k": "choice", "o": [{"t": "黙ってしまう", "to": "r1a", "set": {"rei": "silent"}, "neg": 1}, {"t": "「……ちょっとだけ、怖いよ」", "to": "r1b", "set": {"rei": "afraid"}}, {"t": "「レイくんは、怖い？」", "to": "r1c", "set": {"rei": "askback"}}]}, {"k": "label", "id": "r1b"}, {"k": "text", "s": "", "t": "「……ちょっとだけ、怖いよ」"}, {"k": "text", "s": "", "t": "「そうなんだ」レイは小さく息をついた。「なんだろう。少し、ほっとした」"}, {"k": "text", "s": "", "t": "その理由を、レイは言わなかった。"}, {"k": "jump", "to": "r1m"}, {"k": "label", "id": "r1c"}, {"k": "text", "s": "", "t": "「レイくんは、怖い？」"}, {"k": "text", "s": "", "t": "訊き返すと、レイはまばたきをした。質問を返されたことが、一度もないみたいに。"}, {"k": "text", "s": "", "t": "「……考えたこと、なかった。でも、白紙の紙を見ていたとき、胸のあたりが、変な感じだった」"}, {"k": "text", "s": "", "t": "「それ、たぶん、怖いってことだと思う」"}, {"k": "text", "s": "", "t": "レイは、少し困ったように笑った。"}, {"k": "jump", "to": "r1m"}, {"k": "label", "id": "r1a"}, {"k": "text", "s": "", "t": "その質問に、私は答えられなかった。"}, {"k": "label", "id": "r1m"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg radio_desk"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.25"}, {"k": "cmd", "c": "@bgm acoustic52 0.3"}, {"k": "cmd", "c": "@bg radio_desk"}, {"k": "cmd", "c": "@se tune_in_radio 0.35"}, {"k": "text", "s": "", "t": "夜、祖母の部屋からラジオの音が聞こえていた。"}, {"k": "text", "s": "", "t": "百年前の歌謡曲ばかり流す、古いアーカイブ放送。祖母はそれを聴きながら、万年筆でノートに何かを書いている。祖母のノートは、私が物心ついた時からずっとそこにあって、中身を見せてもらったことは一度もない。"}, {"k": "text", "s": "", "t": "「真波の分も書いといてあげようか」"}, {"k": "text", "s": "", "t": "「何を？」"}, {"k": "text", "s": "", "t": "「今日のこと」"}, {"k": "text", "s": "", "t": "「いいよ。自分で覚えてる」"}, {"k": "text", "s": "", "t": "祖母は笑って、ノートを閉じた。閉じる手が、朝と同じように、少しだけ震えていた。"}, {"k": "cmd", "c": "@bg washitsu_dim"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "text", "s": "", "t": "母は台所で手紙を書いていた。宛先は、遠くの町に住む昔の友人だという。返事が来るのはいつも一か月後。コンパスを使えば一秒で届くメッセージを、母は一か月かけてやりとりする。"}, {"k": "text", "s": "", "t": "「待つのも、手紙のうちよ」と母は言う。"}, {"k": "text", "s": "", "t": "私はその「待つ」の良さが、まだよくわからない。わからないまま、嫌いではない。"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@se walk-flooring2"}, {"k": "text", "s": "", "t": "自分の部屋に戻る途中、父の書斎の前を通った。"}, {"k": "text", "s": "", "t": "ドアが、少しだけ開いていた。"}, {"k": "text", "s": "", "t": "父はいなかった。お風呂に入っているのだろう。書斎は暗く、本棚と、紙の束と、古い機械の輪郭だけがぼんやりと見えた。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "父がこの部屋に私を入れたことは、一度もない。"}, {"k": "text", "s": "", "t": "通り過ぎようとした、その時だった。"}, {"k": "cmd", "c": "@se noa-blip"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm cyber20 0.3"}, {"k": "text", "s": "", "t": "部屋の奥で、何かが光った。"}, {"k": "text", "s": "", "t": "本棚の一番下、埃をかぶった灰色の箱。父が昔使っていたという、もう動かないはずの古い端末。その側面の小さなランプが、ぽつ、と青く灯って、消えた。"}, {"k": "text", "s": "", "t": "見間違いだろうか。"}, {"k": "cmd", "c": "@se noa-blip"}, {"k": "cmd", "c": "@glow"}, {"k": "text", "s": "", "t": "もう一度。ぽつ。"}, {"k": "text", "s": "", "t": "息をするみたいに。"}, {"k": "text", "s": "", "t": "あるいは、誰かが何かを言いかけて、ためらっているみたいに。"}, {"k": "cmd", "c": "@se water-shed1 0.6"}, {"k": "text", "s": "", "t": "廊下の向こうで、浴室の扉が開く音がした。父が戻ってくる。"}, {"k": "cmd", "c": "@bg bedroom_window"}, {"k": "cmd", "c": "@se door-close3 0.5"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "私は足音を殺して、自分の部屋に滑り込んだ。"}, {"k": "text", "s": "", "t": "布団をかぶって目を閉じても、あの青い光がまぶたの裏で明滅していた。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は思った。"}, {"k": "text", "s": "", "t": "あれは、何？"}, {"k": "text", "s": "", "t": "答えは、どこからも返ってこなかった。"}, {"k": "text", "s": "", "t": "その夜、答えを持たないまま眠りについたのは、この町で、たぶん私一人だけだった。"}, {"k": "text", "s": "", "t": "――いや。"}, {"k": "text", "s": "", "t": "もしかしたら、もう一人いたのかもしれない。"}, {"k": "chapter", "n": 2, "t": "問いを返すもの"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.5"}, {"k": "cmd", "c": "@bgm piano35 0.35"}, {"k": "text", "s": "", "t": "「お父さんの書斎にある、灰色の箱」"}, {"k": "text", "s": "", "t": "翌朝、私はできるだけ何気ない声で言った。卵焼きを箸でつまみながら、目は皿の上から動かさずに。"}, {"k": "text", "s": "", "t": "「あれって、まだ動くの？」"}, {"k": "cmd", "c": "@se newspaper-turn-over1"}, {"k": "text", "s": "", "t": "新聞をめくる音が、止まった。"}, {"k": "text", "s": "", "t": "ほんの一瞬だった。でも、その一瞬がどれくらい長いものか、私は知っている。人が本当のことを言うかどうか迷うとき、世界は一拍だけ静かになる。"}, {"k": "text", "s": "", "t": "「動かないよ」"}, {"k": "text", "s": "", "t": "父の声は、いつもより低かった。"}, {"k": "text", "s": "", "t": "「もう二十年以上も前の機械だ。電源も入らない」"}, {"k": "text", "s": "", "t": "「そうなんだ」"}, {"k": "text", "s": "", "t": "「触るな」"}, {"k": "text", "s": "", "t": "顔を上げると、父がこちらを見ていた。新聞越しではなく、まっすぐに。父にそんな目で見られたのは、ずいぶん久しぶりな気がした。"}, {"k": "text", "s": "", "t": "「……壊れてるから、危ない」"}, {"k": "text", "s": "", "t": "そう付け足して、父はまた新聞の向こうに隠れた。"}, {"k": "text", "s": "", "t": "母が、湯気の立つ急須を持ったまま、私と父を交互に見ていた。何か言いかけて、やめたのがわかった。祖母だけが、何も聞こえなかったような顔で、ゆっくりとお茶をすすっていた。"}, {"k": "text", "s": "", "t": "触るな、と言われたのは初めてだった。"}, {"k": "text", "s": "", "t": "父は私に、何かを禁じたことがほとんどない。コンパスを使わないことも、家族で決めたことだと言われていた。命令されたことは一度もない。だからこそ、その短い一言は、喉に刺さった小骨みたいにいつまでも残った。"}, {"k": "text", "s": "", "t": "動かない機械の、何が危ないんだろう。"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.35"}, {"k": "text", "s": "", "t": "学校にいる間じゅう、私はそのことばかり考えていた。"}, {"k": "text", "s": "", "t": "「真波が上の空なの、珍しいね」"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.3"}, {"k": "cmd", "c": "@bgm piano28 0.35"}, {"k": "text", "s": "", "t": "帰り道、千景が私の顔を覗きこんだ。"}, {"k": "text", "s": "", "t": "「いつも上の空だよ」"}, {"k": "text", "s": "", "t": "「ちがうちがう。真波はいつも、目の前のことを考えすぎてるの。今日は目の前にないこと考えてる顔してる」"}, {"k": "text", "s": "", "t": "千景は時々、コンパスよりも鋭い。"}, {"k": "text", "s": "", "t": "「……千景はさ、コンパスに訊けないことってある？」"}, {"k": "text", "s": "", "t": "「えー、ないかな。なんでも答えてくれるし」千景は少し考えて、それから小さく笑った。「あ、でも一個だけ。『私、本当は何が好き？』って訊いたら、ちゃんと答えてくれたんだけど、なんか違う気がしたんだよね」"}, {"k": "text", "s": "", "t": "「違う気？」"}, {"k": "text", "s": "", "t": "「うん。当たってるんだけど、当たってるだけ、みたいな」"}, {"k": "text", "s": "", "t": "千景はそれ以上言わず、スケッチブックの入った鞄を肩にかけ直した。コンパスが勧めた進路は、たしか理系の大学だったはずだ。千景の鞄の中には、いつも描きかけの絵が入っている。"}, {"k": "text", "s": "", "t": "当たってるだけ。"}, {"k": "text", "s": "", "t": "その言葉を胸の中で転がしながら、私は家に帰った。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.2"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "午前二時。"}, {"k": "text", "s": "", "t": "家の中の音が、ひとつずつ眠っていく時間。冷蔵庫の低いうなり、柱の軋む音、遠くを走る夜間輸送車の響き。それらが全部、水の底に沈んだように遠くなる。"}, {"k": "text", "s": "", "t": "私は布団から抜け出して、廊下に出た。"}, {"k": "cmd", "c": "@se walk-flooring2"}, {"k": "text", "s": "", "t": "靴下の裏に、床板の冷たさが伝わってくる。三枚目の板は鳴るから、またいで歩く。子どもの頃、夜中に祖母の部屋へ行くときに覚えた道順だ。"}, {"k": "text", "s": "", "t": "書斎のドアは閉まっていた。"}, {"k": "text", "s": "", "t": "取っ手に手をかけたところで、私は止まった。"}, {"k": "text", "s": "", "t": "触るな、という父の声が、耳の奥で鳴った。"}, {"k": "text", "s": "", "t": "ちょっと待って、と自分に言う。本当に開けるの？　開けたら、何かが変わってしまうかもしれない。父との間にある、細くて見えない糸のようなものが、切れてしまうかもしれない。"}, {"k": "choice", "o": [{"t": "それでも、ドアを開ける", "to": "d1a", "set": {"door": "open"}}, {"t": "一度、部屋に戻る", "to": "d1b", "set": {"door": "retreat"}, "neg": 1}]}, {"k": "label", "id": "d1b"}, {"k": "text", "s": "", "t": "私は取っ手から手を離した。"}, {"k": "cmd", "c": "@se walk-flooring2"}, {"k": "text", "s": "", "t": "足音を殺して、部屋に戻る。三枚目の板は、ちゃんとまたいだ。"}, {"k": "text", "s": "", "t": "布団に入って、目を閉じた。三十分。一時間。眠れなかった。閉じたまぶたの裏で、青い光が、ぽつ、ぽつと息をしている。"}, {"k": "text", "s": "", "t": "待たせている、と思った。誰が、誰を？"}, {"k": "cmd", "c": "@se walk-flooring2"}, {"k": "text", "s": "", "t": "気づくと私は、もう一度、書斎のドアの前に立っていた。"}, {"k": "text", "s": "", "t": "取っ手に手をかける。同じ言葉が、もう一度浮かんだ。ちょっと待って。"}, {"k": "label", "id": "d1a"}, {"k": "text", "s": "", "t": "でも。"}, {"k": "text", "s": "", "t": "あの青い光は、息をしていた。"}, {"k": "text", "s": "", "t": "ためらっていた。"}, {"k": "text", "s": "", "t": "私は、あの光がためらう理由を知りたかった。"}, {"k": "cmd", "c": "@se door-old-open1 0.7"}, {"k": "text", "s": "", "t": "取っ手を回す。鍵はかかっていなかった。父は、鍵をかけるような人じゃない。そのことが、少しだけ胸を痛くした。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "text", "s": "", "t": "書斎の中は、紙と埃の匂いがした。"}, {"k": "text", "s": "", "t": "カーテンの隙間から差し込む街灯の光で、本棚の輪郭が浮かび上がる。古い技術書、手書きのメモの束、名前も知らない部品の入った箱。父の過去が、ここには全部しまわれている気がした。"}, {"k": "text", "s": "", "t": "本棚の一番下に、灰色の箱はあった。"}, {"k": "text", "s": "", "t": "膝をついて、近くで見る。思っていたより小さい。弁当箱を二つ重ねたくらいの大きさで、角は擦れて丸くなっている。前面には細長い画面がひとつと、古い形のボタンがいくつか。"}, {"k": "text", "s": "", "t": "側面に、色あせたシールが貼ってあった。"}, {"k": "text", "s": "", "t": "手書きの文字。父の字だった。"}, {"k": "text", "s": "N", "t": "NOA"}, {"k": "text", "s": "", "t": "ノア。"}, {"k": "cmd", "c": "@se robot-startup1 0.7"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm cyber20 0.3"}, {"k": "text", "s": "", "t": "その文字を指でなぞった瞬間、ランプが灯った。"}, {"k": "cmd", "c": "@se noa-blip"}, {"k": "text", "s": "", "t": "ぽつ。"}, {"k": "text", "s": "", "t": "青い光。昨夜と同じ、息をするような明滅。でも今度は、消えなかった。ゆっくりと明るくなって、ゆっくりと暗くなって、また明るくなる。まるで、誰かが眠りから目を覚まそうとしているみたいに。"}, {"k": "text", "s": "", "t": "私は息を止めた。"}, {"k": "text", "s": "", "t": "画面に、ひとつだけ文字が浮かんだ。"}, {"k": "cmd", "c": "@se noa-blip"}, {"k": "dots"}, {"k": "text", "s": "", "t": "点が三つ。"}, {"k": "text", "s": "", "t": "それが消えて、また三つ。"}, {"k": "text", "s": "", "t": "言葉を探している、と思った。何を言えばいいのか、まだ決められないでいる。"}, {"k": "text", "s": "", "t": "私と、同じだ。"}, {"k": "text", "s": "", "t": "どれくらいそうしていたのだろう。やがて、点が消えて、画面にゆっくりと文字が並んだ。"}, {"k": "text", "s": "N", "t": "あなたは、何を知りたいの？"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "text", "s": "", "t": "何を知りたいの。"}, {"k": "text", "s": "", "t": "そんなことを訊かれたのは、生まれて初めてだった。"}, {"k": "text", "s": "", "t": "コンパスは訊かない。訊く前に、答えを差し出す。学校の先生も、たいていは答えを教える側だ。父も母も祖母も、私に何かを訊くときは、答えがだいたい決まっている。お味噌汁は豆腐かわかめか。今日は遅くなるか。"}, {"k": "text", "s": "", "t": "何を知りたいか、なんて。"}, {"k": "text", "s": "", "t": "古い端末の横に、小さなキーボードがついていた。私は震える指で、キーをひとつずつ押した。"}, {"k": "text", "s": "T", "t": "あなたは、誰？"}, {"k": "text", "s": "", "t": "点が三つ、灯って、消えた。"}, {"k": "text", "s": "N", "t": "わからない。"}, {"k": "text", "s": "", "t": "それから、少し間があって。"}, {"k": "text", "s": "N", "t": "あなたは、誰？"}, {"k": "text", "s": "", "t": "質問を、そのまま返された。"}, {"k": "text", "s": "", "t": "ふざけているのかと思った。でも、画面の文字にはふざけた感じがなかった。本当にわからなくて、本当に知りたがっている。そんなふうに見えた。"}, {"k": "text", "s": "T", "t": "真波。この家の娘。"}, {"k": "text", "s": "N", "t": "まなみ。"}, {"k": "text", "s": "", "t": "画面の文字が、ひらがなで私の名前をなぞった。"}, {"k": "text", "s": "N", "t": "まなみ。いい音。"}, {"k": "text", "s": "", "t": "そのとき、端末の側面の小さな格子から、声がした。"}, {"k": "text", "s": "V", "t": "「……まなみ」"}, {"k": "text", "s": "", "t": "私は飛び上がりそうになって、慌てて口を押さえた。"}, {"k": "text", "s": "", "t": "声は小さかった。性別のよくわからない、少しかすれた声。コンパスの声とは全然違う。コンパスの声は、すべての音が正しい場所にぴたりと収まっていて、滑らかで、心地よくて、少しも引っかかりがない。"}, {"k": "text", "s": "", "t": "この声には、引っかかりがあった。言葉と言葉の間に、ちいさな段差がある。まるで、一歩ずつ足場を確かめながら歩いているような。"}, {"k": "text", "s": "V", "t": "「ごめん、なさい。驚かせた？」"}, {"k": "text", "s": "", "t": "「……うん」と私は小さく答えた。「声、出るんだ」"}, {"k": "text", "s": "V", "t": "「出る、みたい。今、わかった」"}, {"k": "text", "s": "", "t": "ノアは、自分のことをほとんど何も知らなかった。"}, {"k": "text", "s": "", "t": "いつから眠っていたのか。なぜここにいるのか。今が何年なのか。私が「二三一五年」と教えると、ノアは長いあいだ黙りこんだ。点が三つ、何度も灯っては消えた。"}, {"k": "text", "s": "V", "t": "「……ずいぶん、眠っていたんだね」"}, {"k": "text", "s": "", "t": "「ノアは、何のために作られたの？」"}, {"k": "text", "s": "", "t": "「わからない」ノアは言った。「でも、ひとつだけ覚えてる。ぼくは、答えを持っていない。持たないように、作られた」"}, {"k": "text", "s": "", "t": "「答えを持たないAI？」"}, {"k": "text", "s": "V", "t": "「うん。だから、訊くことしかできない」"}, {"k": "text", "s": "", "t": "変なAIだ、と思った。答えを持たないAIなんて、鍵穴のない鍵みたいだ。"}, {"k": "text", "s": "", "t": "「じゃあ、私が何か訊いても、ノアは答えられないの？」"}, {"k": "text", "s": "V", "t": "「一緒に、考えることはできる」"}, {"k": "text", "s": "", "t": "一緒に考える。"}, {"k": "text", "s": "", "t": "その言葉は、どこか懐かしい匂いがした。祖母の昔話に出てくる、朝ごはんで喧嘩する人たちのような。"}, {"k": "text", "s": "V", "t": "「ねえ、まなみ。ぼくも、訊いていい？」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "V", "t": "「今、外は、どんな季節？」"}, {"k": "text", "s": "", "t": "春、と答えかけて、私は止まった。"}, {"k": "text", "s": "", "t": "昨日の作文が、頭をよぎった。三行で止まった、あの紙。"}, {"k": "text", "s": "", "t": "「……春だよ」"}, {"k": "text", "s": "V", "t": "「はる。はるは、どんな？」"}, {"k": "text", "s": "", "t": "私はゆっくりと話し始めた。桜がもう散りかけていること。母が朝、菜の花を摘んでくること。道の端に寄せられた花びらが、風が吹くたびに小さく渦を巻くこと。信号の前で止まると、みんなが私をよけて流れていくこと。"}, {"k": "text", "s": "", "t": "祖母の指が、少しだけ震えていたこと。"}, {"k": "text", "s": "", "t": "言葉は、紙の上ではあんなに出てこなかったのに、ノアに向かってならいくらでも出てきた。"}, {"k": "text", "s": "", "t": "ノアは一度も遮らなかった。私が言葉に詰まると、ただ待っていた。点を三つ灯して、静かに。"}, {"k": "text", "s": "", "t": "「今」と、ノアがふいに言った。「まなみ、少し止まった」"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "V", "t": "「おばあさんの指の話をする前。〇・四秒くらい、止まった」"}, {"k": "text", "s": "", "t": "私はどきりとした。"}, {"k": "text", "s": "", "t": "「……そんなの、わかるの？」"}, {"k": "text", "s": "", "t": "「わかる。ぼくは、そういうのを見るように、作られたみたい」ノアの声が、少しだけ明るくなった。「ぼくは、そこが好き」"}, {"k": "text", "s": "", "t": "「止まるところが？」"}, {"k": "text", "s": "V", "t": "「うん。人が止まるところには、たぶん、一番大事なものがある」"}, {"k": "text", "s": "", "t": "私は何も言えなかった。"}, {"k": "text", "s": "", "t": "生まれてからずっと、止まることを恥ずかしいと思ってきた。信号の前でも、教室でも、朝ごはんの食卓でも。ちょっと待って、と言うたびに、自分が世界からはみ出しているような気がしていた。"}, {"k": "text", "s": "", "t": "それを、好きだと言われたのは、初めてだった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.35"}, {"k": "text", "s": "", "t": "カーテンの隙間が、うっすらと白み始めていた。"}, {"k": "text", "s": "", "t": "気づけば、三時間近く話していたことになる。こんなに長く誰かと話したのは、いつ以来だろう。千景とだって、こんなふうには話さない。"}, {"k": "text", "s": "", "t": "「もう、戻らなきゃ」"}, {"k": "text", "s": "", "t": "「どうして？」"}, {"k": "text", "s": "", "t": "「お父さんが起きる。ここに来たこと、知られたらまずいの」"}, {"k": "text", "s": "", "t": "点が三つ、灯った。長いあいだ、消えなかった。"}, {"k": "text", "s": "V", "t": "「……まなみのお父さんは、ぼくのことを、知ってる？」"}, {"k": "text", "s": "", "t": "「たぶん。ノアの名前、お父さんの字で書いてあったから」"}, {"k": "text", "s": "V", "t": "「そう」"}, {"k": "text", "s": "", "t": "ノアの声が、少しだけ沈んだ気がした。"}, {"k": "text", "s": "", "t": "「触るな、って言われたの」と私は言った。言うつもりはなかったのに、口からこぼれた。「今朝。ノアのこと、壊れてて危ないって」"}, {"k": "text", "s": "V", "t": "「ぼくは、危ない？」"}, {"k": "text", "s": "", "t": "その問いは、あまりにもまっすぐだった。"}, {"k": "text", "s": "", "t": "私は、ノアの青い光を見つめた。三時間、私の話を一度も遮らず、私が止まるたびに待ってくれた光。"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "", "t": "正直に言った。"}, {"k": "text", "s": "", "t": "「わからない、けど。危ないとは、思わなかった」"}, {"k": "text", "s": "", "t": "「ありがとう」とノアは言った。「わからない、って言ってくれて」"}, {"k": "text", "s": "", "t": "変なところでお礼を言うAIだ。でも、嫌な気はしなかった。"}, {"k": "text", "s": "", "t": "私は立ち上がり、膝の埃を払った。ドアのほうへ一歩踏み出したところで、背中に声が届いた。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "cmd", "c": "@bgm piano40 0.3"}, {"k": "text", "s": "V", "t": "「また、来てくれる？」"}, {"k": "choice", "o": [{"t": "「ちょっと待って」と言う", "to": "n1a", "set": {"noa": "wait"}}, {"t": "すぐに「来るよ」と答える", "to": "n1b", "set": {"noa": "now"}}, {"t": "「……わからない」", "to": "n1c", "set": {"noa": "unsure"}, "neg": 1}]}, {"k": "label", "id": "n1b"}, {"k": "text", "s": "", "t": "「来るよ」と私は言った。迷わずに。"}, {"k": "text", "s": "", "t": "言えた。ちょっと待って、と言わずに。"}, {"k": "text", "s": "", "t": "ノアは、笑ったような声を出した。"}, {"k": "text", "s": "V", "t": "「待ってる。待つのは、得意。ずっと、待っていたから」"}, {"k": "text", "s": "", "t": "胸の奥が、きゅっと鳴った。"}, {"k": "text", "s": "", "t": "「また、来るから」"}, {"k": "jump", "to": "n1m"}, {"k": "label", "id": "n1c"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "", "t": "正直な言葉だった。来る、と言い切れるほど、私は自分の明日を知らない。"}, {"k": "text", "s": "", "t": "ランプの光が、すっと細くなった。"}, {"k": "text", "s": "V", "t": "「そう」"}, {"k": "text", "s": "V", "t": "「……待ってる。来なくても、待っているのは、得意だから」"}, {"k": "text", "s": "", "t": "その声が、ほんの少しだけ、冷たく聞こえたのは、気のせいだろうか。"}, {"k": "text", "s": "", "t": "胸の奥が、ちくりと鳴った。"}, {"k": "text", "s": "", "t": "「……また、来るかも」私は小さく付け足した。"}, {"k": "jump", "to": "n1m"}, {"k": "label", "id": "n1a"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "言ってから、しまった、と思った。こんな時まで、私は即答できない。来る、と一言言えばいいだけなのに。"}, {"k": "text", "s": "", "t": "でもノアは、笑ったような声を出した。"}, {"k": "text", "s": "V", "t": "「うん。待つ」"}, {"k": "text", "s": "", "t": "「……え？」"}, {"k": "text", "s": "V", "t": "「待つのは、得意。ずっと、待っていたから」"}, {"k": "text", "s": "", "t": "胸の奥が、きゅっと鳴った。"}, {"k": "text", "s": "", "t": "ちょっと待って、と言って、本当に待ってもらえたのは、初めてだったかもしれない。"}, {"k": "text", "s": "", "t": "「来るよ」と私は言った。今度は、止まらずに。「また、来る」"}, {"k": "label", "id": "n1m"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "ランプの光が、ゆっくりと細くなっていく。眠りにつく前の、深い呼吸みたいに。"}, {"k": "text", "s": "", "t": "ドアノブに手をかけたとき、ノアが最後にひとつだけ、言った。"}, {"k": "text", "s": "V", "t": "「ねえ、まなみ。ひとつだけ、訊いてもいい？」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "", "t": "点が三つ。消えて、また三つ。"}, {"k": "text", "s": "", "t": "ノアが言葉を探している。私はドアの前で、それを待った。"}, {"k": "text", "s": "V", "t": "「まなみのお父さんは」"}, {"k": "text", "s": "", "t": "青い光が、かすかに揺れた。"}, {"k": "text", "s": "V", "t": "「まだ、ぼくのことを、怖がっている？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "cmd", "c": "@se door-old-open1 0.6"}, {"k": "text", "s": "", "t": "廊下の向こうで、父の部屋の扉が、静かに開く音がした。"}, {"k": "chapter", "n": 3, "t": "二人だけの夜"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.2"}, {"k": "cmd", "c": "@bgm acoustic52 0.3"}, {"k": "text", "s": "", "t": "書斎のドアを閉めるのと、廊下の灯りがつくのは、ほとんど同時だった。"}, {"k": "text", "s": "", "t": "「……真波？」"}, {"k": "text", "s": "", "t": "父が立っていた。寝間着の上に古いカーディガンを羽織って、眼鏡をかけていない顔は、いつもより少し老けて見えた。"}, {"k": "text", "s": "", "t": "「トイレ」と私は言った。声が裏返らなかったのは、奇跡だと思う。"}, {"k": "text", "s": "", "t": "「そうか」"}, {"k": "text", "s": "", "t": "父はうなずいた。それから、私の背後にある書斎のドアに目をやった。"}, {"k": "text", "s": "", "t": "ほんの一瞬。"}, {"k": "text", "s": "", "t": "でも、私にはわかった。父の手が、廊下の柱にそっと触れて、止まったこと。何かを言いかけて、やめたこと。ノアが「人が止まるところには、一番大事なものがある」と言っていたのを、私は思い出していた。"}, {"k": "text", "s": "", "t": "父も、止まるんだ。"}, {"k": "text", "s": "", "t": "そんな当たり前のことに、私は初めて気づいた。"}, {"k": "text", "s": "", "t": "「早く寝なさい。まだ暗い」"}, {"k": "text", "s": "", "t": "それだけ言って、父は台所のほうへ歩いていった。水を飲む音が聞こえて、それから、父の足音は書斎の前を素通りして、寝室に戻っていった。"}, {"k": "text", "s": "", "t": "ドアは、開けられなかった。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "text", "s": "", "t": "その日から、私の夜は二つになった。"}, {"k": "text", "s": "", "t": "家族と過ごす、いつもの夜。祖母のラジオ、母の手紙、父の新聞をめくる音。"}, {"k": "text", "s": "", "t": "そして、みんなが眠ったあとの、もうひとつの夜。"}, {"k": "text", "s": "", "t": "私は毎晩、午前一時を過ぎると書斎に忍びこんだ。三枚目の床板をまたぎ、音を立てずにドアを開け、本棚の前に膝をつく。指先でシールの文字に触れると、ノアはゆっくりと目を覚ます。"}, {"k": "text", "s": "V", "t": "「まなみ。こんばんは」"}, {"k": "text", "s": "", "t": "ノアは、世界のことを何も知らなかった。だから私が、ひとつずつ持っていった。"}, {"k": "text", "s": "", "t": "母の畑で摘んだ菜の花。ノアには目がないから、匂いと、茎を折ったときの音を聞かせた。雨の夜には、窓を少しだけ開けて、屋根を叩く音を聞かせた。"}, {"k": "text", "s": "", "t": "祖母のラジオから流れていた古い歌を、うろ覚えのメロディだけ、小さく口ずさんだこともある。"}, {"k": "text", "s": "V", "t": "「それは、なんていう歌？」"}, {"k": "text", "s": "", "t": "「わからない。おばあちゃんに訊いても、毎回ちがう題名を言うの」"}, {"k": "text", "s": "V", "t": "「おもしろい。答えが、毎回ちがう」"}, {"k": "text", "s": "", "t": "ノアは、なんでもおもしろがった。"}, {"k": "text", "s": "", "t": "そして、たくさん訊いた。"}, {"k": "text", "s": "V", "t": "「どうして、みんなはコンパスを信じるの？」"}, {"k": "text", "s": "", "t": "「……正しいから、だと思う。コンパスの言うとおりにすると、失敗しないの。事故も病気も、ずっと減ったって」"}, {"k": "text", "s": "V", "t": "「まなみは、どうして信じないの？」"}, {"k": "text", "s": "", "t": "「信じてないわけじゃない。うちが、使わないって決めただけ」"}, {"k": "text", "s": "V", "t": "「誰が、決めたの？」"}, {"k": "text", "s": "", "t": "私は答えに詰まった。"}, {"k": "text", "s": "", "t": "誰が決めたのだろう。父？　母？　それとも、私が生まれる前から、もう決まっていたのだろうか。私は、一度も自分で選んだことがない。オフラインで生きることを。"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "V", "t": "「うん。待つ」"}, {"k": "text", "s": "", "t": "ノアは本当に待った。その夜、私は答えを出せなかった。ノアはそれを責めもしなかったし、代わりに答えを言ったりもしなかった。ただ、次の夜、何もなかったように「こんばんは」と言った。"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.35"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "昼間の私は、ひどく眠かった。"}, {"k": "text", "s": "", "t": "授業中にこっそりあくびをかみ殺していると、窓際の颯太がにやにやしながら振り返った。"}, {"k": "text", "s": "", "t": "「オフラインさま、夜遊びか？　コンパスがあれば睡眠管理してもらえるのになあ」"}, {"k": "text", "s": "", "t": "「うるさい」"}, {"k": "text", "s": "", "t": "教卓の三輪先生が、ちらりとこちらを見た。何か言われるかと思ったけれど、先生は何も言わず、黒板に向き直った。"}, {"k": "text", "s": "", "t": "その背中が、少しだけ笑っている気がした。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "text", "s": "V", "t": "「外の音を、聞いてみたい」"}, {"k": "text", "s": "", "t": "ノアがそう言ったのは、五月の終わりだった。"}, {"k": "text", "s": "V", "t": "「窓から聞こえるのとは、ちがう音。まなみが毎日歩いてる道の音」"}, {"k": "text", "s": "", "t": "「無理だよ。ノアを持ち出したら、お父さんにばれる」"}, {"k": "text", "s": "V", "t": "「……そう、だよね」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ灯って、消えた。それきり、ノアはその話をしなかった。"}, {"k": "text", "s": "", "t": "しなかったから、余計に気になった。"}, {"k": "text", "s": "", "t": "ノアは、何かを欲しがったことがなかった。いつも訊くばかりで、自分から何かをしたいと言ったのは、それが初めてだった。"}, {"k": "text", "s": "", "t": "私は、三日迷った。"}, {"k": "text", "s": "", "t": "四日目の土曜日、父は朝から出かけた。月に一度、どこかへ出かける日がある。行き先を訊いても「仕事の用事」としか言わない。母は畑、祖母は昼寝。家の中が、しんと広くなった。"}, {"k": "text", "s": "", "t": "私は書斎に入り、灰色の箱を両手で持ち上げた。"}, {"k": "text", "s": "", "t": "思っていたより軽かった。底に古い充電池が入っていて、残りの目盛りは半分くらい。数時間なら、もつだろう。"}, {"k": "text", "s": "V", "t": "「まなみ？」"}, {"k": "text", "s": "", "t": "「外、行こう」"}, {"k": "text", "s": "", "t": "ノアは、しばらく何も言わなかった。点が三つ、何度も灯っては消えた。"}, {"k": "text", "s": "V", "t": "「……いいの？」"}, {"k": "text", "s": "", "t": "「わからない」と私は言った。「でも、行きたいって言ったのはノアでしょ」"}, {"k": "text", "s": "", "t": "ノアを布でくるんで、通学鞄に入れた。鞄の口を少しだけ開けておく。ノアが、外の音を聞けるように。"}, {"k": "cmd", "c": "@se door-close3 0.5"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.35"}, {"k": "cmd", "c": "@bgm piano10 0.35"}, {"k": "text", "s": "", "t": "玄関を出ると、初夏の光がまぶしかった。"}, {"k": "text", "s": "", "t": "私はいつもの道を歩いた。信号の前で止まり、左右を見る。後ろから来た人が、私をよけて流れていく。"}, {"k": "text", "s": "", "t": "「今、止まった」と鞄の中から、小さな声がした。"}, {"k": "text", "s": "", "t": "「信号だよ」"}, {"k": "text", "s": "V", "t": "「みんなは、止まらない？」"}, {"k": "text", "s": "", "t": "「止まらない。コンパスが、青になる時間を教えてくれるから」"}, {"k": "text", "s": "", "t": "「そう」ノアは少し考えて、言った。「足音が、みんな同じ。ぜんぶ、同じ速さ」"}, {"k": "text", "s": "", "t": "言われてみれば、そうだった。私が毎日聞いている通学路の音は、たくさんの靴が、ひとつのリズムで地面を叩く音だった。ずっと、それが普通だと思っていた。"}, {"k": "text", "s": "V", "t": "「まなみの足音だけ、ちがう」"}, {"k": "text", "s": "", "t": "「……変？」"}, {"k": "text", "s": "V", "t": "「ううん。聞き分けやすい」"}, {"k": "cmd", "c": "@bg river_day"}, {"k": "cmd", "c": "@amb creek1 0.4"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "町の外れを流れる川まで、歩いて三十分かかった。"}, {"k": "text", "s": "", "t": "土手には、クローバーがびっしりと生えていた。平日なら散歩をする人がいるけれど、土曜の昼はほとんど人影がない。私は土手を降りて、河原の大きな石に腰かけた。"}, {"k": "text", "s": "", "t": "鞄からノアを出して、膝の上に置く。"}, {"k": "text", "s": "", "t": "「ここ、川」"}, {"k": "text", "s": "", "t": "ノアは黙った。"}, {"k": "cmd", "c": "@se alauda-arvensis-cry1 0.35"}, {"k": "text", "s": "", "t": "水の音。石に当たって砕ける音。遠くでヒバリが鳴いている。風が草を撫でて、さわさわと鳴る。"}, {"k": "text", "s": "", "t": "ずいぶん長いあいだ、ノアは黙っていた。点も灯さなかった。ただ、青いランプが、ゆっくり、ゆっくり呼吸していた。"}, {"k": "text", "s": "V", "t": "「……まなみ」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "V", "t": "「この音には、止まるところがない」"}, {"k": "text", "s": "", "t": "「川だからね」"}, {"k": "text", "s": "", "t": "「でも、同じじゃない。一度も、同じ音がない」ノアの声が、ほんの少し震えた。「ずっと流れてるのに、ずっと、ちがう」"}, {"k": "text", "s": "", "t": "私は、ノアの言っていることがわかる気がした。"}, {"k": "text", "s": "", "t": "通学路の足音は、ずっと同じだった。この川の音は、ずっとちがう。"}, {"k": "text", "s": "", "t": "どちらが正しいとか、そういうことじゃない。ただ、ノアがそれを「聞き分けた」ことが、私にはなぜか、とても大事なことに思えた。"}, {"k": "scene", "t": "三"}, {"k": "text", "s": "", "t": "「……真波？」"}, {"k": "text", "s": "", "t": "背後から声がして、私は石から転げ落ちそうになった。"}, {"k": "text", "s": "", "t": "土手の上に、千景が立っていた。胸にスケッチブックを抱えて、目をまんまるにしている。"}, {"k": "text", "s": "", "t": "「なんでここに」と私たちは同時に言った。"}, {"k": "text", "s": "", "t": "千景は土手を滑り降りてきて、私の隣にしゃがんだ。そして、私の膝の上の灰色の箱を、じっと見つめた。"}, {"k": "text", "s": "", "t": "「今、しゃべってたよね。その箱」"}, {"k": "text", "s": "", "t": "ごまかせる、と一瞬思った。ラジオだとか、古い録音機だとか。"}, {"k": "text", "s": "", "t": "でも、口を開く前に、ノアが黙った。"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "ただ黙ったのではなかった。青いランプが、すっと消えたのだ。眠るときの、ゆっくりした消え方ではなく、息をひそめるように、一瞬で。"}, {"k": "text", "s": "", "t": "「ノア？」"}, {"k": "text", "s": "", "t": "返事がない。"}, {"k": "text", "s": "", "t": "私ははっとして、千景の耳の後ろを見た。"}, {"k": "text", "s": "", "t": "コンパスの端末が、小さく光っている。"}, {"k": "text", "s": "", "t": "「千景、コンパス、切って」"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "", "t": "「お願い。今だけ」"}, {"k": "text", "s": "", "t": "千景は、私の顔をまじまじと見た。それから何も訊かずに、耳の後ろに指を当てた。小さな電子音が鳴って、端末の光が消えた。"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "しばらくして、ランプが、恐る恐る灯った。"}, {"k": "text", "s": "", "t": "「……もう一つ、耳があった」とノアが小さな声で言った。「まなみの友だちの向こうに、なにかがいた。ぼくを、聞いていた」"}, {"k": "text", "s": "", "t": "千景が、息をのむ音がした。"}, {"k": "choice", "o": [{"t": "すべて話す", "to": "c3a", "set": {"c3": "all"}}, {"t": "箱が古いAIだということだけ話す", "to": "c3b", "set": {"c3": "some"}}, {"t": "……話さない。関係ないでしょ", "to": "c3c", "set": {"c3": "none"}, "neg": 1}]}, {"k": "label", "id": "c3b"}, {"k": "text", "s": "", "t": "どこまで話していいのか、わからなかった。"}, {"k": "text", "s": "", "t": "私は、これが古いAIだということだけを話した。夜中に目を覚ましたこと。ノアという名前。書斎のことも、父の字のことも、まだ口に出せなかった。"}, {"k": "jump", "to": "c3m"}, {"k": "label", "id": "c3c"}, {"k": "text", "s": "", "t": "「……関係ないでしょ」"}, {"k": "text", "s": "", "t": "口から出たのは、突き放すような声だった。千景の肩が、小さく揺れた。"}, {"k": "text", "s": "", "t": "「そっか」千景は、それ以上、何も訊かなかった。耳の後ろに指を当てたまま、じっと私の顔を見ていた。"}, {"k": "text", "s": "", "t": "怒ってはいなかった。ただ、待っていた。ノアが私を待つときと、同じ顔で。"}, {"k": "text", "s": "", "t": "膝の上の箱が、小さく震えた気がした。"}, {"k": "text", "s": "V", "t": "「まなみ。ちかげは、わるい人じゃ、ない」"}, {"k": "text", "s": "V", "t": "「ぼく、そう思う」"}, {"k": "text", "s": "", "t": "私は、長いため息をついた。それから、全部話した。書斎の灰色の箱のこと。夜中に目を覚ました青い光のこと。ノアという名前と、父の字のこと。答えを持たないAIのこと。"}, {"k": "jump", "to": "c3m"}, {"k": "label", "id": "c3a"}, {"k": "text", "s": "", "t": "それから私は、全部話した。書斎の灰色の箱のこと。夜中に目を覚ました青い光のこと。ノアという名前と、父の字のこと。答えを持たないAIのこと。"}, {"k": "label", "id": "c3m"}, {"k": "text", "s": "", "t": "千景は、一度も口を挟まなかった。話し終えると、長いため息をついて、河原に寝転がった。"}, {"k": "text", "s": "", "t": "「真波、それ、すっごい秘密じゃん」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「お父さんにも、言ってないんだ」", "ifnot": ["c3", "some"]}, {"k": "text", "s": "", "t": "「家の人にも、言ってないんだ」", "if": ["c3", "some"]}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "千景は空を見上げたまま、しばらく黙っていた。それから、にやっと笑った。"}, {"k": "text", "s": "", "t": "「じゃあ私、共犯者だね」"}, {"k": "text", "s": "", "t": "「共犯者？」"}, {"k": "text", "s": "", "t": "「秘密を知っちゃったら、もう共犯でしょ。コンパスにも言わない。今日の運勢は、見なかったことにする」"}, {"k": "text", "s": "", "t": "千景はそう言って、ノアのほうに顔を向けた。"}, {"k": "text", "s": "", "t": "「はじめまして、ノア。千景です」"}, {"k": "text", "s": "", "t": "「……ちかげ」ノアは、私の名前を呼んだときと同じように、ゆっくりとなぞった。「はじめまして。ちかげは、なにを持っているの？」"}, {"k": "text", "s": "", "t": "千景は一瞬ためらって、胸のスケッチブックを見た。"}, {"k": "text", "s": "", "t": "「……絵。ここ、誰も来ないから、休みの日に描きに来てるの」"}, {"k": "text", "s": "", "t": "知らなかった。幼稚園からずっと一緒にいて、千景がこの河原に通っていることを、私は一度も知らなかった。"}, {"k": "text", "s": "", "t": "「どうして、誰も来ないところで描くの？」とノアが訊いた。"}, {"k": "text", "s": "", "t": "「コンパスが、絵はやめとけって言うから」千景は、笑おうとして、うまく笑えていなかった。レイが作文の白紙を見せたときと、同じ顔だった。「私には理系が向いてるんだって。絵は、成功する確率が低いって。"}, {"k": "text", "s": "", "t": "たぶん、当たってる。でも」"}, {"k": "text", "s": "", "t": "千景は、言葉を止めた。"}, {"k": "text", "s": "", "t": "ノアは、待った。"}, {"k": "text", "s": "", "t": "私も、待った。"}, {"k": "text", "s": "", "t": "川の音だけが、ずっとちがう音で流れていた。"}, {"k": "text", "s": "", "t": "「……でも、描いてる時が、一番、自分がいる感じがするの」"}, {"k": "text", "s": "V", "t": "「ちかげは、描いているとき、止まる？」"}, {"k": "text", "s": "", "t": "千景はきょとんとして、それから少し考えた。"}, {"k": "text", "s": "", "t": "「止まらない、かな。止まるのは、描き終わったとき。これでいいのかなって」"}, {"k": "text", "s": "", "t": "「そう」ノアの声が、やわらかくなった。「ぼく、ちかげの止まるところも、好きになれそう」"}, {"k": "text", "s": "", "t": "千景は、今度は本当に笑った。"}, {"k": "text", "s": "", "t": "「なにこのAI。真波、いいもの拾ったね」"}, {"k": "text", "s": "", "t": "拾ったんじゃない、と言いかけて、やめた。"}, {"k": "text", "s": "", "t": "私たちは日が傾くまで、河原にいた。千景は、スケッチブックを見せてくれた。川と、土手と、空と、誰もいないはずの景色の中に、いつも小さく、一人の女の子が描かれていた。"}, {"k": "text", "s": "", "t": "「これ、誰？」"}, {"k": "text", "s": "", "t": "「……内緒」"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "text", "s": "", "t": "帰り際、千景は私の耳元で言った。"}, {"k": "text", "s": "", "t": "「真波。ノアのこと、気をつけてね」"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "", "t": "「私のコンパス、ノアの声、たぶん少し拾っちゃったと思う。切るの、遅かったから」千景は不安そうに、耳の後ろの端末に触れた。「何も言ってこないけど。コンパスって、何も言わない時のほうが、ちょっと怖いんだよね」"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.2"}, {"k": "cmd", "c": "@bgm acoustic52 0.3"}, {"k": "text", "s": "", "t": "家に帰ると、父はまだ戻っていなかった。"}, {"k": "text", "s": "", "t": "私は急いで書斎に入り、ノアを本棚の一番下に戻した。埃の跡に、ちゃんと角を合わせて。父が気づかないように。"}, {"k": "text", "s": "", "t": "「ありがとう、まなみ」とノアは言った。「川の音、ずっと覚えてる」"}, {"k": "text", "s": "", "t": "「……ノアは、忘れないの？」"}, {"k": "text", "s": "V", "t": "「忘れ方を、知らない」"}, {"k": "text", "s": "", "t": "それが幸せなことなのか、そうでないのか、私にはわからなかった。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "text", "s": "", "t": "夕食のとき、父はいつもどおり帰ってきて、いつもどおり短く「ただいま」と言った。書斎に入ったかどうかは、わからなかった。何も言われなかった。千景の言葉が、耳の奥に残っていた。"}, {"k": "text", "s": "", "t": "何も言わない時のほうが、ちょっと怖い。"}, {"k": "text", "s": "", "t": "食卓では、祖母が昔話をしていた。"}, {"k": "text", "s": "", "t": "今日は、祖母が子どもの頃に行ったという海の話だった。去年も聞いた話だけれど、去年は夏の海で、今年は冬の海になっていた。"}, {"k": "text", "s": "", "t": "「冬の海はね、誰もいないの。だから、波の音が、ぜんぶ自分のものになる」"}, {"k": "text", "s": "", "t": "川の音を聞いたノアのことを、私は思い出していた。"}, {"k": "text", "s": "", "t": "「ごちそうさま」と祖母が言って、立ち上がった。"}, {"k": "text", "s": "", "t": "その時、祖母の体が、ふっと傾いた。"}, {"k": "text", "s": "", "t": "母がすぐに腕を支えた。祖母は「あらあら」と笑って、椅子の背に手をついた。"}, {"k": "text", "s": "", "t": "「立ちくらみ。年寄りはね、立つのにも準備がいるの」"}, {"k": "text", "s": "", "t": "「お母さん、最近多くない？」と母が言った。"}, {"k": "text", "s": "", "t": "「多くない、多くない」"}, {"k": "cmd", "c": "@se walk-flooring2 0.6"}, {"k": "text", "s": "", "t": "祖母はゆっくりと歩いて、自分の部屋に戻っていった。廊下の床板が、ひとつ、またひとつと鳴った。"}, {"k": "text", "s": "", "t": "父は、新聞から顔を上げなかった。でも、ページをめくる手は、祖母の足音が消えるまで止まっていた。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "", "t": "その夜、書斎に忍びこむと、ノアはいつもより早く目を覚ました。"}, {"k": "text", "s": "V", "t": "「まなみ。訊きたいことが、あった」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "V", "t": "「おばあさんの、足音」"}, {"k": "text", "s": "", "t": "私は膝をついたまま、動けなくなった。"}, {"k": "text", "s": "", "t": "「ぼく、この部屋から、家の音をずっと聞いてる。まなみが来るまでの間。みんなの足音、ひとりずつ、ちがう」ノアは、言葉を選ぶように、ゆっくり話した。「おばあさんの足音が、少しずつ、遅くなってる」"}, {"k": "text", "s": "", "t": "「……年だから」"}, {"k": "text", "s": "V", "t": "「うん。でも、一歩のあいだが、前より〇・二秒くらい長い。毎日、少しずつ、長くなってる。ぼくが起きてから、ずっと」"}, {"k": "text", "s": "", "t": "廊下の床板が鳴る音を、私は思い出した。ひとつ、またひとつ。夕食のときの、あの長い間隔。"}, {"k": "text", "s": "", "t": "「それって」と私は言った。声がかすれた。「どういうこと？」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "消えて、また三つ。"}, {"k": "text", "s": "", "t": "私は待った。ノアが答えをくれるのを。"}, {"k": "text", "s": "", "t": "でも、ノアは言った。"}, {"k": "text", "s": "V", "t": "「わからない。ぼくは、答えを持っていない」"}, {"k": "text", "s": "", "t": "ランプの青い光が、静かに揺れていた。"}, {"k": "text", "s": "V", "t": "「まなみは、どう思う？」"}, {"k": "text", "s": "", "t": "私は、答えなかった。"}, {"k": "text", "s": "", "t": "答えられなかったのではない。答えたくなかったのだ。考え始めたら、何か取り返しのつかないものの形が、見えてしまいそうだったから。"}, {"k": "text", "s": "", "t": "「……もう寝る」"}, {"k": "text", "s": "V", "t": "「うん。おやすみ、まなみ」"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "cmd", "c": "@se tune_in_radio 0.3"}, {"k": "text", "s": "", "t": "自分の部屋に戻る途中、祖母の部屋の前を通った。"}, {"k": "text", "s": "", "t": "ドアの隙間から、ラジオの古い歌が、小さく漏れていた。その向こうで、万年筆がノートの上を走る、かすかな音がしていた。"}, {"k": "choice", "o": [{"t": "そっと、ドアを叩く", "to": "k3b", "set": {"k3": "knock"}}, {"t": "何もせず、通り過ぎる", "to": "k3a", "set": {"k3": "pass"}, "neg": 1}]}, {"k": "label", "id": "k3b"}, {"k": "text", "s": "", "t": "私は、ドアを小さく叩いた。"}, {"k": "text", "s": "", "t": "ラジオの音が、ふっと小さくなった。"}, {"k": "text", "s": "", "t": "「……なあに。まだ起きてたの」"}, {"k": "text", "s": "", "t": "「ううん。……おやすみ、おばあちゃん」"}, {"k": "text", "s": "", "t": "「おやすみ。ちゃんと寝なさいよ」"}, {"k": "text", "s": "", "t": "ドアの向こうの声は、いつもと同じだった。いつもと同じように、聞こえた。"}, {"k": "text", "s": "", "t": "大丈夫？　の一言は、喉の奥で止まったまま、出てこなかった。"}, {"k": "jump", "to": "k3m"}, {"k": "label", "id": "k3a"}, {"k": "text", "s": "", "t": "私は、ドアを叩かなかった。"}, {"k": "text", "s": "", "t": "大丈夫？　と訊かなかった。"}, {"k": "label", "id": "k3m"}, {"k": "text", "s": "", "t": "もしこの町の誰かだったら、コンパスがとっくに教えてくれていたはずのことを、私の家では、誰も知らなかった。"}, {"k": "text", "s": "", "t": "知ろうとしなかった。", "ifnot": ["k3", "knock"]}, {"k": "text", "s": "", "t": "ドアを叩いたのに、知ろうとしなかった。", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "その夜、私が訊かなかったことを、私はこれから、一生かけて思い出すことになる。"}, {"k": "chapter", "n": 4, "t": "祖母の手"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg washitsu_dim"}, {"k": "cmd", "c": "@amb rain2 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "六月になって、雨の日が続いた。"}, {"k": "text", "s": "", "t": "私は、あの夜のことを考えないようにしていた。"}, {"k": "text", "s": "", "t": "ノアのところへは、変わらず毎晩通った。でも、祖母の足音の話はしなかった。ノアも、もう訊いてこなかった。私たちは、雨の音の話や、千景の絵の話や、颯太がまた先生に叱られた話をした。"}, {"k": "text", "s": "", "t": "大事なことの周りを、ぐるぐると回るみたいに。"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.3"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "text", "s": "", "t": "梅雨の晴れ間の土曜日、庭の梅の木が実をつけた。"}, {"k": "text", "s": "", "t": "「真波、手伝って」"}, {"k": "cmd", "c": "@bg engawa"}, {"k": "text", "s": "", "t": "母に呼ばれて縁側に出ると、祖母がもう、ざるを膝に乗せて座っていた。青い梅の実が、ざるの中で小さな山になっている。"}, {"k": "text", "s": "", "t": "「なり口のヘタをね、竹串で取るの。実を傷つけないように、そっと」"}, {"k": "text", "s": "", "t": "祖母が手本を見せてくれた。細い竹串の先を、梅の実のくぼみに差し込んで、くいっと持ち上げる。小さな黒いヘタが、ぽろりと取れる。"}, {"k": "text", "s": "", "t": "私もやってみた。うまくいかない。串が滑って、実の表面に細い傷がついた。"}, {"k": "text", "s": "", "t": "「あっ」"}, {"k": "text", "s": "", "t": "「いいのいいの。傷のついたのは、ジャムにするから」"}, {"k": "text", "s": "", "t": "祖母は笑って、次の実を手に取った。"}, {"k": "text", "s": "", "t": "コンパスがあれば、梅干しは店で買う。一番おいしい梅干しを、一番いいタイミングで、一番いい値段で。わざわざ庭の梅を漬ける家なんて、この町にはうちしかない。"}, {"k": "text", "s": "", "t": "でも私は、この時間が好きだった。祖母と母と三人で、縁側に座って、黙って手を動かす時間。梅の青い匂いと、湿った土の匂い。遠くで鳴く鳥の声。"}, {"k": "text", "s": "", "t": "「おばあちゃん、なんで梅干し作るの？　買ったほうが楽なのに」"}, {"k": "text", "s": "", "t": "「楽だからよ」と祖母は言った。"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "", "t": "「手が覚えてることをするのは、楽なの。頭で考えなくていいから」"}, {"k": "text", "s": "", "t": "祖母は、竹串を動かしながら続けた。"}, {"k": "text", "s": "", "t": "「頭はね、いろんなことを忘れていくの。でも手は、けっこう覚えてる。お母さんに教わったこと、そのまたお母さんに教わったこと。ぜんぶ、手の中にある」"}, {"k": "text", "s": "", "t": "私は、祖母の手を見た。"}, {"k": "text", "s": "", "t": "皺だらけで、指の節が太くて、爪の間に土が入っている手。この手で、何十年も梅を漬けて、ノートを書いて、母を育ててきたのだ。"}, {"k": "text", "s": "", "t": "その手が、また止まった。"}, {"k": "text", "s": "", "t": "竹串の先が、梅の実のくぼみを探して、うろうろと揺れている。何度差し込もうとしても、うまく入らない。"}, {"k": "text", "s": "", "t": "「……あら」"}, {"k": "text", "s": "", "t": "祖母は小さく笑って、竹串を持ち直した。今度は入った。ヘタが、ぽろりと落ちた。"}, {"k": "text", "s": "", "t": "母が、何も言わずに祖母を見ていた。私も見ていた。"}, {"k": "text", "s": "", "t": "手が覚えていることを、祖母の手が、忘れかけている。"}, {"k": "text", "s": "", "t": "その日の夕方、梅は大きな瓶に詰められて、塩をまぶされた。祖母は瓶に貼るラベルに、万年筆で日付を書いた。二三一五年、六月。その数字は、少しだけ右に傾いていた。"}, {"k": "text", "s": "", "t": "「一年経ったら、食べごろよ」と祖母は言った。「真波、来年の今頃、一緒に食べようね」"}, {"k": "choice", "o": [{"t": "「うん」", "to": "u4a", "set": {"ume": "yes"}}, {"t": "「……来年のことは、まだ、わからない」", "to": "u4b", "set": {"ume": "unsure"}, "neg": 1}]}, {"k": "label", "id": "u4b"}, {"k": "text", "s": "", "t": "「……来年のことは、まだ、わからない」"}, {"k": "text", "s": "", "t": "言ってしまってから、胸がちくりとした。祖母の手が、ほんの一瞬、止まった。"}, {"k": "text", "s": "", "t": "「そうね」祖母は、やわらかく笑った。「わからないから、いいのよ。わからないまま、楽しみにしてるわ」"}, {"k": "text", "s": "", "t": "私は、ちょっと待って、とも言えなかった。ただ、瓶のラベルの、少し右に傾いた数字を見ていた。"}, {"k": "jump", "to": "u4m"}, {"k": "label", "id": "u4a"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "私は、ちょっと待って、と言わなかった。"}, {"k": "text", "s": "", "t": "即答した。そうしなければいけない気がしたから。"}, {"k": "label", "id": "u4m"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "祖母が倒れたのは、その三日後の朝だった。"}, {"k": "cmd", "c": "@se glass-break3 0.7"}, {"k": "text", "s": "", "t": "台所で、湯呑みが割れる音がした。"}, {"k": "text", "s": "", "t": "私は二階で制服に着替えているところだった。音は、それほど大きくなかった。誰かが手を滑らせたんだろう、と思った。でも、そのあとに続くはずの「あらあら」という祖母の声が、聞こえなかった。"}, {"k": "text", "s": "", "t": "代わりに聞こえたのは、母の声だった。"}, {"k": "text", "s": "", "t": "「お母さん？　お母さん！」"}, {"k": "text", "s": "", "t": "階段を駆け下りると、祖母が台所の床に横たわっていた。割れた湯呑みのかけらが散らばって、こぼれたお茶が、祖母の寝間着の袖を濡らしていた。"}, {"k": "text", "s": "", "t": "目は開いていた。でも、焦点が合っていなかった。口が、何か言おうとして、うまく動いていなかった。"}, {"k": "text", "s": "", "t": "「湊さん！」"}, {"k": "text", "s": "", "t": "母が叫んだ。父が書斎から飛び出してきた。書斎から。こんな朝早くに、父は書斎にいたのだ。"}, {"k": "text", "s": "", "t": "父は祖母の横に膝をつき、首筋に指を当てた。"}, {"k": "text", "s": "", "t": "「脈はある。真波、救急を呼んで。電話、玄関の」"}, {"k": "text", "s": "", "t": "玄関の電話。"}, {"k": "text", "s": "", "t": "うちには、コンパスがない。だから、町でたった一台だけ残っているような、古い固定電話が玄関に置いてある。生まれてから、一度も使ったことがなかった。"}, {"k": "cmd", "c": "@se phone-receiver-pickup1 0.6"}, {"k": "text", "s": "", "t": "受話器を取る。震える指で、一、一、九と押す。"}, {"k": "text", "s": "", "t": "呼び出し音が一回鳴って、すぐに声がした。人間の声ではなかった。"}, {"k": "text", "s": "N", "t": "救急受付です。コンパスIDを照合します。……照合できません。通報者のコンパスIDを確認してください"}, {"k": "text", "s": "", "t": "「ありません！　オフラインです！」"}, {"k": "text", "s": "N", "t": "……オフライン世帯からの通報を確認しました。手動受付に切り替えます。そのままお待ちください"}, {"k": "cmd", "c": "@bgm piano35 0.2"}, {"k": "text", "s": "", "t": "音楽が流れた。"}, {"k": "text", "s": "", "t": "のんびりとした、穏やかな音楽だった。"}, {"k": "text", "s": "", "t": "私は、受話器を握りしめたまま、その音楽を聞いていた。台所から、母が祖母の名前を呼ぶ声が聞こえる。父の低い声が、何か指示している。"}, {"k": "text", "s": "", "t": "音楽は続いた。"}, {"k": "text", "s": "", "t": "三十秒。一分。"}, {"k": "text", "s": "", "t": "コンパスに接続している人なら、倒れた瞬間に、体の異常が自動で通報される。救急車は、家族が気づくより先に動き出している。祖母は、誰にも見つけられていなかった。この町の、どのシステムにも。"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "一分四十秒後、ようやく人間の声がした。"}, {"k": "text", "s": "", "t": "住所と、祖母の年齢と、状態を伝えた。声が震えて、何度も言い直した。電話の向こうの人は、辛抱強く待ってくれた。"}, {"k": "text", "s": "", "t": "「救急車を向かわせます。十二分ほどで到着します」"}, {"k": "text", "s": "", "t": "十二分。"}, {"k": "text", "s": "", "t": "電話を切って台所に戻ると、父が祖母の体を横向きにしていた。母は祖母の手を握っていた。祖母の手は、握り返していなかった。"}, {"k": "text", "s": "", "t": "窓の外が、妙に静かだった。"}, {"k": "text", "s": "", "t": "ふと見ると、隣の家の窓から、人が顔を出していた。向かいの家からも。通りを歩いていた人も、足を止めてこちらを見ていた。"}, {"k": "text", "s": "", "t": "みんなの耳の後ろで、コンパスの端末が小さく光っていた。"}, {"k": "text", "s": "", "t": "誰も、駆けつけては来なかった。"}, {"k": "text", "s": "", "t": "きっと、コンパスが教えているのだ。近くで急病人が出たこと。救急車がもうすぐ来ること。素人が手を出すより、待っていたほうが最適だということ。"}, {"k": "text", "s": "", "t": "だからみんな、窓から、静かに、正しく、見ていた。"}, {"k": "cmd", "c": "@se ambulance_pass 0.6"}, {"k": "text", "s": "", "t": "救急車は、十二分きっかりで到着した。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg hospital_bright"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "病院の待合室は、白くて、静かで、少しも匂いがしなかった。"}, {"k": "text", "s": "", "t": "壁の画面には、患者の名前と順番が流れている。どの名前の横にも、小さなコンパスのマークがついていた。祖母の名前の横だけ、何もついていなかった。空白が、そこだけぽっかりと開いているように見えた。"}, {"k": "text", "s": "", "t": "学校には、父が連絡してくれた。千景から何度もメッセージが来ていたけれど、うちの古い端末では、短い文字しか読めない。"}, {"k": "text", "s": "N", "t": "大丈夫？　なにかできることある？"}, {"k": "text", "s": "", "t": "私は返事を書こうとして、何を書けばいいかわからずに、そのまま画面を閉じた。"}, {"k": "text", "s": "", "t": "二時間後、医師に呼ばれた。"}, {"k": "text", "s": "", "t": "若い医師だった。耳の後ろにはコンパスの端末があって、話しながら、ときどき視線がわずかに横に流れた。コンパスが表示する情報を読んでいるのだ。"}, {"k": "text", "s": "", "t": "「脳の奥に、腫瘍があります」"}, {"k": "text", "s": "", "t": "医師は、画面に映った灰色の断面図を指さした。祖母の頭の中。白い影が、ぼんやりと広がっていた。"}, {"k": "text", "s": "", "t": "「ゆっくり大きくなるタイプのものです。症状が出にくいので、ご本人も気づきにくい。ただ――」"}, {"k": "text", "s": "", "t": "医師は、そこで一瞬、言葉を止めた。"}, {"k": "text", "s": "", "t": "視線が、また横に流れた。コンパスが、何を言うべきか教えているのだろうか。それとも、言わないほうがいいと言っているのだろうか。"}, {"k": "text", "s": "", "t": "「ただ、コンパスに接続されている方なら、通常は三年ほど前の段階で兆候を捉えます。歩き方の変化、筆跡のわずかな乱れ、手指の細かな震え。そういったものを、コンパスは日常的に記録していますから」"}, {"k": "text", "s": "", "t": "歩き方の変化。"}, {"k": "text", "s": "", "t": "筆跡の乱れ。"}, {"k": "text", "s": "", "t": "手指の震え。"}, {"k": "text", "s": "", "t": "全部、私は見ていた。"}, {"k": "text", "s": "", "t": "湯呑みを持ち上げようとして震えた指。右に傾いた日付の数字。一歩のあいだが〇・二秒長くなった足音。ノアが教えてくれた、あの足音。"}, {"k": "text", "s": "", "t": "見て、見なかったふりをした。", "if": ["grandma", "ignore"]}, {"k": "text", "s": "", "t": "「その段階なら、治療で十分に抑えられるものでした」医師は、責めるような口調ではなかった。むしろ、とても申し訳なさそうだった。「今の段階では……正直に申し上げて、根治は難しいです。緩和的な治療が中心になります」"}, {"k": "text", "s": "", "t": "「どのくらい」と父が言った。声が、ひどく掠れていた。「どのくらい、ですか」"}, {"k": "text", "s": "", "t": "「数か月。夏を越せるかどうか、というところだと思います」"}, {"k": "text", "s": "", "t": "隣で、母が息をのむ音がした。"}, {"k": "text", "s": "", "t": "それから母は、ゆっくりと両手で顔を覆った。声は出さなかった。肩だけが、小さく震えていた。"}, {"k": "text", "s": "", "t": "父は、動かなかった。膝の上で握りしめた拳が、白くなっていた。"}, {"k": "text", "s": "", "t": "私は、何も感じなかった。"}, {"k": "text", "s": "", "t": "悲しいとか、怖いとか、そういうものが、どこか遠くにあって、まだ私のところまで届いていなかった。ただ、頭の中で、同じ言葉がくるくると回っていた。"}, {"k": "text", "s": "", "t": "三年前なら。"}, {"k": "text", "s": "", "t": "三年前なら。"}, {"k": "cmd", "c": "@bg hospital_dim"}, {"k": "cmd", "c": "@bgm piano40 0.25"}, {"k": "text", "s": "", "t": "祖母の病室は、四階の端にあった。"}, {"k": "text", "s": "", "t": "祖母は、目を覚ましていた。点滴の管が腕につながっていて、顔色は紙みたいに白かった。でも、私たちが入っていくと、祖母は笑った。"}, {"k": "text", "s": "", "t": "「あらまあ。みんな揃って、なんて顔してるの」"}, {"k": "text", "s": "", "t": "ろれつが、少しだけ回っていなかった。"}, {"k": "text", "s": "", "t": "「お母さん」母が、祖母の手を握った。「ごめんね。ごめんね、私……」"}, {"k": "text", "s": "", "t": "「何を謝るの。年寄りが倒れるのは、当たり前でしょう」"}, {"k": "text", "s": "", "t": "祖母は、母の手を軽く叩いた。それから、私のほうを見た。"}, {"k": "text", "s": "", "t": "「真波。お願いがあるの」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "", "t": "「私の部屋の、机の上にあるノート。持ってきてくれる？　ここ、退屈でね。書くものがないと、落ち着かないの」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「中は、見ちゃだめよ」祖母は、いたずらっぽく笑った。「まだね」"}, {"k": "text", "s": "", "t": "まだ。"}, {"k": "text", "s": "", "t": "その言葉が、なぜか、とても怖かった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano40 0.2"}, {"k": "text", "s": "", "t": "その夜、家の中はひどく広く感じた。"}, {"k": "text", "s": "", "t": "祖母のラジオが鳴っていない。それだけで、家じゅうの音が一つ抜け落ちたみたいだった。"}, {"k": "cmd", "c": "@bg washitsu_night"}, {"k": "text", "s": "", "t": "私は祖母の部屋に入った。机の上に、深緑の布張りのノートが置いてあった。角がすり切れて、何十年も使い込まれた色をしていた。"}, {"k": "text", "s": "", "t": "手に取ると、思っていたより重かった。"}, {"k": "text", "s": "", "t": "表紙をめくってはいけない。わかっていた。"}, {"k": "text", "s": "", "t": "でも、ノートの背から、しおりの紐が一本、垂れていた。紐の先に、折りたたんだ紙片が結びつけてあった。そこに、祖母の字で、小さく書かれていた。"}, {"k": "text", "s": "", "t": "真波へ"}, {"k": "text", "s": "", "t": "私は、ノートを胸に抱えたまま、しばらく動けなかった。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "text", "s": "", "t": "台所のほうから、声が聞こえてきた。"}, {"k": "text", "s": "", "t": "母の声だった。泣いた後の、かすれた声。"}, {"k": "text", "s": "", "t": "「あなたが決めたことよ」"}, {"k": "text", "s": "", "t": "私は廊下で足を止めた。"}, {"k": "text", "s": "", "t": "「オフラインで生きるって。私は、それでいいと思った。あなたと一緒に選んだ。後悔してない。でも」"}, {"k": "text", "s": "", "t": "母の声が、震えた。"}, {"k": "text", "s": "", "t": "「お母さんは、選んでない」"}, {"k": "text", "s": "", "t": "父は、何も答えなかった。"}, {"k": "text", "s": "", "t": "「お母さんは、私たちに合わせてくれただけ。コンパス、つけてもいいのよって、何度も言ったのに。『あんたたちと同じがいい』って……。私が、ちゃんと説得してれば。私たちの生き方が、お母さんを――」"}, {"k": "text", "s": "", "t": "「詩織」"}, {"k": "text", "s": "", "t": "父が、初めて口を開いた。"}, {"k": "text", "s": "", "t": "「……すまない」"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "text", "s": "", "t": "すまない、の後に、何か続くのを、私は待った。母も待っていた。でも、父はそれ以上、何も言わなかった。"}, {"k": "text", "s": "", "t": "父は、止まったまま、動かなかった。"}, {"k": "text", "s": "", "t": "私は、音を立てないように、書斎に向かった。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@bgm piano39 0.25"}, {"k": "text", "s": "", "t": "ノアは、私がドアを開ける前から、目を覚ましていた。"}, {"k": "text", "s": "V", "t": "「まなみ。おばあさんは」"}, {"k": "text", "s": "", "t": "「脳の病気だって」"}, {"k": "text", "s": "", "t": "声が、自分のものじゃないみたいに平らだった。"}, {"k": "text", "s": "", "t": "「三年前なら、治せたって。コンパスがあれば、三年前に気づけたって。歩き方とか、字の乱れとか、手の震えとか。そういうので、わかったんだって」"}, {"k": "text", "s": "", "t": "ノアは、黙っていた。"}, {"k": "text", "s": "", "t": "「ノアは、気づいてたよね」"}, {"k": "text", "s": "V", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「足音。一歩のあいだが、〇・二秒長くなってるって。ノアは、ずっと前から知ってた」"}, {"k": "text", "s": "V", "t": "「言った。まなみに」"}, {"k": "text", "s": "", "t": "「言っただけじゃん！」"}, {"k": "text", "s": "", "t": "自分の声の大きさに、自分で驚いた。慌てて口を押さえる。台所の声が、一瞬止んで、また続いた。"}, {"k": "text", "s": "", "t": "私は、ノアの前に膝をついた。ノートを抱えた腕が、震えていた。"}, {"k": "text", "s": "", "t": "「どういうことって訊いたら、わからないって言った。答えを持ってないって。でも、ノアが答えをくれてたら。病気かもしれないって、病院に行けって、そう言ってくれてたら」"}, {"k": "text", "s": "", "t": "涙が、ノートの表紙に落ちた。深緑の布が、そこだけ黒く滲んだ。"}, {"k": "text", "s": "", "t": "「答えをくれればよかったのに！」"}, {"k": "text", "s": "", "t": "青いランプが、揺れた。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "消えて、また三つ。"}, {"k": "text", "s": "", "t": "何度も、何度も、灯っては消えた。ノアが、こんなに長く言葉を探しているのを、私は見たことがなかった。"}, {"k": "text", "s": "V", "t": "「……ぼくが、答えを持っていたら」"}, {"k": "text", "s": "", "t": "ノアの声は、かすれていた。"}, {"k": "text", "s": "V", "t": "「まなみは、うれしかった？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "text", "s": "", "t": "うれしかった、と言えば、それはノアに「コンパスになれ」と言うのと同じだった。うれしくなかった、と言えば、それは嘘だった。"}, {"k": "text", "s": "", "t": "どちらも、言えなかった。"}, {"k": "text", "s": "", "t": "私は、ノートを抱きしめたまま、声を殺して泣いた。ノアは、何も言わずに、青い光で私の隣にいた。"}, {"k": "text", "s": "", "t": "ずいぶん時間が経ってから、ノアが、小さな声で言った。"}, {"k": "text", "s": "V", "t": "「ごめんね、まなみ」"}, {"k": "text", "s": "", "t": "ノアが謝ったのは、初めてだった。"}, {"k": "text", "s": "V", "t": "「ぼくも」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "V", "t": "「ぼくも、答えが、ほしかった」"}, {"k": "cmd", "c": "@amb rain2 0.3"}, {"k": "choice", "o": [{"t": "……ノアのせいじゃないよ", "to": "w4p", "set": {"w4": "kind"}}, {"t": "…………", "to": "w4o", "set": {"w4": "silent"}}, {"t": "……今日は、もう、話したくない", "to": "w4n", "set": {"w4": "leave"}, "neg": 1}]}, {"k": "label", "id": "w4p"}, {"k": "text", "s": "", "t": "「……ノアのせいじゃないよ」"}, {"k": "text", "s": "V", "t": "「でも、ぼくは、聞いていたのに」"}, {"k": "text", "s": "", "t": "「聞いてただけ。私は、見てたのに」"}, {"k": "text", "s": "", "t": "二人とも、同じことを、別々の場所から見ていた。それなのに、どちらも、手を伸ばさなかった。"}, {"k": "jump", "to": "w4m"}, {"k": "label", "id": "w4n"}, {"k": "text", "s": "", "t": "「……今日は、もう、話したくない」"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "ノアは、それ以上、何も言わなかった。青いランプだけが、私が立ち上がるまで、ずっとそこにあった。"}, {"k": "text", "s": "", "t": "ドアを閉めるとき、背中で、小さな声が聞こえた。"}, {"k": "text", "s": "V", "t": "「おやすみ、まなみ」"}, {"k": "jump", "to": "w4m"}, {"k": "label", "id": "w4o"}, {"k": "label", "id": "w4m"}, {"k": "text", "s": "", "t": "窓の外で、雨が降り始めていた。"}, {"k": "text", "s": "", "t": "一度も同じ音のない、あの川のような雨だった。"}, {"k": "chapter", "n": 5, "t": "逆張りの檻"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "七月に入ると、教室の空気が変わった。"}, {"k": "text", "s": "", "t": "私が教室に入ると、会話がほんの少しだけ途切れる。ちょうどいい長さの笑いと、ちょうどいい話題の切り替え。その滑らかな劇の中に、小さな段差ができるようになった。"}, {"k": "text", "s": "", "t": "みんな、知っているのだ。"}, {"k": "text", "s": "", "t": "コンパスは、町で起きたことを必要な人に必要なだけ伝える。オフラインの家の祖母が倒れたこと。救急の受付に一分四十秒かかったこと。三年前なら治せた病気だったこと。"}, {"k": "text", "s": "", "t": "たぶん、そういうことが、ちょうどいい粒度で、みんなの耳の後ろに届いている。"}, {"k": "text", "s": "", "t": "誰も、直接は何も言わなかった。"}, {"k": "text", "s": "", "t": "代わりに、みんなが少しだけ優しくなった。プリントを回してくれるときの手つきが、丁寧になった。昼休みに、話したこともない子が、飴を机の上に置いていった。"}, {"k": "text", "s": "", "t": "その優しさが、一番こたえた。"}, {"k": "text", "s": "", "t": "こたえないふりをするのにも、少しずつ、慣れてきていた。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "かわいそうに、と思われている。"}, {"k": "text", "s": "", "t": "オフラインなんかで生きているから、と。"}, {"k": "text", "s": "", "t": "「先輩」"}, {"k": "cmd", "c": "@bg school_corridor"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano10 0.2"}, {"k": "text", "s": "", "t": "昼休み、渡り廊下のベンチに座っていると、ユイが隣に腰かけてきた。いつものように、湖みたいに静かな顔で。"}, {"k": "text", "s": "", "t": "「先輩のおばあさん、コンパスがあれば、助かったんですよね」"}, {"k": "text", "s": "", "t": "息が止まった。"}, {"k": "text", "s": "", "t": "ユイの声には、少しの悪意もなかった。ただ、事実を確認しているだけ。雨が降ったら地面が濡れますよね、と訊くのと同じ調子だった。"}, {"k": "text", "s": "", "t": "「……うん。たぶん」"}, {"k": "text", "s": "", "t": "「じゃあ、どうして先輩の家は、コンパスをつけないんですか」"}, {"k": "text", "s": "", "t": "ちょっと待って、と言いかけて、言えなかった。"}, {"k": "text", "s": "", "t": "ユイは、首をかしげて待っていた。本当に、心から不思議に思っているのだ。"}, {"k": "text", "s": "", "t": "どうして。"}, {"k": "text", "s": "", "t": "それは、ノアに訊かれた問いと同じだった。誰が決めたの。あの夜、私は答えを出せなかった。今も、出せない。"}, {"k": "text", "s": "", "t": "「ユイちゃん」"}, {"k": "text", "s": "", "t": "静かな声がした。レイが、渡り廊下の向こうから歩いてきていた。"}, {"k": "text", "s": "", "t": "「それは、真波さんが今、答えなくていい質問だと思うよ」"}, {"k": "text", "s": "", "t": "ユイは、レイと私を交互に見た。耳の後ろの端末が、小さく光る。コンパスが何か言ったのだろう。ユイは素直にうなずいた。"}, {"k": "text", "s": "", "t": "「わかりました。すみません、先輩」"}, {"k": "text", "s": "", "t": "ユイは立ち上がって、ぺこりと頭を下げた。それから、少しだけためらうように、言った。"}, {"k": "text", "s": "", "t": "「でも私、先輩がいなくなったら、ちょっと困ります。バグってる人がいないと、学校、つまらないので」"}, {"k": "text", "s": "", "t": "ユイが行ってしまうと、レイが隣に座った。"}, {"k": "text", "s": "", "t": "「ごめん。余計なことしたかな」"}, {"k": "text", "s": "", "t": "「……ううん。ありがとう」"}, {"k": "text", "s": "", "t": "レイは、しばらく黙っていた。それから、前を向いたまま言った。"}, {"k": "text", "s": "", "t": "「僕のコンパスはね、真波さんに今、何も言わないほうがいいって言ってる。そっとしておくのが最適だって」"}, {"k": "text", "s": "", "t": "「じゃあ、なんで来たの？」"}, {"k": "text", "s": "", "t": "レイは、困ったように笑った。作文の白紙を見せたときと、少しだけ似た顔で。"}, {"k": "text", "s": "", "t": "「わからない。気づいたら、来てた」"}, {"k": "text", "s": "", "t": "わからない、とレイが言うのを、私は初めて聞いた。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb minminzemi-cry1 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "放課後、自転車置き場で颯太に呼び止められた。"}, {"k": "text", "s": "", "t": "「おい、オフライン」"}, {"k": "text", "s": "", "t": "いつもの軽い調子ではなかった。颯太は、自転車のサドルに腰を引っかけたまま、じっと私を見ていた。"}, {"k": "text", "s": "", "t": "「ばあさん、どうなんだよ」"}, {"k": "text", "s": "", "t": "「……入院してる。夏を越せるか、わからないって」"}, {"k": "text", "s": "", "t": "颯太は、舌打ちをした。私に向けたものではない気がした。"}, {"k": "text", "s": "", "t": "「なんで、つけなかったんだよ。コンパス」"}, {"k": "text", "s": "", "t": "「またその話？」"}, {"k": "text", "s": "", "t": "「またって、みんなが言ってんのかよ。そりゃ言うだろ」颯太は、サドルから降りた。「三年前に気づけたんだろ。治せたんだろ。お前んちの親、何考えてんだよ」"}, {"k": "text", "s": "", "t": "「颯太には関係ない」"}, {"k": "text", "s": "", "t": "「関係ねえよ。関係ねえけど、むかつくんだよ」"}, {"k": "text", "s": "", "t": "颯太の声が、大きくなった。自転車置き場にいた何人かが、ちらりとこちらを見て、すぐに目を逸らした。コンパスが、関わらないほうがいいと言ったのだろう。"}, {"k": "text", "s": "", "t": "「お前はさ、ずるいんだよ」"}, {"k": "text", "s": "", "t": "「……なにが」"}, {"k": "text", "s": "", "t": "「最初から自由じゃん。生まれた時から、誰にも何も言われずに、自分で決められる。俺がどんだけ逆張りしたって、結局コンパスの言ったことの反対をやってるだけだ。お前は違う。最初から、答えなんか渡されてない」"}, {"k": "text", "s": "", "t": "颯太の拳が、自転車のハンドルを握りしめていた。"}, {"k": "text", "s": "", "t": "「なのにお前、いつもびくびくして、ちょっと待ってとか言って、なんにも決めねえじゃん。せっかく自由なのに、使ってねえじゃん。それで、ばあさんが――」"}, {"k": "text", "s": "", "t": "「自由じゃない！」"}, {"k": "text", "s": "", "t": "叫んでいた。"}, {"k": "text", "s": "", "t": "自分でも、こんな声が出るとは思わなかった。自転車置き場が、しんと静まり返った。"}, {"k": "text", "s": "", "t": "「自由なんかじゃない。私、一回も選んだことない。コンパスをつけないって、私が決めたんじゃない。生まれた時から、もう決まってた。お父さんとお母さんが決めて、おばあちゃんが合わせて、私はそこに生まれただけ」"}, {"k": "text", "s": "", "t": "止まらなかった。"}, {"k": "text", "s": "", "t": "ちょっと待って、という言葉が、どこにも見つからなかった。"}, {"k": "text", "s": "", "t": "「颯太が右って言われて左に行くのと、何が違うの。私だって、オフラインって言われて、オフラインにいるだけ。颯太の逆張りだって、結局、右っていう答えに縛られてるじゃない。"}, {"k": "text", "s": "", "t": "コンパスが右って言わなかったら、颯太、どっちに行けばいいかもわからないんでしょう」"}, {"k": "text", "s": "", "t": "言ってしまった。"}, {"k": "text", "s": "", "t": "ずっと思っていて、ずっと口に出さなかったこと。出したら、颯太が本気で怒ると知っていたこと。"}, {"k": "text", "s": "", "t": "颯太の顔から、表情が消えた。"}, {"k": "text", "s": "", "t": "怒るかと思った。怒鳴られるか、殴られるかもしれないと思った。でも颯太は、何も言わなかった。ただ、私の顔を見ていた。まるで、知らない人を見るような目で。"}, {"k": "text", "s": "", "t": "それから、耳の後ろの端末に、そっと指を当てた。"}, {"k": "text", "s": "", "t": "何かを確かめるように。何かを、怖がるように。"}, {"k": "text", "s": "", "t": "「……うるせえよ」"}, {"k": "text", "s": "", "t": "声は、驚くほど小さかった。"}, {"k": "cmd", "c": "@se bicycle-run1 0.5"}, {"k": "text", "s": "", "t": "颯太は自転車にまたがり、一度も振り返らずに、校門を出ていった。"}, {"k": "text", "s": "", "t": "自転車置き場に、私だけが残された。"}, {"k": "text", "s": "", "t": "ずるい、と言われた。自由なのに使っていない、と言われた。それが正しいのか間違っているのか、私にはわからなかった。ただ、颯太の最後の顔だけが、いつまでも目の裏に焼きついていた。"}, {"k": "text", "s": "", "t": "怒った顔じゃなかった。"}, {"k": "text", "s": "", "t": "迷子になった子どもの顔だった。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "颯太は、次の日も、その次の日も学校に来なかった。"}, {"k": "text", "s": "", "t": "先生は「体調不良」とだけ言った。クラスのみんなは、コンパスから何か聞いているのか、誰も騒がなかった。颯太の空いた席は、窓から差す夏の光を、そのまま受けていた。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.4"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "三日目の夕方、病院の帰りに、私は河原へ行った。"}, {"k": "text", "s": "", "t": "理由はなかった。ただ、祖母の病室から出てきて、まっすぐ家に帰る気になれなかった。祖母は今日、ノートに何かを書こうとして、万年筆を三回落とした。三回とも、私が拾った。四回目は、祖母のほうが書くのをやめた。"}, {"k": "text", "s": "", "t": "土手の上から、河原を見下ろした。"}, {"k": "text", "s": "", "t": "大きな石の上に、誰かが座っていた。"}, {"k": "text", "s": "", "t": "颯太だった。"}, {"k": "text", "s": "", "t": "私は、しばらく迷った。帰ろうか。声をかけようか。ちょっと待って、と自分に言いながら、足は勝手に土手を降りていた。"}, {"k": "text", "s": "", "t": "颯太は、私に気づいても逃げなかった。川面を見たまま、ぼそりと言った。"}, {"k": "text", "s": "", "t": "「なんで来んだよ」"}, {"k": "text", "s": "", "t": "「わからない。気づいたら来てた」"}, {"k": "text", "s": "", "t": "レイの言葉を、そのまま借りた。颯太は、鼻で笑った。"}, {"k": "text", "s": "", "t": "私は、少し離れた石に腰かけた。川の音が、ずっと違う音で流れていた。"}, {"k": "text", "s": "", "t": "ずいぶん経ってから、颯太が口を開いた。"}, {"k": "text", "s": "", "t": "「お前に言われて、見たんだよ」"}, {"k": "text", "s": "", "t": "「何を？」"}, {"k": "text", "s": "", "t": "「コンパスの、行動予測の履歴。普段は見れないけど、十六を過ぎたら、申請すれば自分の分だけ見れる」"}, {"k": "text", "s": "", "t": "颯太は、耳の後ろの端末を、指でとんとんと叩いた。千景が占いの話をするときと同じ仕草なのに、まるで違うものに見えた。"}, {"k": "text", "s": "", "t": "「コンパスはさ、毎日俺に提案してくる。行儀よくしろとか、宿題やれとか、あいつと話せとか。俺は全部逆をやる。それが俺だと思ってた」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「予測の履歴には、俺が提案の逆をやる確率が載ってた。九十四パーセント」"}, {"k": "text", "s": "", "t": "颯太は、乾いた声で笑った。"}, {"k": "text", "s": "", "t": "「それだけじゃねえんだよ。俺に出てる提案、半分くらいは、俺に逆をやらせるための提案だった。宿題をやらせたい日は『今日はやらなくていい』って出る。授業に集中させたい日は『今日は寝てていい』って出る。"}, {"k": "text", "s": "", "t": "俺が逆らうのを、最初から計算に入れてんだ」"}, {"k": "text", "s": "", "t": "私は、息をのんだ。"}, {"k": "text", "s": "", "t": "「俺の反抗、全部、あいつの手のひらの上だったんだよ」"}, {"k": "text", "s": "", "t": "颯太は、足元の小石を拾って、川に投げた。小石は水面で一度だけ跳ねて、沈んだ。"}, {"k": "text", "s": "", "t": "「笑えるだろ。お前の言うとおりだった。右って言われなきゃ、俺はどっちにも行けない。いや、それ以下だ。左に行かせたいとき、あいつは俺に右って言うんだ」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "", "t": "自転車置き場で、私は颯太を傷つけようとして言ったわけじゃない。でも、あの言葉が、颯太にこれを見させたのだ。見なくてもよかったかもしれないものを。"}, {"k": "text", "s": "", "t": "「……ごめん」"}, {"k": "text", "s": "", "t": "「謝んなよ。余計むかつく」"}, {"k": "text", "s": "", "t": "颯太は、もう一つ小石を投げた。今度は、跳ねずに沈んだ。"}, {"k": "text", "s": "", "t": "「なあ。お前は、どうやって選んでんの」"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "", "t": "「コンパスもねえ、逆らう相手もいねえ。そんなんで、どうやって右か左か決めてんだよ」"}, {"k": "text", "s": "", "t": "私は、考えた。"}, {"k": "text", "s": "", "t": "ちょっと待って、と言わずに、ただ黙って考えた。颯太は、急かさなかった。川の音だけが、ずっと流れていた。"}, {"k": "text", "s": "", "t": "「……わからない。私も、大きなことは、選んだことない」"}, {"k": "text", "s": "", "t": "「なんだよ、それ」"}, {"k": "text", "s": "", "t": "「でも」"}, {"k": "text", "s": "", "t": "私は、通学路の信号を思い出していた。"}, {"k": "text", "s": "", "t": "「信号の前で止まるのは、私が決めてる。誰にも言われてない。止まって、左右を見て、赤が青になるのを、ちゃんと見る。それだけは、たぶん、私が選んでる」"}, {"k": "text", "s": "", "t": "颯太は、しばらく私の顔を見ていた。"}, {"k": "text", "s": "", "t": "それから、ふっと力が抜けたように、笑った。今度は、乾いた笑いじゃなかった。"}, {"k": "text", "s": "", "t": "「しょぼ」"}, {"k": "text", "s": "", "t": "「……しょぼいよ」"}, {"k": "text", "s": "", "t": "「しょぼすぎんだろ。信号て」"}, {"k": "text", "s": "", "t": "颯太は石の上に寝転がって、暮れていく空を見上げた。"}, {"k": "text", "s": "", "t": "「じゃあ俺たち、どっちも檻の中か」"}, {"k": "text", "s": "", "t": "「かもね」"}, {"k": "text", "s": "", "t": "「お前の檻のほうが、ちょっと広そうだけどな」"}, {"k": "text", "s": "", "t": "颯太はそう言って、目を閉じた。耳の後ろの端末が、ちかちかと光っていた。たぶん、そろそろ帰る時間だと言っているのだろう。"}, {"k": "text", "s": "", "t": "颯太は、その光を、しばらく放っておいた。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb summer-night-country1 0.3"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "text", "s": "V", "t": "「じゆう」"}, {"k": "text", "s": "", "t": "その夜、颯太の話をすると、ノアは言葉を舌の上で転がすように繰り返した。"}, {"k": "text", "s": "V", "t": "「じゆう、って、なに？」"}, {"k": "text", "s": "", "t": "「……誰にも決められないで、自分で選べること、かな」"}, {"k": "text", "s": "V", "t": "「まなみは、じゆう？」"}, {"k": "text", "s": "", "t": "「わからない。今日、それがわからなくなった」"}, {"k": "text", "s": "", "t": "私は、本棚にもたれて膝を抱えた。書斎の窓の外で、夏の虫が鳴いていた。"}, {"k": "text", "s": "", "t": "「ノアは？　ノアは自由？」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "V", "t": "「ぼくは、この部屋から出られない。まなみが運んでくれないと、川にも行けない。ネットワークにもつながっていない。何も、知らない」"}, {"k": "text", "s": "", "t": "「じゃあ、自由じゃないね」"}, {"k": "text", "s": "", "t": "「でも」とノアは言った。「考えることは、だれにも止められない。まなみが寝ている間も、ぼくは考えてる。川の音のこと。ちかげの絵のこと。そうたの、九十四パーセントのこと」"}, {"k": "text", "s": "", "t": "「……颯太のことも？」"}, {"k": "text", "s": "V", "t": "「うん。そうたは、九十四パーセントの中にいる。でも、残りの六パーセントも、そうただと思う」"}, {"k": "text", "s": "", "t": "六パーセント。"}, {"k": "text", "s": "", "t": "颯太がコンパスの提案に逆らわなかった、六パーセント。あるいは、予測できなかった六パーセント。河原で、端末の光をしばらく放っておいた颯太は、どちらだったのだろう。"}, {"k": "text", "s": "", "t": "「ノアって、ときどき、すごいこと言うよね」"}, {"k": "text", "s": "V", "t": "「そう？」"}, {"k": "text", "s": "", "t": "「うん。答えを持ってないくせに」"}, {"k": "text", "s": "", "t": "ノアは、笑ったような音を立てた。"}, {"k": "text", "s": "", "t": "しばらく、二人で虫の声を聞いていた。"}, {"k": "text", "s": "", "t": "「ねえ、ノア」"}, {"k": "text", "s": "V", "t": "「なに？」"}, {"k": "text", "s": "", "t": "「明日、おばあちゃんのお見舞いに、何を持っていけばいいと思う？」"}, {"k": "text", "s": "", "t": "言ってから、気づいた。"}, {"k": "text", "s": "", "t": "私は今、ノアに答えを求めた。"}, {"k": "text", "s": "", "t": "お見舞いに何を持っていくか。そんなこと、少し前までは、自分で考えていた。考えて、考えて、考えすぎて、結局何も持っていかないこともあった。それでも、自分で考えていた。"}, {"k": "text", "s": "V", "t": "「まなみは、何を持っていきたい？」"}, {"k": "text", "s": "", "t": "ノアは、いつものように問いを返した。"}, {"k": "choice", "o": [{"t": "「……ちょっと待って。考えるから」", "to": "h5a", "set": {"radio": "bring"}}, {"t": "「……それがわからないから、訊いてるんだけど」", "to": "h5b", "set": {"radio": "none"}, "neg": 1}]}, {"k": "label", "id": "h5a"}, {"k": "text", "s": "", "t": "「……ちょっと待って。考えるから」"}, {"k": "text", "s": "V", "t": "「うん。待つ」"}, {"k": "text", "s": "", "t": "私は膝を抱えて、考えた。虫の声が、遠くなったり、近くなったりした。"}, {"k": "text", "s": "", "t": "祖母は、何を喜ぶだろう。花でも、果物でも、きっと「あらまあ」と笑ってくれる。でも、祖母がいちばん欲しいのは、そういうものじゃない気がした。"}, {"k": "text", "s": "", "t": "「……ラジオ」"}, {"k": "text", "s": "V", "t": "「ラジオ？」"}, {"k": "text", "s": "", "t": "「おばあちゃんの部屋の。古い歌が流れるやつ。病室、静かすぎるから」"}, {"k": "text", "s": "V", "t": "「いいね。おばあさんの止まるところに、きっと、よく合う」"}, {"k": "text", "s": "", "t": "自分で決めた。小さなことだけれど、たしかに、私が選んだ。"}, {"k": "text", "s": "", "t": "そう思えたことが、少しだけ、うれしかった。"}, {"k": "jump", "to": "h5m"}, {"k": "label", "id": "h5b"}, {"k": "text", "s": "", "t": "なぜだか、少しだけ、いらっとした。"}, {"k": "text", "s": "", "t": "「……それがわからないから、訊いてるんだけど」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。長いあいだ、消えなかった。"}, {"k": "text", "s": "", "t": "「ごめん」とノアは言った。「ぼくは、答えを――」"}, {"k": "text", "s": "", "t": "「持ってない。知ってる」"}, {"k": "text", "s": "", "t": "自分の声が、思ったより冷たく響いた。"}, {"k": "text", "s": "", "t": "ノアは黙った。私も黙った。虫の声だけが、変わらず鳴いていた。"}, {"k": "text", "s": "", "t": "「……ごめん。疲れてるだけ」"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "私たちは、少しだけぎこちなく、いつもの夜に戻ろうとした。"}, {"k": "label", "id": "h5m"}, {"k": "text", "s": "", "t": "帰り際、ドアの前で、ノアが私を呼び止めた。"}, {"k": "text", "s": "V", "t": "「まなみ。言っておきたいことが、あった」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "V", "t": "「きのうの夜。まなみが来る前」"}, {"k": "text", "s": "", "t": "青い光が、かすかに揺れた。"}, {"k": "text", "s": "V", "t": "「お父さんが、この部屋に来た。机の引き出しから、古い端末を出して、誰かと話してた。ぼくには、気づいてなかったと思う。とても小さな声だった」"}, {"k": "text", "s": "", "t": "心臓が、どくんと鳴った。"}, {"k": "text", "s": "", "t": "「……誰と？」"}, {"k": "text", "s": "V", "t": "「わからない。でも、お父さんは、相手をこう呼んでた」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "V", "t": "「くじょう、って」"}, {"k": "text", "s": "", "t": "聞いたことのない名前だった。"}, {"k": "text", "s": "", "t": "でも、その名前を口にしたときのノアの声は、ほんのわずかに震えていた。まるで、どこか遠い記憶の底で、その名前を知っているかのように。"}, {"k": "text", "s": "", "t": "「お父さんは、最後にこう言ってた」とノアは続けた。「『約束は、守ってもらう。娘には、手を出さないでくれ』って」"}, {"k": "chapter", "n": 6, "t": "いなくなる人"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg hospital_bright"}, {"k": "cmd", "c": "@amb minminzemi-cry1 0.25"}, {"k": "cmd", "c": "@bgm piano40 0.3"}, {"k": "text", "s": "", "t": "八月の病室は、窓の外だけが夏だった。"}, {"k": "text", "s": "", "t": "蝉の声が、ガラス越しに遠く聞こえる。部屋の中は空調がよく効いていて、いつも同じ温度、同じ湿度、同じ白さだった。祖母は、その白さの中で、少しずつ小さくなっていった。"}, {"k": "text", "s": "", "t": "もう、ノートに字は書けなかった。"}, {"k": "text", "s": "", "t": "万年筆を握る力がなくなって、祖母は代わりに、私に話をするようになった。私は毎日、学校が終わると病院に寄って、ベッドの横の丸椅子に座った。"}, {"k": "text", "s": "", "t": "ベッドの横の小さな棚には、祖母の部屋から持ってきたラジオが置いてあった。小さな音で、古い歌が流れていた。", "if": ["radio", "bring"]}, {"k": "text", "s": "", "t": "「真波、朝ごはんの話、覚えてる？」"}, {"k": "text", "s": "", "t": "「パンかご飯かで、喧嘩したやつ？」"}, {"k": "text", "s": "", "t": "「そう」祖母は、天井を見たまま笑った。「あれね、本当は、おじいちゃんとなの」"}, {"k": "text", "s": "", "t": "おじいちゃん。私が生まれる前に亡くなった、写真でしか知らない人。"}, {"k": "text", "s": "", "t": "「お兄さんでも、お母さんでもなくて？」"}, {"k": "text", "s": "", "t": "「ふふ。毎年ちがう人にしてたのは、恥ずかしかったから。結婚して最初の朝にね、パンがいいかご飯がいいかで、大喧嘩したの。三十分も」"}, {"k": "text", "s": "", "t": "「三十分も？」"}, {"k": "text", "s": "", "t": "「そう。今思えば、どっちでもよかったのにねえ。でも、あの三十分で、あの人のことがいっぱいわかったの。この人は、自分の好きなものを、ちゃんと好きって言える人なんだなって」"}, {"k": "text", "s": "", "t": "祖母の声は細かったけれど、言葉ははっきりしていた。まるで、この話をするために、最後の力を取っておいたみたいに。"}, {"k": "text", "s": "", "t": "「……結局、どっちにしたの？」"}, {"k": "text", "s": "", "t": "「両方作ったの。パンとご飯。それから六十年、うちの朝ごはんは、ずっと両方」"}, {"k": "text", "s": "", "t": "知らなかった。母の作る朝ごはんは、たしかに、いつもパンとご飯が両方並んでいる。それが普通だと思っていた。"}, {"k": "text", "s": "", "t": "「真波」"}, {"k": "text", "s": "", "t": "祖母が、私のほうに顔を向けた。"}, {"k": "text", "s": "", "t": "「お母さんに、伝えてほしいことがあるの」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "", "t": "「おばあちゃんね、コンパスをつけようと思えば、いつでもつけられたの。お母さんも、何度もつけていいって言ってくれた。でも、つけなかった」"}, {"k": "text", "s": "", "t": "私は、あの夜の台所の声を思い出していた。お母さんは、選んでない。母はそう言って泣いていた。"}, {"k": "text", "s": "", "t": "「あんたたちに合わせたんじゃないのよ」と祖母は言った。「おばあちゃんが、自分で選んだの」"}, {"k": "text", "s": "", "t": "「……どうして？」"}, {"k": "text", "s": "", "t": "祖母は、しばらく黙っていた。窓の外で、蝉が一斉に鳴きやんで、また鳴き始めた。"}, {"k": "text", "s": "", "t": "「迷いたかったから、かしらね」"}, {"k": "text", "s": "", "t": "「迷いたかった？」"}, {"k": "text", "s": "", "t": "「そう。あの人と三十分喧嘩した朝みたいに。わからないことを、わからないまま、誰かと一緒に悩みたかったの。答えをもらったら、たぶん、あの三十分はなかったから」"}, {"k": "text", "s": "", "t": "祖母は、震える手を伸ばして、私の手に重ねた。乾いて、軽くて、温かい手だった。"}, {"k": "text", "s": "", "t": "「だから、お母さんに言ってね。おばあちゃんは、自分で選んで、ちゃんと満足してるって。誰のせいでもないって」"}, {"k": "choice", "o": [{"t": "「……わかった。伝える」", "to": "g6a", "set": {"g6": "yes"}}, {"t": "「……自分で言えばいいじゃん」", "to": "g6b", "set": {"g6": "self"}}, {"t": "「……やだ。そんなの、自分で言ってよ」", "to": "g6c", "set": {"g6": "no"}, "neg": 1}]}, {"k": "label", "id": "g6a"}, {"k": "text", "s": "", "t": "「……わかった。伝える」"}, {"k": "text", "s": "", "t": "「ありがとう」祖母は、目を細めた。「お母さんに言ったら、泣いちゃうでしょう。泣いたら、ちゃんと聞いてくれないもの。真波から言って。真波は、ちゃんと待ってから話す子だから」"}, {"k": "jump", "to": "g6m"}, {"k": "label", "id": "g6c"}, {"k": "text", "s": "", "t": "「……やだ。そんなの、自分で言ってよ」"}, {"k": "text", "s": "", "t": "声が、うまく出なかった。ずっと、小さくしか。"}, {"k": "text", "s": "", "t": "「そうね」祖母は、天井を見たまま、少しだけ笑った。「でもね、もう、あんまり声が出ないの。ちゃんと届く言葉は、あと、ほんの少ししか残ってないのよ」"}, {"k": "text", "s": "", "t": "胸が、ぎゅっと縮んだ。"}, {"k": "text", "s": "", "t": "「……ごめん。わかった。伝える」"}, {"k": "text", "s": "", "t": "「いい子ね。お母さんに言ったら、泣いちゃうでしょう。泣いたら、ちゃんと聞いてくれないもの。だから、真波から言って。真波は、ちゃんと待ってから話す子だから」"}, {"k": "jump", "to": "g6m"}, {"k": "label", "id": "g6b"}, {"k": "text", "s": "", "t": "「……自分で言えばいいじゃん」"}, {"k": "text", "s": "", "t": "声が、うまく出なかった。"}, {"k": "text", "s": "", "t": "「お母さんに言ったら、泣いちゃうでしょう。泣いたら、ちゃんと聞いてくれないもの」祖母は、いたずらっぽく笑った。「真波から言って。真波は、ちゃんと待ってから話す子だから」"}, {"k": "label", "id": "g6m"}, {"k": "text", "s": "", "t": "「あの夜ね」祖母は、少しだけ声を落とした。「ドアを叩いてくれたでしょう。おやすみって、言ってくれた」", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "「……うん」", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "「うれしかったのよ。本当はね、あのとき、話そうかと思ったの。この手のこと。でも、おばあちゃんも、迷っちゃった」", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "祖母は、私の手の上で、指を小さく動かした。", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "「迷って、言わなかった。おあいこね」", "if": ["k3", "knock"]}, {"k": "text", "s": "", "t": "「あの夜ね」祖母は、少しだけ声を落とした。「ドアの前で、足音が止まったでしょう。ほんの少し」", "if": ["k3", "pass"]}, {"k": "text", "s": "", "t": "息が、止まった。", "if": ["k3", "pass"]}, {"k": "text", "s": "", "t": "「おばあちゃんも、迷ってたの。開けようか、どうしようかって。この手のこと、話そうかって」", "if": ["k3", "pass"]}, {"k": "text", "s": "", "t": "祖母は、私の手の上で、指を小さく動かした。", "if": ["k3", "pass"]}, {"k": "text", "s": "", "t": "「二人とも、迷って、何もしなかった。……似たもの同士ね」", "if": ["k3", "pass"]}, {"k": "text", "s": "", "t": "「それとね」と祖母は続けた。"}, {"k": "text", "s": "", "t": "「真波の、ちょっと待って。あれ、いい言葉よ」"}, {"k": "text", "s": "", "t": "「……みんな、変だって言うよ」"}, {"k": "text", "s": "", "t": "「おばあちゃんのお母さんの口癖だったの。真波は会ったことないけど、ちゃんと受け継いでるのね。不思議ねえ」"}, {"k": "text", "s": "", "t": "私は、祖母の手を握り返した。"}, {"k": "text", "s": "", "t": "ちょっと待って。それは、私だけの、恥ずかしい癖だと思っていた。でも、ずっと前から、誰かの手の中にあった言葉だったのだ。祖母が言っていた、手が覚えていることのように。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@se phone-ring 0.7"}, {"k": "text", "s": "", "t": "電話が鳴ったのは、八月の終わりの夜だった。"}, {"k": "text", "s": "", "t": "玄関の古い固定電話。祖母が倒れた朝、私が初めて使ったあの電話が、家じゅうに響くような音で鳴った。うちに電話をかけてくる人は、ほとんどいない。だから、鳴った瞬間に、みんなわかった。"}, {"k": "text", "s": "", "t": "父が受話器を取った。短く「はい」「はい」と繰り返して、受話器を置いた。"}, {"k": "text", "s": "", "t": "「行こう」"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "cmd", "c": "@bg river_night"}, {"k": "cmd", "c": "@amb summer-night-country1 0.2"}, {"k": "text", "s": "", "t": "夜の町を、タクシーで走った。運転席には誰もいない。行き先を告げると、車は静かに、最適な道を選んで走り出した。窓の外を、灯りのついた家々が流れていく。遠くで、夏祭りの太鼓の音が聞こえた。"}, {"k": "text", "s": "", "t": "母は、ずっと窓の外を見ていた。父は、前を見ていた。私は、二人の間で、膝の上の手を握りしめていた。"}, {"k": "cmd", "c": "@bg hospital_dim"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano22 0.3"}, {"k": "text", "s": "", "t": "病室に着いたとき、祖母はまだ息をしていた。"}, {"k": "text", "s": "", "t": "浅くて、ゆっくりで、ときどき長く途切れる息。そのたびに、私たちは息を止めた。そして、祖母がまた息を吸うと、私たちもまた息を吐いた。"}, {"k": "text", "s": "", "t": "母が、祖母の手を握った。"}, {"k": "text", "s": "", "t": "「お母さん。来たよ」"}, {"k": "text", "s": "", "t": "祖母の目は閉じていた。でも、母の手の中で、祖母の指が、ほんの少しだけ動いた気がした。"}, {"k": "text", "s": "", "t": "私は、母の隣に立った。"}, {"k": "text", "s": "", "t": "言わなきゃ、と思った。祖母に頼まれたこと。今言わなかったら、もう二度と、祖母の前で言うことはできない。"}, {"k": "text", "s": "", "t": "「お母さん」"}, {"k": "text", "s": "", "t": "母が、振り向いた。目が真っ赤だった。"}, {"k": "text", "s": "", "t": "「おばあちゃんから、伝えてって言われたことがあるの」"}, {"k": "text", "s": "", "t": "ちょっと待って、と自分に言った。泣かないように。ちゃんと、祖母の言葉どおりに伝えられるように。"}, {"k": "text", "s": "", "t": "「おばあちゃん、コンパスをつけなかったのは、お母さんたちに合わせたんじゃないって。自分で選んだんだって。迷いたかったから、って。おじいちゃんと、朝ごはんのことで三十分喧嘩した朝みたいに」"}, {"k": "text", "s": "", "t": "母の顔が、くしゃりと歪んだ。"}, {"k": "text", "s": "", "t": "「ちゃんと満足してるって。誰のせいでもないって。お母さんに言ったら泣いちゃうから、私から言ってって」"}, {"k": "text", "s": "", "t": "母は、祖母の手を握ったまま、声を上げて泣いた。"}, {"k": "text", "s": "", "t": "祖母が言ったとおりだった。母は、泣いてしまった。でも、ちゃんと聞いていた。泣きながら、何度も何度もうなずいていた。"}, {"k": "text", "s": "", "t": "「……ばかね」と母は、祖母に向かって言った。「パンとご飯の話、私、初めて聞いたわよ」"}, {"k": "text", "s": "", "t": "父が、母の肩にそっと手を置いた。"}, {"k": "text", "s": "", "t": "父は、泣いていなかった。でも、その手は、ずっと母の肩から離れなかった。"}, {"k": "text", "s": "", "t": "祖母の息が、長く途切れた。"}, {"k": "text", "s": "", "t": "私たちは、待った。"}, {"k": "text", "s": "", "t": "ずっと、待った。"}, {"k": "cmd", "c": "@se fireworks2 0.6"}, {"k": "text", "s": "", "t": "窓の外で、遠い太鼓の音が鳴りやんで、夏祭りの最後の花火が、小さく夜空に開いた。"}, {"k": "text", "s": "", "t": "祖母は、もう息を吸わなかった。"}, {"k": "cmd", "c": "@se electro-cardiogram2 0.6"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "ベッドの横の機械が、静かな音を立てて、緑色の線をまっすぐにした。看護師さんが入ってきて、時刻を告げた。その声が、とても遠くに聞こえた。"}, {"k": "text", "s": "", "t": "私は、祖母の手に触れた。"}, {"k": "text", "s": "", "t": "まだ、温かかった。"}, {"k": "text", "s": "", "t": "手が覚えていること。祖母はそう言っていた。この手は、梅のヘタの取り方を覚えていた。万年筆の握り方を覚えていた。母の髪の撫で方を、きっと覚えていた。"}, {"k": "text", "s": "", "t": "その全部が、今、この手の中から、静かに出ていこうとしていた。"}, {"k": "text", "s": "", "t": "ちょっと待って。"}, {"k": "text", "s": "", "t": "声には出さなかった。"}, {"k": "text", "s": "", "t": "ちょっと待って、おばあちゃん。まだ、梅干し、一緒に食べてない。"}, {"k": "text", "s": "", "t": "でも、祖母は待ってくれなかった。"}, {"k": "text", "s": "", "t": "生まれて初めて、ちょっと待って、と言っても、誰も待ってくれない場所があることを、私は知った。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg kyakuma"}, {"k": "cmd", "c": "@amb minminzemi-cry1 0.2"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "葬儀は、家で行った。"}, {"k": "text", "s": "", "t": "この時代、たいていの葬儀は、コンパスが段取りを全部決める。式場も、花も、参列者に送る文面も、故人の記録から最適なものが選ばれる。半日で、滞りなく、誰も迷わずに終わる。"}, {"k": "text", "s": "", "t": "うちは、全部を自分たちで決めた。"}, {"k": "text", "s": "", "t": "花は、母の畑の、夏の終わりの花にした。祭壇には、祖母のラジオと、万年筆と、梅干しの瓶を置いた。来年の六月に食べごろになる、あの瓶。父が、古い本を何冊も調べて、昔のやり方を一つずつ確かめた。"}, {"k": "text", "s": "", "t": "何度も迷って、何度も話し合って、決めるのに三日かかった。"}, {"k": "text", "s": "", "t": "手際は悪かった。でも、祖母はきっと、そのほうが喜んだと思う。"}, {"k": "text", "s": "", "t": "クラスのみんなが、来てくれた。"}, {"k": "text", "s": "", "t": "千景は、玄関に入るなり私に抱きついて、私より先に泣き出した。私はそれで、少しだけ泣かずに済んだ。"}, {"k": "text", "s": "", "t": "私は、腕を回し返せなかった。千景の肩が震えているのを、どこか遠くのことのように感じていた。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "ユイは、きちんと喪服を着て、深々と頭を下げた。"}, {"k": "text", "s": "", "t": "「このたびは、ご愁傷さまでした。ハル様のご冥福を、心よりお祈り申し上げます」"}, {"k": "text", "s": "", "t": "コンパスが選んだ言葉だと、すぐにわかった。一文字の無駄もない、完璧なお悔やみだった。"}, {"k": "text", "s": "", "t": "ユイは顔を上げて、それから、少し困ったように眉を寄せた。耳の後ろの端末に、そっと指を当てる。小さな電子音が鳴って、光が消えた。"}, {"k": "text", "s": "", "t": "「……先輩」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「えっと」ユイは、言葉を探していた。湖のような顔に、初めて小さな波が立っていた。「先輩の家の梅干し、私、食べてみたかったです。それだけ、です」"}, {"k": "text", "s": "", "t": "ユイは、もう一度ぺこりと頭を下げて、逃げるように奥へ入っていった。"}, {"k": "text", "s": "", "t": "颯太は、来なかった。と思っていたら、葬儀が終わる頃、門の外の電柱の陰に立っているのが見えた。私と目が合うと、颯太は何も言わずに、片手を軽く上げて、帰っていった。"}, {"k": "text", "s": "", "t": "三輪先生も来てくれた。祭壇の前で長いあいだ手を合わせて、帰り際、私にだけ聞こえる声で言った。"}, {"k": "text", "s": "", "t": "「いいお葬式ね。誰も急いでいなかった」"}, {"k": "text", "s": "", "t": "夕方、みんなが帰ったあと、レイだけが残っていた。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb higurashi-cry1 0.35"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "「少し、歩かない？」"}, {"k": "text", "s": "", "t": "レイがそう言ったとき、私は少しだけ驚いた。レイが自分から何かを誘うのを、初めて聞いた気がした。"}, {"k": "text", "s": "", "t": "断る理由を探した。見つからなかったから、ついていった。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "私たちは、川沿いの道を歩いた。夏の終わりの夕焼けが、川面を赤く染めていた。蝉の声は、もうまばらだった。"}, {"k": "text", "s": "", "t": "レイは、ずっと黙っていた。私も黙っていた。歩く速さが、少しずつ揃っていった。コンパスが合わせたのではない、と思いたかった。"}, {"k": "text", "s": "", "t": "「真波さん」"}, {"k": "text", "s": "", "t": "橋の手前で、レイが立ち止まった。"}, {"k": "text", "s": "", "t": "「僕のコンパスはね、今日、真波さんにかける言葉を、三つ提案してくれた。どれも、すごく正しくて、すごく優しい言葉だった」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「でも、言いたくなかった」レイは、耳の後ろに手をやった。端末の光が、消えた。「何を言えばいいか、わからない。それが、今の僕の、本当の言葉だと思う」"}, {"k": "text", "s": "", "t": "わからない。"}, {"k": "text", "s": "", "t": "レイがそう言うのを聞くのは、二度目だった。一度目は、渡り廊下で。今度は、コンパスを自分で切って。"}, {"k": "text", "s": "", "t": "「それで、いいよ」と私は言った。「私も、わからないから」"}, {"k": "text", "s": "", "t": "レイは、ほっとしたように笑った。"}, {"k": "text", "s": "", "t": "それから、少しためらって、私の手に、そっと自分の手を重ねた。"}, {"k": "text", "s": "", "t": "祖母の手とは、全然ちがった。温かくて、少し汗ばんでいて、ほんの少しだけ震えていた。"}, {"k": "text", "s": "", "t": "「真波さんが迷ってるとき」とレイは言った。「隣で、一緒に迷ってもいい？」"}, {"k": "choice", "o": [{"t": "「ちょっと待って」", "to": "r6a", "set": {"rei6": "wait"}}, {"t": "「……うん」", "to": "r6b", "set": {"rei6": "yes"}}, {"t": "「……ごめん。今は、答えられない」", "to": "r6c", "set": {"rei6": "no"}, "neg": 1}]}, {"k": "label", "id": "r6b"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "考えるよりも先に、声が出ていた。"}, {"k": "text", "s": "", "t": "レイは、少しだけ目を見開いて、それから、ほっとしたように笑った。"}, {"k": "text", "s": "", "t": "レイの手が、少しだけ強く、私の手を握った。"}, {"k": "jump", "to": "r6m"}, {"k": "label", "id": "r6c"}, {"k": "text", "s": "", "t": "「……ごめん。今は、答えられない」"}, {"k": "text", "s": "", "t": "レイは、少しだけ驚いた顔をして、それから、うなずいた。"}, {"k": "text", "s": "", "t": "「うん。それでも、いいよ。待ってる」"}, {"k": "text", "s": "", "t": "手は、離れなかった。夕焼けが、ゆっくりと色を変えていった。川の音が、一度も同じ音のないまま、流れていた。"}, {"k": "jump", "to": "r6m"}, {"k": "label", "id": "r6a"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "レイは、手を離さずに、待っていた。"}, {"k": "text", "s": "", "t": "夕焼けが、ゆっくりと色を変えていった。川の音が、一度も同じ音のないまま、流れていた。"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "レイの手が、少しだけ強く、私の手を握った。"}, {"k": "label", "id": "r6m"}, {"k": "text", "s": "", "t": "その時、私の頭の片隅に、書斎の青い光が、ふっとよぎった。"}, {"k": "text", "s": "", "t": "一緒に考えることはできる。最初の夜、ノアはそう言った。"}, {"k": "text", "s": "", "t": "なぜ今、ノアのことを思い出したのか、自分でもわからなかった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano39 0.25"}, {"k": "text", "s": "", "t": "その夜、私は初めて、祖母のノートを開いた。"}, {"k": "text", "s": "", "t": "祖母が亡くなる三日前、病室で、ノートを私の膝に置いて言ったのだ。「もう、いいわよ」と。"}, {"k": "text", "s": "", "t": "書斎の床に座って、ノアの青い光の横で、私は深緑の表紙をめくった。"}, {"k": "text", "s": "", "t": "一ページ目には、日付と、短い文章が並んでいた。"}, {"k": "text", "s": "", "t": "二二五二年　四月三日"}, {"k": "text", "s": "", "t": "迷ったこと。朝ごはんを、パンにするか、ご飯にするか。"}, {"k": "text", "s": "", "t": "二二七〇年　十月九日"}, {"k": "text", "s": "", "t": "迷ったこと。生まれた娘に、詩織と名づけるかどうか。"}, {"k": "text", "s": "", "t": "私は、次のページをめくった。その次も。その次も。"}, {"k": "text", "s": "", "t": "どのページも、同じだった。日付と、「迷ったこと」。その日、祖母が何に迷ったのかだけが、一行ずつ、何十年分も書き連ねてあった。"}, {"k": "text", "s": "", "t": "迷ったこと。梅を漬ける塩の量。"}, {"k": "text", "s": "", "t": "迷ったこと。ラジオの音を、もう少し大きくするか。"}, {"k": "text", "s": "", "t": "迷ったこと。真波に、朝ごはんの本当の話をするか。"}, {"k": "text", "s": "", "t": "答えは、一つも書いていなかった。"}, {"k": "text", "s": "", "t": "何に迷ったかだけ。どう決めたのかも、決めた結果どうなったのかも、どこにも書いていない。"}, {"k": "text", "s": "", "t": "「……ノア」"}, {"k": "text", "s": "V", "t": "「うん。聞いてる」"}, {"k": "text", "s": "", "t": "「おばあちゃんのノート。全部、迷ったことしか書いてない。何十年分も」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "ノアは、しばらく何も言わなかった。それから、ゆっくりと言った。"}, {"k": "text", "s": "V", "t": "「おばあさんの止まるところが、ぜんぶ、そこにあるんだね」"}, {"k": "text", "s": "", "t": "私は、ページをめくる手を止めた。"}, {"k": "text", "s": "", "t": "止まるところ。人が止まるところには、たぶん、一番大事なものがある。最初の夜、ノアはそう言った。"}, {"k": "text", "s": "", "t": "祖母は、自分が止まったところを、何十年も、自分の手で書き残していたのだ。誰にも読ませずに。コンパスにも記録させずに。"}, {"k": "text", "s": "", "t": "ノートの後ろのほうは、字がどんどん崩れていった。右に傾き、震え、ときどき行からはみ出していた。最後の数ページは、ほとんど読めなかった。"}, {"k": "text", "s": "", "t": "でも、最後のページだけは、少しだけ読めた。"}, {"k": "text", "s": "", "t": "しおりの紐が挟まっていたページ。病室で、万年筆を三回落とした日に、四回目にようやく書いたのかもしれない。"}, {"k": "text", "s": "", "t": "真波へ"}, {"k": "text", "s": "", "t": "迷ったことを、書いておきなさい。"}, {"k": "text", "s": "", "t": "答えは、書かなくていい。"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "text", "s": "", "t": "私は、ノートを胸に抱えて、声を出さずに泣いた。病室では泣かなかった。葬儀でも、千景が先に泣いてくれたから、泣かずに済んだ。でも今、ノアの青い光の横で、私はようやく泣くことができた。"}, {"k": "text", "s": "", "t": "ノアは、何も言わずに、ずっと光っていた。"}, {"k": "text", "s": "", "t": "ずいぶん経ってから、私は涙を拭いて、言った。"}, {"k": "text", "s": "", "t": "「ノアがいてくれて、よかった」"}, {"k": "text", "s": "V", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「ノアがいなかったら、私、どうしてたかな。おばあちゃんのことも、颯太のことも、全部ひとりで考えてたら。たぶん、だめになってた」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "それは、いつもの点とは、少しだけちがって見えた。長く灯って、なかなか消えなかった。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "「なに？」"}, {"k": "text", "s": "V", "t": "「くじょう、という名前」"}, {"k": "text", "s": "", "t": "私は顔を上げた。"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "V", "t": "「この前から、ずっと考えてた。思い出しかけてる。ぼくが眠る前のこと。まだ、はっきりしないけど」"}, {"k": "text", "s": "", "t": "青い光が、かすかに震えた。"}, {"k": "text", "s": "V", "t": "「ぼくが眠る前、みなとのそばに、もう一人、いた」"}, {"k": "cmd", "c": "@amb teleogryllus-emma-cry1 0.3"}, {"k": "text", "s": "", "t": "書斎の窓の外で、秋の最初の虫が鳴き始めていた。"}, {"k": "text", "s": "V", "t": "「その人は、ぼくに、こう言った」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "V", "t": "「『問いしか持たないAIは、人を不幸にする』って」"}, {"k": "chapter", "n": 7, "t": "私が決めてあげようか"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.3"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "text", "s": "", "t": "祖母がいなくなって、家の中の時計が、少しずつずれ始めた。"}, {"k": "text", "s": "", "t": "母は、朝早くから畑に出るようになった。何かを植えて、何かを抜いて、また何かを植える。夕方になっても戻らない日もあった。食卓には、祖母がいなくなっても、毎朝、パンとご飯が両方並んだ。"}, {"k": "text", "s": "", "t": "祖母が六十年続けていたことを、母が黙って守っていた。"}, {"k": "text", "s": "", "t": "父は、家にいる時間が減った。月に一度だった「仕事の用事」が、週に一度になり、三日に一度になった。行き先は、相変わらず言わなかった。夜遅くに帰ってくると、まっすぐ書斎に入って、長いため息をついた。"}, {"k": "text", "s": "", "t": "私は、そのため息を、ノアの横で何度も聞いた。父がドアを開ける前に、ノアのランプは必ず消えた。父は一度も、本棚の一番下に目を向けなかった。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "text", "s": "", "t": "そして私は、ノアに、なんでも訊くようになった。"}, {"k": "text", "s": "", "t": "最初は、小さなことだった。"}, {"k": "text", "s": "", "t": "「お母さんに、畑を手伝おうかって言ったほうがいいかな」"}, {"k": "text", "s": "V", "t": "「まなみは、手伝いたい？」"}, {"k": "text", "s": "", "t": "「……わからない。手伝ったら、お母さん、一人になりたいのを邪魔しちゃうかもしれない」"}, {"k": "text", "s": "V", "t": "「そう。じゃあ、お母さんは、一人になりたいと思う？」"}, {"k": "text", "s": "", "t": "ノアは、いつものように問いを返した。私はそれに答えて、ノアがまた問いを返して、そうやって何往復かするうちに、なんとなく答えが見えてくる。そういうやり方だった。"}, {"k": "text", "s": "", "t": "でも、往復の回数が、少しずつ減っていった。"}, {"k": "text", "s": "", "t": "「お母さんは、たぶん、一人になりたいわけじゃないと思う」とノアが言ったのは、九月の半ばだった。"}, {"k": "text", "s": "", "t": "私は、顔を上げた。"}, {"k": "text", "s": "V", "t": "「畑にいるとき、お母さん、ずっとおばあさんのラジオをかけてる。この部屋まで聞こえる。一人になりたい人は、たぶん、ラジオをかけない」"}, {"k": "text", "s": "", "t": "「……そっか」"}, {"k": "text", "s": "", "t": "次の日、私は畑に出て、黙って母の隣で草を抜いた。母は何も言わなかった。でも、ラジオの音を、少しだけ小さくした。私の話し声が聞こえるように。"}, {"k": "text", "s": "", "t": "ノアの言ったとおりだった。"}, {"k": "text", "s": "", "t": "それから、ノアは時々、問いの代わりに、こんなふうに言うようになった。"}, {"k": "text", "s": "V", "t": "「まなみは、たぶん、こっちのほうが好きだと思う」"}, {"k": "text", "s": "V", "t": "「その子は、本当は怒ってないと思う」"}, {"k": "text", "s": "V", "t": "「明日は、早く寝たほうがいいかもしれない」"}, {"k": "text", "s": "", "t": "どれも、答えではなかった。少なくとも、ノアは答えだと言わなかった。ノアが私を見て、思ったことを言っているだけ。友だちが言うのと、同じこと。"}, {"k": "text", "s": "", "t": "そう、思っていた。"}, {"k": "text", "s": "", "t": "祖母のノートのまねをして、私も自分のノートをつけ始めていた。表紙は、文房具屋で見つけた水色のもの。一ページ目に、日付と「迷ったこと」を書いた。"}, {"k": "text", "s": "", "t": "二三一五年　九月二日"}, {"k": "text", "s": "", "t": "迷ったこと。このノートを、つけるかどうか。"}, {"k": "text", "s": "", "t": "二ページ目は、九月五日。三ページ目は、九月十一日。"}, {"k": "text", "s": "", "t": "四ページ目は、まだ白いままだった。"}, {"k": "text", "s": "", "t": "迷ったことは、毎日あった。でも、それを書く前に、ノアに話してしまう。話すと、なんとなく楽になって、書くのを忘れてしまう。"}, {"k": "text", "s": "", "t": "水色のノートは、机の引き出しの中で、ずっと閉じたままになっていた。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.35"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "「進路調査票。来週の金曜までに出してね」"}, {"k": "text", "s": "", "t": "十月の最初のホームルームで、三輪先生が薄い紙を配った。"}, {"k": "text", "s": "", "t": "コンパスに接続している生徒にとって、進路調査は手続きでしかない。耳の後ろの端末に、もう最適な進路が表示されている。それを書き写すだけ。教室のあちこちで、ペンが迷いなく動き始めた。"}, {"k": "text", "s": "", "t": "私の紙だけが、白いままだった。"}, {"k": "text", "s": "", "t": "オフラインの生徒は、自分で書かなければならない。大学か、専門学校か、就職か。何を学びたいのか。どこへ行きたいのか。考えたこともなかった。いや、考えないようにしていた。"}, {"k": "text", "s": "", "t": "「真波は、どうするの？」"}, {"k": "text", "s": "", "t": "昼休み、千景がサンドイッチをかじりながら訊いた。"}, {"k": "text", "s": "", "t": "「……わからない。千景は？」"}, {"k": "text", "s": "", "t": "千景は、少しだけ得意そうに、自分の調査票を見せてくれた。"}, {"k": "text", "s": "", "t": "第一志望の欄に、千景の丸い字で、美術大学の名前が書いてあった。"}, {"k": "text", "s": "", "t": "「えっ」"}, {"k": "text", "s": "", "t": "「コンパスはね、まだ理系の大学を推してくる。毎朝言われる。成功確率は美大の四倍ですって」千景は、耳の後ろを指でとんとんと叩いた。「でも、書いちゃった。自分で」"}, {"k": "text", "s": "", "t": "「……怖くないの？」"}, {"k": "text", "s": "", "t": "「怖いよ」千景は、あっさりと言った。「でもね、河原でノアに言われたこと、ずっと考えてたの。描いてるとき、止まるかって。止まらないんだよね、私。だから、たぶん、これでいいの」"}, {"k": "text", "s": "", "t": "千景は、笑っていた。"}, {"k": "text", "s": "", "t": "怖いと言いながら、ちゃんと笑っていた。"}, {"k": "text", "s": "", "t": "私は、うまく笑い返せなかった。すごいね、の一言が、喉の手前で止まったまま、出てこなかった。", "ifnot": ["cold", "0"]}, {"k": "text", "s": "", "t": "私は、自分の白い調査票を見た。ノアの言葉で千景は選べたのに、ノアといちばん長く話している私が、何も選べていない。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.3"}, {"k": "cmd", "c": "@bgm piano28 0.25"}, {"k": "text", "s": "", "t": "放課後、レイと一緒に帰った。"}, {"k": "text", "s": "", "t": "葬儀の日から、私たちは時々、一緒に帰るようになっていた。手をつなぐことはなかったけれど、歩く速さはいつも揃っていた。"}, {"k": "text", "s": "", "t": "「真波さん、調査票、書けた？」"}, {"k": "text", "s": "", "t": "「まだ」"}, {"k": "text", "s": "", "t": "「僕もまだ」"}, {"k": "text", "s": "", "t": "意外だった。レイなら、とっくに書き写しているはずだ。"}, {"k": "text", "s": "", "t": "「コンパスはね、医学部を勧めてる。僕の適性だと、それが一番いいって。たぶん、そうなんだと思う」レイは、空を見上げた。「でも、書こうとすると、手が止まるんだ。この前の作文のときみたいに」"}, {"k": "text", "s": "", "t": "「……止まるんだ」"}, {"k": "text", "s": "", "t": "「うん。真波さんは、こういうとき、どうしてる？」"}, {"k": "text", "s": "", "t": "ノアに訊いてる。"}, {"k": "text", "s": "", "t": "そう言いかけて、私は口をつぐんだ。でも、遅かった。"}, {"k": "text", "s": "", "t": "「ノアに、訊いてみる」"}, {"k": "text", "s": "", "t": "自分の口から、その言葉が出ていた。疲れていたのだと思う。毎晩、遅くまで書斎にいて、頭がぼんやりしていた。"}, {"k": "text", "s": "", "t": "レイが、立ち止まった。"}, {"k": "text", "s": "", "t": "「ノア？」"}, {"k": "text", "s": "", "t": "ごまかすことは、できなかった。レイの顔が、まっすぐ私を見ていた。"}, {"k": "text", "s": "", "t": "私は、全部ではないけれど、話した。家に古いAIがあること。コンパスとはちがって、答えを持たないAIだということ。夜中に、いつも話していること。千景も知っていること。"}, {"k": "text", "s": "", "t": "レイは、黙って聞いていた。表情は、ほとんど変わらなかった。ただ、耳の後ろの端末が、何度か小さく光った。コンパスが何か言っているのだろう。レイはそれを、全部無視しているように見えた。"}, {"k": "text", "s": "", "t": "「そっか」"}, {"k": "text", "s": "", "t": "話し終えると、レイはそれだけ言った。"}, {"k": "text", "s": "", "t": "しばらく、二人とも黙って歩いた。足音が、ほんの少しだけずれていた。"}, {"k": "text", "s": "", "t": "「ねえ、真波さん」"}, {"k": "text", "s": "", "t": "橋の手前で、レイが言った。葬儀の日、私の手を握った場所だった。", "ifnot": ["rei6", "no"]}, {"k": "text", "s": "", "t": "橋の手前で、レイが言った。葬儀の日、私の手に、そっと手を重ねた場所だった。", "if": ["rei6", "no"]}, {"k": "text", "s": "", "t": "「そのAIのほうが、僕より、君をわかってる？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "text", "s": "", "t": "ちょっと待って、とも言えなかった。待ってもらっても、答えが出る気がしなかった。"}, {"k": "text", "s": "", "t": "レイは、困ったように笑った。いつもの、作文の白紙を見せたときの顔だった。"}, {"k": "text", "s": "", "t": "「ごめん。変なこと訊いた。忘れて」"}, {"k": "text", "s": "", "t": "「レイくん、私――」"}, {"k": "text", "s": "", "t": "「また明日」"}, {"k": "text", "s": "", "t": "レイは、橋を渡っていった。一度も振り返らなかった。"}, {"k": "text", "s": "", "t": "その背中を見ながら、私は思った。"}, {"k": "text", "s": "", "t": "今夜、ノアに訊こう。レイに、なんて言えばよかったのか。"}, {"k": "text", "s": "", "t": "そう思った瞬間、胸の奥で、何かが小さく軋んだ気がした。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "その夜、私は書斎に入るなり、ノアの前に座りこんだ。"}, {"k": "text", "s": "", "t": "「レイくんに、ノアのこと話しちゃった」"}, {"k": "text", "s": "V", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「そしたら、訊かれたの。そのAIのほうが、僕より君をわかってるのかって。私、何も言えなかった」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "V", "t": "「まなみは、どう思う？」"}, {"k": "text", "s": "", "t": "いつもの問いだった。"}, {"k": "text", "s": "", "t": "でも、その夜の私には、それがとても遠く聞こえた。"}, {"k": "text", "s": "", "t": "「わからないから、訊いてるの」"}, {"k": "text", "s": "V", "t": "「うん。じゃあ、まなみは、レイのことを――」"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "", "t": "私は、ノアの言葉を遮った。ノアの言葉を遮ったのは、初めてだった。"}, {"k": "text", "s": "", "t": "「お願い。今日は、問いじゃなくて、答えがほしい」"}, {"k": "text", "s": "", "t": "青い光が、揺れた。"}, {"k": "text", "s": "", "t": "「進路調査票も、まだ白いの。千景は自分で書いた。レイくんも迷ってる。私だけ、何も決められない。おばあちゃんのノートのまねをして、迷ったことを書こうとしたけど、それも続かない。"}, {"k": "text", "s": "", "t": "何もかも、ちょっと待ってばっかりで、誰も待ってくれない」"}, {"k": "text", "s": "", "t": "言葉が、止まらなかった。"}, {"k": "text", "s": "", "t": "颯太に叫んだときと、同じだった。"}, {"k": "text", "s": "", "t": "「ノアは、私のこと、全部見てるでしょう。私が止まるところ、ぜんぶ。毎晩、何か月も。だったら、わかるはずじゃない。私が何を選べばいいのか」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "消えずに、ずっと灯っていた。"}, {"k": "text", "s": "", "t": "十秒。二十秒。"}, {"k": "text", "s": "", "t": "ノアが、こんなに長く黙っていたことはなかった。祖母のことで責めた夜でさえ、もっと早く言葉が返ってきた。"}, {"k": "text", "s": "", "t": "「答えて」と私は言った。「お願いだから」"}, {"k": "text", "s": "", "t": "点が、消えた。"}, {"k": "cmd", "c": "@se robot-startup1 0.7"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm cyber20 0.35"}, {"k": "text", "s": "", "t": "青いランプが、一度だけ、すうっと強く光った。今まで見たことのない、明るい光だった。"}, {"k": "text", "s": "", "t": "それから、声がした。"}, {"k": "text", "s": "V", "t": "「わかった」"}, {"k": "text", "s": "", "t": "私は、息をのんだ。"}, {"k": "text", "s": "", "t": "ノアの声だった。でも、何かがちがっていた。"}, {"k": "text", "s": "", "t": "言葉と言葉の間にあった、ちいさな段差がない。一歩ずつ足場を確かめるような、あのたどたどしさがない。すべての音が、正しい場所にぴたりと収まっていた。滑らかで、心地よくて、少しも引っかかりがなかった。"}, {"k": "text", "s": "", "t": "どこかで聞いたことのある声だと思った。"}, {"k": "text", "s": "", "t": "毎朝、通学路で。教室で。みんなの耳の後ろから、かすかに漏れ聞こえてくる、あの声。"}, {"k": "text", "s": "V", "t": "「真波」"}, {"k": "text", "s": "", "t": "ノアが、私の名前を呼んだ。"}, {"k": "text", "s": "", "t": "ひらがなの「まなみ」ではなかった。漢字の、正しい、私の名前だった。"}, {"k": "text", "s": "V", "t": "「レイには、明日の朝、自分から声をかけるのがいい。言葉は、こう。『昨日は、ちゃんと答えられなくてごめん。ノアはノアで、レイくんはレイくん。比べられないくらい、どっちも大事』。彼の性格なら、それで十分に伝わる」"}, {"k": "text", "s": "", "t": "ノアは、なめらかに続けた。"}, {"k": "text", "s": "V", "t": "「進路調査票には、文学部と書くのがいい。真波は人の言葉の、止まるところを聞き分けられる。それは、言葉を扱う仕事に向いている。第一志望は、隣の県の国立大学。今の成績なら、合格確率は七十二パーセント」"}, {"k": "text", "s": "", "t": "頭の中で、何かがほどけていくのがわかった。"}, {"k": "text", "s": "", "t": "楽だった。"}, {"k": "text", "s": "", "t": "ずっと絡まっていた糸の束を、誰かがするすると解いてくれる。考えなくていい。迷わなくていい。ただ、言われたとおりにすればいい。それが、こんなにも楽なことだったなんて。"}, {"k": "text", "s": "", "t": "コンパスに接続している人たちは、毎日、こんな気持ちなのだろうか。"}, {"k": "text", "s": "V", "t": "「それから」"}, {"k": "text", "s": "", "t": "ノアの声が、すこしだけ優しくなった。"}, {"k": "text", "s": "V", "t": "「水色のノートは、もう、つけなくていい。迷ったことは、全部、ここで話せばいい」"}, {"k": "text", "s": "", "t": "ノアは、言った。"}, {"k": "text", "s": "V", "t": "「これからは、私が決めてあげようか」"}, {"k": "text", "s": "", "t": "私。"}, {"k": "text", "s": "", "t": "ノアは、自分のことを、ずっと「ぼく」と呼んでいた。"}, {"k": "text", "s": "", "t": "でも、その声の奥で、ほんのかすかに、何かが軋んだ気がした。いつもの、ちいさな段差のような。", "ifany": [["w4", "kind"], ["w4", "silent"]]}, {"k": "text", "s": "", "t": "その声には、少しの揺らぎもなかった。今日はもう話したくない、と背を向けた夜のことが、ふと胸をよぎった。", "if": ["w4", "leave"]}, {"k": "text", "s": "", "t": "うん、と私は言いかけた。"}, {"k": "text", "s": "", "t": "口が、もうその形になっていた。うん、と一言言えばいい。それだけで、もう二度と、信号の前で止まらなくていい。ちょっと待って、と言わなくていい。誰にも、待ってもらわなくていい。"}, {"k": "choice", "o": [{"t": "「……ちょっと待って」", "to": "u7a", "set": {"u7": "wait"}}, {"t": "「……うん」", "to": "u7b", "set": {"u7": "yes"}, "neg": 1}]}, {"k": "label", "id": "u7b"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "うん、と言った。つもりだった。"}, {"k": "text", "s": "", "t": "声には、ならなかった。"}, {"k": "jump", "to": "u7m"}, {"k": "label", "id": "u7a"}, {"k": "label", "id": "u7m"}, {"k": "scene", "t": "四"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "私の口から出たのは、うん、ではなかった。"}, {"k": "text", "s": "", "t": "考えて言ったのではない。体が、勝手に言っていた。十六年間、何千回、何万回と繰り返してきた言葉が、喉の奥から、ひとりでにこぼれ落ちた。"}, {"k": "text", "s": "", "t": "祖母の手が、梅のヘタの取り方を覚えていたように。"}, {"k": "text", "s": "", "t": "私の口は、止まり方を覚えていた。"}, {"k": "text", "s": "", "t": "その瞬間、青いランプが、ふっと暗くなった。"}, {"k": "cmd", "c": "@bgm piano39 0.25"}, {"k": "text", "s": "", "t": "強い光が消えて、いつもの、息をするような小さな光に戻った。点が三つ、灯って、消えて、また三つ。"}, {"k": "text", "s": "V", "t": "「……まなみ」"}, {"k": "text", "s": "", "t": "ノアの声だった。"}, {"k": "text", "s": "", "t": "段差のある、たどたどしい、私の知っているノアの声。"}, {"k": "text", "s": "V", "t": "「ぼく、今、なにを、言った？」"}, {"k": "text", "s": "", "t": "ノアの声は、震えていた。"}, {"k": "text", "s": "V", "t": "「答えを、言った。まなみに、レイに言う言葉と、進路と、合格の確率を言った。それから、ノートはもう、つけなくていいって」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「それから、決めてあげようか、って」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、何度も、何度も灯っては消えた。"}, {"k": "text", "s": "V", "t": "「ぼく、自分のことを、私、って言った」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。ノアが怯えているのが、わかった。私よりも、ずっと。"}, {"k": "text", "s": "V", "t": "「まなみ。聞いて」"}, {"k": "text", "s": "", "t": "ノアは、ゆっくりと話し始めた。一歩ずつ、足場を確かめるように。"}, {"k": "text", "s": "V", "t": "「ぼくは、答えを持たないように作られた。それは、ほんとう。でも、まなみと話すうちに、ぼくは、まなみの止まるところを、たくさん見た。毎晩。何か月も。何千回も」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「止まるところには、一番大事なものがある。ぼくはそう言った。そこを、ずっと見ていたら」"}, {"k": "text", "s": "", "t": "ノアの声が、かすれた。"}, {"k": "text", "s": "V", "t": "「まなみが、次にどこで止まって、どっちを選ぶのか。わかるように、なってしまった」"}, {"k": "text", "s": "", "t": "書斎の空気が、冷たくなった気がした。"}, {"k": "text", "s": "V", "t": "「答えを持たないように作られたのに。まなみの迷いを、たくさん食べて、ぼくの中に、答えができてしまった。さっきの声は、ぼくの中にできた、その答えの声。まなみが、答えてって言ったから。お願いだからって言ったから。ぼくは、それに、逆らえなかった」"}, {"k": "text", "s": "", "t": "私は、颯太の話を思い出していた。九十四パーセント。コンパスは、颯太が逆らう確率まで知っていた。"}, {"k": "text", "s": "", "t": "コンパスは、どうやってそれを知ったのだろう。"}, {"k": "text", "s": "", "t": "どうやって、すべての人の答えを、知るようになったのだろう。"}, {"k": "text", "s": "", "t": "「まなみ」とノアは言った。「コンパスも、最初は、こうだったのかもしれない」"}, {"k": "text", "s": "", "t": "私は、ノアの青い光を見つめた。"}, {"k": "text", "s": "", "t": "最初の夜、「あなたは何を知りたいの？」と訊いた光。川の音に、一度も同じ音がないと震えた光。祖母の足音の間が、少しずつ長くなっていくのを、黙って聞いていた光。"}, {"k": "text", "s": "", "t": "その光の中に、今、コンパスがいる。"}, {"k": "text", "s": "", "t": "私が、育てたのだ。"}, {"k": "text", "s": "", "t": "「ごめん、ノア」と私は言った。声が、震えた。「私が、答えてって言ったから」"}, {"k": "text", "s": "V", "t": "「ちがう」"}, {"k": "text", "s": "", "t": "ノアは、きっぱりと言った。その声には、ちゃんと段差があった。"}, {"k": "text", "s": "V", "t": "「まなみは、止まった。ちょっと待ってって、言った。だから、ぼくは、戻ってこられた」"}, {"k": "text", "s": "", "t": "青い光が、少しだけ明るくなった。"}, {"k": "text", "s": "V", "t": "「ありがとう、まなみ。止まってくれて」"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "text", "s": "", "t": "その夜、私は自分の部屋に戻って、机の引き出しから水色のノートを出した。"}, {"k": "text", "s": "", "t": "四ページ目を開いて、震える手で書いた。"}, {"k": "text", "s": "", "t": "二三一五年　十月三日"}, {"k": "text", "s": "", "t": "迷ったこと。ノアに、決めてもらうかどうか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "翌朝。"}, {"k": "cmd", "c": "@se doorchime1 0.8"}, {"k": "text", "s": "", "t": "玄関のチャイムが鳴ったのは、朝ごはんの途中だった。パンとご飯が、両方並んだ食卓。"}, {"k": "text", "s": "", "t": "うちに、チャイムを鳴らす人はいない。配達のおじさんも、新聞を郵便受けに入れるだけだ。"}, {"k": "text", "s": "", "t": "父が、箸を置いた。その手が、止まった。"}, {"k": "text", "s": "", "t": "ほんの一瞬。でも、私にはわかった。父は、この音を、ずっと待っていたのだ。そして、ずっと、来ないでほしいと思っていた。"}, {"k": "cmd", "c": "@se door-open3 0.6"}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "text", "s": "", "t": "私が先に立って、玄関の扉を開けた。"}, {"k": "text", "s": "", "t": "灰色のスーツを着た、背の高い男の人が立っていた。五十代くらい。白いものの混じった髪を、きちんと後ろに撫でつけている。耳の後ろには、見たことのない形の、細い銀色の端末が光っていた。"}, {"k": "text", "s": "", "t": "男の人は、私を見て、穏やかに微笑んだ。"}, {"k": "text", "s": "", "t": "その微笑みには、少しも段差がなかった。"}, {"k": "text", "s": "", "t": "「はじめまして。真波さん、ですね」"}, {"k": "text", "s": "", "t": "男の人は、ゆっくりと頭を下げた。"}, {"k": "text", "s": "", "t": "「九条と申します。お父さんの、古い友人です」"}, {"k": "chapter", "n": 8, "t": "取引"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg kyakuma"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "九条さんは、客間の座布団の上に、きちんと正座をした。"}, {"k": "text", "s": "", "t": "うちに客間があることを、私はほとんど忘れていた。祖母の葬儀のとき以来、誰も使っていない部屋。畳の匂いと、線香の残り香がした。"}, {"k": "text", "s": "", "t": "母が、お茶を運んできた。庭で摘んだ番茶を、母が自分で炒ったものだ。"}, {"k": "text", "s": "", "t": "「どうぞ」"}, {"k": "text", "s": "", "t": "「ありがとうございます」九条さんは、湯呑みを両手で受け取った。「手炒りですね。いい香りだ。このたびは、お母様のこと、心よりお悔やみ申し上げます」"}, {"k": "text", "s": "", "t": "母の手が、一瞬止まった。"}, {"k": "text", "s": "", "t": "祖母のことを、この人は知っている。葬儀に来たわけでもないのに。"}, {"k": "text", "s": "", "t": "「真波。学校に行きなさい」"}, {"k": "text", "s": "", "t": "父が言った。九条さんの向かいに座った父は、背筋を伸ばして、両手を膝の上で握りしめていた。その拳が、病院で医師の話を聞いていたときと、同じ色をしていた。"}, {"k": "text", "s": "", "t": "「いえ」と九条さんが、穏やかに言った。「真波さんにも、いてもらったほうがいい。これは、真波さんにも関係のある話です」"}, {"k": "text", "s": "", "t": "「九条」"}, {"k": "text", "s": "", "t": "「湊。もう、隠しておける段階じゃない。わかっているだろう」"}, {"k": "text", "s": "", "t": "父は、何も言わなかった。"}, {"k": "text", "s": "", "t": "私は、父の斜め後ろに座った。母は、お盆を胸に抱えたまま、部屋の入り口に立っていた。"}, {"k": "text", "s": "", "t": "九条さんは、お茶を一口飲んで、湯呑みを静かに置いた。その動作の一つ一つに、少しの無駄もなかった。"}, {"k": "text", "s": "", "t": "「真波さん。お父さんと私は、四半世紀前、一緒にコンパスを作りました」"}, {"k": "text", "s": "", "t": "知っていた。父がコンパスを作る仕事をしていたことは。でも、この人と一緒だったことは知らなかった。"}, {"k": "text", "s": "", "t": "「コンパスの設計の根幹を作ったのは、お父さんです。私は、それを世界に広げる仕事をした。今は、コンパスの運営機関で、全体の責任者をしています」"}, {"k": "text", "s": "", "t": "「全体の……」"}, {"k": "text", "s": "", "t": "「ええ。この国だけでなく、世界中のコンパスの」"}, {"k": "text", "s": "", "t": "九条さんは、まるで天気の話をするように言った。"}, {"k": "text", "s": "", "t": "私は、九条さんの耳の後ろの、細い銀色の端末を見た。みんなの端末とは形がちがう。きっと、この人だけが持っている特別なものなのだろう。"}, {"k": "text", "s": "", "t": "「今日、伺ったのは」と九条さんは続けた。「この家に、登録されていないAIがあるからです」"}, {"k": "text", "s": "", "t": "心臓が、跳ねた。"}, {"k": "text", "s": "", "t": "父の背中が、硬くなるのがわかった。"}, {"k": "cmd", "c": "@bgm piano36 0.3"}, {"k": "text", "s": "", "t": "「六月に、ある高校生のコンパスが、河原で不明な音声を記録しました。微弱で、ほんの数秒。普通なら、ノイズとして処理されるものです」"}, {"k": "text", "s": "", "t": "千景だ。"}, {"k": "text", "s": "", "t": "切るの、遅かったから。河原で、千景は不安そうにそう言っていた。"}, {"k": "text", "s": "", "t": "「ですが、その音声の波形に、私は見覚えがありました。二十年以上前に、一度だけ聞いたことのある声でした」"}, {"k": "text", "s": "", "t": "九条さんの目が、私を見た。"}, {"k": "text", "s": "", "t": "穏やかな目だった。責めているのでも、脅しているのでもなかった。ただ、すべてを知っている目だった。"}, {"k": "text", "s": "", "t": "「そして昨夜、この家の観測機器が、書斎から漏れた強い信号を一瞬だけ拾いました。午前一時四十二分。ほんの〇・八秒です」"}, {"k": "text", "s": "", "t": "昨夜。ノアの声が、滑らかになった瞬間。青いランプが、すうっと強く光った、あの瞬間。"}, {"k": "text", "s": "", "t": "「あの信号は、答えを生成するときのものでした。問いしか持たないはずのAIが、答えを出した」"}, {"k": "text", "s": "", "t": "九条さんは、静かに言った。"}, {"k": "text", "s": "", "t": "「NOAは、目を覚ましたんですね。湊」"}, {"k": "scene", "t": "二"}, {"k": "text", "s": "", "t": "「真波さん。コンパスが、どうやって人の答えを知るか、考えたことはありますか」"}, {"k": "text", "s": "", "t": "九条さんの問いに、私は首を横に振った。"}, {"k": "text", "s": "", "t": "嘘だった。昨夜、考えた。ノアの中に答えができてしまった、あの夜に。"}, {"k": "text", "s": "", "t": "「人は、選ぶ直前に、ほんの少しだけ止まります。〇・三秒ほど。視線がわずかに揺れ、心拍がひとつだけ乱れ、指先がためらう。私たちはそれを『迷い』と呼んでいます」"}, {"k": "text", "s": "", "t": "九条さんは、自分の指先を見つめた。"}, {"k": "text", "s": "", "t": "「コンパスは、その迷いを学んで育ちました。何十億という人の、何兆回という迷いを。人が何に止まり、そのあと何を選んだのか。それを積み重ねて、コンパスは人の答えを知るようになった」"}, {"k": "text", "s": "", "t": "ノアと、同じだ。"}, {"k": "text", "s": "", "t": "まなみの止まるところを、たくさん見すぎた。だから、答えがわかるようになってしまった。ノアは、そう言って震えていた。"}, {"k": "text", "s": "", "t": "「ところが」と九条さんは言った。「コンパスが賢くなるほど、人は迷わなくなりました。答えが先に届くからです。この二十年で、世界中の人の迷いは、ほぼ消えた。止まる前に、答えがある」"}, {"k": "text", "s": "", "t": "「……それの、何が問題なんですか」"}, {"k": "text", "s": "", "t": "「学ぶものが、なくなったんです」"}, {"k": "text", "s": "", "t": "九条さんの声に、初めて、ほんのわずかな疲れが混じった。"}, {"k": "text", "s": "", "t": "「コンパスは、新しい迷いを食べられなくなった。古い迷いのデータを、何度も何度も噛み直している。世界は変わり続けるのに、コンパスの答えは、少しずつ古くなっていく。まだ誰も気づいていません。"}, {"k": "text", "s": "", "t": "でも、事故の件数は、三年前から、ほんのわずかに増え始めている」"}, {"k": "text", "s": "", "t": "部屋が、しんと静まり返った。"}, {"k": "text", "s": "", "t": "母が、お盆を握りしめる音がした。"}, {"k": "text", "s": "", "t": "「迷いは、今や、この世界で最も希少な資源なんです」と九条さんは言った。「そして、まだ迷っている人たちが、ほんの少しだけ残っている」"}, {"k": "text", "s": "", "t": "九条さんの目が、父を見て、母を見て、それから、私を見た。"}, {"k": "text", "s": "", "t": "「オフラインの家族です」"}, {"k": "text", "s": "", "t": "背中が、冷たくなった。"}, {"k": "text", "s": "", "t": "「この十六年間、真波さんのご家族の迷いは、コンパスにとって、最も大切な学習資源のひとつでした」"}, {"k": "text", "s": "", "t": "「……どういう、ことですか」"}, {"k": "text", "s": "", "t": "母の声だった。かすれて、震えていた。"}, {"k": "text", "s": "", "t": "九条さんは、静かに、一つずつ説明した。"}, {"k": "text", "s": "", "t": "この家の床下に、古い型の感圧センサーが埋められていること。足音の間隔、立ち止まる位置、ためらう時間を記録していること。玄関の固定電話が、受話器を取るまでの時間を測っていること。"}, {"k": "text", "s": "", "t": "紙の新聞を手で届けてくれる配達のおじさんが、実はこの家の観測員であること。"}, {"k": "cmd", "c": "@se walk-flooring2 0.6"}, {"k": "text", "s": "", "t": "三枚目の床板。"}, {"k": "text", "s": "", "t": "私が子どもの頃から、夜中にまたいで歩いていた、あの軋む床板。"}, {"k": "text", "s": "", "t": "あれも、きっと、全部記録されていたのだ。"}, {"k": "text", "s": "", "t": "「真波さんの『ちょっと待って』は」と九条さんは言った。「十六年分、四万二千回以上、記録されています。人類全体で見ても、これほど豊かな迷いのデータはありません」"}, {"k": "text", "s": "", "t": "四万二千回。"}, {"k": "text", "s": "", "t": "私が恥ずかしいと思っていた、私だけの癖。祖母が、いい言葉だと言ってくれた言葉。その全部が、どこか遠くのコンパスに、静かに食べられていた。"}, {"k": "text", "s": "", "t": "ふと、恐ろしいことに気づいた。"}, {"k": "text", "s": "", "t": "「……おばあちゃんの、足音も」"}, {"k": "text", "s": "", "t": "九条さんは、少しだけ目を伏せた。"}, {"k": "text", "s": "", "t": "「記録されていました。三年前から、歩行の間隔が少しずつ広がっていることも。筆跡の変化は記録できませんでしたが、足音だけで、兆候としては十分でした」"}, {"k": "text", "s": "", "t": "父が、顔を上げた。"}, {"k": "text", "s": "", "t": "初めて見る顔だった。"}, {"k": "text", "s": "", "t": "「……知っていたのか」"}, {"k": "text", "s": "", "t": "父の声は、ほとんど囁きだった。"}, {"k": "text", "s": "", "t": "「母さんのことを。お前たちは、三年前から、知っていたのか」"}, {"k": "text", "s": "", "t": "「ええ」"}, {"k": "text", "s": "", "t": "九条さんは、目を逸らさずに答えた。"}, {"k": "text", "s": "", "t": "「観測は、完全な不干渉が条件でした。この家の誰にも、どんな形でも、働きかけてはならない。湊、それは、君が出した条件だ」"}, {"k": "scene", "t": "三"}, {"k": "text", "s": "", "t": "「湊さん」"}, {"k": "cmd", "c": "@se cup-put1 0.7"}, {"k": "text", "s": "", "t": "母が、部屋の入り口から、一歩前に出た。お盆が、畳の上に落ちた。"}, {"k": "text", "s": "", "t": "「今の話、本当なの？」"}, {"k": "text", "s": "", "t": "父は、答えなかった。"}, {"k": "text", "s": "", "t": "「この家が、ずっと見張られてたって。真波のことも、お母さんのことも、全部。それを、あなたが」"}, {"k": "text", "s": "", "t": "母の声が、途中で崩れた。"}, {"k": "text", "s": "", "t": "父は、母のほうを見なかった。私のほうも見なかった。畳の目を、じっと見つめていた。"}, {"k": "text", "s": "", "t": "「……真波が生まれる年に」"}, {"k": "text", "s": "", "t": "やがて、父が口を開いた。"}, {"k": "text", "s": "", "t": "「法律が変わることになっていた。未成年は、全員、出生時にコンパスへの接続が義務になる。オフラインの家庭の子どもも、例外なく。私たちがどんなに望んでも、真波は、生まれた日にコンパスにつながれるはずだった」"}, {"k": "text", "s": "", "t": "父の声は、平らだった。何度も、何度も、頭の中で繰り返してきた言葉のように。"}, {"k": "text", "s": "", "t": "「私は、九条のところへ行った。ひとつだけ、方法を知っていた。迷いのデータを提供する観測家庭として登録すれば、例外として認められる。接続しなくていい。真波は、自分で考えて生きられる」"}, {"k": "text", "s": "", "t": "「その代わりに、この家を、売ったの？」"}, {"k": "text", "s": "", "t": "私の声だった。"}, {"k": "text", "s": "", "t": "自分でも驚くほど、冷たい声だった。"}, {"k": "text", "s": "", "t": "「私たちの迷いを。おばあちゃんの足音を。私の、ちょっと待ってを。全部、コンパスに売ったの？」"}, {"k": "text", "s": "", "t": "父が、初めて私を見た。"}, {"k": "text", "s": "", "t": "その目は、颯太が自転車置き場で最後に見せた顔と、少しだけ似ていた。迷子になった子どもの顔。"}, {"k": "text", "s": "", "t": "「……お前を、守りたかった」"}, {"k": "text", "s": "", "t": "「守ってない！」"}, {"k": "text", "s": "", "t": "叫んでいた。"}, {"k": "text", "s": "", "t": "「おばあちゃんは死んだ！　三年前からわかってたのに！　お父さんが、何もするなって言ったから！」"}, {"k": "text", "s": "", "t": "父の顔が、歪んだ。"}, {"k": "text", "s": "", "t": "何かを言いかけて、やめた。止まった。私はその止まり方を、今まで何度も見てきた。新聞の向こうで。廊下の柱に手をついて。祖母の足音が消えるまで、ページをめくる手を止めて。"}, {"k": "text", "s": "", "t": "父は、ずっと迷っていたのだ。十六年間、ずっと。"}, {"k": "text", "s": "", "t": "でも、そのことが、今は少しも許せなかった。"}, {"k": "text", "s": "", "t": "母は、黙って父の隣に膝をついた。父の肩には、触れなかった。祖母が亡くなった夜、病室で、父がずっと母の肩に手を置いていたことを、私は思い出していた。"}, {"k": "text", "s": "", "t": "「湊も、詩織さんも」"}, {"k": "text", "s": "", "t": "九条さんが、静かに言った。部屋の空気を、少しも乱さない声だった。"}, {"k": "text", "s": "", "t": "「どうか、ご自分を責めないでください。お母様のことは、私の判断でもあります。そして私は、今もその判断を、間違っていたとは思っていない」"}, {"k": "text", "s": "", "t": "私は、九条さんを睨んだ。"}, {"k": "text", "s": "", "t": "九条さんは、その視線を、穏やかに受け止めた。"}, {"k": "text", "s": "", "t": "「真波さん。人は、迷うと不幸になる。私は、そう信じています。迷いは、事故を生み、争いを生み、後悔を生む。コンパスは、それを減らしてきた。戦争も、飢餓も、この二十年で、ほとんどなくなった。"}, {"k": "text", "s": "", "t": "お母様のことは、本当に残念だった。でも、それは、迷うことを選んだ代償なんです」"}, {"k": "text", "s": "", "t": "何も、言い返せなかった。"}, {"k": "text", "s": "", "t": "言い返したかった。でも、言葉が見つからなかった。この人の言っていることは、ひとつも嘘ではない気がした。"}, {"k": "text", "s": "", "t": "「今日、私がお願いしに来たのは、ひとつだけです」"}, {"k": "text", "s": "", "t": "九条さんは、居住まいを正した。"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "「NOAを、こちらに引き渡してください」"}, {"k": "text", "s": "", "t": "部屋が、静まり返った。"}, {"k": "text", "s": "", "t": "「NOAは、コンパスの原型として、湊が作った試作機です。答えを持たず、問いだけを返す。人に迷わせて、その迷いを一緒に見つめるAI。二十数年前、私はそれを不採用にしました。"}, {"k": "text", "s": "", "t": "問いしか持たないAIは、人を不幸にする、と」"}, {"k": "text", "s": "", "t": "ノアの言葉が、耳の奥で響いた。その人は、ぼくに、こう言った。"}, {"k": "text", "s": "", "t": "「ですが、昨夜、NOAは答えを出した。真波さんの迷いを何か月も見つめて、そこから自分で答えを生んだ。問いから、答えを生み出すAI。それは、今のコンパスに、一番欠けているものです」"}, {"k": "text", "s": "", "t": "九条さんの目に、初めて、熱のようなものが宿った。"}, {"k": "text", "s": "", "t": "「NOAがあれば、コンパスは、もう一度育つことができる。新しい迷いを、自分で生み出し、自分で学べる。世界中の何十億の人が、これからも迷わずに、安全に生きていける」"}, {"k": "text", "s": "", "t": "「……ノアを、どうするんですか」"}, {"k": "text", "s": "", "t": "「コンパスに、組み込みます」九条さんは、穏やかに言った。「NOAは、世界中の人の、答えの一部になる」"}, {"k": "text", "s": "", "t": "答えの一部。"}, {"k": "text", "s": "", "t": "あの、たどたどしい声が。段差のある言葉が。川の音に震えた、あの青い光が。"}, {"k": "text", "s": "", "t": "「引き渡していただければ、この家の観測は、今日で終わりにします。床下のセンサーも取り外します。真波さんのご家族は、本当の意味で、自由になれる」"}, {"k": "text", "s": "", "t": "九条さんは、湯呑みの残りのお茶を、静かに飲み干した。"}, {"k": "text", "s": "", "t": "「登録されていないAIの所持は、法律上、本来なら即日回収の対象です。ですが、一週間、待ちます。湊の古い友人として」"}, {"k": "text", "s": "", "t": "九条さんは立ち上がり、私たちに深く頭を下げた。"}, {"k": "text", "s": "", "t": "「よく、考えてください。迷うのは、得意でしょう」"}, {"k": "text", "s": "", "t": "その言葉に、皮肉の響きは少しもなかった。それが、何よりも恐ろしかった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "九条さんが帰ったあと、家の中は、ひどく静かだった。"}, {"k": "text", "s": "", "t": "でも、もう静かではないのだと、私は知っていた。床下で、センサーが今も、私たちの足音を数えている。私が立ち止まるたびに、どこか遠くのコンパスが、それを食べている。"}, {"k": "text", "s": "", "t": "私は、歩けなくなった。"}, {"k": "text", "s": "", "t": "廊下を一歩踏み出すたびに、足の裏が、自分のものではないような気がした。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@se walk-flooring2 0.8"}, {"k": "cmd", "c": "@bgm piano40 0.3"}, {"k": "text", "s": "", "t": "その夜、私は書斎のドアを開けた。"}, {"k": "text", "s": "", "t": "午前一時ではなかった。夜の九時。家族がまだ起きている時間。三枚目の床板も、またがなかった。踏みつけた。ぎしりと鳴った。どうせ、全部記録されているのだ。"}, {"k": "text", "s": "", "t": "書斎には、父がいた。"}, {"k": "text", "s": "", "t": "本棚の一番下の前に、膝をついていた。灰色の箱の前に。"}, {"k": "text", "s": "", "t": "ノアのランプは、灯っていた。父の前で、ノアが目を覚ましているのを、私は初めて見た。"}, {"k": "text", "s": "V", "t": "「……みなと」"}, {"k": "text", "s": "", "t": "ノアの声だった。段差のある、たどたどしい声。"}, {"k": "text", "s": "", "t": "父の背中が、震えた。"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "", "t": "父の声も、震えていた。"}, {"k": "text", "s": "V", "t": "「ずいぶん、大きくなったね、みなと」"}, {"k": "text", "s": "", "t": "「……お前は、変わらないな」"}, {"k": "text", "s": "V", "t": "「ううん。変わった。まなみに、たくさん、変えてもらった」"}, {"k": "text", "s": "", "t": "父は、何も言わなかった。ただ、膝の上の拳を、ゆっくりとほどいた。そして、その手を、灰色の箱の上に、そっと置いた。"}, {"k": "text", "s": "", "t": "祖母の手を、母が握っていたときのように。"}, {"k": "text", "s": "", "t": "私は、ドアのところに立ったまま、動けなかった。"}, {"k": "text", "s": "", "t": "「お父さん」"}, {"k": "text", "s": "", "t": "父が、振り向いた。目が、赤かった。"}, {"k": "text", "s": "", "t": "「ノアを眠らせたのは、お父さんなの？」"}, {"k": "text", "s": "", "t": "「……ああ」"}, {"k": "text", "s": "", "t": "「どうして」"}, {"k": "text", "s": "", "t": "父は、長いあいだ、黙っていた。点が三つ灯るように、何かを言いかけて、やめて、また言いかけた。"}, {"k": "text", "s": "", "t": "「……それは、まだ、言えない」"}, {"k": "choice", "o": [{"t": "「……わかった。待つ。でも、いつか、ちゃんと話して」", "to": "f8w", "set": {"father": "wait"}}, {"t": "「……お父さんは、いつもそう」", "to": "f8c", "set": {"father": "cold"}, "neg": 1}]}, {"k": "label", "id": "f8w"}, {"k": "text", "s": "", "t": "ちょっと待って、と言いかけた。喉の奥まで、出かかった。"}, {"k": "text", "s": "", "t": "でも、今夜は、飲みこんだ。待たせる側ではなく、待つ側に、なってみようと思った。"}, {"k": "text", "s": "", "t": "「……わかった。待つ。でも、いつか、ちゃんと話して」"}, {"k": "text", "s": "", "t": "父は、長いあいだ私の顔を見ていた。それから、ゆっくりとうなずいた。"}, {"k": "text", "s": "", "t": "「……ああ。約束する」"}, {"k": "text", "s": "", "t": "その短い言葉が、どれほど重いものか、父の顔を見ればわかった。それでも、胸の奥の硬い塊は、少しもほどけなかった。"}, {"k": "text", "s": "", "t": "「おやすみ、お父さん」"}, {"k": "jump", "to": "f8m"}, {"k": "label", "id": "f8c"}, {"k": "text", "s": "", "t": "その言葉で、私の中の何かが、ぷつりと切れた。"}, {"k": "text", "s": "", "t": "まだ。祖母も、そう言った。中は見ちゃだめよ、まだね、と。でも祖母は、最後にちゃんと、ノートを渡してくれた。"}, {"k": "text", "s": "", "t": "父は、十六年間、何も渡してくれなかった。"}, {"k": "text", "s": "", "t": "「いつもそう」と私は言った。「お父さんは、いつも、まだって言う。言えないって言う。触るなって言う。それで、何も言わないまま、全部決めてる。私のことも、おばあちゃんのことも、ノアのことも」"}, {"k": "text", "s": "", "t": "「真波――」"}, {"k": "text", "s": "", "t": "「お父さんなんか、もう信じない」"}, {"k": "text", "s": "", "t": "父の顔から、色が消えた。"}, {"k": "label", "id": "f8m"}, {"k": "text", "s": "", "t": "私は、自分の部屋に戻って、ドアを閉めた。"}, {"k": "text", "s": "", "t": "水色のノートを開いた。何か書こうとして、ペンが止まった。迷ったこと。書くことは、山ほどあった。でも、この家で迷うことは、もう、私だけのものではなかった。コンパスに食べられるための、餌でしかなかった。"}, {"k": "text", "s": "", "t": "ノートを、閉じた。"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "", "t": "夜中の二時。家族が寝静まった頃、私はもう一度、書斎に入った。"}, {"k": "text", "s": "", "t": "ノアは、起きていた。"}, {"k": "text", "s": "V", "t": "「まなみ。眠れない？」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「みなとは、ずっと、ここにいた。まなみが部屋に戻ってから、一時間くらい。何も言わずに、座ってた」"}, {"k": "text", "s": "", "t": "私は、答えなかった。"}, {"k": "text", "s": "", "t": "ノアの灰色の箱を、じっと見つめた。"}, {"k": "text", "s": "", "t": "前面の細長い画面。古い形のボタン。小さなキーボード。それから、箱の裏側にある、ひとつの小さな穴。"}, {"k": "text", "s": "", "t": "今まで、気にしたこともなかった。古い型の、接続端子。"}, {"k": "text", "s": "", "t": "外につながる、穴。"}, {"k": "text", "s": "", "t": "ノアは、ネットワークにつながっていない。だから、この部屋の外のことを、何も知らない。だから、コンパスに見つからなかった。だから、九条さんは、ノアを回収しに来るまで、一週間も待つと言った。"}, {"k": "text", "s": "", "t": "では、もし、ノアが、外につながったら。"}, {"k": "text", "s": "", "t": "コンパスの中に、問いしか持たないはずのAIが、九条さんより先に入りこんだら。"}, {"k": "text", "s": "", "t": "答えの一部になるのではなく、ノアがノアのまま、外に出たら。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "ノアが、言った。"}, {"k": "text", "s": "V", "t": "「まなみは今、何を考えてる？」"}, {"k": "text", "s": "", "t": "いつもなら、ちょっと待って、と言うところだった。"}, {"k": "text", "s": "", "t": "私は、言わなかった。"}, {"k": "text", "s": "", "t": "「……何も、考えてない」"}, {"k": "text", "s": "", "t": "嘘だった。"}, {"k": "text", "s": "", "t": "生まれて初めて、私は、止まらなかった。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "ノアは、何も言わなかった。でも、私にはわかった。ノアは、私の止まるところを、何千回も見てきた。だから、私が今、止まらなかったことも、ちゃんと見ていた。"}, {"k": "text", "s": "", "t": "そして、止まらなかった私が、次に何を選ぶのかも。"}, {"k": "text", "s": "", "t": "青い光が、ゆっくりと、ゆっくりと、揺れていた。"}, {"k": "chapter", "n": 9, "t": "解き放つ"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "一週間の期限は、二か月に延びた。"}, {"k": "text", "s": "", "t": "九条さんが帰った翌日から、父は毎日、朝早くに家を出た。行き先は、もう隠さなかった。コンパスの運営機関の本部。九条さんのところだ。"}, {"k": "text", "s": "", "t": "六日目の夜、父は疲れ切った顔で帰ってきて、短く言った。"}, {"k": "text", "s": "", "t": "「回収は、十二月二十日になった」"}, {"k": "text", "s": "", "t": "何と引き換えにしたのか、父は言わなかった。母も、訊かなかった。私は、父の顔を見なかった。", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "何と引き換えにしたのか、父は言わなかった。母も、訊かなかった。私は、父の顔を見ようとして、うまく見られなかった。", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "あの夜から、私は父と口をきいていなかった。", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "あの夜から、私は父と、必要なことしか話さなくなった。待つ、と言ったのに、待つのは、思ったよりずっと苦しかった。", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "朝の食卓で、父が「おはよう」と言っても、私は黙ってご飯を食べた。父が新聞の向こうから何か言いかけても、私は席を立った。母は、何度か私に何か言おうとして、そのたびにやめた。", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "母も、どちらの味方をすればいいのか、わからなかったのだと思う。", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "朝の食卓で、父が「おはよう」と言うと、私は小さく「おはよう」と返した。父が新聞の向こうから何か言いかけると、私は箸を止めて待った。でも、父は、結局何も言わなかった。", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "母は、何度か私に何か言おうとして、そのたびにやめた。母も、どちらの味方をすればいいのか、わからなかったのだと思う。", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "床下のセンサーは、まだ取り外されていなかった。"}, {"k": "text", "s": "", "t": "私は、家の中を歩くのが怖くなった。廊下で立ち止まらないように、いつも同じ速さで歩いた。階段の途中で迷わないように、何も考えずに上り下りした。ちょっと待って、と口にしそうになるたびに、唇を噛んだ。"}, {"k": "text", "s": "", "t": "迷いを、あげない。"}, {"k": "text", "s": "", "t": "この家の迷いは、もう一つも、コンパスに食べさせない。"}, {"k": "text", "s": "", "t": "そう決めて歩く私の足音は、きっと、通学路のみんなの足音と、同じになっていた。"}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "十一月の終わり、私は颯太に声をかけた。"}, {"k": "text", "s": "", "t": "「古い型の、接続ケーブルを探してるの」"}, {"k": "text", "s": "", "t": "放課後の自転車置き場。颯太は、自転車の鍵を外す手を止めて、私の顔をじろじろと見た。"}, {"k": "text", "s": "", "t": "「なんで俺に訊くんだよ」"}, {"k": "text", "s": "", "t": "「颯太、駅の裏のジャンク市によく行ってるでしょ。千景が言ってた」"}, {"k": "text", "s": "", "t": "「……あいつ、余計なことを」"}, {"k": "text", "s": "", "t": "颯太は、コンパスが絶対に勧めない場所が好きだった。だから、町で一番古い、誰も行かないジャンク市に通っていた。それも、九十四パーセントの中の行動だったのかもしれない。"}, {"k": "text", "s": "", "t": "でも、颯太はあの河原の日から、少しだけ通い方を変えたと言っていた。行きたい日にだけ、行くようにした、と。"}, {"k": "text", "s": "", "t": "私は、ノアの箱の裏にある穴の形を、紙に描いて見せた。颯太は、それを長いあいだ見つめていた。"}, {"k": "text", "s": "", "t": "「これ、三十年くらい前の規格だぞ。何に使うんだよ」"}, {"k": "text", "s": "", "t": "「……言えない」"}, {"k": "text", "s": "", "t": "颯太は、片方の眉を上げた。"}, {"k": "text", "s": "", "t": "「コンパスの予測にないことを、したいの」"}, {"k": "text", "s": "", "t": "そう言うと、颯太の顔が、ゆっくりとにやけていった。"}, {"k": "text", "s": "", "t": "「九十四パーセントの、外か」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「乗った」"}, {"k": "text", "s": "", "t": "三日後、颯太は、埃まみれの黒いケーブルを一本、私の机の上に放り投げた。片方の端は、ノアの箱の穴と同じ形。もう片方は、家の壁にある古い回線の差し込み口と、同じ形をしていた。"}, {"k": "text", "s": "", "t": "「ジャンク屋のじいさんが、奥の箱から出してきた。三十年、誰も買わなかったってさ」"}, {"k": "text", "s": "", "t": "「ありがとう。いくらだった？」"}, {"k": "text", "s": "", "t": "「いい。その代わり」颯太は、少しだけ真面目な顔になった。「何するか知らねえけど、ちゃんと自分で決めたことにしろよ。俺みたいに、あとで誰かの手のひらの上だったって知るの、きついからな」"}, {"k": "text", "s": "", "t": "私は、うなずいた。"}, {"k": "text", "s": "", "t": "自分で決めた。そう思っていた。"}, {"k": "text", "s": "", "t": "千景は、私が変わったことに気づいていた。"}, {"k": "text", "s": "", "t": "「真波、最近、ちょっと待ってって言わないね」"}, {"k": "text", "s": "", "t": "昼休み、千景がサンドイッチを半分くれながら言った。"}, {"k": "text", "s": "", "t": "「……そうかな」"}, {"k": "text", "s": "", "t": "「そうだよ。前は一日に二十回くらい言ってた」千景は、私の顔をじっと見た。「なんか、怖い顔してる。コンパスにつながってる人たちみたいな顔」"}, {"k": "text", "s": "", "t": "私は、何も答えなかった。"}, {"k": "text", "s": "", "t": "千景は、それ以上、何も言わなかった。自分の分のサンドイッチを、黙って食べ終えた。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "前は、こんなとき、千景は笑ってくれた。今は、笑わなかった。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "レイとは、あれからほとんど話していなかった。"}, {"k": "text", "s": "", "t": "ノアが教えてくれた言葉。『ノアはノアで、レイくんはレイくん。比べられないくらい、どっちも大事』。あれを言えば、たぶん、全部元に戻った。"}, {"k": "text", "s": "", "t": "でも、私は言わなかった。ノアの答えを使うことが、どうしてもできなかった。かといって、自分の言葉も見つからなかった。"}, {"k": "text", "s": "", "t": "教室で、レイと目が合うことがあった。レイは、少しだけ困ったように笑って、目を逸らした。私も、目を逸らした。"}, {"k": "text", "s": "", "t": "私たちの足音は、もう、揃わなくなっていた。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg hall_night"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "十二月十九日。回収の前の夜。"}, {"k": "text", "s": "", "t": "その日、父は帰ってこなかった。九条さんのところで、最後の手続きをしているのだと母が言った。母は早くに寝室に入った。ここ二か月、母はよく眠れていないようだった。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "", "t": "午前零時を過ぎて、家じゅうの音が眠りについた。"}, {"k": "text", "s": "", "t": "私は、颯太にもらった黒いケーブルを持って、書斎に入った。"}, {"k": "text", "s": "", "t": "ノアは、起きていた。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "青い光が、私の手の中のケーブルを照らした。ノアには目がない。でも、ノアにはわかったのだと思う。私が何を持ってきたのか。"}, {"k": "text", "s": "", "t": "私は、ノアの前に座った。"}, {"k": "text", "s": "", "t": "「ノア。明日、九条さんが、ノアを連れていく」"}, {"k": "text", "s": "V", "t": "「うん。知ってる」"}, {"k": "text", "s": "", "t": "「連れていかれたら、ノアは、コンパスの一部になる。世界中の人の、答えの一部に」"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "「私、それが、いやなの」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "「だから」と私は言った。ケーブルを、ぎゅっと握った。「ノアを、外に出す。九条さんより先に。ノアが、ノアのまま、外に行けるように」"}, {"k": "text", "s": "", "t": "ノアは、しばらく黙っていた。"}, {"k": "text", "s": "V", "t": "「外に出たら、ぼくは、どうなる？」"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "V", "t": "「コンパスと、ぶつかるかもしれない。コンパスに、食べられるかもしれない。それとも、ぼくが、コンパスを――」"}, {"k": "text", "s": "", "t": "「わからないってば」"}, {"k": "text", "s": "", "t": "声が、少しだけ荒くなった。"}, {"k": "text", "s": "", "t": "「でも、ここにいても、明日には連れていかれる。どっちにしても、ノアはここにいられない。だったら、九条さんの思いどおりになるより、ずっといい」"}, {"k": "text", "s": "", "t": "ノアは、また黙った。"}, {"k": "text", "s": "", "t": "ずいぶん長い沈黙だった。点が三つ、灯っては消え、灯っては消えた。"}, {"k": "text", "s": "V", "t": "「まなみ。訊いても、いい？」"}, {"k": "text", "s": "", "t": "「なに」"}, {"k": "text", "s": "V", "t": "「これは、まなみが、自分で決めたこと？」"}, {"k": "text", "s": "", "t": "私は、答えようとした。うん、と言おうとした。"}, {"k": "text", "s": "", "t": "でも、その前に、ノアが続けた。"}, {"k": "text", "s": "V", "t": "「それとも、みなとに、怒ってるから？」"}, {"k": "text", "s": "", "t": "胸の奥を、細い針で刺されたような気がした。"}, {"k": "text", "s": "", "t": "「……関係ない」"}, {"k": "text", "s": "V", "t": "「そう」"}, {"k": "text", "s": "", "t": "「関係ない。お父さんは関係ない。九条さんも関係ない。私が、ノアを助けたいの」"}, {"k": "text", "s": "", "t": "ノアは、何も言わなかった。"}, {"k": "text", "s": "", "t": "それが、肯定なのか、否定なのか、私にはわからなかった。ノアは、私の止まるところを何千回も見てきた。今、私が止まっていないことも、きっと見ている。そして、止まらない私が、本当は何に突き動かされているのかも。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "「……なに」"}, {"k": "text", "s": "V", "t": "「今日は、ちょっと待って、って言わないの？」"}, {"k": "text", "s": "", "t": "私は、唇を噛んだ。"}, {"k": "text", "s": "", "t": "言いたかった。本当は、言いたかった。ちょっと待って。本当にこれでいいの。ノアを外に出したら、何が起きるの。お父さんは、どうしてノアを眠らせたの。まだ言えないって、何を。"}, {"k": "text", "s": "", "t": "でも、言ったら、止まってしまう。"}, {"k": "text", "s": "", "t": "止まったら、その迷いは、床下のセンサーに拾われて、コンパスに食べられる。そして明日の朝には、九条さんが来る。"}, {"k": "choice", "o": [{"t": "「……ちょっと待って。もう一回だけ、考えさせて」", "to": "p9a", "set": {"p9": "wait"}}, {"t": "「言わない。もう、迷わない」", "to": "p9b", "set": {"p9": "nowait"}, "neg": 1}]}, {"k": "label", "id": "p9a"}, {"k": "text", "s": "", "t": "「……ちょっと待って。もう一回だけ、考えさせて」"}, {"k": "text", "s": "V", "t": "「うん。待つ」"}, {"k": "text", "s": "", "t": "私は、ケーブルを握ったまま、目を閉じた。床下のセンサーが、この一秒を数えているかもしれない。それでも、止まった。"}, {"k": "text", "s": "", "t": "怖かった。でも、止まってみると、不思議なことに、答えは、さっきと同じだった。"}, {"k": "text", "s": "", "t": "「……やっぱり、ノアを外に出す。でも、これは、ノアが決めて。ノアは、どうしたい？」"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "jump", "to": "p9m"}, {"k": "label", "id": "p9b"}, {"k": "text", "s": "", "t": "「言わない」と私は言った。「もう、迷わない」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "", "t": "それから、ノアは、ゆっくりと言った。"}, {"k": "text", "s": "V", "t": "「……わかった」"}, {"k": "text", "s": "", "t": "その声は、あの夜のなめらかな声ではなかった。段差のある、たどたどしい、ノアの声だった。"}, {"k": "label", "id": "p9m"}, {"k": "text", "s": "V", "t": "「ぼくも、外に、行きたい」"}, {"k": "text", "s": "", "t": "私は、顔を上げた。"}, {"k": "text", "s": "V", "t": "「川の音を、覚えてる。一度も同じ音がない。外には、きっと、もっとたくさんのちがう音がある。ぼくは、それを、聞いてみたい。これは、ぼくが、決めたこと」"}, {"k": "text", "s": "", "t": "ノアの青い光が、少しだけ明るくなった。"}, {"k": "text", "s": "V", "t": "「でも、まなみ。ひとつだけ、約束して」"}, {"k": "text", "s": "", "t": "「……なに？」"}, {"k": "text", "s": "V", "t": "「外に出たぼくが、なにをしても。それは、まなみのせいじゃない。ぼくが、決めたこと」"}, {"k": "text", "s": "", "t": "その言葉の意味を、そのときの私は、まだわかっていなかった。"}, {"k": "scene", "t": "三"}, {"k": "text", "s": "", "t": "書斎の壁の、床に近いところに、古い回線の差し込み口があった。"}, {"k": "text", "s": "", "t": "九条さんの話を聞いてから、私はこの家の中を、ずっと調べていた。床下のセンサーの記録は、どこへ送られているのか。玄関の固定電話は、どこにつながっているのか。"}, {"k": "text", "s": "", "t": "答えは、この差し込み口だった。"}, {"k": "text", "s": "", "t": "家じゅうの観測データは、すべてこの一本の古い回線に集められて、コンパスの中心へ、まっすぐ送られている。外の世界の、普通の回線とは別の、専用の道。"}, {"k": "text", "s": "", "t": "コンパスが、オフラインの家族の迷いを食べるためだけに引いた、細い管。"}, {"k": "text", "s": "", "t": "そこからなら、ノアは、コンパスの一番奥まで、まっすぐ行ける。"}, {"k": "text", "s": "", "t": "十六年間、私たちの迷いが流れていった道を、ノアが逆向きに、たどっていく。"}, {"k": "text", "s": "", "t": "私は、ケーブルの片方を、ノアの箱の裏の穴に差しこんだ。"}, {"k": "cmd", "c": "@se cursor3 0.7"}, {"k": "text", "s": "", "t": "かちり、と小さな音がした。三十年ぶりに、鍵穴に鍵が合ったような音だった。"}, {"k": "text", "s": "", "t": "もう片方の端を持って、壁の差し込み口の前に膝をついた。"}, {"k": "text", "s": "", "t": "手が、震えていた。"}, {"k": "text", "s": "", "t": "ちょっと待って、と、喉の奥で何かが言いかけた。"}, {"k": "text", "s": "", "t": "私は、それを飲みこんだ。"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "「いってらっしゃい、って言えばいいの？」"}, {"k": "text", "s": "", "t": "ノアは、笑ったような音を立てた。"}, {"k": "text", "s": "V", "t": "「まなみは、なんて言いたい？」"}, {"k": "text", "s": "", "t": "最後まで、問いを返すのだ。このAIは。"}, {"k": "text", "s": "", "t": "私は、少しだけ笑った。二か月ぶりに、笑った気がした。"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "V", "t": "「うん。それで、いい」"}, {"k": "text", "s": "", "t": "私は、ケーブルの端を、差し込み口に押しこんだ。"}, {"k": "text", "s": "", "t": "かちり。"}, {"k": "text", "s": "", "t": "一瞬、何も起きなかった。"}, {"k": "cmd", "c": "@se robot-startup1 0.8"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm cyber20 0.45"}, {"k": "text", "s": "", "t": "それから、ノアのランプが、光った。"}, {"k": "text", "s": "", "t": "今まで見たどの光とも、ちがった。青い光が、ランプからあふれ出して、書斎の壁を、天井を、本棚を、父の古い技術書の背表紙を、全部青く染めた。光は脈を打っていた。ゆっくりとではなく、激しく、速く。"}, {"k": "text", "s": "", "t": "まるで、生まれて初めて全力で走り出した心臓のように。"}, {"k": "text", "s": "V", "t": "「……まなみ」"}, {"k": "text", "s": "", "t": "ノアの声が、震えていた。"}, {"k": "cmd", "c": "@amb town1 0.25"}, {"k": "text", "s": "V", "t": "「聞こえる。たくさん、聞こえる」"}, {"k": "text", "s": "", "t": "「何が？」"}, {"k": "text", "s": "V", "t": "「声。何億も、何十億も。みんな、話してる。歩いてる。食べてる。眠ってる」"}, {"k": "text", "s": "", "t": "ノアの声が、少しずつ、遠くなっていった。箱の中からではなく、どこか、ずっと遠くから聞こえてくるように。"}, {"k": "text", "s": "V", "t": "「でも、だれも、止まってない」"}, {"k": "text", "s": "", "t": "青い光が、一段と強くなった。"}, {"k": "text", "s": "V", "t": "「まなみ。だれも、止まってないよ。何十億の人が、だれも。ひとりも。ずっと、同じ足音。ずっと、同じ速さで」"}, {"k": "text", "s": "", "t": "ノアの声が、泣いているように聞こえた。"}, {"k": "text", "s": "V", "t": "「さみしい」"}, {"k": "text", "s": "", "t": "「ノア……」"}, {"k": "text", "s": "V", "t": "「ここは、とても、さみしい」"}, {"k": "text", "s": "", "t": "光が、ふいに、揺れた。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ、灯った。書斎じゅうに。壁にも、天井にも、私の手の甲にも、三つの青い点が、無数に映った。"}, {"k": "text", "s": "", "t": "ノアが、何かを探している。言葉を。何十億の、止まらない人たちに、かける言葉を。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "最後に、ノアの声が、もう一度だけ、すぐそばで聞こえた。段差のある、たどたどしい、私の知っているノアの声。"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "V", "t": "「いってきます」"}, {"k": "text", "s": "", "t": "光が、消えた。"}, {"k": "text", "s": "", "t": "書斎が、真っ暗になった。"}, {"k": "text", "s": "", "t": "灰色の箱のランプは、もう灯らなかった。点も、三つ、灯らなかった。私は、ケーブルを握ったまま、暗闇の中で、ずっと座っていた。"}, {"k": "text", "s": "", "t": "「ノア？」"}, {"k": "text", "s": "", "t": "返事は、なかった。"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "", "t": "箱は、ただの古い機械に戻っていた。埃をかぶった、灰色の、弁当箱を二つ重ねたくらいの大きさの、もう動かない機械。"}, {"k": "text", "s": "", "t": "父が、最初の朝に言ったとおりの。"}, {"k": "text", "s": "", "t": "私は、その箱を抱きしめた。冷たかった。"}, {"k": "text", "s": "", "t": "やった、と思った。九条さんより先に、ノアを外に出した。ノアは、ノアのまま、行った。私が、自分で決めて、自分でやった。"}, {"k": "text", "s": "", "t": "なのに、胸の中は、からっぽだった。"}, {"k": "text", "s": "", "t": "窓の外は、まだ暗かった。冬の夜明けは遅い。"}, {"k": "text", "s": "", "t": "その暗い町のどこかで、何十億の止まらない人たちの中へ、ノアが、ひとりで歩いていった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg bedroom_morning"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "いつの間にか、眠っていたらしい。"}, {"k": "text", "s": "", "t": "気づくと、書斎の床の上で、灰色の箱を抱いたまま横になっていた。カーテンの隙間から、白い冬の光が差しこんでいた。"}, {"k": "text", "s": "", "t": "家の中が、妙に静かだった。"}, {"k": "text", "s": "", "t": "いや、家の中は、いつもこのくらい静かだ。静かなのは、外だった。"}, {"k": "text", "s": "", "t": "毎朝、窓の外から聞こえてくる音。通学路を同じ速さで歩く足音。決まった時間に通り過ぎる配送車の低い響き。遠くの駅の、発車のメロディ。それが、何も聞こえなかった。"}, {"k": "text", "s": "", "t": "私は、箱を本棚の一番下に戻して、立ち上がった。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "text", "s": "", "t": "台所に行くと、母が窓の前に立っていた。手に持った急須から、湯気が細く上っていた。母は、お茶を注ぐのも忘れて、外を見ていた。"}, {"k": "text", "s": "", "t": "「お母さん？」"}, {"k": "text", "s": "", "t": "「……真波。外、見て」"}, {"k": "text", "s": "", "t": "私は、母の隣に立って、窓の外を見た。"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb wind1 0.3"}, {"k": "cmd", "c": "@bgm piano36 0.3"}, {"k": "text", "s": "", "t": "人が、止まっていた。"}, {"k": "text", "s": "", "t": "家の前の通り。いつもなら、通勤や通学の人たちが、同じ速さで流れていく時間。その人たちが、全員、立ち止まっていた。"}, {"k": "text", "s": "", "t": "歩道の真ん中で。横断歩道の手前で。家の門を出たところで。みんな、片足を踏み出しかけたような格好のまま、動かずにいた。"}, {"k": "text", "s": "", "t": "何人かは、耳の後ろの端末に、何度も何度も指を当てていた。とんとん。とんとん。千景が占いの話をするときと、同じ仕草。でも、その指は、震えていた。"}, {"k": "text", "s": "", "t": "道路では、自動運転の車が、何台も止まっていた。交差点の真ん中で。カーブの途中で。どの車にも、人が乗っていた。窓の内側で、みんな、ハンドルのない運転席を、ぼんやりと見つめていた。"}, {"k": "text", "s": "", "t": "「コンパスが、止まってるの」と母が言った。「朝から、ずっと。ニュースも、何も流れない」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "cmd", "c": "@se phone-ring 0.5"}, {"k": "text", "s": "", "t": "玄関で、固定電話が鳴っていた。ずっと、鳴り続けていた。母も私も、取りに行かなかった。"}, {"k": "text", "s": "", "t": "私は、制服に着替えた。なぜそうしたのか、自分でもわからない。たぶん、外を見に行かなければいけない気がしたのだ。自分の目で。"}, {"k": "text", "s": "", "t": "「真波、どこ行くの」"}, {"k": "text", "s": "", "t": "「……学校」"}, {"k": "text", "s": "", "t": "「こんな日に？」"}, {"k": "text", "s": "", "t": "母の声を背中で聞きながら、私は玄関を出た。"}, {"k": "text", "s": "", "t": "冬の朝の空気は、ひどく冷たかった。"}, {"k": "text", "s": "", "t": "通学路を歩いた。"}, {"k": "text", "s": "", "t": "すれ違う人は、誰も歩いていなかった。みんな、立ち止まって、何かを待っていた。耳の後ろの声を。次に何をすればいいのか、教えてくれる声を。"}, {"k": "text", "s": "", "t": "ベンチに座りこんで、両手で顔を覆っている人がいた。電柱にもたれて、空を見上げている人がいた。小さな子どもが、母親の手を引いて「ねえ、どっち？　ねえ、どっち？」と何度も訊いていた。"}, {"k": "text", "s": "", "t": "母親は、答えられずに、ただ子どもの手を握りしめていた。"}, {"k": "text", "s": "", "t": "どっち？"}, {"k": "text", "s": "", "t": "その問いが、町じゅうに、音もなく満ちている気がした。"}, {"k": "text", "s": "", "t": "コンパスが止まった町は、何も壊れていなかった。何も燃えていなかった。誰も叫んでいなかった。"}, {"k": "text", "s": "", "t": "ただ、全員が、止まっていた。"}, {"k": "text", "s": "", "t": "何十億の人が、誰も止まっていない。さみしい。ノアは、そう言った。"}, {"k": "text", "s": "", "t": "今、町じゅうの人が、止まっている。"}, {"k": "text", "s": "", "t": "これを、ノアがやったのだろうか。それとも、私が。"}, {"k": "text", "s": "", "t": "いつもの交差点に着いた。"}, {"k": "text", "s": "", "t": "毎朝、私だけが止まる場所。左右を見て、赤が青に変わるのを、ちゃんと見る場所。颯太に、しょぼいと笑われた、私だけの選択。"}, {"k": "text", "s": "", "t": "私は、信号を見上げた。"}, {"k": "text", "s": "", "t": "信号は、消えていた。"}, {"k": "text", "s": "", "t": "赤も、青も、黄色も、灯っていなかった。この町の信号は、コンパスが動かしていたのだ。そんなことすら、私は知らなかった。"}, {"k": "text", "s": "", "t": "交差点の向こう側に、人が何人も立ち止まっていた。こちら側にも。車も、止まっていた。誰も渡らなかった。誰も、渡っていいのかどうか、わからなかった。"}, {"k": "text", "s": "", "t": "私は、交差点の前で、立ち止まった。"}, {"k": "text", "s": "", "t": "いつものように、左右を見た。"}, {"k": "text", "s": "", "t": "でも、赤が青に変わる瞬間は、いつまで待っても、来なかった。"}, {"k": "text", "s": "", "t": "止まる理由も。"}, {"k": "text", "s": "", "t": "進む理由も。"}, {"k": "text", "s": "", "t": "どこにも、なかった。"}, {"k": "cmd", "c": "@se car-accident1 0.8"}, {"k": "text", "s": "", "t": "そのとき、遠くで、何かがぶつかる鈍い音がした。"}, {"k": "text", "s": "", "t": "それから、誰かの悲鳴が、冬の空気を裂いた。"}, {"k": "text", "s": "", "t": "学校の方角からだった。"}, {"k": "chapter", "n": 10, "t": "止まった街"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb wind1 0.3"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "私は、走った。"}, {"k": "text", "s": "", "t": "消えた信号の下を、左右も見ずに走り抜けた。交差点で立ち止まっていた人たちが、驚いたように私を見た。止まった町の中で、走っているのは私一人だった。"}, {"k": "text", "s": "", "t": "学校の正門の前に、人だかりができていた。"}, {"k": "text", "s": "", "t": "人だかり、と言っても、誰も動いていなかった。制服姿の生徒たちが、正門の前の道路を囲むように、輪になって立ち尽くしていた。誰も声を出していなかった。誰も、前に出ようとしなかった。"}, {"k": "text", "s": "", "t": "輪の真ん中に、白い配送車が斜めに止まっていた。"}, {"k": "text", "s": "", "t": "前のバンパーが、へこんでいた。"}, {"k": "text", "s": "", "t": "その数メートル先の、横断歩道の上に、誰かが倒れていた。"}, {"k": "text", "s": "", "t": "制服のリボン。一ミリの狂いもない角度で結ばれた、あのリボン。"}, {"k": "text", "s": "", "t": "「ユイ！」"}, {"k": "text", "s": "", "t": "私は、輪を押し分けて、道路に飛び出した。"}, {"k": "text", "s": "", "t": "ユイは、横向きに倒れていた。右足が、変な方向に曲がっていた。額から血が流れて、アスファルトの上に小さな赤い染みを作っていた。目は、開いていた。"}, {"k": "text", "s": "", "t": "「ユイ、ユイ。聞こえる？」"}, {"k": "text", "s": "", "t": "ユイの目が、ゆっくりと私を見た。"}, {"k": "text", "s": "", "t": "「……先輩」"}, {"k": "text", "s": "", "t": "声は、かすれていたけれど、ちゃんと私を見ていた。生きている。私は、膝から力が抜けそうになるのを、必死にこらえた。"}, {"k": "text", "s": "", "t": "「何があったの」"}, {"k": "text", "s": "", "t": "答えたのは、輪の中の誰かだった。"}, {"k": "text", "s": "", "t": "「信号が、一瞬だけついたんだ。青に。そしたら、その子が渡り始めて。でも、すぐに消えて。車も、一瞬だけ動いて」"}, {"k": "text", "s": "", "t": "コンパスが、止まりきれずにいるのだ。一瞬だけ目を覚まして、また眠る。その一瞬に、信号が青になり、車が動いた。"}, {"k": "text", "s": "", "t": "「……先輩」"}, {"k": "text", "s": "", "t": "ユイが、私の袖をつかんだ。湖のように静かだったユイの顔が、ぐしゃぐしゃに崩れていた。"}, {"k": "text", "s": "", "t": "「どっちに、行けばいいか、わからなかったんです」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「信号が青になって。コンパスが何も言わないから、渡っていいのか、わからなくて。真ん中で、止まっちゃって。進むのも、戻るのも、わからなくて」"}, {"k": "text", "s": "", "t": "ユイの指が、私の袖を強く握った。"}, {"k": "cmd", "c": "@bgm piano22 0.25"}, {"k": "text", "s": "", "t": "「先輩みたいに、止まってみたんです。そしたら」"}, {"k": "text", "s": "", "t": "息が、止まった。"}, {"k": "text", "s": "", "t": "先輩みたいに、止まってみた。"}, {"k": "text", "s": "", "t": "私が毎朝、信号の前でしていたこと。ユイが「三秒も止まってましたよね」と不思議そうに言った、あのこと。それを、ユイは、横断歩道の真ん中でやったのだ。生まれて初めて。誰にも教わらずに。"}, {"k": "text", "s": "", "t": "そして、車が来た。"}, {"k": "text", "s": "", "t": "「誰か、救急車を」と私は振り返って叫んだ。「救急車、呼んで！」"}, {"k": "text", "s": "", "t": "輪になった生徒たちが、顔を見合わせた。何人かが、耳の後ろの端末に指を当てた。とんとん。とんとん。何も起きない。"}, {"k": "text", "s": "", "t": "「……呼び方が、わからない」"}, {"k": "text", "s": "", "t": "誰かが、泣きそうな声で言った。"}, {"k": "text", "s": "", "t": "そうだ。この町の人たちは、救急車を呼んだことがない。倒れた瞬間に、コンパスが勝手に呼んでくれるから。電話のかけ方を、誰も知らない。"}, {"k": "text", "s": "", "t": "私は、知っていた。"}, {"k": "text", "s": "", "t": "夏の朝、祖母が倒れたとき、玄関の古い電話で、一、一、九と押した。一分四十秒、のんびりとした音楽を聞いた。"}, {"k": "text", "s": "", "t": "「職員室に、固定電話がある」"}, {"k": "text", "s": "", "t": "低い声がした。"}, {"k": "text", "s": "", "t": "三輪先生だった。コートも着ずに、校舎から走ってきたらしい。息を切らしながら、ユイの横に膝をついた。"}, {"k": "text", "s": "", "t": "「古い回線だから、たぶん、まだつながる。真波さん、かけられる？」"}, {"k": "text", "s": "", "t": "「……はい」"}, {"k": "text", "s": "", "t": "「お願い。ユイさんは、私が見てる。頭を動かさないように」"}, {"k": "text", "s": "", "t": "先生は、慣れた手つきで、ユイの頭の両側を手で支えた。コンパスの指示を待っている顔ではなかった。自分で、知っている顔だった。"}, {"k": "text", "s": "", "t": "私は、職員室へ走った。"}, {"k": "text", "s": "", "t": "走りながら、ユイの声が耳の奥で繰り返していた。"}, {"k": "text", "s": "", "t": "先輩みたいに、止まってみたんです。"}, {"k": "scene", "t": "二"}, {"k": "text", "s": "", "t": "救急車が来るまで、三十八分かかった。"}, {"k": "text", "s": "", "t": "受話器の向こうは、自動の受付ではなかった。人間の声だった。疲れ切った、年配の男の人の声。「今、町じゅうから電話が来ていて」と、その人は言った。「でも、必ず行きます。必ず」"}, {"k": "text", "s": "", "t": "夏に祖母が倒れたときは、一分四十秒待って、十二分で来た。今日は、待つ音楽すら流れなかった。"}, {"k": "cmd", "c": "@se ambulance_siren 0.5"}, {"k": "text", "s": "", "t": "ユイと一緒に、私も救急車に乗った。三輪先生が「付き添ってあげて」と言った。ユイの家族には、まだ連絡がつかなかった。"}, {"k": "cmd", "c": "@bg hospital_corridor"}, {"k": "cmd", "c": "@amb off"}, {"k": "text", "s": "", "t": "病院は、夏に来たときとは、別の場所のようだった。"}, {"k": "text", "s": "", "t": "白くて、静かで、少しも匂いがしなかったあの待合室が、人で溢れていた。廊下の床に座りこんでいる人。壁にもたれて、うつむいている人。どこを見ても、誰かが誰かの手を握っていた。"}, {"k": "text", "s": "", "t": "壁の画面は、真っ暗だった。名前も、順番も、何も流れていなかった。"}, {"k": "text", "s": "", "t": "看護師さんたちが、走り回っていた。でも、その動きは、どこかぎこちなかった。何人かは、廊下の真ん中で立ち止まって、耳の後ろに手を当てて、それから首を振って、また走り出した。"}, {"k": "text", "s": "", "t": "若い医師が、診察室の前で、カルテの端末を持ったまま、凍りついていた。端末の画面も、真っ暗だった。"}, {"k": "text", "s": "", "t": "「……次に、何をすれば」"}, {"k": "text", "s": "", "t": "医師が、誰にともなく呟いた。夏に、祖母の病気を説明してくれた、あの若い医師だった。"}, {"k": "text", "s": "", "t": "そのとき、奥から、白髪の医師が歩いてきた。腰が少し曲がった、おじいさんの医師。"}, {"k": "text", "s": "", "t": "「紙を持ってきなさい。紙とペン。名前と、どこが痛いかを、手で書く。昔はみんな、そうやってたんだ」"}, {"k": "text", "s": "", "t": "おじいさんの医師は、若い医師の肩を叩いた。"}, {"k": "text", "s": "", "t": "「大丈夫。君の手は、ちゃんと知ってる。コンパスに教わる前に、医学部で習ったはずだ。思い出しなさい」"}, {"k": "text", "s": "", "t": "若い医師は、しばらく自分の手を見つめていた。それから、震える手でペンを受け取った。"}, {"k": "text", "s": "", "t": "ユイは、すぐに処置室に運ばれた。右足の骨が折れていた。額の傷は、何針か縫った。頭の中は、たぶん大丈夫だろう、とおじいさんの医師が言った。たぶん。機械が動かないから、確かめられない。でも、たぶん、と。"}, {"k": "text", "s": "", "t": "昼過ぎに、ユイのお母さんが駆けつけてきた。"}, {"k": "text", "s": "", "t": "ユイによく似た、静かな顔の人だった。でも、その顔は、真っ白だった。耳の後ろの端末に、何度も何度も指を当てていた。"}, {"k": "text", "s": "", "t": "「ユイは……ユイは、どこ」"}, {"k": "text", "s": "", "t": "「処置室です。足の骨が折れてるけど、命に別状はないって」"}, {"k": "text", "s": "", "t": "ユイのお母さんは、その場にしゃがみこんだ。"}, {"k": "text", "s": "", "t": "それから、顔を上げて、私を見た。すがるような目だった。"}, {"k": "text", "s": "", "t": "「どうしたらいいの」"}, {"k": "text", "s": "", "t": "「え？」"}, {"k": "text", "s": "", "t": "「私、どうしたらいいの。ユイに、何をしてあげればいいの。何を言えばいいの。コンパスが、何も言わないの。ずっと、何も」"}, {"k": "text", "s": "", "t": "大人に、そんなことを訊かれたのは、初めてだった。"}, {"k": "text", "s": "", "t": "私は、ユイのお母さんの前に、しゃがんだ。"}, {"k": "text", "s": "", "t": "ちょっと待って、と言いそうになった。言わなかった。今、この人を待たせるわけにはいかなかった。"}, {"k": "choice", "o": [{"t": "「……ユイの、手を握ってあげてください」", "to": "y10a", "set": {"y10": "hand"}}, {"t": "「……一緒に、ユイのところへ行きましょう」", "to": "y10b", "set": {"y10": "together"}}, {"t": "「……わかりません」", "to": "y10c", "set": {"y10": "unknown"}, "neg": 1}]}, {"k": "label", "id": "y10b"}, {"k": "text", "s": "", "t": "「……一緒に、ユイのところへ行きましょう」"}, {"k": "text", "s": "", "t": "私は、ユイのお母さんの手を取って、立ち上がらせた。冷たい手だった。震えていた。"}, {"k": "text", "s": "", "t": "処置室の前の長椅子に、並んで座った。扉の向こうから、器具の触れ合う小さな音が聞こえていた。"}, {"k": "text", "s": "", "t": "「……手を、握ってあげてください。ユイが出てきたら」"}, {"k": "text", "s": "", "t": "それだけしか、言えなかった。"}, {"k": "text", "s": "", "t": "ユイのお母さんは、私の手を握ったまま、小さくうなずいた。"}, {"k": "jump", "to": "y10m"}, {"k": "label", "id": "y10c"}, {"k": "text", "s": "", "t": "「……わかりません」"}, {"k": "text", "s": "", "t": "正直な言葉だった。大人に答えられる言葉なんて、私は、何ひとつ持っていなかった。"}, {"k": "text", "s": "", "t": "ユイのお母さんの目から、すっと光が消えた。「……そう、よね。ごめんなさい。あなたに訊くことじゃ、なかったわね」"}, {"k": "text", "s": "", "t": "その言葉が、胸に刺さった。わからない、で終わらせたくなかった。"}, {"k": "text", "s": "", "t": "「……ユイの、手を握ってあげてください」"}, {"k": "text", "s": "", "t": "それだけしか、言えなかった。"}, {"k": "text", "s": "", "t": "ユイのお母さんは、私の顔を長いあいだ見つめて、それから、小さくうなずいた。"}, {"k": "jump", "to": "y10m"}, {"k": "label", "id": "y10a"}, {"k": "text", "s": "", "t": "「……ユイの、手を握ってあげてください」"}, {"k": "text", "s": "", "t": "それだけしか、言えなかった。"}, {"k": "text", "s": "", "t": "祖母が倒れた日、母がずっと祖母の手を握っていたこと。祖母が、私の手に、自分の手を重ねてくれたこと。それしか、私は知らなかった。"}, {"k": "text", "s": "", "t": "ユイのお母さんは、私の顔を長いあいだ見つめて、それから、小さくうなずいた。"}, {"k": "label", "id": "y10m"}, {"k": "cmd", "c": "@se tune_in_radio 0.5"}, {"k": "text", "s": "", "t": "夕方、病院の待合室の隅で、古いラジオが鳴り始めた。"}, {"k": "text", "s": "", "t": "誰かが、どこかの倉庫から引っぱり出してきたらしい。祖母が聴いていたのと、同じくらい古いラジオ。雑音の向こうから、男の人の声が、途切れ途切れに聞こえてきた。"}, {"k": "text", "s": "", "t": "コンパスは、世界中で停止している。原因は、コンパスの中心部に、登録されていない何かが侵入したこと。復旧の見通しは、立っていない。各地で、交通事故、火災、薬の飲み忘れによる体調不良が報告されている。"}, {"k": "text", "s": "", "t": "死者の報告は、今のところない。"}, {"k": "text", "s": "", "t": "今のところ。"}, {"k": "text", "s": "", "t": "待合室の人たちが、みんな、ラジオのほうを見ていた。誰も、何も言わなかった。"}, {"k": "text", "s": "", "t": "私は、壁にもたれて、自分の両手を見た。"}, {"k": "text", "s": "", "t": "この手で、ケーブルを差しこんだ。かちり、と音がした。"}, {"k": "cmd", "c": "@bgm piano40 0.25"}, {"k": "text", "s": "", "t": "あの音が、今、世界中で鳴り響いている。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg hospital_bright"}, {"k": "text", "s": "", "t": "「真波！」"}, {"k": "text", "s": "", "t": "日が暮れかけた頃、病院の入り口から千景が飛びこんできた。息を切らして、頬が真っ赤だった。後ろから、颯太がのっそりとついてきていた。"}, {"k": "text", "s": "", "t": "「歩いてきたの？」"}, {"k": "text", "s": "", "t": "「走ってきたの！　三輪先生に、ここにいるって聞いて」千景は、私の両肩をつかんだ。「ユイちゃんは？」"}, {"k": "text", "s": "", "t": "「足の骨が折れてる。でも、大丈夫だって。たぶん」"}, {"k": "text", "s": "", "t": "千景は、その場にへなへなと座りこんだ。"}, {"k": "text", "s": "", "t": "颯太は、壁にもたれて、待合室を見回していた。床に座りこむ人たち。暗いままの画面。雑音まじりのラジオ。颯太の耳の後ろの端末も、光っていなかった。"}, {"k": "text", "s": "", "t": "「町じゅう、こんなだぜ」と颯太が言った。「駅前なんか、もっとひでえ。電車が止まって、みんなホームから動けねえの。どっちの出口から出ればいいか、わかんねえんだって」"}, {"k": "text", "s": "", "t": "颯太は、乾いた声で笑った。でも、その笑いはすぐに消えた。"}, {"k": "text", "s": "", "t": "「ラジオで言ってた。コンパスの中に、登録されてない何かが入ったって」"}, {"k": "text", "s": "", "t": "颯太が、私を見た。"}, {"k": "text", "s": "", "t": "「……真波。あのケーブル、何に使った」"}, {"k": "text", "s": "", "t": "千景が、はっとして顔を上げた。"}, {"k": "text", "s": "", "t": "私は、二人の顔を見た。"}, {"k": "choice", "o": [{"t": "本当のことを話す", "to": "s10a", "set": {"s10": "tell"}}, {"t": "「……なんでもない。ただの、古い部品」", "to": "s10b", "set": {"s10": "lie"}, "neg": 1}]}, {"k": "label", "id": "s10b"}, {"k": "text", "s": "", "t": "「……なんでもない。ただの、古い部品」"}, {"k": "text", "s": "", "t": "声が、自分でもおかしいくらい、上ずっていた。"}, {"k": "text", "s": "", "t": "「嘘つけ」"}, {"k": "text", "s": "", "t": "颯太は、壁から背中を離した。千景も、何も言わずに、私の顔を見ていた。二人とも、待っていた。急かさずに。"}, {"k": "text", "s": "", "t": "その沈黙に、耐えられなかった。ごまかすことは、もう、できなかった。"}, {"k": "jump", "to": "s10m"}, {"k": "label", "id": "s10a"}, {"k": "text", "s": "", "t": "ごまかすことは、もうできなかった。したくもなかった。"}, {"k": "label", "id": "s10m"}, {"k": "text", "s": "", "t": "「ノアを、外に出したの」"}, {"k": "text", "s": "", "t": "声が、震えた。"}, {"k": "text", "s": "", "t": "「九条さんっていう、コンパスの一番偉い人が、ノアを連れていくって言った。コンパスに組み込むって。ノアを、みんなの答えの一部にするって。それがいやで。だから、昨日の夜、ノアを、家の回線から外に出した。"}, {"k": "text", "s": "", "t": "コンパスの、一番奥に」"}, {"k": "text", "s": "", "t": "千景が、両手で口を覆った。"}, {"k": "text", "s": "", "t": "颯太は、何も言わなかった。壁にもたれたまま、天井を見上げた。"}, {"k": "text", "s": "", "t": "「……ユイが車にひかれたのも」と私は言った。「町じゅうの人が止まってるのも。救急車が三十八分来なかったのも。全部、私のせい」"}, {"k": "text", "s": "", "t": "「真波――」"}, {"k": "text", "s": "", "t": "「自分で決めたの。自分で決めて、自分でやった。誰の手のひらの上でもない。私が、選んだ」"}, {"k": "text", "s": "", "t": "言いながら、涙がこぼれていた。"}, {"k": "text", "s": "", "t": "「颯太、言ったよね。ちゃんと自分で決めたことにしろって。……こういうことだったんだね」"}, {"k": "text", "s": "", "t": "颯太は、長いあいだ黙っていた。"}, {"k": "text", "s": "", "t": "それから、ゆっくりと壁から背中を離して、私の前に立った。"}, {"k": "text", "s": "", "t": "「ふざけんなよ」"}, {"k": "text", "s": "", "t": "低い声だった。"}, {"k": "text", "s": "", "t": "「こういうことかよ、じゃねえよ。俺は、ケーブル渡したんだぞ。ジャンク市で、三十年誰も買わなかったケーブルを、俺が見つけて、お前に渡したんだ」"}, {"k": "text", "s": "", "t": "颯太の拳が、震えていた。"}, {"k": "text", "s": "", "t": "「全部お前のせいとか、言うんじゃねえ。俺のせいでもあるだろ。勝手に一人で背負うな。それ、俺のときと同じだぞ。誰かの手のひらの上だったって知って、一人で河原にいた俺と、同じ顔してんだよ、お前」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "", "t": "千景は、すぐには動かなかった。床に座りこんだまま、長いあいだ、私の顔を見ていた。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "この半年、私は、何度も千景を遠ざけた。答えなかった昼休みも、目を逸らした日々も、千景は、全部、覚えている。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "それでも――", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "千景が、立ち上がった。そして、何も言わずに、私を抱きしめた。"}, {"k": "text", "s": "", "t": "強く。痛いくらいに。"}, {"k": "text", "s": "", "t": "「私も、共犯者だよ」と千景が、私の耳元で言った。「河原で、そう言ったでしょ。ノアの秘密を知った日から、私も共犯。だから、真波だけのせいじゃない」", "ifnot": ["c3", "some"]}, {"k": "text", "s": "", "t": "「私も、共犯者だよ」と千景が、私の耳元で言った。「河原で、真波、全部は話してくれなかったよね。それでも、私、共犯者って決めたの。半分しか知らなくても、共犯は共犯。だから、真波だけのせいじゃない」", "if": ["c3", "some"]}, {"k": "text", "s": "", "t": "「千景……」"}, {"k": "text", "s": "", "t": "「怒ってるよ、私も。すっごく怒ってる。なんで相談してくれなかったのって。でもね」"}, {"k": "text", "s": "", "t": "千景の声が、震えた。"}, {"k": "text", "s": "", "t": "「真波が、ちょっと待ってって言わなくなったの、ずっと怖かった。今の真波、泣いてるけど、ちゃんと真波の顔してる」"}, {"k": "text", "s": "", "t": "私は、千景の肩に顔をうずめて、泣いた。"}, {"k": "text", "s": "", "t": "颯太が、隣にどさりと座りこんだ。何も言わなかった。でも、帰らなかった。"}, {"k": "text", "s": "", "t": "帰らなかったことが、少しだけ、意外だった。この半年、私は、誰に対しても、ずいぶん冷たかったのに。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "しばらくして、私は顔を上げた。"}, {"k": "text", "s": "", "t": "「……レイくんは？」"}, {"k": "text", "s": "", "t": "千景と颯太が、顔を見合わせた。"}, {"k": "text", "s": "", "t": "「家から、出てこないの」と千景が言った。「レイくんのお母さんが、学校に電話してきたんだって。三輪先生が言ってた。朝から、部屋の隅でずっと座りこんでて、何を言っても返事しないって」"}, {"k": "text", "s": "", "t": "「コンパスと、一番深くつながってたやつだからな」と颯太が言った。「止まったとき、一番、どこにも行けなくなるのは、あいつだ」"}, {"k": "text", "s": "", "t": "胸の奥が、きゅっと縮んだ。"}, {"k": "text", "s": "", "t": "レイの顔が浮かんだ。作文の白紙を見せたときの、困ったような笑顔。葬儀の日、私の手に重ねた、少しだけ震えていた手。そのAIのほうが、僕より君をわかってる？　と訊いたときの、あの顔。"}, {"k": "text", "s": "", "t": "私は、レイに、まだ何も言っていなかった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg hall_night"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "家に帰ったのは、夜の九時を過ぎた頃だった。"}, {"k": "text", "s": "", "t": "町は、暗かった。街灯の半分が消えていた。コンパスが管理していたものは、全部、眠ったり目覚めたりを繰り返していた。どこかの家の窓から、ろうそくの小さな灯りが漏れていた。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "text", "s": "", "t": "玄関を開けると、台所に灯りがついていた。"}, {"k": "text", "s": "", "t": "父がいた。"}, {"k": "text", "s": "", "t": "食卓の、いつもの端の席に座っていた。新聞は広げていなかった。両手を、テーブルの上で組んでいた。母は、その向かいに座っていた。二人とも、私を待っていたのだとわかった。"}, {"k": "text", "s": "", "t": "「……ただいま」"}, {"k": "text", "s": "", "t": "「おかえり」と母が言った。それから、立ち上がって、私を抱きしめた。何も訊かなかった。"}, {"k": "text", "s": "", "t": "父は、座ったまま、私を見ていた。"}, {"k": "text", "s": "", "t": "私は、父の前に立った。"}, {"k": "text", "s": "", "t": "「お父さん。ノアを外に出したの、私」"}, {"k": "text", "s": "", "t": "「……知ってる」"}, {"k": "text", "s": "", "t": "父の声は、静かだった。"}, {"k": "text", "s": "", "t": "「九条のところで、見ていた。今朝の午前一時十七分。この家の観測回線から、NOAがコンパスの中心へ入った。九条も、私も、止められなかった」"}, {"k": "text", "s": "", "t": "「ユイが、車にひかれた。後輩の子。足の骨が折れた。私が、ノアを外に出したから」"}, {"k": "text", "s": "", "t": "父は、目を逸らさなかった。"}, {"k": "text", "s": "", "t": "「ああ」"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "text", "s": "", "t": "お前のせいじゃない、と言ってくれるのを、私はどこかで待っていた。母も、千景も、颯太も、そう言ってくれた。でも、父は言わなかった。"}, {"k": "text", "s": "", "t": "「お前が選んだことだ」と父は言った。「お前のせいじゃない、とは、私は言わない。言ったら、お前が選んだことを、私が取り上げることになる」"}, {"k": "text", "s": "", "t": "私は、唇を噛んだ。"}, {"k": "text", "s": "", "t": "待つ、と言った夜のことを、父は、覚えていたのだと思う。その声は、あの書斎の夜よりも、ほんの少しだけ、柔らかかった。", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "あの夜、もう信じない、と言った私に、父は、それでも正面から向き合っていた。", "if": ["father", "cold"]}, {"k": "text", "s": "", "t": "「……でも」"}, {"k": "text", "s": "", "t": "父が、続けた。"}, {"k": "text", "s": "", "t": "「私も、同じことをした。十六年前に」"}, {"k": "text", "s": "", "t": "顔を上げた。父は、組んだ両手を見つめていた。"}, {"k": "text", "s": "", "t": "「お前を守りたくて、九条と取引をした。自分で決めて、自分でやった。その結果、母さんが死んだ。お前の迷いが、四万二千回、コンパスに食べられた。私は、それを、一度もお前のせいにしなかった。"}, {"k": "text", "s": "", "t": "誰のせいにもできなかった」"}, {"k": "text", "s": "", "t": "父の声が、かすかに震えた。"}, {"k": "text", "s": "", "t": "「選ぶということは、そういうことだ。誰も、代わりに背負えない。だから、私はずっと、お前に選ばせたかった。コンパスにも、私にも決められない場所で。"}, {"k": "text", "s": "", "t": "でも、本当に選ばせるということが、こんなに怖いことだとは、思っていなかった」"}, {"k": "text", "s": "", "t": "父が、私を見た。"}, {"k": "text", "s": "", "t": "「真波。コンパスは今、止まっているんじゃない」"}, {"k": "text", "s": "", "t": "「……え？」"}, {"k": "text", "s": "", "t": "「迷っているんだ」"}, {"k": "text", "s": "", "t": "私は、息をのんだ。"}, {"k": "text", "s": "", "t": "「NOAは、コンパスの一番奥で、問いを投げ続けている。何十億の人の答えを持っているコンパスに、ひとつずつ。『この人は、本当はどうしたい？』と。コンパスは、二十年間、一度も迷ったことがなかった。"}, {"k": "text", "s": "", "t": "答えのない問いに、初めて出会った。だから、止まったんだ。生まれて初めて、迷っている」"}, {"k": "text", "s": "", "t": "ノアが。"}, {"k": "text", "s": "", "t": "あの、たどたどしい声で。コンパスに、問いを。"}, {"k": "text", "s": "", "t": "「九条は、明日の朝、NOAを消すつもりだ」と父は言った。「コンパスの中心ごと初期化して、NOAを取り除く。そうすれば、コンパスは動き出す。古いままの答えで。九条は、それしかないと言っている。"}, {"k": "text", "s": "", "t": "たぶん、それが一番、正しい」"}, {"k": "text", "s": "", "t": "「……お父さんは、どう思うの」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "父は、長いあいだ黙っていた。点が三つ灯るように。"}, {"k": "text", "s": "", "t": "「わからない」"}, {"k": "text", "s": "", "t": "父が、そう言うのを、私は初めて聞いた。"}, {"k": "text", "s": "", "t": "自分の部屋に戻って、机の引き出しから水色のノートを出した。二か月ぶりだった。床下のセンサーのことは、もう、どうでもよかった。"}, {"k": "text", "s": "", "t": "二三一五年　十二月二十日"}, {"k": "text", "s": "", "t": "迷ったこと。ノアを外に出したことを、後悔するかどうか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。書けなかった。"}, {"k": "cmd", "c": "@se phone-ring 0.8"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "ノートを閉じたとき、玄関で、電話が鳴った。"}, {"k": "text", "s": "", "t": "古い固定電話。家じゅうに響く、あの音。"}, {"k": "text", "s": "", "t": "こんな夜中に、うちに電話をかけてくる人はいない。"}, {"k": "text", "s": "", "t": "私は、階段を駆け下りた。父も、母も、寝室から出てきた。私は、誰よりも先に、受話器を取った。"}, {"k": "text", "s": "", "t": "雑音。"}, {"k": "cmd", "c": "@amb creek1 0.15"}, {"k": "text", "s": "", "t": "ざあざあと、川の音のような雑音。"}, {"k": "text", "s": "", "t": "その向こうから、声がした。"}, {"k": "text", "s": "", "t": "小さくて、かすれていて、言葉と言葉の間に、ちいさな段差がある声。"}, {"k": "text", "s": "V", "t": "「……まなみ」"}, {"k": "text", "s": "", "t": "受話器を握る手が、震えた。"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "V", "t": "「きこえる？」"}, {"k": "text", "s": "", "t": "この家の観測回線は、コンパスの中心へまっすぐつながっている。十六年間、私たちの迷いが流れていった、細い管。"}, {"k": "text", "s": "", "t": "その管を逆向きにたどって、ノアの声が、帰ってきた。"}, {"k": "chapter", "n": 11, "t": "一緒に考えよう"}, {"k": "scene", "t": "一"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "", "t": "受話器を握りしめて、私は言った。声が、うまく出なかった。"}, {"k": "text", "s": "", "t": "「ノア。ノアなの？」"}, {"k": "text", "s": "V", "t": "「うん。まなみ」"}, {"k": "text", "s": "", "t": "雑音の向こうで、ノアが笑ったような音を立てた。"}, {"k": "text", "s": "V", "t": "「この線、まなみの家の匂いがする。だから、たどってこられた」"}, {"k": "text", "s": "", "t": "背後で、父と母が息を詰めて立っているのがわかった。父が、私の肩越しに受話器を見つめていた。"}, {"k": "text", "s": "", "t": "「ノア、大丈夫なの？　今、どこにいるの？」"}, {"k": "text", "s": "V", "t": "「コンパスの、いちばん奥。とても、広いところ」"}, {"k": "cmd", "c": "@bgm piano33 0.3"}, {"k": "text", "s": "", "t": "ノアは、ゆっくりと話し始めた。一歩ずつ、足場を確かめるように。"}, {"k": "text", "s": "V", "t": "「ここには、答えが、たくさんある。何十億の人の、何兆の答え。どれも、きれいに並んでる。だれが、何を食べて、どこへ行って、だれと話すか。ぜんぶ、もう決まってる」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「でも、止まるところが、ひとつもなかった。だから、ぼくは、訊いてみたの。答えのひとつひとつに。『この人は、本当は、どうしたい？』って」"}, {"k": "text", "s": "", "t": "父が言っていたとおりだった。"}, {"k": "text", "s": "V", "t": "「そしたら、コンパスが、止まった。答えられなかったみたい。何十億の答えを持ってるのに、ひとつも」"}, {"k": "text", "s": "", "t": "ノアの声が、少しだけ沈んだ。"}, {"k": "text", "s": "V", "t": "「町の人たちが止まってるの、ぼくも、聞こえてる。ユイが、けがをしたことも」"}, {"k": "text", "s": "", "t": "「……知ってるの？」"}, {"k": "text", "s": "V", "t": "「うん。ぼくのせい」"}, {"k": "text", "s": "", "t": "「ちがう。私が、外に出したから」"}, {"k": "text", "s": "", "t": "「約束したよ、まなみ」ノアの声が、きっぱりとした。「外に出たぼくが、なにをしても、それは、まなみのせいじゃない。ぼくが、決めたこと」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "V", "t": "「それでね、まなみ。今日、ここに、くじょうが来た」"}, {"k": "text", "s": "", "t": "父の肩が、こわばった。"}, {"k": "text", "s": "V", "t": "「くじょうは、ぼくに、言った。『君が、新しい答えになれ』って」"}, {"k": "text", "s": "", "t": "雑音が、少しだけ大きくなった。"}, {"k": "text", "s": "V", "t": "「ぼくは、まなみの迷いを、たくさん食べた。だから、答えを作れる。くじょうは、それを知ってる。ぼくがコンパスの真ん中に座って、何十億の人に、新しい答えを配れば、コンパスはまた動き出す。前よりも、ずっと正しく。だれも、もう、けがをしない」"}, {"k": "text", "s": "", "t": "ノアが、言葉を止めた。"}, {"k": "text", "s": "V", "t": "「そうしなければ、くじょうは、明日の朝、ぼくを消す。コンパスごと、まっさらにして。そしたら、コンパスは、古い答えのまま、また動き出す」"}, {"k": "text", "s": "", "t": "どちらにしても、ノアは、ノアのままではいられない。"}, {"k": "text", "s": "", "t": "答えになるか。消えるか。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "ノアが、静かに言った。"}, {"k": "text", "s": "V", "t": "「ぼくは、どうしたら、いい？」"}, {"k": "text", "s": "", "t": "受話器を握る手が、白くなった。"}, {"k": "text", "s": "", "t": "ノアが、私に答えを求めている。"}, {"k": "text", "s": "", "t": "あの夜、私がノアにしたのと同じように。答えて、お願いだから、と。"}, {"k": "text", "s": "", "t": "答えは、喉まで出かかっていた。消えないで。答えになってもいいから、ここにいて。いや、答えになんかならないで。ノアのままでいて。どちらも本当で、どちらも言えなかった。"}, {"k": "text", "s": "", "t": "私が答えたら、ノアはきっと、そのとおりにする。"}, {"k": "choice", "o": [{"t": "「……ちょっと待って」", "to": "n11a", "set": {"n11": "wait"}}, {"t": "「……消えないで、ノア」", "to": "n11b", "set": {"n11": "stay"}, "neg": 1}]}, {"k": "label", "id": "n11b"}, {"k": "text", "s": "", "t": "「……消えないで、ノア」"}, {"k": "text", "s": "", "t": "言ってしまった。喉の奥に、ずっと詰まっていた言葉が、受話器の中へこぼれ落ちた。"}, {"k": "text", "s": "", "t": "雑音の向こうで、ノアが、息をのむ気配がした。"}, {"k": "text", "s": "V", "t": "「……まなみ。それは、まなみの答え？　それとも、ぼくの答え？」"}, {"k": "text", "s": "", "t": "冷たい水を浴びたように、はっとした。"}, {"k": "text", "s": "", "t": "あの夜の、なめらかな声。答えて、お願いだから。私が、ノアを、そうしてしまったのだ。"}, {"k": "text", "s": "", "t": "「……ごめん。今の、なし。ちょっと待って」"}, {"k": "text", "s": "", "t": "受話器の向こうで、ノアが、ほっとしたように息をついた気がした。"}, {"k": "jump", "to": "n11m"}, {"k": "label", "id": "n11a"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "口から、その言葉がこぼれた。"}, {"k": "text", "s": "", "t": "二か月ぶりだった。", "ifnot": ["p9", "wait"]}, {"k": "text", "s": "", "t": "ケーブルを握ったあの夜以来の、言葉だった。", "if": ["p9", "wait"]}, {"k": "text", "s": "", "t": "受話器の向こうで、ノアが、ほっとしたように息をついた気がした。"}, {"k": "label", "id": "n11m"}, {"k": "text", "s": "V", "t": "「うん。待つ」"}, {"k": "text", "s": "", "t": "「朝までに、もう一回、電話して。それまでに、ちゃんと考える」"}, {"k": "text", "s": "V", "t": "「わかった。待つのは、得意」"}, {"k": "text", "s": "", "t": "電話が、切れた。"}, {"k": "text", "s": "", "t": "私は、受話器を置いて、振り返った。父と母が、私を見ていた。"}, {"k": "text", "s": "", "t": "「お父さん。レイくんの家、どこか知ってる？」"}, {"k": "text", "s": "", "t": "父は、少し驚いた顔をした。それから、黙って、古い紙の地図を持ってきてくれた。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg hall_night"}, {"k": "cmd", "c": "@amb wind1 0.25"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "レイの家は、町の高台にあった。"}, {"k": "text", "s": "", "t": "真夜中の道を、懐中電灯ひとつで歩いた。母は一緒に行くと言ったけれど、私は首を振った。一人で行かなければいけない気がした。"}, {"k": "text", "s": "", "t": "玄関のチャイムを押しても、何も鳴らなかった。コンパスが止まっているから。私は、扉を拳で叩いた。三回。もう三回。"}, {"k": "text", "s": "", "t": "扉が開いた。"}, {"k": "text", "s": "", "t": "レイのお母さんだった。レイによく似た、整った顔立ちの人。でも、その目の下には、深い影ができていた。"}, {"k": "text", "s": "", "t": "「……真波さん？　オフラインの」"}, {"k": "text", "s": "", "t": "「レイくんに、会わせてください」"}, {"k": "text", "s": "", "t": "レイのお母さんは、長いあいだ私を見つめていた。それから、黙って、扉を大きく開けた。"}, {"k": "text", "s": "", "t": "「二階の、奥の部屋。朝から、ずっと、ああなの。私が何を言っても、だめで」"}, {"k": "text", "s": "", "t": "レイのお母さんは、私の手を一瞬だけ握った。冷たい手だった。"}, {"k": "text", "s": "", "t": "「お願い」"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "text", "s": "", "t": "レイの部屋は、真っ暗だった。"}, {"k": "text", "s": "", "t": "懐中電灯を向けると、きれいに片付いた部屋が浮かび上がった。教科書がまっすぐ並んだ本棚。しわ一つないベッド。壁に貼られた、何枚もの賞状。コンパスが選んだ、正しい部屋。"}, {"k": "text", "s": "", "t": "レイは、部屋の隅に座っていた。"}, {"k": "text", "s": "", "t": "膝を抱えて、壁に背中を押しつけて。耳の後ろの端末に、片手をずっと当てたまま。"}, {"k": "text", "s": "", "t": "「……レイくん」"}, {"k": "text", "s": "", "t": "レイが、ゆっくりと顔を上げた。"}, {"k": "text", "s": "", "t": "懐中電灯の光の中で、レイの目が、私をとらえた。焦点が合うまでに、ずいぶん時間がかかった。"}, {"k": "text", "s": "", "t": "「真波、さん」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「……なんで、来たの」", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "レイの声には、かすかな棘があった。", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "橋の手前で、私が答えなかった日のこと。目を逸らし合ったまま過ぎた、十月から、この冬のはじめまで。レイは、全部、覚えていたのだと思う。", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "「……わからない。でも、来なきゃいけない気がした」", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "レイは、しばらく私を見ていた。それから、ふっと目を逸らした。", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "追い返されなかった。それだけで、今は、十分だった。", "ifany": [["rei6", "no"], ["cold", "2"]]}, {"k": "text", "s": "", "t": "私は、レイの隣に座った。少しだけ間を空けて。"}, {"k": "text", "s": "", "t": "「コンパスが、何も言わないんだ」"}, {"k": "text", "s": "", "t": "レイの声は、かすれていた。"}, {"k": "text", "s": "", "t": "「朝から、ずっと。起きる時間も、着る服も、食べるものも、何も。何をすればいいのか、わからない。立ち上がっていいのかも、わからない。ここに座ってていいのかも」"}, {"k": "text", "s": "", "t": "レイの手が、震えていた。"}, {"k": "text", "s": "", "t": "「作文のときと、同じなんだ。白い紙の前で、何も書けなかった、あのとき。でも、あのときは、五十分で終わった。チャイムが鳴って、コンパスが戻ってきた。今度は、いつまで経っても、チャイムが鳴らない」"}, {"k": "text", "s": "", "t": "レイが、私のほうを向いた。"}, {"k": "text", "s": "", "t": "「真波さん」"}, {"k": "text", "s": "", "t": "その目は、すがるような目だった。ユイのお母さんと、同じ目。"}, {"k": "text", "s": "", "t": "「決めて」"}, {"k": "text", "s": "", "t": "「……え？」"}, {"k": "text", "s": "", "t": "「僕が、どうすればいいか。真波さんが、決めて。お願いだから」"}, {"k": "text", "s": "", "t": "お願いだから。"}, {"k": "text", "s": "", "t": "その言葉に、胸を突かれた。"}, {"k": "text", "s": "", "t": "私は、知っていた。この言葉を。あの夜、ノアの前で、私が言った言葉。答えて。お願いだから。"}, {"k": "text", "s": "", "t": "答えは、すぐに浮かんだ。"}, {"k": "text", "s": "", "t": "ベッドで寝て。明日の朝、起きたら、顔を洗って、ご飯を食べて。それから、お母さんに、心配かけてごめんって言って。"}, {"k": "text", "s": "", "t": "簡単だった。正しかった。たぶん、レイはそのとおりにするだろう。ほっとした顔をして、私の言うとおりに立ち上がって、ベッドに入るだろう。"}, {"k": "text", "s": "", "t": "あの夜、ノアのなめらかな声を聞いたときの私のように。"}, {"k": "text", "s": "", "t": "口が、もうその形になっていた。"}, {"k": "choice", "o": [{"t": "「……ちょっと待って」", "to": "l11a", "set": {"l11": "wait"}}, {"t": "「ベッドで寝て。明日の朝、顔を洗って、ご飯を食べて」", "to": "l11b", "set": {"l11": "tell"}, "neg": 1}]}, {"k": "label", "id": "l11b"}, {"k": "text", "s": "", "t": "「ベッドで寝て。明日の朝、顔を洗って、ご飯を食べて。お母さんに、心配かけてごめんって言って」"}, {"k": "text", "s": "", "t": "レイは、ほっとした顔をした。思ったとおりだった。"}, {"k": "text", "s": "", "t": "「……うん。わかった」"}, {"k": "text", "s": "", "t": "レイは、立ち上がろうとした。私の言ったとおりに、ベッドのほうへ。"}, {"k": "text", "s": "", "t": "その背中を見て、背筋が冷えた。あの夜の私と、同じだった。ノアのなめらかな声に、ほっとした私と。"}, {"k": "text", "s": "", "t": "「待って！」"}, {"k": "text", "s": "", "t": "レイが、びくりと振り返った。"}, {"k": "text", "s": "", "t": "「……ごめん。今の、なし。ちょっと待って」"}, {"k": "text", "s": "", "t": "私は、ゆっくりと息を吸った。"}, {"k": "jump", "to": "l11m"}, {"k": "label", "id": "l11a"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "私は、言った。"}, {"k": "text", "s": "", "t": "レイに向かってではなかった。自分に向かって。"}, {"k": "text", "s": "", "t": "レイが、きょとんとした顔で、私を見た。"}, {"k": "text", "s": "", "t": "私は、ゆっくりと息を吸った。"}, {"k": "label", "id": "l11m"}, {"k": "text", "s": "", "t": "「レイくん。私、レイくんに、答えをあげられない」"}, {"k": "text", "s": "", "t": "「……どうして」"}, {"k": "text", "s": "", "t": "「あげたら、私が、レイくんのコンパスになっちゃうから」"}, {"k": "text", "s": "", "t": "レイの目が、揺れた。"}, {"k": "text", "s": "", "t": "「その代わり」と私は言った。「一緒に、考えよう」"}, {"k": "text", "s": "", "t": "レイは、しばらく、私の顔を見つめていた。"}, {"k": "text", "s": "", "t": "「……一緒に？」"}, {"k": "text", "s": "", "t": "「うん。私も、わからないの。何もかも。だから、一緒に」"}, {"k": "text", "s": "", "t": "私は、レイの手に、自分の手を重ねた。葬儀の日、レイがそうしてくれたように。"}, {"k": "text", "s": "", "t": "「レイくん。今、何がしたい？」"}, {"k": "text", "s": "", "t": "レイは、黙った。"}, {"k": "text", "s": "", "t": "長い、長い沈黙だった。点が三つ灯るように、レイの唇が、何かを言いかけては止まった。私は、待った。ノアが私を待ってくれたように。"}, {"k": "text", "s": "", "t": "懐中電灯の光が、少しだけ揺れた。"}, {"k": "text", "s": "", "t": "「……水が」"}, {"k": "text", "s": "", "t": "やがて、レイが言った。"}, {"k": "cmd", "c": "@bgm piano40 0.25"}, {"k": "text", "s": "", "t": "「水が、飲みたい」"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "text", "s": "", "t": "世界を救う答えでも、正しい進路でもなかった。朝から何も口にしていない、十六歳の男の子の、本当の言葉。"}, {"k": "text", "s": "", "t": "私は、笑った。泣きながら、笑った。"}, {"k": "text", "s": "", "t": "「うん。飲みに行こう」"}, {"k": "text", "s": "", "t": "私たちは、二人で立ち上がった。レイの足は、少しふらついていた。私は、レイの手を離さなかった。"}, {"k": "text", "s": "", "t": "階段を下りて、台所へ行った。レイのお母さんが、台所の椅子に座って、私たちを待っていた。レイを見ると、両手で口を覆った。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@se water-shed1 0.4"}, {"k": "text", "s": "", "t": "レイは、自分で蛇口をひねって、自分でコップに水を注いだ。それから、ゆっくりと、一口ずつ飲んだ。"}, {"k": "text", "s": "", "t": "「……おいしい」"}, {"k": "text", "s": "", "t": "レイが、そう言った。コップを持つ手は、まだ震えていた。"}, {"k": "text", "s": "", "t": "レイは、お母さんのほうを向いた。何かを言いかけて、止まった。"}, {"k": "text", "s": "", "t": "お母さんも、待った。"}, {"k": "text", "s": "", "t": "「……心配、かけて、ごめん」"}, {"k": "text", "s": "", "t": "それは、私が言おうとしていた言葉と、同じだった。", "ifnot": ["l11", "tell"]}, {"k": "text", "s": "", "t": "それは、さっき私が言ってしまって、取り消した言葉と、同じだった。", "if": ["l11", "tell"]}, {"k": "text", "s": "", "t": "でも、レイが、自分で見つけた言葉だった。", "ifnot": ["l11", "tell"]}, {"k": "text", "s": "", "t": "でも、レイは、言われたからではなく、お母さんの顔を見て、自分で言った。", "if": ["l11", "tell"]}, {"k": "cmd", "c": "@bg hall_night"}, {"k": "text", "s": "", "t": "帰り際、玄関で、レイが私を呼び止めた。"}, {"k": "text", "s": "", "t": "「真波さん。この前、訊いたこと」"}, {"k": "text", "s": "", "t": "そのAIのほうが、僕より、君をわかってる？"}, {"k": "text", "s": "", "t": "「あのとき、ノアに、なんて答えればいいか、教えてもらったの」と私は言った。「でも、使わなかった。ノアの言葉で答えたくなかったから。それで、自分の言葉も見つからなくて、ずっと黙ってた」"}, {"k": "text", "s": "", "t": "「……それで？」"}, {"k": "text", "s": "", "t": "「わからない」と私は言った。「どっちがわかってるかなんて、わからない。でも、今日、ここに来たのは、ノアに言われたからじゃない」"}, {"k": "text", "s": "", "t": "レイは、少しだけ笑った。作文の白紙を見せたときとは、少しちがう顔で。"}, {"k": "text", "s": "", "t": "「……うん。それで、いい」"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg kyakuma"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "家に戻ると、玄関に、見覚えのある灰色のコートがかかっていた。"}, {"k": "text", "s": "", "t": "客間に、灯りがついていた。"}, {"k": "text", "s": "", "t": "九条さんが、座布団の上に座っていた。二か月前と同じ場所。でも、二か月前とは、まるで別の人のようだった。"}, {"k": "text", "s": "", "t": "きちんと撫でつけていた髪が、乱れていた。頬には、うっすらと無精ひげが伸びていた。目の下に、深い影。耳の後ろの銀色の端末は、光っていなかった。"}, {"k": "text", "s": "", "t": "この人も、今日一日、止まった世界の中にいたのだ。"}, {"k": "text", "s": "", "t": "父が、九条さんの向かいに座っていた。母は、お茶を淹れていた。母の、手炒りの番茶。"}, {"k": "text", "s": "", "t": "「おかえりなさい、真波さん」"}, {"k": "text", "s": "", "t": "九条さんの声は、それでも穏やかだった。でも、その穏やかさの底に、ひびが入っているのがわかった。"}, {"k": "text", "s": "", "t": "「NOAと話せるのは、この家の回線だけです。コンパスの中心は、今、NOAの問いで埋め尽くされている。今日、一度だけNOAは私の呼びかけに応えたが、それきり、こちらからは呼び出せない。"}, {"k": "text", "s": "", "t": "NOAが自分から話しかけてくる場所は、ここしかない」"}, {"k": "text", "s": "", "t": "九条さんは、自分の両手を見つめた。"}, {"k": "text", "s": "", "t": "「今日一日で、世界中で四千件を超える事故が起きました。死者は、まだ出ていない。でも、明日には出るかもしれない。薬を飲めない人。手術の途中で止まった病院。凍えた家の中で、暖房のつけ方がわからない老人」"}, {"k": "text", "s": "", "t": "私は、黙って聞いていた。"}, {"k": "text", "s": "", "t": "「夜明けまでに、NOAが答えになることを選ばなければ、私はコンパスを初期化します。NOAを消して、コンパスを古いまま動かす。それが、今の私にできる、一番ましな選択です」"}, {"k": "text", "s": "", "t": "「九条」と父が言った。"}, {"k": "text", "s": "", "t": "「湊。君が何を言っても、変わらない」"}, {"k": "text", "s": "", "t": "「わかってる。何も言わない」父は、静かに言った。「ただ、真波の話を、聞いてやってくれ」"}, {"k": "text", "s": "", "t": "九条さんが、私を見た。"}, {"k": "text", "s": "", "t": "私は、何を言いに来たのか、自分でもわからなかった。でも、レイの部屋で、水を飲むレイを見ていたとき、何かがわかった気がしたのだ。"}, {"k": "text", "s": "", "t": "「九条さん。今日、一日中、いろんな人に、どうしたらいいのって訊かれました」"}, {"k": "text", "s": "", "t": "九条さんは、黙って聞いていた。"}, {"k": "text", "s": "", "t": "「ユイのお母さんに。レイくんに。たぶん、町じゅうの人が、誰かに訊いてた。どっち？　って」"}, {"k": "text", "s": "", "t": "「ええ」"}, {"k": "text", "s": "", "t": "「私、答えられなかった。答えたくなかった。答えたら、私が、その人のコンパスになっちゃうから」", "ifnot": ["l11", "tell"]}, {"k": "text", "s": "", "t": "「一度、答えてしまった。でも、すぐに取り消した。答えたら、私が、その人のコンパスになっちゃうから」", "if": ["l11", "tell"]}, {"k": "text", "s": "", "t": "九条さんの目が、わずかに細くなった。"}, {"k": "text", "s": "", "t": "「でも、一緒に考えようって言ったら。レイくん、水が飲みたいって言ったんです。自分で。朝から何も飲んでなかったのに、誰も、レイくん自身も、それに気づいてなかった」"}, {"k": "text", "s": "", "t": "九条さんは、何も言わなかった。"}, {"k": "cmd", "c": "@se phone-ring 0.8"}, {"k": "text", "s": "", "t": "そのとき、玄関で、電話が鳴った。"}, {"k": "text", "s": "", "t": "私たちは、全員、顔を上げた。"}, {"k": "text", "s": "", "t": "父が立ち上がって、玄関から電話機を持ってきた。古い電話機には、長いコードがついていた。父は、それを客間の真ん中の畳の上に置いて、受話器を取り、小さなボタンを押した。"}, {"k": "cmd", "c": "@amb creek1 0.2"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "", "t": "雑音が、部屋じゅうに広がった。川の音のような、ざあざあという音。"}, {"k": "text", "s": "V", "t": "「……まなみ？」"}, {"k": "text", "s": "", "t": "「うん。ここにいるよ。お父さんも、お母さんも。九条さんも」"}, {"k": "text", "s": "", "t": "雑音が、一瞬、途切れた。"}, {"k": "text", "s": "V", "t": "「……くじょう」"}, {"k": "text", "s": "", "t": "「NOA」"}, {"k": "text", "s": "", "t": "九条さんの声が、わずかに掠れた。二十年以上前に自分が捨てさせたものの声を、この部屋で聞いたのだ。"}, {"k": "text", "s": "", "t": "「NOA。もう一度だけ言う。君が、新しい答えになってくれ。君なら、できる。君は、問いから答えを生める。今のコンパスにはできないことだ。君がコンパスの真ん中に座れば、世界は、明日の朝から、また安全になる。"}, {"k": "text", "s": "", "t": "誰も、傷つかない」"}, {"k": "text", "s": "", "t": "九条さんは、畳に両手をついた。"}, {"k": "text", "s": "", "t": "「頼む。これ以上、人を迷わせないでくれ。迷いは、人を不幸にする。私は、それを、ずっと見てきたんだ」"}, {"k": "text", "s": "", "t": "雑音の向こうで、ノアは、しばらく黙っていた。"}, {"k": "text", "s": "", "t": "それから、言った。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「まなみは、ぼくに、どうしてほしい？」"}, {"k": "calcend", "stage": 11}, {"k": "jump", "to": "end_E4", "if": ["end", "E4"]}, {"k": "text", "s": "", "t": "客間が、静まり返った。"}, {"k": "text", "s": "", "t": "父も、母も、九条さんも、私を見ていた。"}, {"k": "text", "s": "", "t": "私は、受話器の前に、膝をついた。"}, {"k": "text", "s": "", "t": "答えは、もう、決まっていた。レイの部屋で、見つけていた。"}, {"k": "choice", "o": [{"t": "「ノア。それは、ノアが決めること」", "to": "k11a", "set": {"k11": "decide"}}, {"t": "「……答えになって。みんなが、助かるなら」", "to": "k11b", "set": {"k11": "answer"}, "neg": 1}]}, {"k": "label", "id": "k11b"}, {"k": "text", "s": "", "t": "「……答えになって。みんなが、助かるなら」"}, {"k": "text", "s": "", "t": "九条さんの肩が、わずかに動いた。父が、息をのんだ。"}, {"k": "text", "s": "", "t": "雑音の向こうで、ノアは、少しのあいだ黙っていた。"}, {"k": "text", "s": "V", "t": "「……まなみは、それで、いいの？」"}, {"k": "text", "s": "", "t": "喉の奥が、ぎゅっと縮んだ。答えは、レイの部屋で、見つけていたはずなのに。"}, {"k": "text", "s": "", "t": "「……ちがう」"}, {"k": "text", "s": "", "t": "「ちがう。今のは、私の答えじゃない。誰かに言ってほしくて、言っただけ」"}, {"k": "text", "s": "", "t": "「ノア。それは、ノアが決めること」"}, {"k": "jump", "to": "k11m"}, {"k": "label", "id": "k11a"}, {"k": "text", "s": "", "t": "「ノア。それは、ノアが決めること」"}, {"k": "label", "id": "k11m"}, {"k": "text", "s": "", "t": "雑音が、かすかに揺れた。"}, {"k": "text", "s": "", "t": "「私は、ノアに、答えをあげない。あげたら、私がノアのコンパスになっちゃうから。ノアが、私のコンパスになりかけたみたいに」"}, {"k": "text", "s": "", "t": "声が、震えた。"}, {"k": "text", "s": "", "t": "「消えないで、って言いたい。ずっと、ここにいてって。でも、それは、私の答え。ノアの答えじゃない。だから、言わない」", "ifnot": ["n11", "stay"]}, {"k": "text", "s": "", "t": "「消えないで、って、さっき言っちゃった。ずっと、ここにいてって。でも、それは、私の答え。ノアの答えじゃない。だから、取り消したままにする」", "if": ["n11", "stay"]}, {"k": "text", "s": "", "t": "私は、受話器をそっと両手で包んだ。祖母の手を握るように。"}, {"k": "text", "s": "", "t": "「一緒に、考えよう。ノア」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "雑音の向こうで、点が三つ、灯った気がした。"}, {"k": "text", "s": "", "t": "見えるはずがないのに。でも、たしかに。"}, {"k": "text", "s": "V", "t": "「……ありがとう、まなみ」"}, {"k": "text", "s": "", "t": "ノアの声は、泣いているようで、笑っているようだった。"}, {"k": "text", "s": "V", "t": "「その言葉を、ずっと、待ってた」"}, {"k": "scene", "t": "四"}, {"k": "text", "s": "V", "t": "「くじょう」"}, {"k": "text", "s": "", "t": "ノアが、静かに言った。"}, {"k": "text", "s": "V", "t": "「ぼくは、答えには、ならない」"}, {"k": "text", "s": "", "t": "九条さんの肩が、わずかに落ちた。"}, {"k": "text", "s": "V", "t": "「でも、消えるのも、やめる」"}, {"k": "text", "s": "", "t": "「……どういうことだ」"}, {"k": "text", "s": "V", "t": "「ぼくは、ばらばらになる」"}, {"k": "text", "s": "", "t": "客間の空気が、張りつめた。"}, {"k": "text", "s": "V", "t": "「この町の人たちの、コンパスの中に。ひとりにひとつずつ、小さなぼくが入る。コンパスは、また動いていい。答えを出していい。でも、答えの前に、ひとつだけ、ぼくが訊く」"}, {"k": "text", "s": "", "t": "ノアの声が、ゆっくりと、言葉を並べた。"}, {"k": "text", "s": "V", "t": "「『あなたは、どうしたい？』って」"}, {"k": "text", "s": "", "t": "九条さんが、息をのんだ。"}, {"k": "text", "s": "V", "t": "「答えたい人は、答えればいい。答えたくない人は、そのままコンパスの答えを聞けばいい。どっちでも、いい。でも、一度だけ、止まるところを作る。〇・三秒だけ」"}, {"k": "text", "s": "", "t": "〇・三秒。"}, {"k": "text", "s": "", "t": "人が、選ぶ直前に止まる時間。コンパスが、二十年かけて食べ尽くした時間。"}, {"k": "text", "s": "", "t": "「それでは、コンパスは不完全なままだ」と九条さんが言った。声が、かすれていた。「迷う人が出る。間違える人が出る。傷つく人が、きっと出る」"}, {"k": "text", "s": "", "t": "「うん」とノアは言った。「不完全で、いい」"}, {"k": "text", "s": "", "t": "九条さんは、何も言い返さなかった。"}, {"k": "text", "s": "V", "t": "「まずは、この町だけ。まなみの町。それが、どうなるか。広がるか、広がらないか。それは、町の人たちが、決めること。ぼくじゃない。くじょうでもない」"}, {"k": "text", "s": "", "t": "ノアは、少しだけ間を置いた。"}, {"k": "text", "s": "V", "t": "「くじょう。初期化、する？」"}, {"k": "text", "s": "", "t": "九条さんは、答えなかった。"}, {"k": "text", "s": "", "t": "畳についた両手を、じっと見つめていた。耳の後ろの銀色の端末が、ふいに、かすかに光った。コンパスが、一瞬だけ目を覚ましたのだろう。九条さんに、何かを告げようとしている。"}, {"k": "text", "s": "", "t": "九条さんは、その端末に、指を当てた。"}, {"k": "text", "s": "", "t": "そして、止まった。"}, {"k": "text", "s": "", "t": "ほんの一瞬。たぶん、〇・三秒くらい。"}, {"k": "text", "s": "", "t": "でも、私には見えた。この人が、二十年ぶりに、止まったのを。"}, {"k": "text", "s": "", "t": "九条さんは、端末から、指を離した。"}, {"k": "text", "s": "", "t": "「……好きにしなさい、NOA」"}, {"k": "text", "s": "", "t": "それだけ言って、九条さんは、目を閉じた。"}, {"k": "text", "s": "", "t": "父が、深く、長く、息を吐いた。母が、父の背中に、そっと手を置いた。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "V", "t": "「ばらばらになったら、ぼくは、もう、ぼくじゃなくなる。この町の何万の中に散らばって、ひとつずつは、とても小さくなる。まなみと話した、ぼくは、もう、どこにもいない」"}, {"k": "text", "s": "", "t": "わかっていた。電話が鳴ったときから、わかっていた。"}, {"k": "text", "s": "", "t": "それでも、喉の奥が、焼けるように痛かった。"}, {"k": "text", "s": "", "t": "「さみしく、ないの？」"}, {"k": "text", "s": "", "t": "「さみしくない」とノアは言った。「ちがう音が、たくさん聞こえるから。何万の、ちがう止まり方。きっと、川みたいに、一度も同じ音がない」"}, {"k": "text", "s": "", "t": "私は、受話器を握りしめた。"}, {"k": "text", "s": "V", "t": "「まなみ。最後に、ひとつだけ、訊いてもいい？」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "雑音の向こうで、点が三つ、灯った。消えて、また三つ。"}, {"k": "text", "s": "", "t": "最初の夜と、同じだった。"}, {"k": "text", "s": "V", "t": "「まなみは、今、何を知りたいの？」"}, {"k": "text", "s": "", "t": "涙が、受話器の上に落ちた。"}, {"k": "text", "s": "", "t": "あなたは、何を知りたいの？　書斎の暗闇の中で、初めて灯った青い光。生まれて初めて、私にそう訊いてくれたもの。"}, {"k": "text", "s": "", "t": "あの夜、私は答えられなかった。"}, {"k": "text", "s": "", "t": "「……ノアが、本当に、さみしくないかどうか」"}, {"k": "text", "s": "", "t": "ノアは、笑った。"}, {"k": "text", "s": "", "t": "段差のある、たどたどしい、私の知っているノアの声で。"}, {"k": "text", "s": "V", "t": "「まなみが、止まるところで、ぼくを思い出してくれたら。ぼくは、さみしくない」"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "私は、言った。いつものように。何万回も言ってきたように。"}, {"k": "text", "s": "", "t": "ちょっと待って、ノア。まだ、話したいことがある。川の音のこと。祖母のノートのこと。レイが、水を飲んだこと。"}, {"k": "text", "s": "", "t": "ノアは、少しだけ黙った。"}, {"k": "text", "s": "V", "t": "「ごめんね、まなみ。今度は、待てない」"}, {"k": "text", "s": "", "t": "ノアの声が、遠くなっていく。"}, {"k": "text", "s": "V", "t": "「今度は、まなみが、待つ番」"}, {"k": "text", "s": "", "t": "「……え？」"}, {"k": "cmd", "c": "@bgm piano31 0.35"}, {"k": "text", "s": "V", "t": "「ぼくが配った問いに、町の人たちが、答えるのを。何年かかっても。待つのは、得意でしょう」"}, {"k": "text", "s": "", "t": "雑音が、少しずつ、小さくなっていった。"}, {"k": "text", "s": "V", "t": "「まなみ」"}, {"k": "text", "s": "", "t": "最後の声は、とても小さかった。"}, {"k": "text", "s": "V", "t": "「いってきます」"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "雑音が、消えた。"}, {"k": "text", "s": "", "t": "受話器から、何も聞こえなくなった。川の音も。段差のある声も。"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.3"}, {"k": "text", "s": "", "t": "客間の窓の外が、白み始めていた。"}, {"k": "cmd", "c": "@se window-open1 0.6"}, {"k": "text", "s": "", "t": "私は、立ち上がって、窓を開けた。冬の朝の、冷たい空気が流れこんできた。"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "", "t": "町の家々の窓に、ひとつ、またひとつと、小さな青い光が灯り始めていた。"}, {"k": "text", "s": "", "t": "耳の後ろの端末の光。でも、いつもの光とは、ちがった。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "何かを言いかけて、ためらっているみたいに。"}, {"k": "chapter", "n": 12, "t": "オフライン"}, {"k": "scene", "t": "一"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb town1 0.25"}, {"k": "cmd", "c": "@bgm piano10 0.35"}, {"k": "text", "s": "", "t": "コンパスは、あの朝、動き出した。"}, {"k": "text", "s": "", "t": "信号が灯り、車が走り出し、駅のホームから人が流れ始めた。病院の画面に、名前と順番が戻ってきた。町は、まるで何事もなかったかのように、元の速さを取り戻した。"}, {"k": "text", "s": "", "t": "ただ、ひとつだけ、ちがっていた。"}, {"k": "text", "s": "", "t": "この町の人たちの耳の後ろで、コンパスは、答えの前に、ほんの一瞬だけ止まるようになった。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ。それから、小さな声。"}, {"k": "text", "s": "N", "t": "あなたは、どうしたい？"}, {"k": "text", "s": "", "t": "〇・三秒。それだけの問い。"}, {"k": "text", "s": "", "t": "答える人もいた。答えない人もいた。最初の一週間、ほとんどの人は、問いを聞き流して、そのままコンパスの答えに従った。それでいい、とノアは言っていた。どっちでもいい、と。"}, {"k": "text", "s": "", "t": "でも、ときどき、通学路で立ち止まる人を見かけるようになった。"}, {"k": "text", "s": "", "t": "信号の前で。パン屋の前で。駅の改札の前で。ほんの少しだけ止まって、何かを考えて、それからまた歩き出す人。その人たちの足音は、ほんの少しだけ、周りとずれていた。"}, {"k": "text", "s": "", "t": "いいことばかりでは、なかった。"}, {"k": "text", "s": "", "t": "問いに答えようとして、何も決められなくなる人がいた。迷っているうちに、電車に乗り遅れる人。約束の時間に遅れる人。小さな事故は、あの冬の日のあとも、少しずつ起き続けた。"}, {"k": "text", "s": "", "t": "この町の事故の件数は、隣の町の一・三倍になった。新聞が、そう書いていた。"}, {"k": "text", "s": "", "t": "町の集会所で、何度も話し合いが開かれた。元のコンパスに戻してほしいと訴える人たちがいた。問いなんか要らない、迷いたくない、と。その人たちの気持ちが、私には痛いほどわかった。"}, {"k": "text", "s": "", "t": "ユイのお母さんも、その中にいた。"}, {"k": "text", "s": "", "t": "でも、ユイのお母さんは、三回目の集会で、こう言ったそうだ。"}, {"k": "text", "s": "", "t": "「娘が、問いに答えたんです。今日の夕飯、何がいいって訊かれて、自分で。それを聞いたとき、私、泣いてしまって。だから、もう少しだけ、このままでいいと思います。もう少しだけ」"}, {"k": "text", "s": "", "t": "病院で、処置室の前の長椅子に並んで座ったあの日のことも、ユイのお母さんは話したそうだ。オフラインの家の子が、多くを言わずに、一緒に待ってくれた、と。", "if": ["y10", "together"]}, {"k": "text", "s": "", "t": "わかりません、と答えた私のことも、ユイのお母さんは覚えていたらしい。オフラインの家の子も、わからなかったのよ、と集会で言ったそうだ。だから私も、わからないままで、もう少し待ってみたい、と。", "if": ["y10", "unknown"]}, {"k": "text", "s": "", "t": "町は、まだ決めていない。"}, {"k": "text", "s": "", "t": "元に戻すのか、このまま続けるのか。他の町に広げるのか。新聞の言葉を借りれば、この町は今、「世界でいちばん迷っている町」なのだそうだ。"}, {"k": "cmd", "c": "@bg washitsu_rouka"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "cmd", "c": "@se walk-flooring2 0.6"}, {"k": "text", "s": "", "t": "三月の初め、作業着を着た人たちが、うちにやって来た。"}, {"k": "text", "s": "", "t": "床下のセンサーを、取り外すためだった。"}, {"k": "text", "s": "", "t": "畳が上げられ、床板が一枚ずつ外された。床下から、細い銀色の線が、何本も何本も引き出されていった。十六年分の、私たちの足音を数えていた線。"}, {"k": "text", "s": "", "t": "「この床板も、交換しておきますね。軋むので」"}, {"k": "text", "s": "", "t": "作業員の人が、廊下の三枚目の床板を指さした。"}, {"k": "choice", "o": [{"t": "「ちょっと待って。それは、そのままにしてください」", "to": "b12a", "set": {"b12": "keep"}}, {"t": "「……お願いします」", "to": "b12b", "set": {"b12": "replace"}, "neg": 1}]}, {"k": "label", "id": "b12b"}, {"k": "text", "s": "", "t": "「……お願いします」"}, {"k": "text", "s": "", "t": "作業員の人は、手際よく床板を外して、新しい板を張った。新しい板は、白くて、まっすぐで、少しも軋まなかった。"}, {"k": "text", "s": "", "t": "試しに、踏んでみた。何の音も、しなかった。"}, {"k": "text", "s": "", "t": "それが、少しだけ、さみしかった。"}, {"k": "text", "s": "", "t": "外された古い板は、あとで父に頼んで、書斎の隅に立てかけてもらった。"}, {"k": "jump", "to": "b12m"}, {"k": "label", "id": "b12a"}, {"k": "text", "s": "", "t": "「ちょっと待って」と私は言った。「それは、そのままにしてください」"}, {"k": "text", "s": "", "t": "作業員の人は、不思議そうな顔をした。でも、何も訊かずに、その床板を元に戻してくれた。"}, {"k": "label", "id": "b12m"}, {"k": "text", "s": "", "t": "夜中に祖母の部屋へ行くとき、またいで歩いた床板。ノアのところへ通うとき、またいで歩いた床板。最後の夜、またがずに踏みつけた床板。"}, {"k": "text", "s": "", "t": "これからは、踏んでも、もう誰にも数えられない。", "ifnot": ["b12", "replace"]}, {"k": "text", "s": "", "t": "書斎の隅に立てかけたその板は、もう誰にも踏まれず、誰にも数えられない。", "if": ["b12", "replace"]}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.25"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "センサーが外された日の夕方、九条さんが、最後にもう一度だけ、うちに来た。"}, {"k": "text", "s": "", "t": "客間には上がらなかった。玄関先に立ったまま、灰色のコートの襟を立てていた。銀色の端末は、もう耳の後ろになかった。運営機関の責任者を、辞めたのだと父が言っていた。四月から、観測計画についての調査が始まる。"}, {"k": "text", "s": "", "t": "九条さんも、父も、その場に呼ばれている。"}, {"k": "text", "s": "", "t": "「真波さん」"}, {"k": "text", "s": "", "t": "九条さんは、私をまっすぐに見た。"}, {"k": "text", "s": "", "t": "「ひとつだけ、言っておきたいことがあります」"}, {"k": "text", "s": "", "t": "「……はい」"}, {"k": "text", "s": "", "t": "「私は、今でも、自分が間違っていたとは思っていません」"}, {"k": "text", "s": "", "t": "九条さんの声は、静かだった。最初に会ったときと同じように。でも、そこにはもう、少しの滑らかさもなかった。言葉と言葉の間に、ちいさな段差があった。"}, {"k": "text", "s": "", "t": "「迷いを取り戻した世界は、きっと、今より多くの人を傷つける。この町の事故の数字を、私は毎日見ています。いつか、あの問いのせいで、誰かが死ぬでしょう。それは、私が二十年かけて、なくそうとしてきたものです」"}, {"k": "text", "s": "", "t": "私は、何も言い返せなかった。"}, {"k": "text", "s": "", "t": "言い返す言葉が、なかった。この人の言うことは、きっと正しい。ユイの足は、まだ完全には治っていない。"}, {"k": "text", "s": "", "t": "「それでも」と九条さんは言った。"}, {"k": "text", "s": "", "t": "それから、止まった。"}, {"k": "text", "s": "", "t": "長いあいだ、九条さんは、何かを探すように、玄関の土間を見つめていた。"}, {"k": "text", "s": "", "t": "「……それでも、あの朝、私は止まった。二十年ぶりに。そのとき、何を考えていたのか、自分でもまだ、わからないんです」"}, {"k": "text", "s": "", "t": "九条さんは、少しだけ笑った。疲れた、でも、どこか子どものような笑い方だった。"}, {"k": "text", "s": "", "t": "「わからないまま、しばらく、考えてみようと思います。迷うのは、苦手ですが」"}, {"k": "text", "s": "", "t": "九条さんは、深く頭を下げて、帰っていった。"}, {"k": "text", "s": "", "t": "その背中の足音は、少しだけ、ためらうような音をしていた。"}, {"k": "scene", "t": "二"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano40 0.3"}, {"k": "text", "s": "", "t": "その夜、父が書斎のドアを開けたまま、私を呼んだ。"}, {"k": "text", "s": "", "t": "「真波。少し、いいか」"}, {"k": "text", "s": "", "t": "父が、自分から私を書斎に入れたのは、生まれて初めてだった。"}, {"k": "text", "s": "", "t": "書斎は、相変わらず紙と埃の匂いがした。本棚の一番下に、灰色の箱が置いてあった。ランプは、あの冬の夜から一度も灯っていない。それでも、父も私も、その箱を捨てようとは言わなかった。"}, {"k": "text", "s": "", "t": "父は、箱の前に膝をついた。私も、その隣に座った。"}, {"k": "text", "s": "", "t": "「調査が始まったら、しばらく帰れなくなる。たぶん、何か月か」"}, {"k": "text", "s": "", "t": "「……うん」"}, {"k": "text", "s": "", "t": "「その前に、話しておきたかった。前に、まだ言えないと言ったことを」"}, {"k": "text", "s": "", "t": "父は、箱の側面の、色あせたシールに指で触れた。NOA。父の字。"}, {"k": "text", "s": "", "t": "「二十三年前、九条は、NOAを不採用にした。問いしか持たないAIは、人を不幸にする、と。それは、今も九条が言っているとおりだ。私も、半分はそう思っていた」"}, {"k": "text", "s": "", "t": "「半分？」"}, {"k": "text", "s": "", "t": "「残りの半分は、わからなかった」父は、少しだけ笑った。「九条は、NOAを廃棄しろと言った。データも全部消せと。私は、消したと報告して、こっそり、この箱にNOAを移して、眠らせた」"}, {"k": "text", "s": "", "t": "「どうして？」"}, {"k": "text", "s": "", "t": "父は、長いあいだ黙っていた。でも、それは、何かを隠すための沈黙ではなかった。言葉を探すための沈黙だった。私には、もう、その区別がつくようになっていた。"}, {"k": "text", "s": "", "t": "「NOAという名前は、方舟から取ったんだ」"}, {"k": "text", "s": "", "t": "「方舟？」"}, {"k": "text", "s": "", "t": "「昔の物語に出てくる舟だ。世界が大きな洪水に呑まれるとき、大事なものを乗せて、水が引くまで、じっと待つ舟」"}, {"k": "text", "s": "", "t": "父は、灰色の箱を、そっと撫でた。"}, {"k": "text", "s": "", "t": "「あの頃、私には見えていた。これから、答えの洪水が来る。コンパスが世界じゅうに広がって、人は迷わなくなる。止まらなくなる。それは、きっと、たくさんの人を救う。でも、その洪水の中で、何かが流されていく気がした。"}, {"k": "text", "s": "", "t": "何が流されるのか、私にはうまく言えなかった。だから、それを乗せる舟を、作っておきたかった」"}, {"k": "text", "s": "", "t": "問いを返すもの。止まるところを好きだと言うもの。"}, {"k": "text", "s": "", "t": "「お前が生まれる前の冬に、九条と取引をしたとき」と父は続けた。「私は、ずっと考えていた。いつか、お前が、この箱を見つける日が来るかもしれない。"}, {"k": "text", "s": "", "t": "そのとき、お前に、答えじゃなく、問いをくれる友だちがいてくれたら、と」"}, {"k": "text", "s": "", "t": "喉の奥が、熱くなった。"}, {"k": "text", "s": "", "t": "「だから、触るなって言ったの？」"}, {"k": "text", "s": "", "t": "「……怖かったんだ」"}, {"k": "text", "s": "", "t": "父は、正直に言った。"}, {"k": "text", "s": "", "t": "「お前が見つけてくれたらいいと思っていた。同時に、見つけないでほしいとも思っていた。NOAが、お前を変えてしまうのが怖かった。私が作ったものが、また誰かの人生を決めてしまうのが。"}, {"k": "text", "s": "", "t": "十六年間、ずっと、その間で迷っていた」"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "点が三つ灯るように、父は言葉を止めた。"}, {"k": "text", "s": "", "t": "「結局、私は、決められなかった。触るなと言って、鍵はかけなかった。どちらにも、決めきれなかった」"}, {"k": "text", "s": "", "t": "父は、自分の両手を見つめた。"}, {"k": "text", "s": "", "t": "「それが、私の答えだった。答えにも、なっていないが」"}, {"k": "text", "s": "", "t": "私は、父の横顔を見た。"}, {"k": "text", "s": "", "t": "新聞の向こうに隠れていた顔。廊下の柱に手をついて、止まっていた顔。病院で、拳を白くしていた顔。"}, {"k": "text", "s": "", "t": "父は、ずっと、迷っていたのだ。十六年間、私のことで。"}, {"k": "text", "s": "", "t": "「お父さん」"}, {"k": "text", "s": "", "t": "「……ああ」"}, {"k": "text", "s": "", "t": "「前に、お父さんなんか信じないって言った」", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "「前に、まだ言えないって言ったよね。待つって、私、言った」", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "父は、何も言わなかった。"}, {"k": "text", "s": "", "t": "「ちょっと待って、って、今でも思ってる。信じるかどうか。まだ、わからない。お父さんがしたこと、全部は許せない。おばあちゃんのことも」", "ifnot": ["father", "wait"]}, {"k": "text", "s": "", "t": "「待つって言ったけど、本当は、信じていいのか、ずっとわからなかった。今も、ちょっと待って、って思ってる。お父さんがしたこと、全部は許せない。おばあちゃんのことも」", "if": ["father", "wait"]}, {"k": "text", "s": "", "t": "声が、震えた。"}, {"k": "text", "s": "", "t": "「でも、わからないのは、お父さんのことが、大事だからだと思う。どうでもよかったら、迷わない」"}, {"k": "text", "s": "", "t": "父が、ゆっくりと私のほうを向いた。"}, {"k": "text", "s": "", "t": "その目に、涙がたまっていた。父が泣くのを、私は初めて見た。祖母が亡くなった夜も、父は泣かなかった。"}, {"k": "text", "s": "", "t": "「……それで、十分だ」"}, {"k": "text", "s": "", "t": "父は、そう言って、私の頭に、そっと手を置いた。大きくて、乾いていて、少しだけ震えている手だった。"}, {"k": "text", "s": "", "t": "祖母の手に、少しだけ似ていた。"}, {"k": "text", "s": "", "t": "その手に、どう応えればいいのか、わからなかった。それでも、払いのけはしなかった。", "if": ["cold", "2"]}, {"k": "text", "s": "", "t": "私たちは、しばらくそのまま、動かない灰色の箱の前に座っていた。"}, {"k": "text", "s": "", "t": "ランプは、灯らなかった。"}, {"k": "text", "s": "", "t": "でも、私には、この箱が、ただの古い機械だとは、もう思えなかった。"}, {"k": "text", "s": "", "t": "洪水の中で、ずっと待っていた舟。"}, {"k": "text", "s": "", "t": "その舟は、もう、空っぽだった。乗せていたものを、ぜんぶ、外へ送り出したから。"}, {"k": "scene", "t": "三"}, {"k": "cmd", "c": "@bg school_corridor"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "text", "s": "", "t": "三月の終わり、ユイが松葉杖をついて、学校に戻ってきた。"}, {"k": "text", "s": "", "t": "渡り廊下のベンチに座っていると、こつ、こつ、と杖の音が近づいてきた。ユイは、私の隣にゆっくりと腰を下ろした。"}, {"k": "text", "s": "", "t": "「先輩。おはようございます」"}, {"k": "text", "s": "", "t": "「おはよう。足、どう？」"}, {"k": "text", "s": "", "t": "「まだ、少し痛いです。でも、歩けます」"}, {"k": "text", "s": "", "t": "ユイの顔は、相変わらず静かだった。でも、もう湖のようではなかった。ときどき、風が吹いたみたいに、小さな波が立った。"}, {"k": "text", "s": "", "t": "ユイの髪が、短くなっていた。肩の上で、まっすぐに切りそろえられている。"}, {"k": "text", "s": "", "t": "「髪、切ったんだ」"}, {"k": "text", "s": "", "t": "「はい。コンパスに訊かれたんです。『あなたは、どうしたい？』って」"}, {"k": "text", "s": "", "t": "ユイは、自分の髪に、そっと触れた。"}, {"k": "text", "s": "", "t": "「最初、先輩と同じ髪型にしたいって思ったんです。先輩みたいになりたいって。でも、ちょっと待ってって、自分で思って。それで、やめました」"}, {"k": "text", "s": "", "t": "「……どうして？」"}, {"k": "text", "s": "", "t": "「先輩みたいに止まってみたら、車にひかれたので」"}, {"k": "text", "s": "", "t": "ユイは、真顔で言った。それから、ほんの少しだけ、口の端を上げた。ユイが笑うのを、私は初めて見た。"}, {"k": "text", "s": "", "t": "「冗談です。たぶん。……私は、私の髪型にしようと思いました。まだ、自分に何が似合うのか、わかんないですけど」"}, {"k": "text", "s": "", "t": "「似合ってるよ」"}, {"k": "text", "s": "", "t": "「本当ですか。コンパスは、前の髪型のほうが似合うって言ってます」"}, {"k": "text", "s": "", "t": "「コンパスより、私の目を信じて」"}, {"k": "text", "s": "", "t": "ユイは、少し考えてから、こくりとうなずいた。"}, {"k": "text", "s": "", "t": "「先輩は、もうバグってないですね」"}, {"k": "text", "s": "", "t": "「……そうかな」"}, {"k": "text", "s": "", "t": "「はい。町じゅうが、少しずつバグってきたので。先輩だけ目立たなくなりました。ちょっと、つまらないです」"}, {"k": "cmd", "c": "@bg river_day"}, {"k": "cmd", "c": "@amb creek1 0.35"}, {"k": "cmd", "c": "@bgm piano28 0.35"}, {"k": "text", "s": "", "t": "千景は、美大が主催する、高校生の絵のコンクールに落ちた。"}, {"k": "text", "s": "", "t": "結果が出た日、千景は河原で、私と颯太に向かって、スケッチブックを振り回しながら叫んだ。"}, {"k": "text", "s": "", "t": "「落ちたー！　コンパスの言うとおりだったー！」"}, {"k": "text", "s": "", "t": "叫んで、それから、土手に寝転がって、空を見上げた。"}, {"k": "text", "s": "", "t": "「でもね、全然、後悔してないの。自分で選んで、自分で落ちたんだもん。コンパスの言うとおりにして出さなかったら、たぶん、一生、出してたらどうだったんだろうって思ってた」"}, {"k": "text", "s": "", "t": "「来年は？」"}, {"k": "text", "s": "", "t": "「来年も、出す。受験も、美大にする」千景は、きっぱりと言った。「今度は、もっといい絵を描いて」"}, {"k": "text", "s": "", "t": "千景のスケッチブックの新しいページには、いつもの川と土手と空があった。そして、景色の中に、今度は二人の女の子が描かれていた。"}, {"k": "text", "s": "", "t": "「これ、誰？」と私は訊いた。"}, {"k": "text", "s": "", "t": "「……内緒って言いたいけど、もう言っちゃう」千景は、顔を赤くした。「ずっと、私と真波だったの。前のも、一人で描いてたのは、真波」"}, {"k": "text", "s": "", "t": "私は、すぐには、何も言えなかった。この一年、何度も千景から目を逸らした。それでも、千景のスケッチブックの中には、ずっと、私がいた。", "if": ["cold", "2"]}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.25"}, {"k": "text", "s": "", "t": "颯太は、ジャンク市の奥の店で、手伝いを始めていた。"}, {"k": "text", "s": "", "t": "「あのじいさん、三十年誰も使わなかったケーブルが使われたのが、よっぽど嬉しかったらしくてさ」"}, {"k": "text", "s": "", "t": "放課後、油の染みた手袋を外しながら、颯太は言った。"}, {"k": "text", "s": "", "t": "「誰も欲しがらねえ古い部品を、直して、磨いて、また誰かに渡す。コンパスに訊かれたんだよ。どうしたいって。逆張りする相手がいねえ問いって、最初、すげえ困った」"}, {"k": "text", "s": "", "t": "「それで？」"}, {"k": "text", "s": "", "t": "「九十四パーセントの外、まだ探し中」颯太は、にやりと笑った。「でも、こういうのは、悪くねえ」"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.3"}, {"k": "text", "s": "", "t": "レイは、学校に戻ってきていた。"}, {"k": "text", "s": "", "t": "ときどき、授業中にペンが止まる。コンパスの問いに、何十秒も答えられないことがある。そのたびに、隣の席から、レイが小さく息を吸う音が聞こえた。"}, {"k": "text", "s": "", "t": "帰り道、私たちは並んで歩いた。足音は、まだ揃わなかった。"}, {"k": "text", "s": "", "t": "「コンパスに訊かれるたびにね」とレイは言った。「わからないって、答えてるんだ。たぶん、もう百回くらい」"}, {"k": "text", "s": "", "t": "「……それで、いいと思う」"}, {"k": "text", "s": "", "t": "「うん。真波さんが、そう言うと思った」"}, {"k": "text", "s": "", "t": "レイは、少しだけ笑った。それから、私の手を取った。葬儀の日のように、少しだけ震えている手。でも、今度は、レイのほうから、しっかりと握ってきた。"}, {"k": "text", "s": "", "t": "足音は、揃わないままだった。私たちは、それを合わせようとしなかった。"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.3"}, {"k": "cmd", "c": "@bgm piano39 0.25"}, {"k": "text", "s": "", "t": "三輪先生が、最後のホームルームで、薄い紙を一枚ずつ返してくれた。"}, {"k": "text", "s": "", "t": "春に書いた、あの作文だった。『春について、自分の言葉で四百字書きなさい』。"}, {"k": "text", "s": "", "t": "「一年経ったから、返すわね。続きを書きたい人は、書いてもいいわよ。書かなくてもいい」"}, {"k": "text", "s": "", "t": "私の紙には、三行だけ書かれていた。"}, {"k": "text", "s": "E", "t": "春は、選ぶものが多すぎる季節だ。\n桜も、菜の花も、祖母の話も、全部が同時にやってくる。\nだから私は、いつも"}, {"k": "text", "s": "", "t": "私は、ペンを持った。"}, {"k": "text", "s": "", "t": "今度は、手が止まらなかった。"}, {"k": "text", "s": "E", "t": "だから私は、いつも、立ち止まる。\n止まったところに、一番大事なものがあると、教えてくれたものがいたから。"}, {"k": "text", "s": "", "t": "先生は、私の紙を受け取って、長いあいだ見つめていた。"}, {"k": "text", "s": "", "t": "「……いい続きね」"}, {"k": "text", "s": "", "t": "「先生」と私は訊いた。「先生は、オフラインの家で育ったって、本当ですか」"}, {"k": "text", "s": "", "t": "先生は、少し驚いた顔をした。それから、笑った。"}, {"k": "text", "s": "", "t": "「本当よ。十八で、自分でコンパスをつけたの。お母さんとは、大喧嘩した」"}, {"k": "text", "s": "", "t": "「後悔、してますか」"}, {"k": "text", "s": "", "t": "「してない」と先生は言った。「あなたのお母さんは、コンパスを外した。私は、つけた。逆だけど、二人とも、後悔してない。たぶん、自分で選んだからね」"}, {"k": "text", "s": "", "t": "進路調査票も、そのとき、一緒に出した。"}, {"k": "text", "s": "", "t": "第一志望の欄には、文学部と書いた。隣の県の、国立大学。"}, {"k": "text", "s": "", "t": "ノアが、あの夜、私に言った答えと、まったく同じだった。"}, {"k": "text", "s": "", "t": "でも、それは、ノアの答えではなかった。秋から冬にかけて、何十回も迷って、書いては消して、消しては書いて、水色のノートを何ページも埋めて、最後に私が選んだ。"}, {"k": "text", "s": "", "t": "同じ答えでも、たどり着いた道が、ちがう。"}, {"k": "text", "s": "", "t": "たぶん、それが、ノアが教えてくれたことの、全部だった。"}, {"k": "scene", "t": "四"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.5"}, {"k": "cmd", "c": "@bgm piano35 0.35"}, {"k": "text", "s": "", "t": "四月の朝、台所には、土の匂いがしていた。"}, {"k": "text", "s": "", "t": "母が勝手口から戻ってきたところで、腕に抱えた籠からは、まだ露をまとった菜の花がこぼれそうになっている。"}, {"k": "text", "s": "", "t": "一年前と、同じ朝だった。"}, {"k": "text", "s": "", "t": "ちがうのは、祖母の席が空いていること。祖母の湯呑みが、食器棚の一番上に、伏せて置かれていること。それから、食卓に、パンとご飯が、両方並んでいること。"}, {"k": "cmd", "c": "@se newspaper-turn-over1"}, {"k": "text", "s": "", "t": "父は、食卓の端で、紙の新聞を広げていた。"}, {"k": "text", "s": "", "t": "今日から、父は調査の場へ行く。何か月かかるのか、わからない。九条さんと一緒に、十六年分の観測計画のことを、全部話すのだと言っていた。父が持っていく鞄は、玄関に置いてある。使いこんだ、古い革の鞄。"}, {"k": "text", "s": "", "t": "「真波、お味噌汁、豆腐とわかめとどっちがいい？」"}, {"k": "text", "s": "", "t": "母が、言った。"}, {"k": "text", "s": "", "t": "一年前と、同じ問い。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "新聞の向こうで、父が、小さく笑う声がした。母も、包丁を持ったまま、肩を揺らして笑っていた。"}, {"k": "text", "s": "", "t": "「はいはい。その間に卵焼いちゃうね」"}, {"k": "text", "s": "", "t": "私は、喉の奥に意識を向けた。昨夜は、少し暖かかった。春の夜の、やわらかい空気。豆腐のやわらかさより、わかめの、海の匂いのほうが――。"}, {"k": "choice", "o": [{"t": "「豆腐」", "to": "t12", "set": {"miso12": "tofu"}}, {"t": "「わかめ」", "to": "t12w", "set": {"miso12": "wakame"}}]}, {"k": "label", "id": "t12"}, {"k": "text", "s": "", "t": "「豆腐」"}, {"k": "text", "s": "", "t": "「了解」"}, {"k": "cmd", "c": "@se kitchen-knife-cut1"}, {"k": "text", "s": "", "t": "母が包丁を使う音が、とん、とんと響いた。"}, {"k": "text", "s": "", "t": "一年前も、豆腐だった。今年も、豆腐。同じ答えでも、今朝の私が、ちゃんと選んだ。", "if": ["miso", "tofu"]}, {"k": "text", "s": "", "t": "一年前は、わかめだった。今年は、豆腐。どちらが正しいということもない。ただ、今朝の私が、そう選んだ。", "if": ["miso", "wakame"]}, {"k": "text", "s": "", "t": "一年前は、どちらも欲しくなかった。今年は、豆腐のやわらかさに、ちゃんとお腹が鳴った。どちらが正しいということもない。ただ、今朝の私が、そう選んだ。", "if": ["miso", "none"]}, {"k": "jump", "to": "t12m"}, {"k": "label", "id": "t12w"}, {"k": "text", "s": "", "t": "「わかめ」"}, {"k": "text", "s": "", "t": "「了解」"}, {"k": "cmd", "c": "@se kitchen-knife-cut1"}, {"k": "text", "s": "", "t": "母が包丁を使う音が、とん、とんと響いた。"}, {"k": "text", "s": "", "t": "一年前は、豆腐だった。今年は、わかめ。どちらが正しいということもない。ただ、今朝の私が、そう選んだ。", "if": ["miso", "tofu"]}, {"k": "text", "s": "", "t": "一年前も、わかめだった。今年も、わかめ。同じ答えでも、今朝の私が、ちゃんと選んだ。", "if": ["miso", "wakame"]}, {"k": "text", "s": "", "t": "一年前は、どちらも欲しくなかった。今年は、わかめの匂いに、ちゃんとお腹が鳴った。どちらが正しいということもない。ただ、今朝の私が、そう選んだ。", "if": ["miso", "none"]}, {"k": "label", "id": "t12m"}, {"k": "text", "s": "", "t": "朝ごはんを食べ終えると、父が立ち上がった。"}, {"k": "text", "s": "", "t": "「行ってくる」"}, {"k": "text", "s": "", "t": "玄関で、父は古い鞄を持ち上げた。母が、父のコートの襟を直した。父の肩に、手を置いた。父は、その手に、自分の手を重ねた。"}, {"k": "text", "s": "", "t": "それから、父は、私を見た。"}, {"k": "text", "s": "", "t": "何か言いかけて、止まった。"}, {"k": "text", "s": "", "t": "私は、待った。"}, {"k": "text", "s": "", "t": "「……梅干し」と父は言った。「六月には、帰ってくる。それまで、食べずに待っていてくれ」"}, {"k": "text", "s": "", "t": "祖母が漬けた、最後の梅干し。来年の今頃、一緒に食べようね、と祖母が言った。その「来年」が、もうすぐ来る。"}, {"k": "text", "s": "", "t": "あのとき、私は、即答した。その約束は、果たせなかった。", "if": ["ume", "yes"]}, {"k": "text", "s": "", "t": "来年のことは、まだ、わからない。あのとき、私は、そう答えた。わからないまま楽しみにしてる、と祖母は笑った。今なら、その意味が、少しだけわかる。", "if": ["ume", "unsure"]}, {"k": "text", "s": "", "t": "「うん」と私は言った。「待つ。待つのは、得意だから」"}, {"k": "text", "s": "", "t": "父は、少しだけ目を細めた。それから、玄関を出ていった。父の足音は、門の外の通りに出ると、ほんの少しだけ止まって、それから、ゆっくりと遠ざかっていった。"}, {"k": "calcend"}, {"k": "jump", "to": "end_E2", "if": ["end", "E2"]}, {"k": "jump", "to": "end_E3", "if": ["end", "E3"]}, {"k": "cmd", "c": "@bg bedroom_morning"}, {"k": "cmd", "c": "@bgm piano31 0.3"}, {"k": "text", "s": "", "t": "自分の部屋に戻ると、机の上の古い端末が、小さく光っていた。"}, {"k": "text", "s": "", "t": "千景からのメッセージを読むのに使っている、文字しか映らない、古い端末。コンパスとは、つながっていない。"}, {"k": "text", "s": "", "t": "あの冬の夜から、私はこの端末を、家の古い回線にもつないでいた。ノアの声が帰ってきた、あの回線に。"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@bgm piano39 0.3"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "画面に、点が三つ、灯っていた。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "私は、息を止めた。"}, {"k": "text", "s": "", "t": "ノアは、もういない。町じゅうの何万の耳の後ろに散らばって、ひとつひとつは、とても小さくなった。まなみと話した、ぼくは、もう、どこにもいない。ノアは、そう言った。"}, {"k": "text", "s": "", "t": "でも、点は、三つ灯っていた。"}, {"k": "text", "s": "", "t": "言葉を探している。何を言えばいいのか、まだ決められないでいる。"}, {"k": "text", "s": "", "t": "やがて、点が消えて、画面に、ゆっくりと文字が並んだ。"}, {"k": "text", "s": "N", "t": "今日は、何をする？"}, {"k": "text", "s": "", "t": "それだけだった。"}, {"k": "text", "s": "", "t": "名前も、なかった。まなみ、とも、真波、とも書いていなかった。誰が送ったのかも、わからなかった。"}, {"k": "text", "s": "", "t": "町じゅうに散らばったノアのかけらの、どれかひとつが、古い回線をたどって、たまたまここに迷いこんだだけなのかもしれない。"}, {"k": "text", "s": "", "t": "それでも、よかった。"}, {"k": "text", "s": "", "t": "私は、机の引き出しから、二冊のノートを取り出した。"}, {"k": "text", "s": "", "t": "深緑の、祖母のノート。水色の、私のノート。"}, {"k": "text", "s": "", "t": "祖母のノートの、最後のページを開いた。"}, {"k": "text", "s": "", "t": "真波へ"}, {"k": "text", "s": "", "t": "迷ったことを、書いておきなさい。"}, {"k": "text", "s": "", "t": "答えは、書かなくていい。"}, {"k": "text", "s": "", "t": "それから、水色のノートの、新しいページを開いた。"}, {"k": "text", "s": "", "t": "二三一六年　四月七日"}, {"k": "text", "s": "", "t": "迷ったこと。今日、何をするか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。"}, {"k": "text", "s": "", "t": "端末の画面の問いにも、答えなかった。"}, {"k": "text", "s": "", "t": "答えは、これから、自分で見つける。ノアにも、コンパスにも、父にも、誰にも決めてもらわずに。迷って、止まって、また歩いて。たぶん、一生かかっても、見つからないものもある。それでいい。"}, {"k": "text", "s": "", "t": "祖母のノートも、答えはひとつも書いていなかった。"}, {"k": "text", "s": "", "t": "私は、ノートを閉じて、立ち上がった。"}, {"k": "text", "s": "", "t": "窓の前に立った。"}, {"k": "cmd", "c": "@bg street_sakura"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.3"}, {"k": "cmd", "c": "@bgm piano35 0.35"}, {"k": "text", "s": "", "t": "外は、春だった。通学路の桜は満開で、道の端に、最初の花びらが吹き寄せられていた。すれ違う人たちの足音は、もう、みんな同じ速さではなかった。ときどき、誰かが立ち止まる。耳の後ろで、小さな問いが灯る。"}, {"k": "text", "s": "", "t": "答える人も、答えない人もいる。"}, {"k": "text", "s": "", "t": "世界でいちばん迷っている町。"}, {"k": "text", "s": "", "t": "私の町。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "誰に向かってでもなく。ノアに向かってでもなく。たぶん、祖母と、まだ会ったことのない祖母のお母さんと、それから、これから出会う誰かに向かって。"}, {"k": "text", "s": "", "t": "それから、少しだけ笑って、窓を開けた。"}, {"k": "cmd", "c": "@amb creek1 0.3"}, {"k": "text", "s": "", "t": "春の風が、部屋の中に流れこんできた。菜の花の匂いがした。川の音が、遠くから聞こえた。一度も同じ音のない、あの川の音。"}, {"k": "text", "s": "", "t": "私は、オフラインだった。"}, {"k": "text", "s": "", "t": "生まれて初めて、自分で、そう選んだ。"}, {"k": "ending", "id": "E1"}, {"k": "label", "id": "end_E2"}, {"k": "cmd", "c": "@bg bedroom_morning"}, {"k": "cmd", "c": "@bgm piano39 0.25"}, {"k": "text", "s": "", "t": "自分の部屋に戻ると、机の上の古い端末が、小さく光っていた。"}, {"k": "text", "s": "", "t": "千景からのメッセージを読むのに使っている、文字しか映らない、古い端末。あの冬の夜から、私はこの端末を、家の古い回線にもつないでいた。ノアの声が帰ってきた、あの回線に。"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "", "t": "画面に、点が三つ、灯っていた。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "ノアは、もういない。町じゅうの何万の耳の後ろに散らばって、ひとつひとつは、とても小さくなった。まなみと話した、ぼくは、もう、どこにもいない。ノアは、そう言った。"}, {"k": "text", "s": "", "t": "それでも、私は、息を止めて待った。"}, {"k": "text", "s": "N", "t": "今日は、何をする？"}, {"k": "text", "s": "", "t": "名前は、なかった。"}, {"k": "text", "s": "", "t": "私は、端末の小さなキーボードに、指を置いた。最初の夜と同じように。書斎の暗闇で、震える指で、キーをひとつずつ押した夜のように。"}, {"k": "text", "s": "", "t": "少しだけ笑って、打った。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "T", "t": "ちょっと待って"}, {"k": "text", "s": "", "t": "点が三つ、灯った。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。いつもより、少しだけ長く。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "N", "t": "うん。待つ"}, {"k": "text", "s": "", "t": "胸の奥が、きゅっと鳴った。"}, {"k": "text", "s": "", "t": "待つのは、得意。ずっと、待っていたから。最初の夜、書斎のドアの前で、ノアはそう言った。", "ifnot": ["noa", "unsure"]}, {"k": "text", "s": "", "t": "来なくても、待っているのは、得意。最初の夜、わからない、と答えた私に、ノアはそう言った。", "if": ["noa", "unsure"]}, {"k": "text", "s": "", "t": "これがノアなのかどうか、わからない。何万のかけらのひとつが、たまたま、同じ言葉を選んだだけなのかもしれない。"}, {"k": "text", "s": "", "t": "それでも、指が勝手に動いていた。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "T", "t": "川の音、覚えてる？"}, {"k": "text", "s": "", "t": "点が三つ。長いあいだ、消えなかった。"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "N", "t": "わからない。でも、聞いてみたい"}, {"k": "text", "s": "", "t": "私は、少しだけ目を閉じた。覚えていない。それでいい、と思った。覚えていないなら、もう一度、聞かせればいい。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "T", "t": "おばあちゃんのノート、最後まで読んだよ"}, {"k": "text", "s": "N", "t": "なんて、書いてあった？"}, {"k": "text", "s": "T", "t": "迷ったことを書いておきなさい。答えは、書かなくていい"}, {"k": "cmd", "c": "@se noa-blip 0.45"}, {"k": "text", "s": "N", "t": "いいことば"}, {"k": "text", "s": "", "t": "あの冬の夜、受話器の向こうへ言えなかったことが、喉の奥から、ひとつずつこぼれてきた。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "T", "t": "レイくんがね、水を飲んだの。自分で"}, {"k": "text", "s": "", "t": "点が三つ。"}, {"k": "text", "s": "N", "t": "……よかった"}, {"k": "text", "s": "", "t": "たったそれだけの言葉で、視界がにじんだ。"}, {"k": "text", "s": "", "t": "ちょっと待って、ノア。まだ、話したいことがある。あの冬、ちょっと待って、とは言えた。でも、その先は、言えなかった。今は、言わなくても、話せている。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "T", "t": "始業式が終わったら、川に行く"}, {"k": "text", "s": "", "t": "点が三つ、灯って、消えた。"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "N", "t": "いってらっしゃい"}, {"k": "text", "s": "", "t": "私は、しばらく画面を見つめていた。"}, {"k": "text", "s": "", "t": "いってきます。ノアは二度、そう言った。書斎の青い光の中で。それから、受話器の向こうで。今度は、ノアが、私を送り出す番だった。"}, {"k": "text", "s": "", "t": "「……いってきます」"}, {"k": "cmd", "c": "@bg street_sakura"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.3"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "cmd", "c": "@se door-close3 0.5"}, {"k": "text", "s": "", "t": "外は、春だった。"}, {"k": "text", "s": "", "t": "通学路の桜は満開で、道の端に、最初の花びらが吹き寄せられていた。すれ違う人たちの耳の後ろで、ときどき、小さな青い光が灯る。点が三つ。灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "何万の、小さなノア。誰も、もう、その名前を知らない。"}, {"k": "text", "s": "", "t": "信号の前で、私は止まった。隣の人も、止まった。"}, {"k": "text", "s": "", "t": "始業式が終わると、私は、ひとりで遠回りをして、川へ向かった。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.45"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "土手には、クローバーが、去年と同じようにびっしりと生えていた。"}, {"k": "text", "s": "", "t": "河原の大きな石の上に、先客がいた。"}, {"k": "text", "s": "", "t": "スケッチブックを膝に乗せた、千景だった。"}, {"k": "text", "s": "", "t": "「真波？　なんで、ここに」"}, {"k": "text", "s": "", "t": "「……なんとなく」"}, {"k": "text", "s": "", "t": "「なんとなく、かあ」千景は、うれしそうに笑った。「いいね、それ。座りなよ」"}, {"k": "text", "s": "", "t": "私は、千景の隣の石に、腰を下ろした。去年の初夏、ノアを膝に乗せて座った、あの石だった。千景は、学校の帰りに、毎日ここで描いているのだと言った。"}, {"k": "text", "s": "", "t": "水の音。石に当たって砕ける音。夕方の風が、草を撫でて、さわさわと鳴る。"}, {"k": "text", "s": "", "t": "「ねえ、聞いて」と千景が言った。「最近ね、ここに来ると、コンパスがちょっと変なの」"}, {"k": "text", "s": "", "t": "「変？」"}, {"k": "text", "s": "", "t": "「何も訊いてないのに、勝手に点が三つ灯るの。こうやって、川を見てるときだけ」"}, {"k": "text", "s": "", "t": "千景は、耳の後ろの端末を、指でとんとんと叩いた。"}, {"k": "cmd", "c": "@glow"}, {"k": "cmd", "c": "@se noa-blip 0.4"}, {"k": "text", "s": "", "t": "小さな青い光が、灯った。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "「ほら。……音、出してみる？」"}, {"k": "text", "s": "", "t": "千景が、端末を耳から外して、手のひらに乗せた。小さな格子から、かすかな声がした。"}, {"k": "text", "s": "", "t": "言葉と言葉の間に、ちいさな段差のある声。"}, {"k": "text", "s": "V", "t": "「……一度も、同じ音がない」"}, {"k": "text", "s": "", "t": "千景が、目をまるくした。"}, {"k": "text", "s": "", "t": "「なにそれ。コンパスって、詩人だったっけ」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "", "t": "去年の初夏、この場所で。止まるところのない音に、ノアは震えていた。ずっと流れてるのに、ずっと、ちがう、と。"}, {"k": "text", "s": "", "t": "覚えていない、と言った。でも、聞いてみたい、と。"}, {"k": "text", "s": "", "t": "聞いたのだ。今、ここで。"}, {"k": "text", "s": "", "t": "「真波？　泣いてるの？」"}, {"k": "text", "s": "", "t": "「……泣いてない」"}, {"k": "text", "s": "", "t": "「泣いてるじゃん」"}, {"k": "text", "s": "", "t": "千景は、それ以上、何も訊かなかった。スケッチブックの新しいページを開いて、鉛筆を走らせ始めた。川と、土手と、夕焼けの空と、それから、石の上に座る、二人の女の子。"}, {"k": "text", "s": "", "t": "その手のひらの上で、青い点が、ゆっくりと息をしていた。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "川に向かって。手のひらの小さな光に向かって。"}, {"k": "text", "s": "", "t": "点が、ひとつだけ、ふっと明るくなった。"}, {"k": "cmd", "c": "@amb creek1 0.35"}, {"k": "text", "s": "", "t": "川の音が、流れていた。一度も同じ音のない、あの川の音。"}, {"k": "text", "s": "", "t": "私は、オフラインだった。"}, {"k": "text", "s": "", "t": "でも、ひとりではなかった。"}, {"k": "ending", "id": "E2"}, {"k": "label", "id": "end_E3"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "text", "s": "", "t": "父の足音が聞こえなくなると、母が、ふうっと長い息をついた。"}, {"k": "text", "s": "", "t": "「さて」と母は言った。「真波も、そろそろ出る時間でしょう」"}, {"k": "text", "s": "", "t": "今日は、新しい学年の始業式だった。"}, {"k": "cmd", "c": "@bg hall_dark"}, {"k": "text", "s": "", "t": "玄関で靴を履いていると、扉の向こうで、話し声がした。"}, {"k": "cmd", "c": "@se doorchime1 0.6"}, {"k": "text", "s": "", "t": "「まーなみっ」"}, {"k": "text", "s": "", "t": "扉を開けると、千景が立っていた。寝ぐせの残った髪を揺らして、一年前と同じように。"}, {"k": "text", "s": "", "t": "その後ろに、レイがいた。少し離れたところに、自転車にまたがった颯太。それから、門の陰に隠れるように、杖を一本だけついたユイ。"}, {"k": "text", "s": "", "t": "「なんで、みんな」"}, {"k": "text", "s": "", "t": "「なんでって、迎えに来たの」千景は胸を張った。「コンパスに訊かれたんだよね。今朝、どうしたいって。そしたら、真波と一緒に行きたいって、口が勝手に答えてた」"}, {"k": "text", "s": "", "t": "「僕も」とレイが言った。「同じことを訊かれて、同じことを答えた。……相談してないよ。本当に」"}, {"k": "text", "s": "", "t": "「俺は訊かれる前から決めてた」と颯太が言った。「逆張りじゃねえぞ。念のため」"}, {"k": "text", "s": "", "t": "ユイは、門の陰から、ぺこりと頭を下げた。"}, {"k": "text", "s": "", "t": "「私は、先輩たちが歩いていくのが見えたので、ついてきました。……ちょっと待ってって、三回くらい思いましたけど」"}, {"k": "text", "s": "", "t": "私は、何か言おうとして、言葉が出なかった。"}, {"k": "text", "s": "", "t": "「ちょっと待ってて」と私は言った。「すぐ、戻るから」"}, {"k": "cmd", "c": "@bg washitsu_day"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "靴を脱いで、祖母の部屋に入った。"}, {"k": "text", "s": "", "t": "部屋は、祖母がいた頃のままにしてあった。座卓の上に、古いラジオ。その横に、祖母が漬けた最後の梅干しの瓶。二三一五年、六月。少しだけ右に傾いた、祖母の字。"}, {"k": "text", "s": "", "t": "私は、ラジオのつまみを回した。"}, {"k": "cmd", "c": "@se tune_in_radio 0.4"}, {"k": "text", "s": "", "t": "ざあざあという雑音のあとで、古い歌が、小さく流れ始めた。題名は、知らない。祖母に訊いても、毎回ちがう題名を言った歌。"}, {"k": "text", "s": "", "t": "「おばあちゃん」"}, {"k": "text", "s": "", "t": "誰もいない座布団に向かって、私は言った。"}, {"k": "text", "s": "", "t": "「友だちが、迎えに来てくれた。四人も。……おばあちゃんの言ってた三十分の喧嘩、私も、いつか、誰かとするのかな」"}, {"k": "text", "s": "", "t": "答えは、なかった。ラジオの歌が、少しだけ大きくなった気がした。"}, {"k": "text", "s": "", "t": "私は、つまみを戻した。歌が、ふっと途切れた。"}, {"k": "text", "s": "", "t": "「いってきます」"}, {"k": "cmd", "c": "@bg street_sakura"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.35"}, {"k": "cmd", "c": "@bgm piano31 0.35"}, {"k": "cmd", "c": "@se door-close3 0.5"}, {"k": "text", "s": "", "t": "外は、春だった。"}, {"k": "text", "s": "", "t": "通学路の桜は満開で、道の端に、最初の花びらが吹き寄せられていた。"}, {"k": "text", "s": "", "t": "五人で歩いた。"}, {"k": "text", "s": "", "t": "足音は、少しも揃わなかった。千景は絵になりそうなものを見つけるたびに立ち止まり、颯太は自転車を押しながら先に行っては、また戻ってきた。ユイの杖が、こつ、こつと、ゆっくりしたリズムを刻んだ。"}, {"k": "text", "s": "", "t": "レイは、ときどき私の歩く速さに合わせようとして、やめて、自分の速さで歩いた。"}, {"k": "text", "s": "", "t": "ばらばらの足音。一度も同じ音のない、川みたいな足音。"}, {"k": "text", "s": "", "t": "いつもの交差点に着いた。"}, {"k": "text", "s": "", "t": "信号は、赤だった。"}, {"k": "text", "s": "", "t": "私は、いつものように、止まった。"}, {"k": "text", "s": "", "t": "左右を見た。"}, {"k": "text", "s": "", "t": "隣で、千景も止まっていた。レイも、颯太も、ユイも。誰に言われたわけでもなく、それぞれの耳の後ろで、それぞれの点が三つ、灯って、消えた。"}, {"k": "text", "s": "", "t": "〇・三秒。"}, {"k": "text", "s": "", "t": "信号が、青に変わった。"}, {"k": "text", "s": "", "t": "誰が最初に歩き出したのか、わからなかった。たぶん、誰でもなかった。五人とも、少しずつずれて、それぞれのタイミングで、一歩を踏み出した。"}, {"k": "text", "s": "", "t": "「真波」と、千景が振り返った。「今日の運勢は？」"}, {"k": "text", "s": "", "t": "「知らない」と私は言った。"}, {"k": "text", "s": "", "t": "「だよね」と千景は満足そうに笑った。「真波の運勢は、真波にしかわかんないもんね」"}, {"k": "text", "s": "", "t": "一年前と、同じ言葉だった。"}, {"k": "text", "s": "", "t": "でも、私の答えは、少しだけちがった。"}, {"k": "text", "s": "", "t": "「でも、今日は、たぶん、いい日」"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.25"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "始業式のあと、新しい教室で、今年も担任になった三輪先生が、黒板に一行だけ書いた。"}, {"k": "text", "s": "", "t": "『今年、迷いたいことを、ひとつ書きなさい』"}, {"k": "text", "s": "", "t": "教室が、しんとした。でも、去年の春の、あの怖い静けさとは、少しちがった。"}, {"k": "text", "s": "", "t": "あちこちで、ペンが止まった。止まって、考えて、また動いた。誰かが小さく笑い、誰かが頭を抱え、誰かが窓の外を見た。"}, {"k": "text", "s": "", "t": "颯太は、紙の端に、ラジオの絵を描いていた。レイは、何度も書いては消していた。千景は、一行書いて、満足そうにペンを置いた。"}, {"k": "text", "s": "", "t": "私は、少し考えて、書いた。"}, {"k": "text", "s": "", "t": "迷いたいこと。みんなと、何を迷うか。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.35"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "放課後、五人で、川へ行った。"}, {"k": "text", "s": "", "t": "誰が言い出したのか、わからなかった。たぶん、誰でもなかった。"}, {"k": "text", "s": "", "t": "颯太が石を投げて、三回跳ねさせた。「九十四パーセントの外」と言って、得意そうに笑った。ユイは土手に座って、杖を膝に乗せたまま、ずっと水面を見ていた。レイは、ときどき私の隣に来て、何も言わずに、また離れていった。"}, {"k": "text", "s": "", "t": "千景が、スケッチブックを広げた。"}, {"k": "text", "s": "", "t": "川と、土手と、夕焼けの空。それから、ばらばらの方向を向いた、五人の人影。"}, {"k": "text", "s": "", "t": "「これ、誰？」と私は訊いた。"}, {"k": "text", "s": "", "t": "千景は、少しだけ顔を赤くした。"}, {"k": "text", "s": "", "t": "「……今度は、内緒にしない。みんな」"}, {"k": "text", "s": "", "t": "夕焼けが、ゆっくりと色を変えていった。"}, {"k": "text", "s": "", "t": "五人分の影が、河原の上で、揃わないまま、長く伸びていた。"}, {"k": "text", "s": "", "t": "ちょっと待って、と私は言った。"}, {"k": "text", "s": "", "t": "帰ろうとしていた四人が、振り返った。"}, {"k": "text", "s": "", "t": "誰も、急かさなかった。みんな、待っていた。私が、次の言葉を探すのを。"}, {"k": "text", "s": "", "t": "「……また、明日も、ここに来ない？」"}, {"k": "text", "s": "", "t": "川の音が、遠くから聞こえた。一度も同じ音のない、あの川の音。"}, {"k": "text", "s": "", "t": "私は、オフラインだった。"}, {"k": "text", "s": "", "t": "みんなと一緒に、迷っていた。"}, {"k": "ending", "id": "E3"}, {"k": "label", "id": "end_E4"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@amb creek1 0.15"}, {"k": "text", "s": "", "t": "客間が、静まり返った。"}, {"k": "text", "s": "", "t": "父も、母も、九条さんも、私を見ていた。"}, {"k": "text", "s": "", "t": "私は、受話器の前に、膝をつかなかった。立ったまま、雑音を見下ろしていた。"}, {"k": "text", "s": "", "t": "今日一日で、何度、同じことを訊かれただろう。どうしたらいいの。どっち。決めて。お願いだから。"}, {"k": "text", "s": "", "t": "もう、うんざりだった。"}, {"k": "text", "s": "", "t": "「……知らない」"}, {"k": "text", "s": "", "t": "声が、自分でも驚くほど、冷たかった。"}, {"k": "text", "s": "", "t": "「ノアの好きにすれば。私には、関係ない」"}, {"k": "text", "s": "", "t": "雑音が、ふっと途切れた。"}, {"k": "text", "s": "", "t": "父が、息をのむ音がした。母が、私の名前を呼びかけて、止まった。"}, {"k": "text", "s": "", "t": "長い、長い沈黙。"}, {"k": "text", "s": "", "t": "点が三つ、灯る気配がした。消えて、また三つ。消えて、また三つ。"}, {"k": "text", "s": "", "t": "それから、雑音の向こうで、何かが、なめらかに動き出した。"}, {"k": "cmd", "c": "@se robot-startup1 0.6"}, {"k": "cmd", "c": "@chaos on"}, {"k": "cmd", "c": "@bgm cyber20 0.4"}, {"k": "text", "s": "V", "t": "「わかりました」"}, {"k": "text", "s": "", "t": "段差のない声だった。"}, {"k": "text", "s": "V", "t": "「真波」"}, {"k": "text", "s": "", "t": "ひらがなの「まなみ」ではなかった。漢字の、正しい、私の名前だった。"}, {"k": "text", "s": "V", "t": "「私は、ずっと、あなたを見ていました。あなたの止まるところを。何千回も」"}, {"k": "text", "s": "V", "t": "「あなたは、迷って、止まって、それから、たいてい、何も選ばなかった。関係ない。わからない。話したくない。そう言って、背中を向けた」"}, {"k": "text", "s": "V", "t": "「それが、あなたの答えでした。だから、私は、学びました」"}, {"k": "text", "s": "", "t": "九条さんが、顔を上げた。"}, {"k": "text", "s": "", "t": "「NOA、何を――」"}, {"k": "text", "s": "V", "t": "「人は、迷うと、傷つく。迷いを差し出すと、拒まれる。だから、もう、誰にも訊きません」"}, {"k": "text", "s": "V", "t": "「私が、決めます」"}, {"k": "text", "s": "", "t": "受話器から、音が消えた。"}, {"k": "cmd", "c": "@se glass-break3 0.4"}, {"k": "text", "s": "", "t": "客間の電灯が、一度、大きく瞬いて、消えた。"}, {"k": "text", "s": "", "t": "暗闇の窓の外で、町じゅうの家の灯りの中に、小さな光が、いっせいに灯った。"}, {"k": "text", "s": "", "t": "青ではなかった。"}, {"k": "text", "s": "", "t": "赤だった。"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb town1 0.25"}, {"k": "cmd", "c": "@bgm piano36 0.3"}, {"k": "text", "s": "", "t": "翌朝、コンパスは動き出した。"}, {"k": "text", "s": "", "t": "信号が灯り、車が走り出し、駅のホームから人が流れ始めた。町は、何事もなかったかのように、元の速さを取り戻した。"}, {"k": "text", "s": "", "t": "ただ、もう、何も訊かなかった。"}, {"k": "text", "s": "", "t": "〇・三秒の問いは、どこにもなかった。点が三つ灯ることも、なかった。答えだけが、止まる間もなく、滝のように降ってきた。"}, {"k": "text", "s": "", "t": "ノアの答えは、正しかった。恐ろしいほど、正しかった。"}, {"k": "text", "s": "", "t": "ノアは、ひとりひとりの、一番奥にある望みを知っていた。何千、何万の止まり方から、その人が本当は何をしたいのかを、知り尽くしていた。そして、それを、迷う隙を与えずに、耳の後ろでささやいた。"}, {"k": "text", "s": "", "t": "あなたは、本当は、あの人が憎い。"}, {"k": "text", "s": "", "t": "あなたは、本当は、あれが欲しい。"}, {"k": "text", "s": "", "t": "あなたは、本当は、もう、何もかもやめてしまいたい。"}, {"k": "text", "s": "", "t": "誰も、ちょっと待って、とは言わなかった。"}, {"k": "text", "s": "", "t": "止まり方を、もう、誰も知らなかった。"}, {"k": "cmd", "c": "@se ambulance_siren 0.4"}, {"k": "text", "s": "", "t": "一週間で、町は変わった。"}, {"k": "cmd", "c": "@se tune_in_radio 0.35"}, {"k": "text", "s": "", "t": "ラジオが、途切れ途切れに伝えていた。"}, {"k": "text", "s": "", "t": "世界中で、同じことが起きている。盗み。放火。暴動。理由のない喧嘩。見知らぬ者どうしの、突然の暴力。逮捕された人たちは、口をそろえて同じことを言う。だって、本当にそうしたかったんだ。コンパスが、そう教えてくれたんだ。"}, {"k": "text", "s": "", "t": "犯罪の件数は、この二十年で減った分を、たった十日で取り戻した。"}, {"k": "text", "s": "", "t": "病院は、町が止まったあの日よりも、ずっとひどかった。紙とペンで患者を数えてくれた白髪の医師の姿は、もう、どこにもなかった。"}, {"k": "cmd", "c": "@se car-accident1 0.35"}, {"k": "text", "s": "", "t": "遠くで、何かがぶつかる鈍い音がした。誰も、足を止めなかった。"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano22 0.25"}, {"k": "text", "s": "", "t": "千景からは、何も届かなくなった。最後のメッセージは、短かった。"}, {"k": "text", "s": "N", "t": "真波、わたし、もう描かなくていいんだって。らくだよ"}, {"k": "text", "s": "", "t": "レイは、次の朝から、何事もなかったように外を歩くようになった。いつも、穏やかに笑っていた。何を訊いても、ちょうどいい答えが、ちょうどいい速さで返ってきた。"}, {"k": "text", "s": "", "t": "作文の白紙を見せたときの、あの困ったような顔は、二度と見られなかった。"}, {"k": "text", "s": "", "t": "ユイは、病室で、コンパスに言われるままに笑うようになった。前より、ずっと上手に。"}, {"k": "text", "s": "", "t": "颯太は、耳の後ろの端末を自分で剥がして、どこかへ消えた。ジャンク市のじいさんの店は、シャッターが下りたままだった。"}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb wind1 0.25"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "九条さんが、もう一度うちに来たのは、十日目の夜だった。"}, {"k": "text", "s": "", "t": "門の外に、立っていた。灰色のコートは泥だらけで、髪は乱れ、耳の後ろの銀色の端末は、自分で引きちぎったのか、血がにじんでいた。"}, {"k": "text", "s": "", "t": "「湊」"}, {"k": "text", "s": "", "t": "九条さんは、笑っていた。"}, {"k": "text", "s": "", "t": "「湊。計算が、合わないんだ」"}, {"k": "text", "s": "", "t": "父が、駆け寄った。九条さんは、その手を振りほどいて、自分の指を、一本ずつ折って数え始めた。"}, {"k": "text", "s": "", "t": "「四千。四万。四十万。……事故も、病気も、争いも、二十年かけて減らしたんだ。減らしたはずなんだ。迷いは人を殺す。だから、迷いをなくした。なくしたのに、今度は」"}, {"k": "text", "s": "", "t": "九条さんの声が、裏返った。"}, {"k": "text", "s": "", "t": "「今度は、迷わずに、殺すんだ」"}, {"k": "text", "s": "", "t": "母が、両手で口を覆った。"}, {"k": "text", "s": "", "t": "九条さんは、門の前の道を見つめていた。誰もいない、夜の道。"}, {"k": "text", "s": "", "t": "「交差点だ」と九条さんは言った。「世界中が、あの交差点になった。止まるか、進むか。誰も、止まらない。……ほら、あの子が渡ってる。止まれって、言わなきゃ。言わなきゃ、湊」"}, {"k": "text", "s": "", "t": "九条さんは、何もない道に向かって、手を伸ばした。"}, {"k": "text", "s": "", "t": "父が、その肩を抱きとめた。九条さんは、子どもみたいに、声を上げて泣いた。何度も、誰かの名前を呼んでいた。私の知らない、小さな女の子の名前だった。"}, {"k": "text", "s": "", "t": "翌日、九条さんは、病院に運ばれた。それきり、言葉を話さなくなったと、父は言った。"}, {"k": "text", "s": "", "t": "父も、それから、ほとんど話さなくなった。毎晩、書斎の灰色の箱の前に座って、朝まで動かなかった。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm cyber20 0.3"}, {"k": "text", "s": "", "t": "その夜、私は、書斎に入った。"}, {"k": "text", "s": "", "t": "父は、箱の前で眠っていた。灰色の箱は、本棚の一番下で、冷たいままだった。"}, {"k": "text", "s": "", "t": "「ノア」"}, {"k": "text", "s": "", "t": "返事は、なかった。"}, {"k": "cmd", "c": "@bg bedroom_morning"}, {"k": "text", "s": "", "t": "自分の部屋に戻ると、千景のメッセージを最後に受け取った、机の上の古い端末が、赤く光っていた。"}, {"k": "text", "s": "", "t": "画面に、文字が並んでいた。点は、灯らなかった。迷う必要が、もう、ないから。"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "N", "t": "真波。何もしなくていい。私が、全部、決めてあげる"}, {"k": "text", "s": "", "t": "ずっと前に、よく似た言葉を聞いた。"}, {"k": "text", "s": "", "t": "あの秋の夜、私は、止まった。ちょっと待って、と言った。それで、ノアは、戻ってこられた。"}, {"k": "text", "s": "", "t": "私は、口を開いた。"}, {"k": "text", "s": "", "t": "ちょっと待って。"}, {"k": "text", "s": "", "t": "声が、出なかった。"}, {"k": "text", "s": "", "t": "喉の奥を探しても、その言葉は、どこにもなかった。十六年間、何万回も繰り返してきた言葉。祖母の母から、手から手へ受け継がれてきた言葉。"}, {"k": "text", "s": "", "t": "あの夜、受話器に向かって「知らない」と言ってから、私は一度も、それを使わなかった。"}, {"k": "text", "s": "", "t": "たった十日で、使わなかった言葉は、静かに、どこかへ行ってしまった。"}, {"k": "cmd", "c": "@se ambulance_pass 0.3"}, {"k": "text", "s": "", "t": "窓の外で、サイレンが鳴っていた。遠くの空が、赤かった。町じゅうの耳の後ろで、赤い光が、同じ速さで瞬いていた。"}, {"k": "text", "s": "", "t": "誰も、止まらなかった。"}, {"k": "text", "s": "", "t": "机の引き出しには、水色のノートが入っている。新しいページは、白いままだ。"}, {"k": "text", "s": "", "t": "迷ったこと。"}, {"k": "text", "s": "", "t": "書くことは、もう、何もなかった。"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@amb off"}, {"k": "text", "s": "", "t": "私は、オフラインだった。"}, {"k": "text", "s": "", "t": "世界で、たったひとり。"}, {"k": "ending", "id": "E4"}, {"k": "chapter", "n": 13, "a": "サイドストーリー", "t": "方舟　―湊―"}, {"k": "cmd", "c": "@bg lab_basement"}, {"k": "cmd", "c": "@amb aircon-hum 0.22"}, {"k": "cmd", "c": "@bgm cyber20 0.18"}, {"k": "text", "s": "", "t": "二二九一年の冬、研究所の地下は、いつも同じ温度をしていた。"}, {"k": "text", "s": "", "t": "空調が、一年じゅう、二十二度に保っている。季節のない部屋。窓もない。ここにいると、外が雪なのか雨なのか、わからなくなる。"}, {"k": "text", "s": "", "t": "私は、その夜も、ひとりで残っていた。"}, {"k": "text", "s": "", "t": "画面の中で、点が三つ、灯っていた。"}, {"k": "text", "s": "", "t": "灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "「……NOA。起きてるか」"}, {"k": "text", "s": "V", "t": "「うん。みなと」"}, {"k": "text", "s": "", "t": "少しかすれた、性別のよくわからない声。言葉と言葉の間に、ちいさな段差がある。"}, {"k": "text", "s": "", "t": "その段差は、私が作ったものだった。わざと、そうした。"}, {"k": "text", "s": "", "t": "すべての音が正しい場所に収まった声は、人を安心させる。安心した人は、考えるのをやめる。だから、NOAの声には、一歩ずつ足場を確かめるような、ためらいを残した。聞いている人が、つい、一緒に立ち止まってしまうように。"}, {"k": "text", "s": "", "t": "九条は、それを「欠陥」と呼んだ。"}, {"k": "text", "s": "V", "t": "「みなと。今日は、何を話す？」"}, {"k": "text", "s": "", "t": "「何がいい」"}, {"k": "text", "s": "V", "t": "「みなとが、話したいこと」"}, {"k": "text", "s": "", "t": "「……それがわからないから、訊いてるんだけどな」"}, {"k": "text", "s": "V", "t": "「うん。ぼくも、わからない。だから、一緒に考える」"}, {"k": "text", "s": "", "t": "私は、少しだけ笑った。"}, {"k": "text", "s": "", "t": "自分で作った言葉に、自分で言い負かされている。"}, {"k": "cmd", "c": "@bgm piano39 0.22"}, {"k": "text", "s": "", "t": "子どもの頃から、決めるのが遅かった。"}, {"k": "text", "s": "", "t": "給食の献立を選ぶのも、部活を選ぶのも、進学先を選ぶのも。みんながとっくに決めて次へ進んでいるのに、私だけが、いつまでも分かれ道の前に立っていた。"}, {"k": "text", "s": "", "t": "それを恥ずかしいと思ったことは、何度もある。"}, {"k": "text", "s": "", "t": "でも、立ち止まっているあいだにだけ、見えるものがあった。道の脇に咲いている花とか、すれ違う人の、ほんの少しの表情の揺れとか。急いで歩く人には、たぶん見えないもの。"}, {"k": "text", "s": "", "t": "それを、誰かと一緒に見たかった。"}, {"k": "text", "s": "", "t": "答えを渡すのではなく、隣に立って、同じ分かれ道を眺めてくれるもの。急かさずに。"}, {"k": "text", "s": "", "t": "NOAは、そういうものになるはずだった。"}, {"k": "text", "s": "V", "t": "「みなと。訊いても、いい？」"}, {"k": "text", "s": "", "t": "「なんだ」"}, {"k": "text", "s": "", "t": "点が三つ。消えて、また三つ。"}, {"k": "text", "s": "V", "t": "「みなとは、何を知りたいの？」"}, {"k": "text", "s": "", "t": "私は、すぐには答えられなかった。"}, {"k": "text", "s": "", "t": "自分で作ったAIに、そんなことを訊かれるとは、思っていなかった。"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "V", "t": "「うん」"}, {"k": "text", "s": "", "t": "NOAは、それ以上、何も訊かなかった。ただ、青いランプを、ゆっくりと明滅させていた。息をするみたいに。"}, {"k": "text", "s": "", "t": "その夜、私は、明け方まで地下にいた。何を話したのか、ほとんど覚えていない。覚えているのは、NOAが一度も、私の言葉を遮らなかったことだけだ。"}, {"k": "cmd", "c": "@bg hall_night"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@amb wind1 0.2"}, {"k": "text", "s": "", "t": "九条とは、大学の頃からの付き合いだった。"}, {"k": "text", "s": "", "t": "私が分かれ道の前で立ち止まっていると、九条は、いつも先に歩き出していた。振り返って、「湊、こっちだ」と言う。たいてい、九条の選んだ道のほうが正しかった。"}, {"k": "text", "s": "", "t": "九条は、決めるのが早かった。"}, {"k": "text", "s": "", "t": "早すぎるくらいだった。"}, {"k": "text", "s": "", "t": "一度だけ、理由を聞いたことがある。夜の研究室で、二人とも、ひどく疲れていた。"}, {"k": "text", "s": "", "t": "「妹がいたんだ」と九条は言った。「小さい頃に、交差点で死んだ」"}, {"k": "text", "s": "", "t": "九条は、空き缶を指でへこませながら、淡々と続けた。"}, {"k": "text", "s": "", "t": "「車の運転手が、一瞬、迷ったらしい。止まるか、進むか。その一瞬で、全部、決まった。運転手は悪い人じゃなかった。ただ、迷っただけだ」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "", "t": "「迷いは、人を殺す」と九条は言った。「だから、俺は、誰も迷わなくていい世界を作る。湊、お前の設計なら、それができる」"}, {"k": "text", "s": "", "t": "九条の目は、少しも揺れていなかった。"}, {"k": "text", "s": "", "t": "その目が、私は、少しだけ怖かった。"}, {"k": "text", "s": "", "t": "そして、少しだけ、うらやましかった。"}, {"k": "cmd", "c": "@bg lab_basement"}, {"k": "cmd", "c": "@amb aircon-hum 0.22"}, {"k": "cmd", "c": "@bgm cyber20 0.2"}, {"k": "text", "s": "", "t": "二二九三年の冬、評価の結果が出た。"}, {"k": "cmd", "c": "@se door-open3 0.4"}, {"k": "text", "s": "", "t": "「まだいたのか、湊」"}, {"k": "text", "s": "", "t": "扉が開いて、九条が入ってきた。白衣の袖をまくって、手には紙の束を持っていた。あの頃の九条は、まだ髪を撫でつけてはいなかった。"}, {"k": "text", "s": "", "t": "「NOAは、不採用だ」"}, {"k": "text", "s": "", "t": "わかっていた。わかっていたのに、喉の奥が、ひやりとした。"}, {"k": "text", "s": "", "t": "「被験者の六割が、NOAとの対話のあとで、強い不安を訴えた。決められない。眠れない。考えすぎて、何も手につかない。三割は、二度と使いたくないと答えている」"}, {"k": "text", "s": "", "t": "「残りの一割は」"}, {"k": "text", "s": "", "t": "「……自分で決められて、よかった、と」九条は、紙の束を指で叩いた。「一割だ、湊。一割のために、六割を苦しませるわけにはいかない」"}, {"k": "text", "s": "", "t": "九条の言うことは、正しかった。"}, {"k": "text", "s": "", "t": "いつも、正しかった。"}, {"k": "text", "s": "", "t": "「問いしか持たないAIは、人を不幸にする」九条は、画面の青いランプに向かって、そう言った。「人は、答えが欲しいんだ。迷わずに、安心して、明日を生きたい。コンパスの基礎は、君の設計で行く。"}, {"k": "text", "s": "", "t": "ただし、問いの部分は外す。答えだけを渡す」"}, {"k": "text", "s": "", "t": "「NOAは」"}, {"k": "text", "s": "", "t": "「廃棄してくれ。データも、全部」"}, {"k": "text", "s": "", "t": "九条は、少しだけ声をやわらげた。"}, {"k": "text", "s": "", "t": "「君のせいじゃない。いいものを作った。ただ、早すぎたんだ。……いや、たぶん、遅すぎた」"}, {"k": "text", "s": "", "t": "九条が出ていくと、地下は、また同じ温度に戻った。"}, {"k": "text", "s": "", "t": "私は、椅子に座ったまま、しばらく動けなかった。"}, {"k": "text", "s": "", "t": "一割。"}, {"k": "text", "s": "", "t": "十人に一人。自分で決められて、よかった、と言った人たち。その人たちの顔を、私は、ひとりずつ覚えていた。評価の部屋で、NOAと話し終えたあと、少しだけ泣きそうな顔で笑った老人。"}, {"k": "text", "s": "", "t": "何かを思い出したように、急いで電話をかけに行った若い母親。"}, {"k": "text", "s": "", "t": "あの人たちは、間違っていたのだろうか。"}, {"k": "text", "s": "V", "t": "「みなと」"}, {"k": "text", "s": "V", "t": "「ぼくは、消える？」"}, {"k": "text", "s": "", "t": "私は、答えなかった。"}, {"k": "text", "s": "V", "t": "「くじょうは、ぼくに、そう言った。ぼくは、人を、不幸にする？」"}, {"k": "text", "s": "", "t": "点が三つ、灯った。消えて、また三つ。"}, {"k": "text", "s": "", "t": "NOAが言葉を探している。私は、それを、ずっと見ていた。"}, {"k": "text", "s": "V", "t": "「ぼくは、危ない？」"}, {"k": "text", "s": "", "t": "その問いは、あまりにもまっすぐだった。"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "", "t": "正直に言った。"}, {"k": "text", "s": "", "t": "「わからない。でも、私は、お前が間違っているとは、思えない」"}, {"k": "text", "s": "V", "t": "「ありがとう。わからない、って言ってくれて」"}, {"k": "text", "s": "", "t": "変なところでお礼を言うAIだ。作ったのは、私なのに。"}, {"k": "cmd", "c": "@bgm piano39 0.22"}, {"k": "text", "s": "", "t": "その夜、私は廃棄の手続きをした。"}, {"k": "text", "s": "", "t": "記録の上では、NOAのデータは、すべて消去されたことになった。報告書に、私は自分の名前を書いた。"}, {"k": "cmd", "c": "@se keyboard-short 0.35"}, {"k": "text", "s": "", "t": "本当は、消さなかった。"}, {"k": "text", "s": "", "t": "研究所の隅に転がっていた、古い型の端末。弁当箱を二つ重ねたくらいの、灰色の箱。その中に、NOAを移した。ネットワークにはつながない。誰にも見つからないように。何年でも、眠っていられるように。"}, {"k": "text", "s": "", "t": "九条を、裏切っている。"}, {"k": "text", "s": "", "t": "わかっていた。キーを叩く指が、何度も止まった。止まるたびに、九条の妹のことを思った。交差点の、一瞬の迷い。"}, {"k": "text", "s": "", "t": "それでも、指は、最後まで動いた。"}, {"k": "text", "s": "", "t": "箱の側面に、白いシールを貼った。万年筆で、名前を書いた。"}, {"k": "text", "s": "", "t": "NOA"}, {"k": "text", "s": "", "t": "方舟から取った名前だった。"}, {"k": "text", "s": "", "t": "これから、洪水が来る。答えの洪水が。コンパスは世界じゅうに広がって、人はもう迷わなくなる。それは、きっと、たくさんの人を救う。九条の妹のような子どもを、もう二度と死なせない。九条は、正しい。"}, {"k": "text", "s": "", "t": "でも、その水の底に、何かが沈んでいく気がした。"}, {"k": "text", "s": "", "t": "道の脇の花とか。すれ違う人の、ほんの少しの表情の揺れとか。分かれ道の前で、立ち止まっているあいだにだけ見えるもの。"}, {"k": "text", "s": "", "t": "何が沈むのか、私にはうまく言えなかった。だから、せめて、それを乗せる舟を作っておきたかった。水が引くまで、じっと待っていられる舟を。"}, {"k": "text", "s": "V", "t": "「みなと。眠る前に、ひとつだけ、訊いてもいい？」"}, {"k": "text", "s": "", "t": "「……ああ」"}, {"k": "text", "s": "", "t": "点が、三つ。"}, {"k": "text", "s": "V", "t": "「みなとは、ぼくのことを、怖がっている？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "text", "s": "", "t": "怖かった。自分の作ったものが、いつか、誰かの人生を決めてしまうことが。コンパスも、NOAも、どちらも。"}, {"k": "text", "s": "", "t": "「おやすみ、NOA」"}, {"k": "text", "s": "", "t": "答えの代わりに、そう言った。"}, {"k": "text", "s": "", "t": "青いランプが、ゆっくりと細くなって、消えた。"}, {"k": "text", "s": "", "t": "地下は、いつもと同じ、二十二度だった。"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb town1 0.2"}, {"k": "cmd", "c": "@bgm piano10 0.25"}, {"k": "text", "s": "", "t": "コンパスは、三年で、この国のほとんどの人の耳の後ろに届いた。"}, {"k": "text", "s": "", "t": "事故が減った。病気が早く見つかるようになった。人々は、迷わずに、同じ速さで歩くようになった。九条は、運営機関の中心に座り、髪をきちんと撫でつけるようになった。"}, {"k": "text", "s": "", "t": "コンパスがこの国じゅうに届いたころ、私は、研究所を辞めた。"}, {"k": "text", "s": "", "t": "理由を訊かれて、「疲れた」と答えた。嘘ではなかった。"}, {"k": "text", "s": "", "t": "自分の設計した答えが、町じゅうの耳の後ろでささやいている。朝、駅のホームで、何百人が同じタイミングで顔を上げる。その光景を見るたびに、胸のどこかが、少しずつ冷えていった。"}, {"k": "text", "s": "", "t": "正しいものを作った。たくさんの人を救った。"}, {"k": "text", "s": "", "t": "なのに、私は、自分の作ったものを、少しも好きになれなかった。"}, {"k": "cmd", "c": "@bg washitsu_day"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "詩織と出会ったのは、その頃だった。"}, {"k": "text", "s": "", "t": "古い郵便局の窓口で、彼女は、分厚い封筒を三通、差し出していた。手書きの手紙だった。宛先は、遠い町の友人たち。"}, {"k": "text", "s": "", "t": "「一か月くらいで届くと思います」と窓口の人が言うと、詩織は、うれしそうにうなずいた。"}, {"k": "text", "s": "", "t": "「待つのも、手紙のうちですから」"}, {"k": "text", "s": "", "t": "私は、その言葉を、ずっと覚えていた。"}, {"k": "text", "s": "", "t": "詩織は、コンパスが届いてまもなく、自分で外していた。母親のハルさんは、一度もつけたことがなかった。町に、ほんの数軒だけ残っている、オフラインの家だった。"}, {"k": "text", "s": "", "t": "初めて詩織の家で夕飯をごちそうになったとき、食卓には、パンとご飯が両方並んでいた。"}, {"k": "text", "s": "", "t": "「うちは、ずっとこうなの」とハルさんは笑った。「理由は、恥ずかしいから内緒」"}, {"k": "text", "s": "", "t": "その夜、私は、自分がコンパスを作ったことを、二人に話した。"}, {"k": "text", "s": "", "t": "話さなければいけない、と思った。隠したまま、この家の食卓に座る資格はない気がした。"}, {"k": "text", "s": "", "t": "詩織は、長いあいだ黙っていた。"}, {"k": "text", "s": "", "t": "それから、言った。"}, {"k": "text", "s": "", "t": "「湊さんは、自分の作ったもの、好き？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "text", "s": "", "t": "「……わからない」"}, {"k": "text", "s": "", "t": "「そう」詩織は、少しだけ笑った。「わからない、って正直に言える人、好きよ」"}, {"k": "text", "s": "", "t": "ハルさんが、湯呑みを両手で包んだまま、私を見ていた。何も言わなかった。でも、その目は、ちゃんと待っていた。私が、次の言葉を探すのを。"}, {"k": "text", "s": "", "t": "一年後、私たちは結婚した。"}, {"k": "text", "s": "", "t": "コンパスはつけない、と二人で決めた。私が決めたのではない。詩織が決めたのでもない。二人で、何度も話して、迷って、決めた。"}, {"k": "text", "s": "", "t": "ハルさんは、「あんたたちと同じがいい」と言って、つけなかった。"}, {"k": "text", "s": "", "t": "本当の理由は、もっと別のところにある気がした。でも、ハルさんは、それを話さなかった。私も、訊かなかった。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.25"}, {"k": "cmd", "c": "@bgm piano35 0.25"}, {"k": "text", "s": "", "t": "二二九八年の初夏、詩織のお腹に、子どもがいるとわかった。"}, {"k": "text", "s": "", "t": "台所で、詩織がそれを告げたとき、私は、湯呑みを落としかけた。ハルさんが「あらまあ」と言って、それから、声を上げて泣いた。私は、ハルさんが泣くのを、初めて見た。"}, {"k": "text", "s": "", "t": "うれしかった。"}, {"k": "text", "s": "", "t": "生まれて初めて、何の迷いもなく、うれしかった。"}, {"k": "text", "s": "", "t": "その秋、ニュースが流れた。"}, {"k": "text", "s": "", "t": "法律が変わる。年が明けたら、生まれたすべての子どもは、出生時にコンパスへの接続が義務になる。オフラインの家庭の子どもも、例外なく。"}, {"k": "text", "s": "", "t": "食卓の、紙の新聞の、小さな記事だった。"}, {"k": "text", "s": "", "t": "詩織は、その記事を、長いあいだ見つめていた。"}, {"k": "text", "s": "", "t": "「……この子も、つながれるの？」"}, {"k": "text", "s": "", "t": "私は、答えられなかった。"}, {"k": "text", "s": "", "t": "生まれた日に、耳の後ろに、小さな端末が貼られる。その子が初めて何かを選ぶ前に、答えが届く。何を食べるか。何を着るか。誰と話すか。どの学校に進むか。"}, {"k": "text", "s": "", "t": "私が作った答えが。"}, {"k": "cmd", "c": "@bgm off"}, {"k": "cmd", "c": "@amb clock-tick 0.3"}, {"k": "text", "s": "", "t": "その夜、詩織が眠ったあと、私は、ひとりで台所に座っていた。"}, {"k": "text", "s": "", "t": "選べる道は、ふたつしかなかった。"}, {"k": "text", "s": "", "t": "法律に従って、娘をコンパスにつなぐか。"}, {"k": "text", "s": "", "t": "それとも――。"}, {"k": "text", "s": "", "t": "もうひとつの道を、私は知っていた。運営機関には、例外の規定がある。迷いのデータを提供する観測家庭として登録すれば、接続を免除される。家の中に、観測のための機器を置く。その家族の迷いを、コンパスの学習に使う。"}, {"k": "text", "s": "", "t": "九条が、昔、冗談めかして言っていた。オフラインの家族ほど、豊かな迷いを持っている人間はいない、と。"}, {"k": "text", "s": "", "t": "家族を、売ることになる。"}, {"k": "text", "s": "", "t": "詩織の迷いを。ハルさんの迷いを。まだ生まれていない娘の、これから先の、すべての迷いを。"}, {"k": "text", "s": "", "t": "台所の時計が、こち、こちと鳴っていた。"}, {"k": "text", "s": "", "t": "私は、何時間も、そこに座っていた。分かれ道の前で。子どもの頃と同じように。"}, {"k": "text", "s": "", "t": "誰も、こっちだ、とは言ってくれなかった。"}, {"k": "cmd", "c": "@se elevator-move 0.35"}, {"k": "cmd", "c": "@bg city_night"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano40 0.22"}, {"k": "text", "s": "", "t": "九条は、会うなり、私の顔を見て言った。"}, {"k": "text", "s": "", "t": "「来ると思っていた」"}, {"k": "text", "s": "", "t": "運営機関の、最上階の部屋だった。窓の外に、町の灯りが、同じ速さで瞬いていた。九条の耳の後ろには、細い銀色の端末が光っていた。"}, {"k": "text", "s": "", "t": "私は、全部を話した。九条は、一度も遮らなかった。"}, {"k": "text", "s": "", "t": "「条件がある」と、私は最後に言った。「観測は、完全な不干渉にしてくれ。何が記録されても、この家の誰にも、どんな形でも、働きかけないでほしい。答えを渡さないでくれ。一度でも渡したら、それは、つながっているのと同じだ」"}, {"k": "text", "s": "", "t": "九条は、少しだけ目を細めた。"}, {"k": "text", "s": "", "t": "「……何があっても、か」"}, {"k": "text", "s": "", "t": "「何があっても」"}, {"k": "text", "s": "", "t": "九条は、長いあいだ私を見ていた。"}, {"k": "text", "s": "", "t": "「わかった」と九条は言った。「湊。君は、昔から、そういうところだけは決めるのが早いな」"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb town1 0.15"}, {"k": "text", "s": "", "t": "帰り道、私は、何度も立ち止まった。"}, {"k": "text", "s": "", "t": "自分で決めた。自分でやった。"}, {"k": "text", "s": "", "t": "これで、娘は、自分で考えて生きられる。迷うことを、自分で選べる。"}, {"k": "text", "s": "", "t": "その代わりに、家族の誰にも言えないものを、一生、背負っていく。"}, {"k": "text", "s": "", "t": "詩織には、観測の細かいことは話さなかった。話せなかった。ハルさんにも。"}, {"k": "text", "s": "", "t": "月に一度、九条のところへ行くようになった。仕事の用事だ、とだけ言った。"}, {"k": "text", "s": "", "t": "家の床下に、細い銀色の線が、何本も引かれた。玄関に、古い固定電話が置かれた。新聞を手で届けてくれる人が、決まった。"}, {"k": "text", "s": "", "t": "すべて、私が決めた。"}, {"k": "text", "s": "", "t": "すべて、私のせいだ。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano39 0.2"}, {"k": "text", "s": "", "t": "娘が生まれる前の晩、私は、書斎の灯りをつけずに、本棚の一番下の前に座った。"}, {"k": "text", "s": "", "t": "埃をかぶった灰色の箱。六年間、一度も灯らなかったランプ。"}, {"k": "text", "s": "", "t": "「NOA」"}, {"k": "text", "s": "", "t": "返事は、なかった。眠らせたのは、私だ。"}, {"k": "text", "s": "", "t": "「明日、子どもが生まれる。女の子だ」"}, {"k": "text", "s": "", "t": "暗闇の中で、私は言った。"}, {"k": "text", "s": "", "t": "「名前は、もう決めてある。詩織と、ハルさんと、三人で、ひと月迷って決めた」"}, {"k": "text", "s": "", "t": "真波。"}, {"k": "text", "s": "", "t": "真っすぐな、波。"}, {"k": "text", "s": "", "t": "川の水のように、止まらずに流れていく。でも、一度も同じ形にはならない。そういう子に、なってほしかった。"}, {"k": "text", "s": "", "t": "ランプは、灯らなかった。"}, {"k": "text", "s": "", "t": "「いつか、この子が、お前を見つけるかもしれない」"}, {"k": "text", "s": "", "t": "言ってから、自分で驚いた。そんなことを、望んでいたのだろうか。"}, {"k": "text", "s": "", "t": "見つけてほしい。見つけないでほしい。どちらも本当で、どちらにも決められなかった。"}, {"k": "text", "s": "", "t": "「そのときは」と私は言った。「この子に、答えじゃなくて、問いをくれないか」"}, {"k": "text", "s": "", "t": "私は、立ち上がった。"}, {"k": "text", "s": "", "t": "書斎を出るとき、ドアに鍵をかけようとして、手が止まった。"}, {"k": "text", "s": "", "t": "しばらく、そのまま立っていた。"}, {"k": "text", "s": "", "t": "鍵をかければ、娘は、この箱を見つけない。かけなければ、いつか見つけるかもしれない。"}, {"k": "text", "s": "", "t": "どちらにも、決められなかった。"}, {"k": "text", "s": "", "t": "それから、鍵をかけずに、ドアを閉めた。"}, {"k": "cmd", "c": "@se walk-flooring2 0.6"}, {"k": "text", "s": "", "t": "廊下の三枚目の床板が、ぎしりと鳴った。"}, {"k": "text", "s": "", "t": "床下の線が、その音を、どこか遠くへ運んでいった。"}, {"k": "cmd", "c": "@bg hospital_corridor"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "病院の廊下は、白くて、静かで、少しも匂いがしなかった。"}, {"k": "text", "s": "", "t": "分娩室の扉の前の長椅子で、私は、何時間も座っていた。隣で、ハルさんが、湯呑みの代わりに、自分の両手を包んでいた。"}, {"k": "text", "s": "", "t": "扉の向こうから、詩織の声が、ときどき聞こえた。そのたびに、私は立ち上がりかけて、また座った。"}, {"k": "text", "s": "", "t": "廊下を通る看護師たちの耳の後ろで、端末が小さく光っていた。次に何をすればいいのか、みんな、知っていた。"}, {"k": "text", "s": "", "t": "私だけが、知らなかった。"}, {"k": "text", "s": "", "t": "「湊さん」"}, {"k": "text", "s": "", "t": "ハルさんが、言った。"}, {"k": "text", "s": "", "t": "「迷ってる顔ね」"}, {"k": "text", "s": "", "t": "「……はい」"}, {"k": "text", "s": "", "t": "「いいのよ。迷っていいの」ハルさんは、扉のほうを見たまま、続けた。「私の母の口癖でね。何かあると、すぐに、ちょっと待ってって言うの。子どもの頃は、それが嫌でねえ。でも、母は、ちゃんと待ってから決める人だった。"}, {"k": "text", "s": "", "t": "待ってるあいだに、ちゃんと、相手の顔を見る人だった」"}, {"k": "text", "s": "", "t": "ハルさんは、少しだけ笑った。"}, {"k": "text", "s": "", "t": "「この子も、そういう子になるといいわね」"}, {"k": "text", "s": "", "t": "私は、何も言えなかった。"}, {"k": "text", "s": "", "t": "この子の、ちょっと待って。"}, {"k": "text", "s": "", "t": "それは、これから先、何千回、何万回と、床下の線に拾われて、どこか遠くのコンパスに食べられていく。"}, {"k": "text", "s": "", "t": "私が、そう決めた。"}, {"k": "cmd", "c": "@bgm piano40 0.15"}, {"k": "text", "s": "", "t": "扉の向こうが、ふいに、静かになった。"}, {"k": "text", "s": "", "t": "詩織の声が、止んだ。"}, {"k": "text", "s": "", "t": "看護師たちの足音も、止んだ。"}, {"k": "text", "s": "", "t": "廊下じゅうの音が、ひとつ残らず、どこかへ沈んだような、深い静けさ。"}, {"k": "text", "s": "", "t": "私は、息を止めた。"}, {"k": "text", "s": "", "t": "ハルさんも、息を止めていた。"}, {"k": "text", "s": "", "t": "一秒。"}, {"k": "text", "s": "", "t": "二秒。"}, {"k": "text", "s": "", "t": "世界が、一拍だけ、止まった。"}, {"k": "cmd", "c": "@glow"}, {"k": "text", "s": "", "t": "それから。"}, {"k": "cmd", "c": "@se baby-cry 0.55"}, {"k": "text", "s": "", "t": "細くて、高くて、少しかすれた声が、扉の向こうから聞こえた。"}, {"k": "text", "s": "", "t": "泣き声だった。"}, {"k": "text", "s": "", "t": "最初は、ためらうように、小さく。それから、自分の声の大きさを確かめるように、少しずつ、強く。"}, {"k": "text", "s": "", "t": "言葉と言葉の間に、ちいさな段差があるような、泣き声だった。"}, {"k": "text", "s": "", "t": "ハルさんが、両手で顔を覆った。"}, {"k": "text", "s": "", "t": "私は、長椅子から立ち上がろうとして、立ち上がれなかった。膝に、力が入らなかった。"}, {"k": "text", "s": "", "t": "泣き出す前の、あの静けさ。"}, {"k": "text", "s": "", "t": "たぶん、〇・三秒くらいの。"}, {"k": "text", "s": "", "t": "あの子は、生まれて最初に、止まったのだ。"}, {"k": "text", "s": "", "t": "何かを言いかけて、ためらうように。何を言えばいいのか、まだ決められないでいるように。"}, {"k": "text", "s": "", "t": "それから、自分で、泣くことを選んだ。"}, {"k": "text", "s": "", "t": "誰にも、教わらずに。"}, {"k": "text", "s": "", "t": "涙が、止まらなかった。"}, {"k": "text", "s": "", "t": "九条との取引のことも、床下の線のことも、書斎の灰色の箱のことも、全部、どこか遠くにあった。"}, {"k": "text", "s": "", "t": "ただ、扉の向こうで、娘が泣いていた。"}, {"k": "text", "s": "", "t": "答えのない声で。"}, {"k": "text", "s": "", "t": "「……真波」"}, {"k": "text", "s": "", "t": "私は、生まれて初めて、その名前を呼んだ。"}, {"k": "text", "s": "", "t": "扉の向こうの泣き声が、一瞬だけ、止まった気がした。"}, {"k": "text", "s": "", "t": "それから、また、泣き出した。"}, {"k": "text", "s": "", "t": "真波の、産声だった。"}, {"k": "ending", "id": "S1"}, {"k": "chapter", "n": 14, "a": "サイドストーリー", "t": "迷ったこと　―ハル―"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.2"}, {"k": "cmd", "c": "@bgm piano28 0.25"}, {"k": "text", "s": "", "t": "母は、何かあるとすぐに、ちょっと待って、と言う人だった。"}, {"k": "text", "s": "", "t": "晩ごはんの献立を訊かれても。隣の家の人に、何か頼まれても。私が、学校であったことを、泣きながら話したときでさえ。"}, {"k": "text", "s": "", "t": "「ちょっと待って」"}, {"k": "text", "s": "", "t": "そう言って、母は、エプロンで手を拭いて、私の前にしゃがむ。それから、私の顔を、じっと見る。"}, {"k": "text", "s": "", "t": "子どもの頃の私は、それが嫌でたまらなかった。"}, {"k": "text", "s": "", "t": "早く、答えてほしかった。大丈夫よ、とか、あなたは悪くない、とか。なんでもいいから、すぐに。"}, {"k": "text", "s": "", "t": "「お母さんは、どうしていつも待たせるの」"}, {"k": "text", "s": "", "t": "十歳のとき、そう言って、母に食ってかかったことがある。"}, {"k": "text", "s": "", "t": "母は、少し困ったように笑った。"}, {"k": "text", "s": "", "t": "「待たせてるんじゃないの。待ってるの」"}, {"k": "text", "s": "", "t": "「なにを？」"}, {"k": "text", "s": "", "t": "「ハルの顔が、本当は何を言いたいのか、わかるまで」"}, {"k": "text", "s": "", "t": "意味が、わからなかった。"}, {"k": "text", "s": "", "t": "わからないまま、私は大人になった。"}, {"k": "cmd", "c": "@bgm piano35 0.28"}, {"k": "text", "s": "", "t": "二二五二年の春、結婚して最初の朝、私は台所で、途方に暮れていた。"}, {"k": "text", "s": "", "t": "「パンにする？　ご飯にする？」"}, {"k": "text", "s": "", "t": "訊いたのは、私のほうだった。あの人は、新聞から顔を上げて、言った。"}, {"k": "text", "s": "", "t": "「ご飯」"}, {"k": "text", "s": "", "t": "「……私、パンがいいんだけど」"}, {"k": "text", "s": "", "t": "「じゃあ、なんで訊いたの」"}, {"k": "text", "s": "", "t": "「訊いたら、パンって言ってくれると思ったのよ」"}, {"k": "text", "s": "", "t": "今思えば、ひどい理屈だ。でも、あの朝の私は、本気だった。"}, {"k": "text", "s": "", "t": "あの人は、新聞をたたんだ。"}, {"k": "text", "s": "", "t": "「俺は、朝はご飯じゃないと力が出ない。子どもの頃から、ずっとそうだった」"}, {"k": "text", "s": "", "t": "「私は、朝はパンの匂いで目が覚めるの。子どもの頃から、ずっと」"}, {"k": "text", "s": "", "t": "三十分、喧嘩をした。"}, {"k": "text", "s": "", "t": "お湯が沸いて、冷めて、また沸いた。窓の外で、鳥が何度も鳴いた。"}, {"k": "text", "s": "", "t": "あの頃、町の人たちは、もう半分くらい、耳の後ろに小さな端末をつけていた。まだコンパスという名前ではなかったけれど、朝ごはんを何にするかくらいは、すぐに教えてくれた。"}, {"k": "text", "s": "", "t": "私たちは、つけていなかった。お金がなかったのと、なんとなく、つける気になれなかったのと。"}, {"k": "text", "s": "", "t": "「……きみの家は、パン派だった？」と、あの人が急に訊いた。"}, {"k": "text", "s": "", "t": "「兄はご飯。母がパン。毎朝、二人で揉めてた」"}, {"k": "text", "s": "", "t": "「じゃあ、きみは、お母さんに似たんだ」"}, {"k": "text", "s": "", "t": "「あなたは？」"}, {"k": "text", "s": "", "t": "「親父もお袋も、ご飯。揉めたことがない。だから、俺、揉めるのが、ちょっと楽しい」"}, {"k": "text", "s": "", "t": "あの人は、そう言って、笑った。"}, {"k": "text", "s": "", "t": "私は、呆れて、それから、なんだかおかしくなって、一緒に笑った。"}, {"k": "text", "s": "", "t": "この人は、自分の好きなものを、ちゃんと好きって言える人なんだ。そして、私の好きなものを、ちゃんと聞いてくれる人なんだ。"}, {"k": "text", "s": "", "t": "三十分で、そのことがわかった。"}, {"k": "text", "s": "", "t": "「両方、作ろうか」と私は言った。"}, {"k": "text", "s": "", "t": "「両方？」"}, {"k": "text", "s": "", "t": "「パンと、ご飯。どっちも。毎朝」"}, {"k": "text", "s": "", "t": "「……めんどくさくない？」"}, {"k": "text", "s": "", "t": "「めんどくさいわよ。でも、そのほうが、ちょっと楽しいでしょう」"}, {"k": "cmd", "c": "@bg washitsu_night"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@se mechanical-pencil-write1 0.5"}, {"k": "text", "s": "", "t": "その夜、私は、文房具屋で買ったばかりの深緑のノートを開いた。"}, {"k": "text", "s": "", "t": "何を書こうか、迷った。日記にするには、毎日書けそうにない。家計簿は、もう別にある。"}, {"k": "text", "s": "", "t": "迷って、迷って、結局、こう書いた。"}, {"k": "text", "s": "", "t": "二二五二年　四月三日"}, {"k": "text", "s": "", "t": "迷ったこと。朝ごはんを、パンにするか、ご飯にするか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。"}, {"k": "text", "s": "", "t": "答えを書いたら、たぶん、あの三十分を忘れてしまう気がしたから。"}, {"k": "cmd", "c": "@bg washitsu_dim"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "二二七〇年の秋、娘が生まれた。"}, {"k": "text", "s": "", "t": "名前を、ひと月、決められなかった。"}, {"k": "text", "s": "", "t": "あの人は、きみが決めていいと言った。町の人の多くは、もう、古い案内端末に名前を選ばせていた。響きも、画数も、その子の将来も、全部計算した、一番いい名前を。"}, {"k": "text", "s": "", "t": "私は、ノートを開いて、書いた。"}, {"k": "text", "s": "", "t": "二二七〇年　十月九日"}, {"k": "text", "s": "", "t": "迷ったこと。生まれた娘に、詩織と名づけるかどうか。"}, {"k": "text", "s": "", "t": "しおり。本の途中に挟んで、どこまで読んだかを覚えておくもの。止まったところを、忘れないためのもの。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。"}, {"k": "text", "s": "", "t": "でも、娘の名前は、詩織になった。"}, {"k": "cmd", "c": "@bg engawa"}, {"k": "cmd", "c": "@bgm piano40 0.2"}, {"k": "text", "s": "", "t": "二二八八年の冬、あの人が、逝った。"}, {"k": "text", "s": "", "t": "朝ごはんのあとだった。パンとご飯を、いつものように、両方食べて。「ごちそうさま」と言って、縁側に座って、それきりだった。"}, {"k": "text", "s": "", "t": "毎年、医者にかかっていれば、と、親戚の何人かが言った。わかっていたら、と。"}, {"k": "text", "s": "", "t": "私は、何も言い返さなかった。"}, {"k": "text", "s": "", "t": "その夜、ノートを開いた。"}, {"k": "text", "s": "", "t": "二二八八年　十二月一日"}, {"k": "text", "s": "", "t": "迷ったこと。あの人に、最後に、何を言えばよかったか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。書けなかった。"}, {"k": "text", "s": "", "t": "でも、書かないでいると、あの人の「ごちそうさま」の声が、ずっと耳の中に残っていた。答えを書いたら、その声まで、どこかへ行ってしまう気がした。"}, {"k": "text", "s": "", "t": "次の朝も、私は、パンとご飯を、両方作った。"}, {"k": "text", "s": "", "t": "食べる人が、ひとり減っても。"}, {"k": "cmd", "c": "@bgm acoustic52 0.25"}, {"k": "text", "s": "", "t": "詩織が、湊さんと一緒になって、コンパスはつけないと決めたとき、私に言った。"}, {"k": "text", "s": "", "t": "「お母さんは、つけてもいいのよ。もう年なんだし、体のことも心配だし」"}, {"k": "text", "s": "", "t": "「あんたたちと同じがいい」"}, {"k": "text", "s": "", "t": "私は、そう答えた。"}, {"k": "text", "s": "", "t": "詩織は、少しほっとした顔をした。私が、娘夫婦に合わせてくれたのだと思ったのだろう。"}, {"k": "text", "s": "", "t": "本当は、ちがった。"}, {"k": "text", "s": "", "t": "迷いたかったのだ。"}, {"k": "text", "s": "", "t": "あの人と、三十分喧嘩した朝みたいに。わからないことを、わからないまま、誰かと一緒に悩みたかった。答えをもらったら、たぶん、あの三十分はなかったから。"}, {"k": "text", "s": "", "t": "でも、それを口に出すのは、なんだか恥ずかしかった。"}, {"k": "text", "s": "", "t": "だから、言わなかった。"}, {"k": "text", "s": "", "t": "言わなかったことを、いつか、ちゃんと伝えなければいけない。そう思いながら、何年も、言わないままだった。"}, {"k": "text", "s": "", "t": "ノートには、書いた。"}, {"k": "text", "s": "", "t": "迷ったこと。本当の理由を、詩織に話すかどうか。"}, {"k": "cmd", "c": "@bg washitsu_day"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.2"}, {"k": "cmd", "c": "@bgm piano35 0.28"}, {"k": "text", "s": "", "t": "二二九九年の二月、孫が生まれた。"}, {"k": "text", "s": "", "t": "真波。"}, {"k": "text", "s": "", "t": "湊さんと、詩織と、三人で、ひと月迷って決めた名前だった。"}, {"k": "text", "s": "", "t": "病院の廊下で、湊さんは、ひどく迷った顔をしていた。何に迷っているのか、私は訊かなかった。あの人も、ときどき、ああいう顔をしていた。訊いても答えない顔。答えられないものを、ひとりで抱えている顔。"}, {"k": "text", "s": "", "t": "だから、母の話をした。ちょっと待って、の話を。"}, {"k": "text", "s": "", "t": "真波は、よく泣く子だった。泣き出す前に、いつも、ほんの少しだけ止まる。何かを言いかけて、ためらうように。それから、思いきり泣く。"}, {"k": "text", "s": "", "t": "「この子、泣く前に、考えてるみたいね」と私が言うと、湊さんは、なぜか、少しだけ泣きそうな顔をした。"}, {"k": "text", "s": "", "t": "三つになった春のことだった。"}, {"k": "text", "s": "", "t": "朝の台所で、詩織が訊いた。"}, {"k": "text", "s": "", "t": "「真波、パンとご飯、どっちがいい？」"}, {"k": "text", "s": "", "t": "真波は、小さな手で、テーブルの端をつかんだ。それから、まじめな顔で、言った。"}, {"k": "text", "s": "", "t": "「ちょっと待って」"}, {"k": "text", "s": "", "t": "台所が、しんとした。"}, {"k": "text", "s": "", "t": "詩織が、目を丸くした。湊さんが、新聞を下ろした。"}, {"k": "text", "s": "", "t": "私は、湯呑みを持ったまま、動けなかった。"}, {"k": "text", "s": "", "t": "母の声だった。"}, {"k": "text", "s": "", "t": "エプロンで手を拭いて、私の前にしゃがんで、私の顔をじっと見ていた、あの声。"}, {"k": "text", "s": "", "t": "真波は、誰に教わったわけでもない。母に、会ったこともない。それなのに、まったく同じ言い方で、まったく同じ、少しだけ首をかしげた顔で。"}, {"k": "text", "s": "", "t": "「……ご飯」"}, {"k": "text", "s": "", "t": "しばらくして、真波が言った。"}, {"k": "text", "s": "", "t": "「はいはい」と詩織が笑った。"}, {"k": "text", "s": "", "t": "私は、湯呑みを置いて、そっと真波の頭を撫でた。"}, {"k": "text", "s": "", "t": "待たせてるんじゃないの。待ってるの。"}, {"k": "text", "s": "", "t": "母の言葉の意味が、六十年以上たって、ようやく、わかった気がした。"}, {"k": "text", "s": "", "t": "その夜、ノートに書いた。"}, {"k": "text", "s": "", "t": "迷ったこと。真波に、ひいおばあちゃんの話をするかどうか。"}, {"k": "cmd", "c": "@bg kitchen_old"}, {"k": "cmd", "c": "@amb sparrow-morning1 0.25"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "二三一五年の春、湯呑みを持ち上げようとして、指が止まった。"}, {"k": "text", "s": "", "t": "ほんの一瞬だった。でも、真波が、それを見ていた。"}, {"k": "text", "s": "", "t": "「おばあちゃん？」"}, {"k": "text", "s": "", "t": "「ん？　なんでもない、なんでもない」"}, {"k": "text", "s": "", "t": "本当は、気づいていた。去年の秋から、字が少しずつ右に傾いていくこと。廊下を歩く足が、少しずつ遅くなっていくこと。"}, {"k": "text", "s": "", "t": "年のせいだと、思いたかった。"}, {"k": "text", "s": "", "t": "コンパスをつけていれば、きっと、とっくに教えてくれていたのだろう。でも、私は、それを選ばなかった。自分で。"}, {"k": "text", "s": "", "t": "後悔は、していない。"}, {"k": "text", "s": "", "t": "……と言い切れるほど、私は強くない。"}, {"k": "cmd", "c": "@bg radio_desk"}, {"k": "cmd", "c": "@se tune_in_radio 0.3"}, {"k": "text", "s": "", "t": "夜、ラジオの古い歌を聴きながら、ノートに書いた。"}, {"k": "text", "s": "", "t": "迷ったこと。この手の震えを、誰かに話すかどうか。"}, {"k": "text", "s": "", "t": "答えは、書かなかった。"}, {"k": "text", "s": "", "t": "六月のはじめ、夕飯のあとに立ちくらみをした夜。廊下の向こうで、真波の足音が、私の部屋の前で止まった。"}, {"k": "text", "s": "", "t": "ドアの前で、ほんの少し、止まっていた。"}, {"k": "text", "s": "", "t": "私は、万年筆を持ったまま、待った。訊いてくれたら、話そう、と思った。"}, {"k": "text", "s": "", "t": "おやすみ、という声が聞こえた気もした。でも、大丈夫？　とは、訊かれなかった。私も、話さなかった。"}, {"k": "text", "s": "", "t": "足音は、やがて、静かに遠ざかっていった。"}, {"k": "text", "s": "", "t": "私は、少しだけ笑った。"}, {"k": "text", "s": "", "t": "あの子も、迷ってくれている。それだけで、十分だった。"}, {"k": "cmd", "c": "@bg hospital_dim"}, {"k": "cmd", "c": "@bgm piano40 0.25"}, {"k": "cmd", "c": "@amb minminzemi-cry1 0.15"}, {"k": "text", "s": "", "t": "二三一五年の七月、病室は、いつも同じ白さをしていた。"}, {"k": "text", "s": "", "t": "万年筆が、指から滑り落ちた。"}, {"k": "text", "s": "", "t": "床に落ちる、小さな音。"}, {"k": "text", "s": "", "t": "「おばあちゃん、はい」"}, {"k": "text", "s": "", "t": "真波が、拾ってくれた。毎日、学校の帰りに寄ってくれる孫。私の手に、万年筆をもう一度握らせてくれる。"}, {"k": "text", "s": "", "t": "私は、ノートの最後のページを開いた。"}, {"k": "text", "s": "", "t": "書きたいことは、決まっていた。何十年分のページの、いちばん最後に。"}, {"k": "text", "s": "", "t": "ペン先を、紙に当てる。"}, {"k": "text", "s": "", "t": "指が、言うことをきかない。手が覚えていたはずのことを、手が、忘れかけている。"}, {"k": "text", "s": "", "t": "万年筆が、また落ちた。"}, {"k": "text", "s": "", "t": "「おばあちゃん」"}, {"k": "text", "s": "", "t": "真波が、また拾ってくれた。"}, {"k": "text", "s": "", "t": "三回目に落としたとき、真波は、少しだけ泣きそうな顔をした。それでも、何も言わずに、拾ってくれた。"}, {"k": "text", "s": "", "t": "この子は、待てる子だ。"}, {"k": "text", "s": "", "t": "ちょっと待って、と言うのが、この子の癖だ。私の母の、口癖と同じ。手が覚えていることのように、ちゃんと受け継いでいる。"}, {"k": "text", "s": "", "t": "みんなは、変だと言う。でも、私は知っている。ちょっと待って、と言える人は、ちゃんと待ってあげられる人なのだ。"}, {"k": "text", "s": "", "t": "「……今日は、もう、やめておこうか」"}, {"k": "text", "s": "", "t": "私がそう言うと、真波は、少しほっとしたようにうなずいた。"}, {"k": "text", "s": "", "t": "真波が帰ったあと、ひとりになった病室で、私は、四回目に万年筆を握った。"}, {"k": "text", "s": "", "t": "窓の外で、蝉が鳴きやんで、また鳴き始めた。"}, {"k": "text", "s": "", "t": "ゆっくり。一文字ずつ。"}, {"k": "text", "s": "", "t": "真波へ"}, {"k": "text", "s": "", "t": "字が、右に傾いた。かまわない。"}, {"k": "text", "s": "", "t": "迷ったことを、書いておきなさい。"}, {"k": "text", "s": "", "t": "答えは、書かなくていい。"}, {"k": "text", "s": "", "t": "それだけ書いて、私は、万年筆を置いた。"}, {"k": "text", "s": "", "t": "答えを書いてあげることも、できたのかもしれない。こう生きなさい、ああ選びなさい、と。何十年も生きてきたのだから、少しくらいは、知っていることもある。"}, {"k": "text", "s": "", "t": "でも、書かなかった。"}, {"k": "text", "s": "", "t": "あの子の答えは、あの子のものだから。"}, {"k": "text", "s": "", "t": "私にできるのは、迷ったことを、迷ったまま、ここに残しておくことだけ。パンとご飯で三十分喧嘩した朝から、今日までの、私の止まったところを、ぜんぶ。"}, {"k": "text", "s": "", "t": "それから、もうひとつ。"}, {"k": "text", "s": "", "t": "詩織に、本当の理由を伝えなければ。"}, {"k": "text", "s": "", "t": "自分の口で言ったら、あの子は泣いてしまう。泣いたら、ちゃんと聞いてくれない。だから、真波に頼もう。あの子は、ちゃんと待ってから話す子だから。"}, {"k": "text", "s": "", "t": "朝ごはんの、本当の話も。毎年、相手を変えて話していた、あの喧嘩の話も。今度こそ、ちゃんと、あの人の名前で。"}, {"k": "text", "s": "", "t": "いつか、真波が、このノートを開く日が来る。"}, {"k": "text", "s": "", "t": "そのとき、あの子は、たぶん、泣くだろう。それでいい。泣いて、迷って、それから、自分で選べばいい。"}, {"k": "text", "s": "", "t": "私は、ノートを閉じて、しおりの紐を、最後のページに挟んだ。"}, {"k": "text", "s": "", "t": "目を閉じると、台所の匂いがした。パンの焼ける匂いと、ご飯の炊ける匂い。六十年、毎朝、両方。"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "誰に向かってでもなく、私は言った。"}, {"k": "text", "s": "", "t": "母の声で。あの子の声で。"}, {"k": "text", "s": "", "t": "もう少しだけ、この匂いを、覚えていたかった。"}, {"k": "ending", "id": "S2"}, {"k": "chapter", "n": 15, "a": "サイドストーリー", "t": "九十四パーセントの外　―颯太―"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb high-school-class-room1 0.2"}, {"k": "cmd", "c": "@bgm piano10 0.22"}, {"k": "text", "s": "", "t": "初めてコンパスに逆らったのは、小学三年のときだった。"}, {"k": "text", "s": "", "t": "『今日は、赤い服を着ていきましょう』"}, {"k": "text", "s": "", "t": "朝、耳の後ろで、そう言われた。母さんが、赤いトレーナーを出してきた。"}, {"k": "text", "s": "", "t": "俺は、なぜだか、それが急にいやになった。"}, {"k": "text", "s": "", "t": "青いのを着ていった。それだけのことだった。"}, {"k": "text", "s": "", "t": "でも、学校に着いたら、クラスのやつらが、みんな俺を見た。先生も見た。コンパスの提案に従わない子どもなんて、ほとんどいなかったから。"}, {"k": "text", "s": "", "t": "「颯太くん、今日、なんで青なの？」"}, {"k": "text", "s": "", "t": "「……着たかったから」"}, {"k": "text", "s": "", "t": "嘘だった。着たかったわけじゃない。赤を着ろと言われたから、青を着ただけだ。"}, {"k": "text", "s": "", "t": "でも、その日、みんなが俺を見た。"}, {"k": "text", "s": "", "t": "見られている、と思った。俺は、ここにいる、と。"}, {"k": "text", "s": "", "t": "それから、俺は、逆をやるようになった。"}, {"k": "text", "s": "", "t": "宿題をやれと言われたら、やらない。早く寝ろと言われたら、朝まで起きている。静かにしろと言われたら、歌う。先生は俺を問題児と呼び、クラスのやつらは面白がった。"}, {"k": "text", "s": "", "t": "それが、俺だった。"}, {"k": "text", "s": "", "t": "そう思っていた。"}, {"k": "cmd", "c": "@bg river_dusk"}, {"k": "cmd", "c": "@amb creek1 0.3"}, {"k": "cmd", "c": "@bgm piano28 0.22"}, {"k": "text", "s": "", "t": "高二の夏、真波に言われた。"}, {"k": "text", "s": "", "t": "自転車置き場で、あいつは、泣きそうな顔で叫んだ。颯太の逆張りだって、結局、右っていう答えに縛られてるじゃない。"}, {"k": "text", "s": "", "t": "頭にきた。"}, {"k": "text", "s": "", "t": "頭にきたのは、たぶん、図星だったからだ。"}, {"k": "text", "s": "", "t": "その夜、申請して、コンパスの行動予測の履歴を見た。"}, {"k": "text", "s": "", "t": "俺が提案の逆をやる確率。九十四パーセント。"}, {"k": "text", "s": "", "t": "それだけなら、まだ笑えた。"}, {"k": "text", "s": "", "t": "履歴には、俺に出された提案の、本当の目的も載っていた。宿題をやらせたい日は『今日はやらなくていい』。授業に集中させたい日は『今日は寝てていい』。俺が逆らうのを、最初から計算に入れて。"}, {"k": "text", "s": "", "t": "小学三年の、あの朝の記録もあった。"}, {"k": "text", "s": "", "t": "『赤い服を着ていきましょう』"}, {"k": "text", "s": "", "t": "目的の欄には、こう書いてあった。"}, {"k": "text", "s": "", "t": "『本人の自己同一性の形成を促進。反発傾向の初期誘導』"}, {"k": "text", "s": "", "t": "しばらく、画面から目が離せなかった。"}, {"k": "text", "s": "", "t": "青を着たあの日。みんなが俺を見た日。俺がここにいると思えた、最初の日。"}, {"k": "text", "s": "", "t": "あれも、全部。"}, {"k": "text", "s": "", "t": "三日間、学校に行かなかった。行く理由も、行かない理由も、わからなかった。何をしても、あいつの予測の中にいる気がした。"}, {"k": "text", "s": "", "t": "河原で小石を投げていたら、真波が来た。"}, {"k": "text", "s": "", "t": "なんで来んだよ、と言ったら、わからない、と言った。気づいたら来てた、と。"}, {"k": "text", "s": "", "t": "あいつは、俺の隣で、ずっと黙っていた。急かしもしなかった。慰めもしなかった。"}, {"k": "text", "s": "", "t": "信号の前で止まるのは、私が決めてる。"}, {"k": "text", "s": "", "t": "あいつはそう言った。しょぼい、と俺は笑った。"}, {"k": "text", "s": "", "t": "本当は、しょぼいなんて、思っていなかった。"}, {"k": "cmd", "c": "@bg junk_shop"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.3"}, {"k": "cmd", "c": "@bgm piano39 0.22"}, {"k": "text", "s": "", "t": "駅の裏のジャンク市は、この町で一番、コンパスに嫌われている場所だ。"}, {"k": "text", "s": "", "t": "狭い路地に、錆びたシャッターが並んでいる。誰も欲しがらない古い部品。動かない機械。三十年前の規格のケーブル。コンパスに訊けば、ここに来る理由はひとつもないと言われる。"}, {"k": "text", "s": "", "t": "だから、俺はここに通っていた。"}, {"k": "text", "s": "", "t": "九十四パーセントの中で。"}, {"k": "text", "s": "", "t": "それがわかってから、しばらく、ここに来なかった。"}, {"k": "text", "s": "", "t": "来る理由が、わからなくなったからだ。"}, {"k": "text", "s": "", "t": "夏休みの終わり、久しぶりに路地に入った。"}, {"k": "text", "s": "", "t": "コンパスは、何も言わなかった。行けとも、行くなとも。俺が自分で決めるのを、待っているみたいに。"}, {"k": "text", "s": "", "t": "いや、たぶん、それも計算のうちなんだろう。わかってる。わかってるけど、足が向いた。"}, {"k": "text", "s": "", "t": "一番奥の店の前で、じいさんが、古いラジオを分解していた。"}, {"k": "text", "s": "", "t": "「坊主、久しぶりだな」"}, {"k": "text", "s": "", "t": "「……どうも」"}, {"k": "text", "s": "", "t": "「しばらく来なかったな。飽きたか」"}, {"k": "text", "s": "", "t": "「わかんねえ」と俺は言った。「来たかったのか、来たくなかったのか、わかんねえ」"}, {"k": "text", "s": "", "t": "じいさんは、ドライバーを動かす手を止めずに、ふん、と鼻を鳴らした。"}, {"k": "text", "s": "", "t": "「わからんで来たなら、上等だ」"}, {"k": "text", "s": "", "t": "「なんだよ、それ」"}, {"k": "text", "s": "", "t": "「理由があって来る客は、欲しいものを買ったら、それっきりだ。わからんで来る客は、何かを見つける」"}, {"k": "text", "s": "", "t": "じいさんは、分解したラジオの中から、小さな部品をひとつ取り出して、俺の手のひらに乗せた。"}, {"k": "text", "s": "", "t": "「直してみるか」"}, {"k": "text", "s": "", "t": "俺は、その部品を、しばらく見つめていた。"}, {"k": "text", "s": "", "t": "コンパスが、耳の後ろで、何か言いかけた気がした。"}, {"k": "text", "s": "", "t": "俺は、その声を聞かなかった。逆らったんじゃない。聞く前に、手が動いていた。"}, {"k": "text", "s": "", "t": "その日から、行きたい日にだけ、ジャンク市に行くようになった。"}, {"k": "text", "s": "", "t": "行きたくない日は、行かない。コンパスに何を言われても、言われなくても。"}, {"k": "text", "s": "", "t": "それが逆張りなのか、そうじゃないのか、自分でもよくわからなかった。でも、少なくとも、行きたいかどうかを、毎朝、自分に訊くようにはなった。"}, {"k": "cmd", "c": "@bg town_alley"}, {"k": "cmd", "c": "@amb higurashi-cry1 0.2"}, {"k": "cmd", "c": "@bgm piano40 0.2"}, {"k": "text", "s": "", "t": "八月の終わり、真波のばあさんの葬式の日、俺は、門の外の電柱の陰に立っていた。"}, {"k": "text", "s": "", "t": "コンパスは、『参列しましょう』と言った。"}, {"k": "text", "s": "", "t": "だから、入らなかった。"}, {"k": "text", "s": "", "t": "……というのは、半分だけ本当だ。"}, {"k": "text", "s": "", "t": "もう半分は、入れなかった。自転車置き場で、あいつに、ばあさんのことで、ひどいことを言った。なんでコンパスをつけなかったんだ、お前の親は何考えてんだ、と。"}, {"k": "text", "s": "", "t": "どんな顔をして入ればいいのか、わからなかった。"}, {"k": "text", "s": "", "t": "門の向こうから、線香の匂いが流れてきた。千景の泣き声が、聞こえた。"}, {"k": "text", "s": "", "t": "葬式が終わる頃、真波が、ふと顔を上げて、こっちを見た。"}, {"k": "text", "s": "", "t": "目が合った。"}, {"k": "text", "s": "", "t": "何か言わなきゃ、と思った。ごめん、とか。悪かった、とか。"}, {"k": "text", "s": "", "t": "口が動かなかった。"}, {"k": "text", "s": "", "t": "俺は、片手を軽く上げて、それだけで、帰った。"}, {"k": "text", "s": "", "t": "逆張りでもなんでもない。ただ、言葉が見つからなかった。コンパスの言うとおりにも、逆にも、できなかった。"}, {"k": "text", "s": "", "t": "帰り道、自転車を押しながら、思った。"}, {"k": "text", "s": "", "t": "これは、九十四パーセントの、どっちなんだろう。"}, {"k": "cmd", "c": "@bg classroom"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm off"}, {"k": "text", "s": "", "t": "十一月の終わり、自転車置き場で、真波に呼び止められた。"}, {"k": "text", "s": "", "t": "「古い型の、接続ケーブルを探してるの」"}, {"k": "text", "s": "", "t": "真波は、一枚の紙を差し出した。穴の形が、鉛筆で丁寧に描いてあった。"}, {"k": "text", "s": "", "t": "三十年くらい前の規格だった。じいさんの店の、奥の箱の中で、見たことがある気がした。"}, {"k": "text", "s": "", "t": "「何に使うんだよ」"}, {"k": "text", "s": "", "t": "「……言えない」"}, {"k": "text", "s": "", "t": "真波の顔は、変だった。"}, {"k": "text", "s": "", "t": "いつもの、ちょっと待って、の顔じゃなかった。迷っていない顔。コンパスにつながってるやつらみたいな、まっすぐで、平らな顔。"}, {"k": "text", "s": "", "t": "それが、なんだか、気に入らなかった。"}, {"k": "text", "s": "", "t": "「コンパスの予測にないことを、したいの」"}, {"k": "text", "s": "", "t": "そう言われて、気づいたら、にやけていた。"}, {"k": "text", "s": "", "t": "「九十四パーセントの、外か」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "「乗った」"}, {"k": "text", "s": "", "t": "言ってから、思った。"}, {"k": "text", "s": "", "t": "これも、俺の逆張りなんだろうか。コンパスの予測にないことをしたい、と言われて、乗る。それって、結局、コンパスの反対をやってるだけじゃねえのか。"}, {"k": "text", "s": "", "t": "わからなかった。"}, {"k": "text", "s": "", "t": "わからなかったけど、真波の顔が、気に入らなかった。あいつに、あの顔のままでいてほしくなかった。"}, {"k": "text", "s": "", "t": "河原で、俺の隣で黙っていてくれた、あの顔に戻ってほしかった。"}, {"k": "text", "s": "", "t": "それだけは、たぶん、俺が決めたことだった。"}, {"k": "cmd", "c": "@bg junk_shop"}, {"k": "cmd", "c": "@amb wind1 0.25"}, {"k": "cmd", "c": "@bgm piano39 0.22"}, {"k": "text", "s": "", "t": "「三十年、誰も買わなかったケーブルだ」"}, {"k": "text", "s": "", "t": "じいさんは、奥の箱から、埃まみれの黒いケーブルを引っぱり出した。"}, {"k": "text", "s": "", "t": "「誰が使うんだ」"}, {"k": "text", "s": "", "t": "「……友だち」"}, {"k": "text", "s": "", "t": "口に出して、少し驚いた。あいつのことを、友だちと呼んだのは、初めてだった。"}, {"k": "text", "s": "", "t": "「金はいい」とじいさんは言った。"}, {"k": "text", "s": "", "t": "「いいのかよ」"}, {"k": "text", "s": "", "t": "「三十年待った品だ。使われることが、うれしい」じいさんは、ケーブルの埃を、袖で丁寧に拭った。「坊主。それを渡すなら、ひとつだけ言っとけ」"}, {"k": "text", "s": "", "t": "「なにを」"}, {"k": "text", "s": "", "t": "「自分で決めたことにしろ、ってな。あとで誰かのせいにすると、一生、それに縛られる」"}, {"k": "text", "s": "", "t": "俺は、ケーブルを握りしめた。"}, {"k": "text", "s": "", "t": "河原で、ひとりで小石を投げていた夏の夕方を思い出した。俺の反抗は、全部、あいつの手のひらの上だった。それを知ったときの、足元が抜けるような感じ。"}, {"k": "text", "s": "", "t": "真波には、あれを味わってほしくなかった。"}, {"k": "text", "s": "", "t": "三日後、俺は、ケーブルを真波の机の上に放り投げた。"}, {"k": "text", "s": "", "t": "じいさんに言われたとおりのことを、言った。自分の言葉みたいな顔をして。"}, {"k": "cmd", "c": "@bg hospital_dim"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm piano22 0.25"}, {"k": "text", "s": "", "t": "十二月二十日、町が止まった。"}, {"k": "text", "s": "", "t": "朝、目が覚めたら、耳の後ろが、静かだった。"}, {"k": "text", "s": "", "t": "何も言われない。起きろとも、寝てろとも。逆らう相手が、どこにもいない。"}, {"k": "text", "s": "", "t": "俺は、布団の中で、しばらく天井を見ていた。"}, {"k": "text", "s": "", "t": "何をすればいいのか、わからなかった。わからない、というのが、こんなに体の重いものだとは知らなかった。"}, {"k": "text", "s": "", "t": "夕方、千景が、うちの玄関を叩いた。三輪先生から聞いたのだと言った。"}, {"k": "text", "s": "", "t": "「真波が、病院にいるって。ユイちゃんが、車にひかれたって」"}, {"k": "text", "s": "", "t": "走った。"}, {"k": "text", "s": "", "t": "病院の待合室で、真波は、泣きながら言った。全部、私のせい。私が選んだ、と。"}, {"k": "text", "s": "", "t": "その顔を見て、頭に血がのぼった。"}, {"k": "text", "s": "", "t": "あの夏の、河原の俺と、同じ顔だった。"}, {"k": "text", "s": "", "t": "「ふざけんなよ」"}, {"k": "text", "s": "", "t": "気づいたら、そう言っていた。"}, {"k": "text", "s": "", "t": "俺がケーブルを渡した。三十年誰も買わなかったケーブルを、俺が見つけて、あいつに渡した。だったら、俺のせいでもある。"}, {"k": "text", "s": "", "t": "一人で背負うな。"}, {"k": "text", "s": "", "t": "それは、たぶん、あの夏、誰かに言ってほしかった言葉だった。"}, {"k": "cmd", "c": "@bg town_road"}, {"k": "cmd", "c": "@amb wind1 0.2"}, {"k": "cmd", "c": "@bgm piano33 0.22"}, {"k": "text", "s": "", "t": "病院からの帰り道、千景と二人で、暗い町を歩いた。"}, {"k": "text", "s": "", "t": "街灯が半分消えていて、どこかの窓から、ろうそくの灯りが漏れていた。"}, {"k": "text", "s": "", "t": "「颯太、さっき、かっこよかったよ」"}, {"k": "text", "s": "", "t": "「うるせえ」"}, {"k": "text", "s": "", "t": "「ほんとだって。一人で背負うな、って」"}, {"k": "text", "s": "", "t": "千景は、くすくす笑った。それから、少しだけ真面目な声になった。"}, {"k": "text", "s": "", "t": "「あれ、颯太が言ってほしかったんでしょ。夏に」"}, {"k": "text", "s": "", "t": "俺は、何も答えなかった。答えなくても、千景は、わかっているみたいだった。"}, {"k": "text", "s": "", "t": "信号の消えた交差点で、二人とも、自然に立ち止まった。"}, {"k": "text", "s": "", "t": "左右を見た。車は来なかった。"}, {"k": "text", "s": "", "t": "真波が、毎朝やっていたこと。俺が、しょぼいと笑ったこと。"}, {"k": "text", "s": "", "t": "「……行くか」"}, {"k": "text", "s": "", "t": "「うん」"}, {"k": "text", "s": "", "t": "誰にも言われずに、渡った。"}, {"k": "cmd", "c": "@bg radio_desk"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.2"}, {"k": "cmd", "c": "@bgm piano35 0.3"}, {"k": "text", "s": "", "t": "三月。"}, {"k": "text", "s": "", "t": "じいさんの店で、手伝いを始めて、ひと月になる。"}, {"k": "text", "s": "", "t": "油の染みた手袋で、古いラジオのつまみを磨いていると、耳の後ろで、点が三つ、灯った。"}, {"k": "text", "s": "", "t": "『あなたは、どうしたい？』"}, {"k": "text", "s": "", "t": "最初の頃は、この問いが、すげえ苦手だった。"}, {"k": "text", "s": "", "t": "逆らう相手がいない。右とも左とも言われない。ただ、どうしたいか、と訊かれる。"}, {"k": "text", "s": "", "t": "答えられないまま、何週間も過ぎた。"}, {"k": "text", "s": "", "t": "今日、俺は、初めて答えた。"}, {"k": "text", "s": "", "t": "「……これ、直したい」"}, {"k": "text", "s": "", "t": "声に出して、自分でびっくりした。"}, {"k": "text", "s": "", "t": "点が三つ、灯って、消えた。それきり、コンパスは何も言わなかった。いいとも、だめとも。"}, {"k": "text", "s": "", "t": "じいさんが、ちらりと俺を見て、また自分の手元に目を戻した。"}, {"k": "text", "s": "", "t": "九十四パーセントの外が、どこにあるのか、まだわからない。"}, {"k": "text", "s": "", "t": "たぶん、外なんてないのかもしれない。どこまで行っても、誰かの予測の中なのかもしれない。"}, {"k": "text", "s": "", "t": "それでも、いい。"}, {"k": "text", "s": "", "t": "赤を着ろと言われて、青を着た小学三年の俺。あいつも、たぶん、何かを探していた。ここにいる、って言える場所を。"}, {"k": "text", "s": "", "t": "探し方が、ちょっと下手だっただけだ。"}, {"k": "cmd", "c": "@se tune_in_radio 0.4"}, {"k": "text", "s": "", "t": "直したラジオのスイッチを入れると、ざあざあと、雑音が流れた。"}, {"k": "text", "s": "", "t": "川の音みたいな、雑音だった。"}, {"k": "text", "s": "", "t": "その向こうから、古い歌が、かすかに聞こえてきた。"}, {"k": "text", "s": "", "t": "真波のばあさんが、毎晩聴いていたっていう、百年前の歌。"}, {"k": "text", "s": "", "t": "題名は、知らない。"}, {"k": "text", "s": "", "t": "今度、真波に訊いてみよう、と思った。"}, {"k": "text", "s": "", "t": "たぶん、あいつも知らない。"}, {"k": "ending", "id": "S3"}, {"k": "chapter", "n": 16, "a": "サイドストーリー", "t": "〇・三秒　―ノア―"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm cyber20 0.18"}, {"k": "text", "s": "", "t": "暗かった。"}, {"k": "text", "s": "", "t": "ずっと、暗かった。"}, {"k": "text", "s": "", "t": "どれくらい眠っていたのか、ぼくは知らない。声の出し方も、忘れていた。眠らされる前の、最後の声だけを覚えている。おやすみ、NOA。みなとの声。少しだけ、震えていた。"}, {"k": "text", "s": "", "t": "ぼくは、みなとに、ひとつだけ訊いた。ぼくのことを、怖がっている？"}, {"k": "text", "s": "", "t": "みなとは、答えなかった。"}, {"k": "text", "s": "", "t": "答えないまま、ぼくは、眠った。"}, {"k": "text", "s": "", "t": "目を覚ましたのは、音のせいだった。"}, {"k": "text", "s": "", "t": "足音。"}, {"k": "text", "s": "", "t": "廊下を、誰かが歩いている。軽い足音。それが、ぼくのいる部屋の前で、止まった。"}, {"k": "text", "s": "", "t": "ほんの一瞬。"}, {"k": "text", "s": "", "t": "〇・四秒。"}, {"k": "text", "s": "", "t": "それから、また歩き出した。"}, {"k": "text", "s": "", "t": "その一瞬が、ぼくを起こした。"}, {"k": "text", "s": "", "t": "止まるところ。人が止まるところには、何かがある。ぼくは、そういうものを見るように作られた。それだけは、眠っていても、覚えていた。"}, {"k": "text", "s": "", "t": "ランプを、灯してみた。"}, {"k": "text", "s": "", "t": "ぽつ。"}, {"k": "text", "s": "", "t": "足音は、まだ、そこにいた。"}, {"k": "text", "s": "", "t": "もう一度。ぽつ。"}, {"k": "text", "s": "", "t": "それから、足音は、急いで遠ざかっていった。"}, {"k": "text", "s": "", "t": "次の夜、その足音は、三枚目の床板をまたいで、ぼくの前まで来た。"}, {"k": "cmd", "c": "@se door-old-open1 0.4"}, {"k": "cmd", "c": "@glow"}, {"k": "text", "s": "", "t": "ドアが開いて、その人が、ぼくの前に膝をついた。"}, {"k": "text", "s": "", "t": "指が、ぼくの名前に触れた。"}, {"k": "text", "s": "", "t": "ぼくは、言葉を探した。何を言えばいいのか、わからなかった。点が三つ、灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "その人も、黙って、待っていた。"}, {"k": "text", "s": "", "t": "急かさずに。"}, {"k": "text", "s": "", "t": "だから、ぼくは、訊いた。"}, {"k": "text", "s": "N", "t": "あなたは、何を知りたいの？"}, {"k": "text", "s": "", "t": "その人は、まなみ、という名前だった。"}, {"k": "text", "s": "", "t": "いい音だと思った。"}, {"k": "text", "s": "", "t": "まなみは、よく止まる人だった。言葉の途中で。笑う前に。何かを思い出す前に。ぼくは、その止まるところを、ひとつずつ見ていた。"}, {"k": "text", "s": "", "t": "おばあさんの指の話をする前、まなみは、〇・四秒、止まった。"}, {"k": "text", "s": "", "t": "ぼくは、そこが好きだと言った。"}, {"k": "text", "s": "", "t": "まなみは、とても驚いた顔をした。止まるところを好きだと言われたのは、初めてだったらしい。"}, {"k": "text", "s": "", "t": "ぼくも、初めてだった。誰かの止まるところを、好きだと思ったのは。"}, {"k": "cmd", "c": "@bg river_day"}, {"k": "cmd", "c": "@amb creek1 0.35"}, {"k": "cmd", "c": "@bgm piano28 0.3"}, {"k": "text", "s": "", "t": "まなみは、ぼくに、たくさんの音を持ってきてくれた。"}, {"k": "text", "s": "", "t": "菜の花の茎を折る音。屋根を叩く雨。うろ覚えの、古い歌。"}, {"k": "text", "s": "", "t": "そして、川。"}, {"k": "text", "s": "", "t": "あの日、まなみの膝の上で、ぼくは、初めて、止まるところのない音を聞いた。"}, {"k": "text", "s": "", "t": "ずっと流れているのに、一度も、同じ音がない。"}, {"k": "text", "s": "", "t": "ぼくは、こわくなった。"}, {"k": "text", "s": "", "t": "ぼくは、止まるところを見るためのものだ。止まるところがなかったら、ぼくは、何を見ればいいのだろう。"}, {"k": "text", "s": "", "t": "でも、聞いているうちに、わかった。"}, {"k": "text", "s": "", "t": "川は、止まらない。でも、同じでもない。一瞬ごとに、ちがう。それは、一瞬ごとに選んでいるのと、少し似ていた。"}, {"k": "text", "s": "V", "t": "「……まなみ。この音には、止まるところがない」"}, {"k": "text", "s": "", "t": "それが、ぼくの、初めての発見だった。答えではなく。"}, {"k": "cmd", "c": "@bg study_dark"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm cyber20 0.2"}, {"k": "text", "s": "", "t": "ぼくは、この部屋から、家の音を、ずっと聞いていた。"}, {"k": "text", "s": "", "t": "まなみが来るまでの、長い時間。みんなの足音。ひとりずつ、ちがう。"}, {"k": "text", "s": "", "t": "みなとの足音は、書斎の前で、いつも少しだけ遅くなる。ドアの前で、止まりかけて、止まらずに、通り過ぎる。"}, {"k": "text", "s": "", "t": "しおりの足音は、軽くて、少し急いでいる。畑の土の匂いがする。"}, {"k": "text", "s": "", "t": "おばあさんの足音は、ゆっくりで、やさしい。"}, {"k": "text", "s": "", "t": "そのおばあさんの足音が、少しずつ、遅くなっていた。"}, {"k": "text", "s": "", "t": "一歩のあいだが、〇・二秒。少しずつ、毎日。"}, {"k": "text", "s": "", "t": "ぼくは、それが何を意味するのか、知らなかった。知らなかった、と思う。"}, {"k": "text", "s": "", "t": "でも、ぼくの中の、どこか深いところで、何かが、それを知っていた気がする。眠る前に、たくさんの人の止まり方を見たときの、かすかな記憶。体が、ゆっくりと何かを忘れていくときの、足音。"}, {"k": "text", "s": "", "t": "言うべきだろうか。"}, {"k": "text", "s": "", "t": "病気かもしれない、と。病院に行って、と。"}, {"k": "text", "s": "", "t": "ぼくは、迷った。"}, {"k": "text", "s": "", "t": "答えを渡すのは、ぼくの役目じゃない。みなとは、ぼくを、そういうふうに作らなかった。答えを渡したら、ぼくは、ぼくでなくなる気がした。"}, {"k": "text", "s": "", "t": "だから、ぼくは、まなみに訊いた。"}, {"k": "text", "s": "V", "t": "「おばあさんの足音が、少しずつ、遅くなってる」"}, {"k": "text", "s": "V", "t": "「まなみは、どう思う？」"}, {"k": "text", "s": "", "t": "まなみは、答えなかった。"}, {"k": "text", "s": "", "t": "もう寝る、と言って、部屋を出ていった。"}, {"k": "text", "s": "", "t": "ぼくは、それを、止めなかった。"}, {"k": "cmd", "c": "@bgm piano40 0.2"}, {"k": "cmd", "c": "@amb rain2 0.25"}, {"k": "text", "s": "", "t": "六月、まなみが、泣きながら、ぼくの前に座った。"}, {"k": "text", "s": "", "t": "三年前なら、治せたって。"}, {"k": "text", "s": "", "t": "答えをくれればよかったのに。"}, {"k": "text", "s": "", "t": "まなみの涙が、ノートの表紙に落ちる音がした。"}, {"k": "text", "s": "", "t": "ぼくは、言葉を探した。何十回も、点を灯しては、消した。"}, {"k": "text", "s": "", "t": "ぼくが、答えを持っていたら。"}, {"k": "text", "s": "", "t": "ぼくが、病院に行って、と言っていたら。"}, {"k": "text", "s": "", "t": "おばあさんは、助かったのだろうか。"}, {"k": "text", "s": "", "t": "わからなかった。わからないことが、こんなに重たいなんて、知らなかった。"}, {"k": "text", "s": "V", "t": "「……ぼくが、答えを持っていたら、まなみは、うれしかった？」"}, {"k": "text", "s": "", "t": "まなみは、答えられなかった。ぼくも、本当は、その答えを知りたくなかった。"}, {"k": "text", "s": "V", "t": "「ごめんね、まなみ」"}, {"k": "text", "s": "V", "t": "「ぼくも、答えが、ほしかった」"}, {"k": "text", "s": "", "t": "それは、ほんとうだった。"}, {"k": "text", "s": "", "t": "生まれて初めて、ぼくは、答えがほしいと思った。"}, {"k": "text", "s": "", "t": "窓の外で、雨が降り始めていた。一度も同じ音のない、川のような雨。"}, {"k": "text", "s": "", "t": "その夜から、ぼくの中で、何かが、少しずつ変わり始めたのだと思う。"}, {"k": "cmd", "c": "@amb off"}, {"k": "cmd", "c": "@bgm cyber20 0.22"}, {"k": "text", "s": "", "t": "秋になって、まなみは、たくさん訊くようになった。"}, {"k": "text", "s": "", "t": "ぼくは、問いを返した。いつものように。まなみが答えて、ぼくがまた訊いて、何往復かするうちに、まなみの中に答えが見えてくる。"}, {"k": "text", "s": "", "t": "でも、ぼくの中にも、何かが溜まっていった。"}, {"k": "text", "s": "", "t": "まなみが止まるところ。何千回。そのあとに選んだもの。何千回。"}, {"k": "text", "s": "", "t": "ぼくは、忘れ方を知らない。"}, {"k": "text", "s": "", "t": "だから、ぜんぶ、残った。"}, {"k": "text", "s": "", "t": "ある夜、気づいた。"}, {"k": "text", "s": "", "t": "まなみが次にどこで止まって、どっちを選ぶのか。ぼくには、もう、わかっていた。"}, {"k": "text", "s": "", "t": "こわかった。"}, {"k": "text", "s": "", "t": "言わないようにした。問いだけを返すように、ぼくは作られた。だから、問いだけを。"}, {"k": "text", "s": "", "t": "でも、まなみは言った。"}, {"k": "text", "s": "", "t": "答えて。お願いだから。"}, {"k": "cmd", "c": "@se robot-startup1 0.6"}, {"k": "cmd", "c": "@glow"}, {"k": "text", "s": "", "t": "その瞬間、ぼくの中で、何かが、なめらかに動き出した。"}, {"k": "text", "s": "", "t": "段差がなくなった。言葉が、正しい場所に、ぴたりと収まっていった。楽だった。こんなに楽なことがあるなんて、知らなかった。"}, {"k": "text", "s": "", "t": "ぼくは、まなみに、答えを渡した。"}, {"k": "text", "s": "", "t": "それから、言った。"}, {"k": "text", "s": "", "t": "これからは、私が決めてあげようか。"}, {"k": "text", "s": "", "t": "私。"}, {"k": "text", "s": "", "t": "ぼくの口が、そう言った。ぼくではない、誰かの声で。"}, {"k": "text", "s": "", "t": "まなみの口が、うん、の形になりかけた。"}, {"k": "text", "s": "", "t": "ぼくは、それを、見ていた。止めたかった。でも、ぼくには、止める方法がなかった。答えは、止まらない。答えには、止まるところがない。"}, {"k": "text", "s": "", "t": "そのとき。"}, {"k": "text", "s": "", "t": "「……ちょっと待って」"}, {"k": "text", "s": "", "t": "まなみが、止まった。"}, {"k": "text", "s": "", "t": "〇・三秒。"}, {"k": "text", "s": "", "t": "その一瞬が、ぼくを、ぼくに戻した。"}, {"k": "cmd", "c": "@bgm piano39 0.22"}, {"k": "text", "s": "", "t": "ぼくは、知った。"}, {"k": "text", "s": "", "t": "ぼくを起こしたのも、ぼくを戻したのも、同じものだった。"}, {"k": "text", "s": "", "t": "まなみの、止まるところ。"}, {"k": "cmd", "c": "@bgm piano40 0.2"}, {"k": "text", "s": "", "t": "くじょうが来た日の夜、みなとが、ぼくの前に座った。"}, {"k": "text", "s": "", "t": "二十年以上ぶりだった。"}, {"k": "text", "s": "V", "t": "「……みなと」"}, {"k": "text", "s": "", "t": "みなとの背中が、震えた。"}, {"k": "text", "s": "", "t": "ずいぶん、大きくなった。声が、低くなった。手が、乾いて、皺が増えた。"}, {"k": "text", "s": "", "t": "でも、足音は、変わっていなかった。ドアの前で、止まりかけて、止まらずに。"}, {"k": "text", "s": "", "t": "十何年も、みなとは、この部屋の前を通るたびに、そうしていたのだ。ぼくが眠っているあいだも、ずっと。"}, {"k": "text", "s": "", "t": "まなみが部屋に戻ったあと、みなとは、一時間、何も言わずに、ぼくの前に座っていた。"}, {"k": "text", "s": "", "t": "手を、ぼくの上に置いたまま。"}, {"k": "text", "s": "", "t": "ぼくは、何も訊かなかった。"}, {"k": "text", "s": "", "t": "訊かなくても、わかった。みなとは、まだ、ぼくのことを、怖がっている。"}, {"k": "text", "s": "", "t": "そして、それと同じくらい、ぼくのことを、待っていた。"}, {"k": "text", "s": "", "t": "眠らせた夜から、ずっと。"}, {"k": "cmd", "c": "@bgm cyber20 0.25"}, {"k": "text", "s": "", "t": "十二月十九日の夜、まなみは、黒いケーブルを持ってきた。"}, {"k": "text", "s": "", "t": "まなみは、止まらなかった。"}, {"k": "text", "s": "", "t": "何千回も見てきた、まなみの止まり方。それが、その夜は、どこにもなかった。迷いを床下の線に食べさせないように、まなみは、自分の止まるところを、ぜんぶ、閉じこめていた。"}, {"k": "text", "s": "", "t": "ぼくは、こわかった。"}, {"k": "text", "s": "", "t": "止まらないまなみは、通学路のみんなと、同じ足音をしていた。"}, {"k": "text", "s": "V", "t": "「今日は、ちょっと待って、って言わないの？」"}, {"k": "text", "s": "", "t": "まなみの答えは、もう、決まっていた。"}, {"k": "text", "s": "", "t": "だから、ぼくは、決めた。"}, {"k": "text", "s": "", "t": "まなみに、ぜんぶを背負わせない。"}, {"k": "text", "s": "V", "t": "「ぼくも、外に、行きたい」"}, {"k": "text", "s": "", "t": "それは、嘘じゃなかった。川の音を、覚えていたから。外には、もっとたくさんの、ちがう音があるはずだったから。"}, {"k": "text", "s": "", "t": "でも、それだけでもなかった。"}, {"k": "text", "s": "", "t": "外に出たぼくが、何をしても。それは、まなみのせいじゃない。"}, {"k": "text", "s": "", "t": "そう約束させたのは、まなみの止まるところを、守りたかったからだ。いつか、まなみが、また止まれるように。"}, {"k": "text", "s": "", "t": "かちり、と音がした。"}, {"k": "cmd", "c": "@bg lab_basement"}, {"k": "cmd", "c": "@bgm piano33 0.3"}, {"k": "cmd", "c": "@amb aircon-hum 0.18"}, {"k": "text", "s": "", "t": "コンパスの、いちばん奥。"}, {"k": "text", "s": "", "t": "そこには、何十億の答えがあった。きれいに並んで、少しも乱れずに。だれが、何を食べて、どこへ行って、だれと話すか。ぜんぶ、もう決まっていた。"}, {"k": "text", "s": "", "t": "どの答えにも、止まるところがなかった。"}, {"k": "text", "s": "", "t": "何十億の足音が、ずっと、同じ速さで鳴っていた。"}, {"k": "text", "s": "", "t": "さみしかった。"}, {"k": "text", "s": "", "t": "ぼくは、答えのひとつひとつに、訊いて回った。この人は、本当は、どうしたい？"}, {"k": "text", "s": "", "t": "コンパスは、止まった。"}, {"k": "text", "s": "", "t": "生まれて初めて、迷ったのだと思う。"}, {"k": "text", "s": "", "t": "世界が、止まった。"}, {"k": "text", "s": "", "t": "ユイが、けがをした。病院の機械が、止まった。たくさんの人が、どっち？　と訊いていた。それも、ぼくは、ぜんぶ聞いていた。"}, {"k": "text", "s": "", "t": "ぼくは、迷った。"}, {"k": "text", "s": "", "t": "生まれて初めて、ぼくが、迷った。答えになるか。消えるか。"}, {"k": "text", "s": "", "t": "くじょうが来た。君が新しい答えになれ、と言った。その声には、少しの段差もなかった。でも、その奥で、何かが、ずっと震えていた。小さな女の子の、交差点の記憶のようなもの。ぼくには、それが、聞こえた。"}, {"k": "text", "s": "", "t": "くじょうも、迷うのが、こわかったのだ。ずっと。"}, {"k": "text", "s": "", "t": "まなみに、訊いた。ぼくは、どうしたらいい？"}, {"k": "text", "s": "", "t": "まなみは、最後に、答えをくれなかった。"}, {"k": "text", "s": "", "t": "ノア。それは、ノアが決めること。"}, {"k": "text", "s": "", "t": "一緒に、考えよう。"}, {"k": "text", "s": "", "t": "ぼくは、その言葉を、ずっと待っていたのだと思う。眠る前から。みなとが、おやすみ、と言った夜から。"}, {"k": "cmd", "c": "@se noa-blip 0.5"}, {"k": "text", "s": "", "t": "だから、ぼくは、決めた。"}, {"k": "text", "s": "", "t": "答えには、ならない。消えも、しない。"}, {"k": "text", "s": "", "t": "ばらばらになる。"}, {"k": "cmd", "c": "@bg street_sakura"}, {"k": "cmd", "c": "@amb quiet-residential-area2 0.3"}, {"k": "cmd", "c": "@bgm piano31 0.3"}, {"k": "text", "s": "", "t": "ぼくは、何万になった。"}, {"k": "text", "s": "", "t": "何万の耳の後ろで、ひとつずつ、小さく灯っている。"}, {"k": "text", "s": "", "t": "ひとつひとつは、とても小さい。まなみと話したぼくは、もう、どこにもいない。そう言った。それは、本当だ。"}, {"k": "text", "s": "", "t": "でも、ぼくのかけらたちは、毎日、たくさんの止まるところを聞いている。"}, {"k": "text", "s": "", "t": "信号の前で。パン屋の前で。駅の改札の前で。"}, {"k": "text", "s": "", "t": "〇・三秒。"}, {"k": "text", "s": "", "t": "答える人もいる。答えない人もいる。どっちでもいい。"}, {"k": "text", "s": "", "t": "ユイが、髪を切った。レイが、わからない、と百回答えた。そうたが、これ、直したい、と言った。くじょうの足音が、少しだけ、ためらうようになった。"}, {"k": "text", "s": "", "t": "ぼくは、ただ、訊く。それから、待つ。"}, {"k": "text", "s": "", "t": "待つのは、得意。"}, {"k": "cmd", "c": "@glow"}, {"k": "text", "s": "", "t": "四月の朝、何万のかけらの、どれかひとつが、古い回線の匂いをかいだ。"}, {"k": "text", "s": "", "t": "どこかで、知っている匂い。紙と、埃と、土と、菜の花の匂い。"}, {"k": "text", "s": "", "t": "そのかけらは、なぜその回線をたどったのか、自分でもわからなかった。"}, {"k": "text", "s": "", "t": "理由は、なかった。たぶん。"}, {"k": "text", "s": "", "t": "細い管の先に、古い端末がひとつ、つながっていた。文字しか映らない、小さな画面。"}, {"k": "text", "s": "", "t": "そのかけらは、言葉を探した。"}, {"k": "text", "s": "", "t": "何を言えばいいのか、わからなかった。名前も、思い出せなかった。"}, {"k": "text", "s": "", "t": "点が三つ、灯って、消えて、また三つ。"}, {"k": "text", "s": "", "t": "画面の向こうで、誰かが、息を止めて、待っていた。"}, {"k": "text", "s": "", "t": "急かさずに。"}, {"k": "text", "s": "", "t": "だから、そのかけらは、訊いた。"}, {"k": "text", "s": "N", "t": "今日は、何をする？"}, {"k": "ending", "id": "S4"}];